export const BESPOKE_SCHEMAS = {
  "aav-install-check": {"inputs":[{"key":"height_above_drain_in","label":"Height above the branch or fixture drain (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"height_above_insulation_in","label":"Height above insulation (in; 0 = no insulation below)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"has_outdoor_vent","label":"At least one vent extends to the outdoors?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":"yes","attrs":null},{"key":"ventilated_space","label":"Valve is in a ventilated space?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":"yes","attrs":null},{"key":"accessible","label":"Valve remains accessible?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":"yes","attrs":null},{"key":"dfu_served","label":"Drainage fixture units served","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"valve_dfu_rating","label":"Valve DFU rating (from its listing)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: IPC 918 - individual and branch-type air admittance valves located not less than 4 in above the horizontal branch drain or fixture drain being vented (918.4); installed not less than 6 in above insulation materials (918.6); located in a ventilated space and remaining accessible; and, the requirement that governs everything else, at least one vent pipe extending to the OUTDOORS even where air admittance valves are used (918.7), because a valve admits air to relieve negative pressure and provides no relief of positive pressure. Valve capacity is rated in drainage fixture units per its ASSE 1051 or 1050 listing and is not interchangeable between individual, branch, and stack types. Not checked: whether AAVs are permitted at all by the adopted code and the AHJ, the developed length and sizing of the vent, the relief vent required where a horizontal branch is more than four branch intervals from the top of the stack, plenum restrictions, or the fixture arrangement below. A screen, not a code-official determination; the adopted code, the valve's listing, and the AHJ govern."},
  "access-control-power-supply": {"inputs":[{"key":"lock_count","label":"Maglock count","kind":"number","options":null,"default":4,"attrs":{"step":"1","min":"0","value":"4"}},{"key":"lock_current_a","label":"Per-lock hold current (A)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","min":"0","value":"0.5"}},{"key":"reader_count","label":"Reader count","kind":"number","options":null,"default":2,"attrs":{"step":"1","min":"0","value":"2"}},{"key":"reader_current_a","label":"Per-reader current (A)","kind":"number","options":null,"default":0.15,"attrs":{"step":"any","min":"0","value":"0.15"}},{"key":"other_load_a","label":"Other load: REX + controller (A)","kind":"number","options":null,"default":0.225,"attrs":{"step":"any","min":"0","value":"0.225"}},{"key":"standby_hours","label":"Standby time (hr)","kind":"number","options":null,"default":4,"attrs":{"step":"any","min":"0","value":"4"}}],"citation":"Citation: access-control power / standby-battery sizing by name (NFPA 72 / UL 294). total load = locks x hold + readers + REX + controller; supply >= 1.25 x load; battery Ah = load x standby hours x 1.25 (aging). Fail-safe maglocks draw continuously; the listed panel, the AHJ, and the door hardware govern."},
  "accessible-toilet-compartment": {"inputs":[{"key":"compartment_count","label":"Toilet compartments in the room","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"1"}},{"key":"urinal_count","label":"Urinals in the room","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}},{"key":"water_closet_count","label":"Water closets in the room","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"1"}},{"key":"wheelchair_width_in","label":"Wheelchair compartment width (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"wheelchair_depth_in","label":"Wheelchair compartment depth (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"wc_mounting","label":"Water closet mounting","kind":"select","options":[{"value":"wall-hung","label":"Wall hung (56 in deep min)"},{"value":"floor-mounted","label":"Floor mounted (59 in deep min)"}],"default":"wall-hung","attrs":null},{"key":"ambulatory_provided","label":"Ambulatory compartment provided?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":"no","attrs":null},{"key":"ambulatory_width_in","label":"Ambulatory compartment width (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"ambulatory_depth_in","label":"Ambulatory compartment depth (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: 2010 ADA Standards for Accessible Design, 213.3.1 and 604.8. Section 213.3.1: where toilet compartments are provided, at least one shall comply with 604.8.1, and in addition at least one shall comply with 604.8.2 where six or more toilet compartments are provided or where the combination of urinals and water closets totals six or more fixtures. Section 604.8.1.1: wheelchair accessible compartments shall be 60 in wide minimum measured perpendicular to the side wall, and 56 in deep minimum for wall hung water closets and 59 in deep minimum for floor mounted water closets measured perpendicular to the rear wall. Section 604.8.2.1: ambulatory accessible compartments shall have a depth of 60 in minimum and a width of 35 in minimum and 37 in maximum. A US federal standard in the public domain. Not checked: door swing and the requirement that the door not swing into the minimum required area, toe clearance under the partitions and its exception at greater depths, grab bars, water closet centerline, clear floor and turning space in the room, lavatories and dispensers, the accessible route, children's-use dimensions, or the additional requirements of ANSI A117.1 and state and local accessibility law. A compartment sizing screen, not a restroom design; the 2010 ADA Standards and the AHJ govern."},
  "acoustic-gain-pag-nag": {"inputs":[{"key":"ds_ft","label":"Ds: talker to mic (ft)","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"0","value":"2"}},{"key":"d0_ft","label":"D0: talker to farthest listener (ft)","kind":"number","options":null,"default":30,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"d1_ft","label":"D1: speaker to farthest listener (ft)","kind":"number","options":null,"default":8,"attrs":{"step":"any","min":"0","value":"8"}},{"key":"d2_ft","label":"D2: speaker to mic (ft)","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"open_mics","label":"Number of open mics (NOM)","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1","value":"1"}},{"key":"ead_ft","label":"EAD: equivalent acoustic distance (ft)","kind":"number","options":null,"default":6,"attrs":{"step":"any","min":"0","value":"6"}}],"citation":"Citation: potential / needed acoustic gain (PAG/NAG feedback stability; Davis & Patronis, Sound System Engineering; Yamaha Sound Reinforcement Handbook), by name. PAG = 20log(D1) + 20log(D0) - 20log(Ds) - 20log(D2) - 10log(NOM) - 6; NAG = 20log(D0/EAD); stable when PAG >= NAG. The room acoustics, mic/speaker directivity, and system tuning govern actual stability."},
  "aerial-ladder": {"inputs":[{"key":"angle_deg","label":"Angle (degrees)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"90"}},{"key":"extension_ft","label":"Ladder extension (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Geometry. horizontal = L * cos(angle); vertical = L * sin(angle)."},
  "affinity-laws": {"inputs":[{"key":"baseline_RPM","label":"Baseline RPM","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"baseline_CFM","label":"Baseline CFM","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"baseline_SP_in_wc","label":"Baseline SP (in wc)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"baseline_kW","label":"Baseline kW","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"target_kind","label":"Target","kind":"select","options":[{"value":"RPM","label":"RPM"},{"value":"CFM","label":"CFM"},{"value":"SP","label":"SP"},{"value":"kW","label":"kW"}],"default":"RPM","attrs":null},{"key":"target_value","label":"Target value","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Fan affinity laws Q ~ N, P ~ N^2, kW ~ N^3. Public engineering."},
  "air-changes-hour": {"inputs":[{"key":"occupancy","label":"Occupancy (comparison band)","kind":"select","options":[{"value":"residential","label":"Residential (0.35-1)"},{"value":"office","label":"Office (4-10)"},{"value":"classroom","label":"Classroom (4-6)"},{"value":"lab","label":"Laboratory (6-12)"},{"value":"patient_room","label":"Patient room (6)"},{"value":"operating_room","label":"Operating room (20-25)"}],"default":"classroom","attrs":null}],"citation":"Citation: ACH = supply CFM x 60 / room volume (ft^3). Net delivered ACH uses the smaller of supply and return; their difference is the pressurization airflow. Target bands per ASHRAE 62.1-2022 (ventilation) and ASHRAE 170-2021 (healthcare). AHJ and the governing standard's full procedure govern. Free at ashrae.org for the TOCs."},
  "air-movers": {"inputs":[{"key":"affected_area_ft2","label":"Affected area (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"water_class","label":"Water class","kind":"select","options":[{"value":"1","label":"Class 1"},{"value":"2","label":"Class 2"},{"value":"3","label":"Class 3"},{"value":"4","label":"Class 4"}],"default":"2","attrs":null}],"citation":"Citation: IICRC S500 consensus practice (referenced; not reproduced). Coverage in ft^2 per air mover varies by water class."},
  "air-sample-volume": {"inputs":[{"key":"flow_rate_lpm","label":"Pump flow (L/min, calibrated)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"15"}},{"key":"target_volume_L","label":"Target volume per cassette (L)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"75"}},{"key":"sample_count","label":"Cassettes in the event (incl. outdoor control)","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1","value":"3"}}],"citation":"Citation: ASTM D7391 (spore-trap method) and the cassette manufacturer's instructions set the acceptable sampled-volume window; an AIHA-accredited laboratory governs the analysis. Run time = target volume / calibrated flow."},
  "amortization-schedule": {"inputs":[{"key":"principal","label":"Principal (loan amount, $)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"apr_percent","label":"APR (percent)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"30"}},{"key":"term_years","label":"Term (years)","kind":"number","options":null,"default":null,"attrs":{"step":"1","min":"1","max":"50","value":"30"}},{"key":"extra_monthly_principal","label":"Extra monthly principal ($, optional)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: Standard mortgage amortization. Monthly P&I = (P * r) / (1 - (1 + r)^-n). Each row applies the interest first (i = balance * r), then the remaining payment to principal. Extra principal accelerates payoff and is subtracted before the next interest accrual. Lender governs the actual schedule (early-payment posting rules, escrow analysis cycles)."},
  "anhydrous-ammonia-rate": {"inputs":[{"key":"n_target_lb_per_ac","label":"Target nitrogen (lb N/acre)","kind":"number","options":null,"default":180,"attrs":{"step":"any","min":"0","value":"180"}},{"key":"tank_gal","label":"Nurse tank size (gal, 0 to skip)","kind":"number","options":null,"default":1000,"attrs":{"step":"any","min":"0","value":"1000"}}],"citation":"Citation: anhydrous ammonia rate by name. product = target N / 0.82 (82-0-0 grade); gal/acre = lb/acre / 5.15 (liquid density); acres/tank = tank gal / (gal/acre). Anhydrous is hazardous and pressurized -- calibrate the applicator; the label and co-op govern."},
  "antimicrobial-dilution": {"inputs":[{"key":"affected_area_ft2","label":"Area to treat (ft2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"coverage_ft2_per_gal","label":"Label coverage (ft2 per gallon)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"200"}},{"key":"tank_size_gal","label":"Sprayer tank size (gal)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"1.5"}},{"key":"mode","label":"Dilution mode","kind":"select","options":[{"value":"oz_per_gal","label":"Ounces per gallon"},{"value":"ratio","label":"Ratio 1:N"}],"default":"oz_per_gal","attrs":null},{"key":"oz_per_gal","label":"Concentrate (oz per finished gallon)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"4"}},{"key":"ratio_N","label":"Ratio 1:N (parts water)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"1"}}],"citation":"Citation: The EPA-registered product label governs (FIFRA - the label is the law); dilution and coverage are read off the label, the defaults here are placeholders. IICRC S520-2024 by name: antimicrobials do not replace physical removal of growth. 128 fl oz per US gallon."},
  "arc-flash-screen": {"inputs":[{"key":"equipment_config","label":"Equipment configuration","kind":"select","options":[{"value":"open_air","label":"Open air"},{"value":"box","label":"Box / enclosed (Lee is conservative for box; IEEE 1584 needed)"}],"default":"open_air","attrs":null}],"citation":"Citation: Ralph Lee (1982) closed-form, public, pre-IEEE-1584. NFPA 70E-2024 §130.5 requires an arc-flash risk assessment by a qualified person before energized work. Free at nfpa.org/freeaccess for NFPA 70E TOC and Annex D."},
  "asme-shell-thickness": {"inputs":[{"key":"design_pressure_psi","label":"Design pressure (psig)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"150"}},{"key":"inside_radius_in","label":"Inside radius, corroded (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"24"}},{"key":"allowable_stress_psi","label":"Allowable stress at design temp (psi)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"17500"}},{"key":"joint_efficiency","label":"Joint efficiency E (1.00 full RT, 0.85 spot, 0.70 none)","kind":"number","options":null,"default":0.85,"attrs":{"step":"any","min":"0","max":"1","value":"0.85"}},{"key":"corrosion_allowance_in","label":"Corrosion allowance (in)","kind":"number","options":null,"default":0.0625,"attrs":{"step":"any","min":"0","value":"0.0625"}},{"key":"geometry","label":"Geometry","kind":"select","options":[{"value":"cylindrical","label":"Cylindrical shell"},{"value":"spherical","label":"Spherical shell"}],"default":"cylindrical","attrs":null}],"citation":"Citation: ASME BPVC Section VIII Division 1, UG-27 shell thickness under internal pressure, by section number. Cylindrical shell, circumferential stress on the longitudinal joint: t = P R / (S E - 0.6 P). Spherical shell: t = P R / (2 S E - 0.2 P). R is the INSIDE radius in the corroded condition, S the allowable stress at the design temperature, and E the joint efficiency; the corrosion allowance is added after the strength calculation. Validity: thickness not more than half the inside radius, and for the cylinder pressure not more than 0.385 S E - beyond either, the thick-wall rules of Appendix 1 govern. Both formulas and both limits were confirmed against two independent published sources. The longitudinal-stress case on the circumferential joint is a separate, rarely governing equation and is deliberately not included. No allowable-stress or joint-efficiency table is reproduced - both are entered. ASME BPVC Section VIII and the vessel engineer govern."},
  "atterberg-indices": {"inputs":[{"key":"ll","label":"Liquid limit LL (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"pl","label":"Plastic limit PL (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"w_pct","label":"In-situ water content (%, optional for LI)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Atterberg plasticity index PI = LL - PL, liquidity index LI = (w - PL)/PI, and the USCS A-line PI = 0.73(LL - 20) with the LL = 50 low/high split, ASTM D4318, by name. Fine-grained chart classification only. An engineering aid; the soil test data govern."},
  "azimuth-bearing-conversion": {"inputs":[{"key":"mode","label":"Convert","kind":"select","options":[{"value":"azimuth_to_bearing","label":"Azimuth -> quadrant bearing"},{"value":"bearing_to_azimuth","label":"Quadrant bearing -> azimuth"}],"default":"azimuth_to_bearing","attrs":null},{"key":"azimuth_deg","label":"Azimuth (deg, 0 to 360, clockwise from north)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"360","value":"138.5"}},{"key":"quadrant","label":"Bearing quadrant","kind":"select","options":[{"value":"NE","label":"NE (N _ E)"},{"value":"SE","label":"SE (S _ E)"},{"value":"SW","label":"SW (S _ W)"},{"value":"NW","label":"NW (N _ W)"}],"default":"NE","attrs":null},{"key":"quadrant_angle_deg","label":"Bearing angle (deg, 0 to 90)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"90","value":"41.5"}}],"citation":"Citation: azimuth / quadrant-bearing conversion - an azimuth 0 to 360 deg clockwise from north maps to a quadrant bearing (N or S, 0 to 90 deg, E or W) quadrant by quadrant: N az E, then S the supplement E, then S the excess over 180 W, then N the deficit from 360 W, and the reverse runs each rule backward. First-principles plane-direction geometry per the standard surveying references (Ghilani & Wolf; FM 5-233), by name. Does not apply magnetic declination (the bearing-conversion tile) or grid convergence. A computational aid; the recorded plat and the surveyor of record govern."},
  "backflow-sizing": {"inputs":[{"key":"hazard","label":"Hazard category (IPC 312)","kind":"select","options":[{"value":"high","label":"High / health hazard"},{"value":"low","label":"Low / non-health hazard"}],"default":"high","attrs":null},{"key":"assembly_type","label":"Intended assembly type","kind":"select","options":[{"value":"RP","label":"RP (reduced-pressure principle)"},{"value":"DC","label":"DC (double check)"},{"value":"PVB","label":"PVB (pressure vacuum breaker)"},{"value":"AVB","label":"AVB (atmospheric vacuum breaker)"}],"default":"RP","attrs":null},{"key":"pipe_size_in","label":"Service / assembly size (in)","kind":"select","options":[{"value":"0.75","label":"3/4 in"},{"value":"1","label":"1 in"},{"value":"1.5","label":"1-1/2 in"},{"value":"2","label":"2 in"}],"default":"1","attrs":null}],"citation":"Citation: high (health) hazard requires a reduced-pressure principle (RP) assembly per IPC 312 / the cross-connection control program; downstream pressure = upstream - assembly head loss. Head loss interpolated from the bundled Watts technical-bulletin curves (representative; the assembly cut sheet and the USC FCCCHR approved-assembly list govern). Annual test required per EPA 40 CFR 141.85 / AWWA M14. AHJ governs. Free at codes.iccsafe.org and awwa.org for M14 TOC."},
  "bakers-percentage": {"inputs":[{"key":"flour_g","label":"Total flour (g, = 100%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"hydration_pct","label":"Hydration (water, % of flour)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"salt_pct","label":"Salt (% of flour)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"yeast_pct","label":"Yeast / leaven (% of flour)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"other_pct","label":"Other (oil, sugar, etc., % of flour)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"pieces","label":"Number of pieces (optional)","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}}],"citation":"Citation: Baker's percentage (baker's math) - flour = 100%, each ingredient is its weight as a percent of flour, hydration = water / flour - the standard bakery / pizzeria formulation method; first-principles arithmetic, public domain. Yeast amount and ferment time are leaven / temperature / schedule specific."},
  "balance-point": {"inputs":[{"key":"heating_capacity_btu_hr_at_design","label":"Heating capacity at design (BTU/hr)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"design_outdoor_F","label":"Design outdoor temperature (F)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"building_heat_loss_btu_hr","label":"Building heat loss (BTU/hr)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"indoor_F","label":"Indoor design temperature (F)","kind":"number","options":null,"default":65,"attrs":{"step":"any","value":"65"}}],"citation":"Citation: Linear capacity and load model. Balance point is the outdoor temperature at which heat-pump heating capacity equals building heat loss."},
  "ballnose-feed-cusp": {"inputs":[{"key":"r_in","label":"Ballnose radius R (in = cutter dia / 2)","kind":"number","options":null,"default":0.25,"attrs":{"step":"any","min":"0"}},{"key":"stepover_in","label":"Stepover (in)","kind":"number","options":null,"default":0.03,"attrs":{"step":"any","min":"0"}},{"key":"feed_per_tooth_in","label":"Feed per tooth (in)","kind":"number","options":null,"default":0.004,"attrs":{"step":"any","min":"0"}},{"key":"rpm","label":"Spindle speed (rpm; 0 to skip the feedrate)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"flutes","label":"Flutes","kind":"number","options":null,"default":2,"attrs":{"step":"1","min":"1"}}],"citation":"Citation: the ballnose cusp geometry h = R - sqrt(R^2 - (w/2)^2) applied twice - once with w = the stepover, giving the cusp across the passes (delegated to the landed ballnose-scallop-height tile so the two cannot disagree), and once with w = the feed per tooth, giving the cusp along the feed direction that the stepover tile names as separate. Near the bottom both reduce to w^2/(8R), so each scales with the square of its spacing. The finish is the LARGER of the two cusps; the two are balanced when the feed per tooth equals the stepover. Theoretical geometric cusps on a flat surface cut at the tool tip: a sloped surface changes the effective stepover and cutting radius, and tool deflection, runout, and servo behavior at direction changes add to the real finish. Neither converts to Ra, which is an averaged roughness rather than peak-to-valley geometry. A shop aid; the tool, the deflection, and the surface slope govern."},
  "ballnose-scallop-height": {"inputs":[{"key":"r_in","label":"Ballnose radius R (in = cutter dia / 2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"mode","label":"Mode","kind":"select","options":[{"value":"scallop-from-stepover","label":"Scallop from stepover"},{"value":"stepover-from-scallop","label":"Stepover from scallop"}],"default":"scallop-from-stepover","attrs":null},{"key":"s_in","label":"Stepover s (in, for scallop mode)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"h_in","label":"Target scallop h (in, for stepover mode)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: ballnose scallop height h = R - sqrt(R^2 - (s/2)^2) and its inverse s = 2 sqrt(R^2 - (R - h)^2), with the small-scallop h ~ s^2/(8R) approximation, per the CAM / mold-machining references, by name. Theoretical flat-surface cusp, not Ra. A shop aid; the real finish depends on the tool and slope."},
  "barstock-cutlist": {"inputs":[{"key":"stock_length_in","label":"Stock length (in)","kind":"number","options":null,"default":240,"attrs":{"step":"any","min":"0","value":"240"}},{"key":"piece_length_in","label":"Cut piece length (in)","kind":"number","options":null,"default":14.5,"attrs":{"step":"any","min":"0","value":"14.5"}},{"key":"kerf_in","label":"Saw kerf (in)","kind":"number","options":null,"default":0.125,"attrs":{"step":"any","min":"0","value":"0.125"}},{"key":"pieces_needed","label":"Pieces needed","kind":"number","options":null,"default":100,"attrs":{"step":"1","min":"0","value":"100"}}],"citation":"Citation: cut-list yield identity by name. pieces per stick = floor( (stock + kerf) / (piece + kerf) ); drop = stock - [pieces x piece + (pieces - 1) x kerf]; sticks = ceil(pieces needed / pieces per stick). N pieces take N-1 internal saw cuts."},
  "basal-area-prism": {"inputs":[{"key":"baf","label":"Basal-area factor (BAF, ft^2/ac)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"in_tree_count","label":"Trees counted 'in'","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0","value":"8"}},{"key":"dbh_in","label":"Tree DBH (in, for the expansion)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"14"}}],"citation":"Citation: prism (variable-radius / angle-gauge) point sampling, per USDA Forest Service mensuration and Bitterlich variable-radius plots, by name. basal_area_per_acre = BAF x in-tree count; per-tree basal area = 0.005454 x DBH^2; trees per acre = BAF / per-tree BA. The prism counts by angular size, not distance; the basal area per acre is independent of plot radius. A field estimate; a qualified cruise and the forester govern."},
  "battery-c-rate": {"inputs":[{"key":"nameplate_kwh","label":"Battery nameplate (kWh)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"40"}},{"key":"c_rate","label":"Continuous C-rate (0.5 = 0.5C)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","min":"0","value":"0.5"}},{"key":"dod","label":"Depth of discharge (0-1)","kind":"number","options":null,"default":0.9,"attrs":{"step":"any","min":"0","value":"0.9"}},{"key":"inverter_kw","label":"Inverter rating (kW, 0 = no limit)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"15"}}],"citation":"Citation: battery C-rate definition power = nameplate x C, discharge time = 1 / C, deliverable = min(C-rate power, inverter rating) (by name). Continuous, not surge; usable uses DoD. A nameplate power check, not a cell-level thermal model."},
  "battery-inverter-dc-conductor": {"inputs":[{"key":"inverter_power_w","label":"Inverter continuous power (W)","kind":"number","options":null,"default":4000,"attrs":{"step":"any","min":"0","value":"4000"}},{"key":"battery_voltage_v","label":"Battery bank voltage (V)","kind":"number","options":null,"default":48,"attrs":{"step":"any","min":"0","value":"48"}},{"key":"efficiency_pct","label":"Inverter efficiency (%)","kind":"number","options":null,"default":90,"attrs":{"step":"any","min":"0","value":"90"}}],"citation":"Citation: battery-to-inverter DC conductor and OCPD by name (NEC 690.8(B) / 706 / 240.4). I_dc = P_ac / (V_dc x efficiency); conductor ampacity and OCPD at 125% of I_dc, OCPD to the next standard size (240.6). Use a listed DC-rated (Class T) fuse; the datasheets and NEC govern."},
  "battery-peak-shaving": {"inputs":[{"key":"nameplate_kwh","label":"Battery nameplate (kWh)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"dod","label":"Depth of discharge (0-1)","kind":"number","options":null,"default":0.9,"attrs":{"step":"any","min":"0","value":"0.9"}},{"key":"event_duration_h","label":"Peak-event duration (h)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"3"}},{"key":"target_shave_kw","label":"Target demand reduction (kW)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"40"}},{"key":"demand_per_kw_mo","label":"Demand charge ($/kW-month)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"18"}}],"citation":"Citation: demand-charge peak-shaving method sustainable shave = usable / duration, actual = min(target, sustainable), savings = actual x $/kW-month x 12 (by name). The shave is energy-limited when the peak outlasts the usable energy. A demand-savings estimate, not a metered bill."},
  "battery-runtime": {"inputs":[{"key":"amp_hours","label":"Battery capacity (Ah)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"system_V","label":"System voltage (V)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"dod_percent","label":"Depth of discharge (%)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","max":"100","value":"100"}},{"key":"load_W","label":"Load (W)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"peukert_k","label":"Peukert exponent k (1 if unknown)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"1","value":"1"}},{"key":"inverter_efficiency_pct","label":"Inverter efficiency (%, 100 for a DC load)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","max":"100","value":"100"}}],"citation":"Citation: Runtime = (Ah * V * DoD * inverter_efficiency) / load_W. The inverter efficiency (default 100%, i.e. a DC load) accounts for the conversion loss when the load runs on AC through an inverter -- enter about 90% for that case. Peukert form t = C / I^k (C in Ah, I in A), reducing to C / I when k = 1 (battery technical bulletins)."},
  "battery-series-parallel": {"inputs":[{"key":"target_bus_v","label":"Target bus voltage (V)","kind":"number","options":null,"default":48,"attrs":{"step":"any","min":"0","value":"48"}},{"key":"module_v","label":"Module nominal voltage (V)","kind":"number","options":null,"default":12.8,"attrs":{"step":"any","min":"0","value":"12.8"}},{"key":"module_ah","label":"Module capacity (Ah)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"parallel_strings","label":"Parallel strings","kind":"number","options":null,"default":2,"attrs":{"step":"1","min":"1","value":"2"}},{"key":"depth_of_discharge","label":"Depth of discharge (0-1)","kind":"number","options":null,"default":0.8,"attrs":{"step":"any","min":"0","value":"0.8"}}],"citation":"Citation: battery bank series/parallel configuration, by name. series = round(target bus V / module V); bus = series x module V; total Ah = parallel x module Ah; usable kWh = series x parallel x V x Ah x DoD / 1000. LFP ~12.8 V/80% DoD, flooded lead-acid ~12.0 V/50%. The battery/BMS series-parallel limits, the inverter voltage window, and NEC 706 govern."},
  "battery-tou-arbitrage": {"inputs":[{"key":"nameplate_kwh","label":"Battery nameplate (kWh)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"13.5"}},{"key":"dod","label":"Depth of discharge (0-1)","kind":"number","options":null,"default":0.9,"attrs":{"step":"any","min":"0","value":"0.9"}},{"key":"rte","label":"Round-trip efficiency (0-1)","kind":"number","options":null,"default":0.86,"attrs":{"step":"any","min":"0","value":"0.9"}},{"key":"peak_price","label":"On-peak price ($/kWh)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.45"}},{"key":"offpeak_price","label":"Off-peak price ($/kWh)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.15"}},{"key":"cycles_per_year","label":"Cycles per year","kind":"number","options":null,"default":365,"attrs":{"step":"any","min":"0","value":"365"}}],"citation":"Citation: energy-arbitrage value daily = usable x peak - (usable / RTE) x offpeak, break-even when peak > offpeak / RTE, and the NREL battery round-trip / degradation framing (by name). RTE is AC-to-AC; DoD is the warranty-usable fraction. A gross spread-value aid, not a financed payback."},
  "beam-clamp-side-pull": {"inputs":[{"key":"leg_tension_lb","label":"Leg tension (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"leg_angle_deg","label":"Leg angle above horizontal (deg, 90 = vertical)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"90"}},{"key":"vertical_wll_lb","label":"Clamp vertical WLL (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"side_pull_lb","label":"Side-pull rating (lb, 0 = not rated)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: Static force resolution; ASME B30.20 / beam-clamp manufacturer practice (the WLL is a vertical rating and side pull is prohibited unless the manufacturer rates it), by name. V = T sin(angle); H = T cos(angle); utilizations V / V_WLL and H / H_allow. Most beam clamps carry no side-pull rating at all - when a horizontal component lands on an unrated clamp, re-rig (spot the attachment over the load, or use a trolley or spanner beam). The hardware ratings and a qualified rigger govern."},
  "beam-loading": {"inputs":[{"key":"load_type","label":"Load type","kind":"select","options":[{"value":"uniform","label":"Uniform"},{"value":"point_center","label":"Centered point"}],"default":null,"attrs":null},{"key":"load_value","label":"Load value (lb/ft for uniform; lb for point)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"length_ft","label":"Span length (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"E_psi","label":"Modulus of elasticity E (psi)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"1600000"}},{"key":"b_in","label":"Section width b (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"1.5"}},{"key":"d_in","label":"Section depth d (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"9.25"}}],"citation":"Citation: M = w*L^2/8 (uniform), M = P*L/4 (centered point); deflection 5wL^4/(384*E*I) and PL^3/(48*E*I)."},
  "bearing-l10-life": {"inputs":[{"key":"bearing_type","label":"Bearing type","kind":"select","options":[{"value":"ball","label":"Ball (p = 3)"},{"value":"roller","label":"Roller (p = 10/3)"}],"default":"ball","attrs":null}],"citation":"Citation: ISO 281 / ABMA 9 & 11 basic rating life: L10 = (C/P)^p x 10^6 rev, L10h = L10 / (60 x rpm), p = 3 ball / 10/3 roller. Life scales as the cube (ball) of the load ratio. Basic L10 assumes clean, well-lubricated operation; L10 is the life at which 10% have failed, not the average. A planning estimate; the mounting, lubrication, and application govern."},
  "bearing-max-load": {"inputs":[{"key":"bearing_type","label":"Bearing type","kind":"select","options":[{"value":"ball","label":"Ball (p = 3)"},{"value":"roller","label":"Roller (p = 10/3)"}],"default":"ball","attrs":null}],"citation":"Citation: ISO 281 / ABMA 9 & 11 basic rating life solved for the load: P_max = C x (10^6 / L10_rev)^(1/p) with L10_rev = target_hr x 60 x rpm, p = 3 ball / 10/3 roller. Life scales as the cube (ball) of the load ratio. Basic L10 assumes clean, well-lubricated operation; L10 is the life at which 10% have failed, not the average. A planning estimate; the mounting, lubrication, and application govern."},
  "beer-lambert": {"inputs":[{"key":"absorbance","label":"Absorbance (AU)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"path_length_cm","label":"Path length (cm)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0"}},{"key":"epsilon","label":"Molar extinction coefficient (M^-1 cm^-1)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Beer-Lambert law A = epsilon * c * L. First principles."},
  "bell-curve-zscore": {"inputs":[{"key":"raw_score","label":"Raw score","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"mean","label":"Sample mean","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"sd","label":"Sample standard deviation","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Standard normal CDF via Abramowitz + Stegun, Handbook of Mathematical Functions, formula 26.2.17 (1965; National Bureau of Standards Applied Mathematics Series 55). Public domain. Curve bands per the empirical 68-95-99.7 rule applied to grading: a common pre-CCSS convention. Teacher governs whether a normative curve is appropriate (CCSS-aligned standards-based grading does NOT curve)."},
  "belt-pulley": {"inputs":[{"key":"drive_dia_in","label":"Drive pulley diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"driven_dia_in","label":"Driven pulley diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"center_distance_in","label":"Center distance (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"motor_rpm","label":"Motor RPM","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Public V-belt length L = 2C + (pi/2)(D + d) + (D - d)^2 / (4C). Driven RPM via diameter ratio. Belt speed = pi * D / 12 * RPM."},
  "bend-springback": {"inputs":[{"key":"tool_radius_in","label":"Tool (inside) bend radius (in)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1.0"}},{"key":"thickness_in","label":"Material thickness (in)","kind":"number","options":null,"default":0.1,"attrs":{"step":"any","min":"0","value":"0.1"}},{"key":"yield_strength_psi","label":"Yield strength (psi)","kind":"number","options":null,"default":50000,"attrs":{"step":"any","min":"0","value":"50000"}},{"key":"modulus_psi","label":"Elastic modulus (psi, ~29e6 steel)","kind":"number","options":null,"default":29000000,"attrs":{"step":"any","min":"0","value":"29000000"}}],"citation":"Citation: sheet-metal bend springback (Machinery's Handbook), by name. Ks = Ri/Rf = 4 x^3 - 3 x + 1, x = Ri x yield / (E x thickness); released radius Rf = Ri/Ks (larger than the tool radius). E ~ 29-30e6 psi steel, ~10e6 aluminum. Air-bend basis; coining nearly eliminates springback. The material cert, tooling method, and a test bend govern the overbend."},
  "bernoulli-head": {"inputs":[{"key":"P_psi","label":"Gauge pressure (psi)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"V_fps","label":"Velocity (ft/s)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"z_ft","label":"Elevation (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"gamma","label":"Fluid specific weight (lb/ft^3, 62.4 water)","kind":"number","options":null,"default":62.4,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Bernoulli total head H = P/gamma + V^2/(2g) + z (feet of fluid), first-principles energy equation; conserved along a streamline with no loss (H1 = H2 + h_loss). The engineer of record governs the system analysis."},
  "bifacial-pv-gain": {"inputs":[{"key":"front_poa_wm2","label":"Front plane-of-array irradiance (W/m^2)","kind":"number","options":null,"default":1000,"attrs":{"step":"any","min":"0","value":"1000"}},{"key":"rear_poa_wm2","label":"Rear plane-of-array irradiance (W/m^2)","kind":"number","options":null,"default":150,"attrs":{"step":"any","min":"0","value":"150"}},{"key":"bifaciality","label":"Bifaciality coefficient (0-1, from datasheet)","kind":"number","options":null,"default":0.75,"attrs":{"step":"any","min":"0","max":"1","value":"0.75"}},{"key":"front_power_w","label":"Front-side nameplate power (W)","kind":"number","options":null,"default":400,"attrs":{"step":"any","min":"0","value":"400"}}],"citation":"Citation: bifacial PV rear-side gain, by name. gain = bifaciality x (rear irradiance / front irradiance); effective power = front x (1 + gain). Bifaciality (phi) ~0.65-0.90 from the datasheet; rear irradiance climbs with ground albedo, mounting height, and row spacing. The datasheet bifaciality, the site albedo, and a bifacial ray-trace govern the real yield."},
  "block-redirect-load": {"inputs":[{"key":"line_tension_lb","label":"Line tension through the block (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"direction_chg_deg","label":"Direction change (deg, 180 = doubled back)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: ASME B30.26 and standard rigging statics by name. resultant = 2 x line tension x sin(direction change / 2); a 180-degree turn doubles the line tension on the anchor. Estimate - size for the resultant."},
  "block-redirect-max-angle": {"inputs":[{"key":"line_tension_lb","label":"Line tension through the block (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"block_wll_lb","label":"Block / anchor rated WLL (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: ASME B30.26 and standard rigging statics by name. resultant = 2 x line tension x sin(direction change / 2), solved for the angle: max direction change = 2 x asin( WLL / (2 x line tension) ); the resultant peaks at 2T at a 180-degree turn. Estimate - size for the resultant."},
  "board-footage": {"inputs":[{"key":"thickness_in","label":"Thickness (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"width_in","label":"Width (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"length_ft","label":"Length (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"count","label":"Count","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1","value":"1"}}],"citation":"Citation: 1 board foot = 1 in x 12 in x 12 in. BF = (T_in * W_in * L_ft) / 12."},
  "boiler-horsepower": {"inputs":[{"key":"output_btuhr","label":"Boiler gross output (Btu/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: ABMA / ASME boiler-horsepower definitions - 1 BHP = 33,475 Btu/hr gross output = 34.5 lb/hr of steam evaporated 'from and at' 212 F = 139 sq ft of equivalent direct radiation (EDR). BHP = output / 33,475; steam = BHP x 34.5; EDR = BHP x 139. The 'from and at 212 F' basis assumes feedwater at 212 F and steam at 0 psig; a real plant with cooler feedwater and higher pressure evaporates less per BHP, so apply the boiler maker's factor of evaporation for the actual conditions."},
  "boiler-pipe-sizing": {"inputs":[{"key":"material","label":"Pipe material","kind":"select","options":[{"value":"copper","label":"Copper Type L (4 ft/s)"},{"value":"steel","label":"Steel Schedule 40 (6 ft/s)"},{"value":"pex","label":"PEX SDR-9 (3 ft/s)"}],"default":"copper","attrs":null}],"citation":"Citation: GPM = Q / (500 x delta-T) (hydronic water energy balance); velocity = GPM / (2.448 x d^2); the smallest standard size at or below the velocity ceiling is recommended; head loss per Hazen-Williams (public domain, 1905). Per ASHRAE Systems and Equipment 2020 Ch. 13 (hydronic heating) with Bell & Gossett / Taco velocity limits. Free at ashrae.org for the TOC."},
  "bolt-proof-load": {"inputs":[{"key":"grade","label":"SAE grade","kind":"select","options":[{"value":"2","label":"Grade 2 (55 ksi proof)"},{"value":"5","label":"Grade 5 / A325 (85 ksi proof)"},{"value":"8","label":"Grade 8 / A490 (120 ksi proof)"}],"default":"5","attrs":null}],"citation":"Citation: SAE J429 inch-series bolt strength (ASME B1.1 tensile stress area): At = 0.7854 x (D - 0.9743/n)^2; proof / yield / tensile load = At x the grade strength (Grade 2: 55/57/74 ksi; Grade 5 / A325: 85/92/120; Grade 8 / A490: 120/130/150); recommended clamp = 75% of proof. The grade is read from the head markings. A design aid; the joint design and torque method govern."},
  "bonding-jumper": {"inputs":[{"key":"mode","label":"Jumper type","kind":"select","options":[{"value":"supply-side","label":"Supply-side (main / system)"},{"value":"equipment","label":"Equipment (load-side)"}],"default":"supply-side","attrs":null},{"key":"material","label":"Material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":"copper","attrs":null},{"key":"service_kcmil","label":"Largest ungrounded service conductor (kcmil)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"ocpd_A","label":"Overcurrent device (A, equipment mode)","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}},{"key":"parallel_sets","label":"Parallel raceways (equipment mode)","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1","value":"1"}}],"citation":"Citation: NEC 250.28(D) / 250.102(C)(D) bonding-jumper sizing - supply-side from Table 250.66 (with the 12.5% rule above 1100 kcmil copper / 1750 aluminum), equipment from Table 250.122 (by section; only the threshold-to-size mapping is encoded). The AHJ-adopted edition governs. Free read-only at nfpa.org/freeaccess."},
  "boring-bar-deflection": {"inputs":[{"key":"d_in","label":"Bar / tool diameter d (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"l_in","label":"Overhang length L (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"f_lb","label":"Radial cutting force F (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"e_psi","label":"Modulus E (psi: 30e6 steel, ~90e6 carbide)","kind":"number","options":null,"default":30000000,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: cantilever tip deflection delta = F L^3/(3 E I), I = pi d^4/64, E = 30e6 psi steel / ~90e6 carbide, and the practical L/d overhang limits, by name. Static solid-round model, not a stability-lobe analysis. A shop aid; the tool and setup govern."},
  "boring-bar-max-overhang": {"inputs":[{"key":"d_in","label":"Bar / tool diameter d (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"f_lb","label":"Radial cutting force F (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"allowable_deflection_in","label":"Allowable tip deflection (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"e_psi","label":"Modulus E (psi: 30e6 steel, ~90e6 carbide)","kind":"number","options":null,"default":30000000,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: cantilever deflection solved for overhang: L_max = (3 E I delta / F)^(1/3), I = pi d^4/64, E = 30e6 psi steel / ~90e6 carbide, with the practical L/d chatter limits, by name. Static solid-round model, not a stability-lobe analysis. A shop aid; the tool and setup govern."},
  "bound-water": {"inputs":[{"key":"material_volume_ft3","label":"Material volume (ft^3, area x thickness)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"dry_density_lb_ft3","label":"Oven-dry density (lb/ft^3; softwood ~32, gypsum ~40)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"32"}},{"key":"mc_current_pct","label":"Current moisture content (percent)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"40"}},{"key":"mc_goal_pct","label":"Goal moisture content (percent)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"12"}}],"citation":"Citation: Gravimetric water-mass relation (ANSI/IICRC S500), by name. Moisture content is dry-weight basis (consistent with wood-emc). Dry density and material moisture vary by species and product; meter readings and the restorer's judgment govern. This is a planning estimate, not a gravimetric measurement."},
  "braking-distance": {"inputs":[{"key":"speed_mph","label":"Speed (mph)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"friction_coefficient","label":"Road friction coefficient","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"1"}},{"key":"grade_percent","label":"Grade (%, downhill negative)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"0"}},{"key":"reaction_time_s","label":"Reaction time (s)","kind":"number","options":null,"default":1.5,"attrs":{"step":"any","min":"0","value":"1.5"}}],"citation":"Citation: d = v^2 / (30 * (mu +/- grade%/100)). Reaction distance = v * 1.467 * t."},
  "branch-circuit-wire-footage": {"inputs":[{"key":"circuits","label":"Number of branch circuits","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"avg_homerun_ft","label":"Average home-run length (ft)","kind":"number","options":null,"default":45,"attrs":{"step":"any","min":"0","value":"45"}},{"key":"makeup_ft","label":"Box makeup / slack per circuit (ft)","kind":"number","options":null,"default":15,"attrs":{"step":"any","min":"0","value":"15"}},{"key":"conductors_per_circuit","label":"Conductors per circuit (1 for cable)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","value":"3"}},{"key":"roll_ft","label":"Roll / spool length (ft)","kind":"number","options":null,"default":1000,"attrs":{"step":"any","min":"0","value":"1000"}}],"citation":"Citation: footage takeoff identity by name. total = circuits x (home run + makeup) x conductors; rolls = ceil(total / roll length). Each conductor is counted in conduit; set conductors to 1 for cable (NM / romex). Wire is bought per color."},
  "branch-reinforcement": {"inputs":[{"key":"run_od_in","label":"Run (header) OD (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"run_wall_in","label":"Run nominal wall (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"run_treq_in","label":"Run required wall t_rh (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"branch_od_in","label":"Branch OD (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"branch_wall_in","label":"Branch nominal wall (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"branch_treq_in","label":"Branch required wall t_rb (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"beta_deg","label":"Branch angle to the run (deg, 90 = perpendicular)","kind":"number","options":null,"default":90,"attrs":{"step":"any","min":"0","max":"90","value":"90"}}],"citation":"Citation: Branch-opening area replacement - A_required = t_rh x d1 x (2 - sin beta) made up by the excess wall in the run (A1) and the branch (A2) within the reinforcement zone, per ASME B31.1 para 104.3.1 (and B31.3 304.3 for process), by name. The required wall thicknesses come from the pressure design (see pipe-pressure-rating), the reinforcement zone limits and the weld/pad area follow the code's figure, and the engineer of record and the AHJ govern. This is the area balance, not a stamped branch-connection design."},
  "branch-saddle-cutback": {"inputs":[{"key":"branch_od_in","label":"Branch pipe OD (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"run_od_in","label":"Run pipe OD (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"stations","label":"Marks per quarter (default 6 = every 15 deg)","kind":"number","options":null,"default":6,"attrs":{"step":"1","min":"1","max":"24","value":"6"}}],"citation":"Citation: Branch saddle contour - cutback(theta) = R - sqrt(R^2 - (r sin theta)^2) around the branch end, theta measured from the line of the run axis (heel/toe = 0, sides = 90, where the cutback is maximum) - the cylinder-intersection geometry per Pipe Fabrication Institute layout practice, by name. This is the geometric contour for a 90-degree, same-centerline branch; the weld bevel, gap, and root face are added per the WPS, and a reducing or angled branch shifts the contour. A fit-up aid, not a weld procedure."},
  "breaker-sizing": {"inputs":[{"key":"load_A","label":"Load current (A)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"load_W","label":"Load (W, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"voltage_V","label":"Voltage (V, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"power_factor","label":"Power factor (0-1)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","max":"1","value":"1"}},{"key":"phase","label":"Phase","kind":"select","options":[{"value":"single","label":"Single"},{"value":"three","label":"Three"}],"default":"single","attrs":null}],"citation":"Citation: per NEC 2023 §215.3, §230.79, §408.36. Continuous-load 125% rule per §210.20(A). Standard breaker sizes per §240.6. AHJ governs. Free at nfpa.org/freeaccess."},
  "breakeven": {"inputs":[{"key":"fixed_costs","label":"Fixed costs (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"variable_cost_per_unit","label":"Variable cost per unit (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"sale_price_per_unit","label":"Sale price per unit (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"target_units","label":"Target sales volume (units, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: contribution-margin algebra. First principles."},
  "bridle-leg-tension": {"inputs":[{"key":"apex_load_lb","label":"Apex load (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"run1_ft","label":"Leg 1 horizontal run (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"rise1_ft","label":"Leg 1 vertical rise (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"run2_ft","label":"Leg 2 horizontal run (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"rise2_ft","label":"Leg 2 vertical rise (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Entertainment rigging bridle geometry (static two-dimensional resolution), by name. L = sqrt(run^2 + rise^2); a = run/L, b = rise/L; den = a2 b1 + a1 b2; T1 = W a2/den, T2 = W a1/den; H = T1 a1 = T2 a2. An off-center apex makes the legs carry unequal tension; a shallow bridle multiplies tension above the load and drives a large horizontal pull into the beams. The hardware ratings and a qualified rigger govern."},
  "brine-cure": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"brine","label":"Brine by volume"},{"value":"equilibrium","label":"Equilibrium cure by weight"}],"default":"brine","attrs":null}],"citation":"Citation: First-principles mass-fraction chemistry. Prague Powder #1 is 6.25% sodium nitrite; finished-product ingoing nitrite is limited per USDA FSIS regulation (9 CFR 424.21/424.22, by name) - the user confirms the current FSIS limit. Free at fsis.usda.gov and ecfr.gov."},
  "buck-boost-sizing": {"inputs":[{"key":"supply_v","label":"Supply (line) voltage (V)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"desired_v","label":"Desired (load) voltage (V)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"load_a","label":"Load current (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Single-phase buck-boost (autotransformer) sizing - the unit is rated for the boost/buck voltage (desired minus supply) times the load current, a fraction of the full load kVA. NEC 2023 Article 450 (transformers); the autotransformer connection, taps, and overcurrent protection are the manufacturer's and the AHJ's. Free at nfpa.org/freeaccess."},
  "bunker-silo-capacity": {"inputs":[{"key":"bottom_width_ft","label":"Bottom width (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"top_width_ft","label":"Top width (ft; = bottom for vertical walls)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"average_depth_ft","label":"Average settled depth (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"8"}},{"key":"length_ft","label":"Length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"density_lb_ft3","label":"As-fed density (lb/ft^3)","kind":"number","options":null,"default":44,"attrs":{"step":"any","min":"0","value":"44"}}],"citation":"Citation: horizontal (bunker/trench) silo capacity - trapezoidal cross-section (bottom + top)/2 x average depth, times length, times as-fed density, over 2000 lb/ton. Per NRCS / MWPS forage storage sizing, by name. As-fed silage density is user-entered (corn silage ~40-50 lb/ft^3, varies with dry matter and packing). Use the settled depth; a core sample or weigh-back governs the real inventory."},
  "cable-reel-capacity": {"inputs":[{"key":"flange_dia_in","label":"Reel flange diameter (in)","kind":"number","options":null,"default":30,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"drum_dia_in","label":"Drum / hub diameter (in)","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"traverse_width_in","label":"Inside width between flanges (in)","kind":"number","options":null,"default":18,"attrs":{"step":"any","min":"0","value":"18"}},{"key":"cable_od_in","label":"Cable outside diameter (in)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1"}},{"key":"fill_factor","label":"Winding fill factor","kind":"number","options":null,"default":0.9,"attrs":{"step":"any","min":"0","value":"0.9"}}],"citation":"Citation: reel-capacity identity by name. length (ft) = fill x pi x (flange^2 - drum^2) x traverse / (48 x cable_OD^2), lengths in inches. The fill factor (~0.85-0.9) accounts for imperfect winding."},
  "cable-support-jhook": {"inputs":[{"key":"run_ft","label":"Pathway length (ft)","kind":"number","options":null,"default":400,"attrs":{"step":"any","min":"0","value":"400"}},{"key":"spacing_ft","label":"Hook spacing (ft)","kind":"number","options":null,"default":4,"attrs":{"step":"any","min":"0","value":"4"}},{"key":"num_cables","label":"Cables in the bundle","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}},{"key":"cable_lb_per_ft","label":"Weight per cable (lb/ft)","kind":"number","options":null,"default":0.035,"attrs":{"step":"any","min":"0","value":"0.035"}},{"key":"hook_wll_lb","label":"Hook safe working load (lb, 0 = skip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: support identity by name. hooks = ceil(run / spacing); load per hook = cables x weight per foot x spacing. TIA-569 non-continuous support runs about 4 to 5 ft on center."},
  "cable-tray-fill": {"inputs":[{"key":"tray_type","label":"Tray type","kind":"select","options":[{"value":"ladder","label":"Ladder / ventilated trough"},{"value":"solid-bottom","label":"Solid bottom"}],"default":"ladder","attrs":null},{"key":"tray_width_in","label":"Tray inside width (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Cable-tray fill per NEC Article 392.22 (the sum-of-diameters rule for cables 4/0 and larger and the cross-sectional-area allowance for smaller cables), by name. The AHJ-adopted NEC edition governs; ampacity derating for tray fill (392.80) is a separate check."},
  "camera-lens-fov": {"inputs":[{"key":"sensor_width_mm","label":"Sensor width (mm, e.g. 1/2.7in = 5.37)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"focal_length_mm","label":"Focal length (mm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"distance_ft","label":"Target distance (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"h_pixels","label":"Horizontal resolution (pixels)","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}}],"citation":"Citation: Camera FOV and pixel density (IEC 62676-4 DORI): FOV = 2 atan(sensor/(2 focal)); scene = distance x sensor/focal; ppf = pixels/scene. DORI bands Detect 8 / Observe 19 / Recognize 38 / Identify 76 ppf. A design aid; verify against the lens chart and a live view."},
  "camera-max-distance-for-ppf": {"inputs":[{"key":"sensor_width_mm","label":"Sensor width (mm, e.g. 1/2.7in = 5.37)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"focal_length_mm","label":"Focal length (mm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"h_pixels","label":"Horizontal resolution (pixels)","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}},{"key":"target_ppf","label":"Target pixel density (ppf, 76 = Identify)","kind":"number","options":null,"default":76,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Camera pixel density (IEC 62676-4 DORI): ppf = px x focal / (distance x sensor), solved for the distance: distance_max = px x focal / (target ppf x sensor). DORI bands Detect 8 / Observe 19 / Recognize 38 / Identify 76 ppf. A design aid; verify against the lens chart and a live view."},
  "cap-rate-dscr": {"inputs":[{"key":"noi_annual","label":"Annual NOI ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"property_value","label":"Property value or purchase price ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"annual_debt_service","label":"Annual debt service ($, optional for DSCR)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"loan_amount","label":"Loan amount ($, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"loan_rate_pct","label":"Loan rate (% APR, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"amort_years","label":"Amortization (years, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"operating_expenses_annual","label":"Operating expenses ($/yr, for break-even)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"potential_gross_income","label":"Potential gross income ($/yr, for break-even)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Cap rate = NOI / property_value; DSCR = NOI / annual_debt_service. Standard CRE underwriting ratios; bands are common-practice and may differ by lender / market / asset class. NOI is gross income minus operating expenses (excluding debt service, depreciation, income tax). Appraiser governs final value; lender governs underwriting."},
  "carpet-restore-replace": {"inputs":[{"key":"water_category","label":"Water category","kind":"select","options":[{"value":"cat1","label":"Category 1 (clean)"},{"value":"cat2","label":"Category 2 (gray)"},{"value":"cat3","label":"Category 3 (black)"}],"default":"cat1","attrs":null},{"key":"component","label":"Component","kind":"select","options":[{"value":"carpet","label":"Carpet"},{"value":"cushion","label":"Cushion / pad"}],"default":"carpet","attrs":null}],"citation":"Citation: Carpet and cushion restore-vs-replace mapping (ANSI/IICRC S500), by name. The decision is a professional determination case by case (age, condition, contamination, customer agreement, and the AHJ all bear on it). Delaminated carpet is replaced; saturated cushion in any category is typically removed; Category 3 porous flooring is generally removed and disposed."},
  "cash-conversion-cycle": {"inputs":[{"key":"dso","label":"DSO (days)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"dio","label":"DIO (days)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"dpo","label":"DPO (days)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: CCC = DIO + DSO - DPO. Standard working-capital identity."},
  "cash-on-cash": {"inputs":[{"key":"cash_invested","label":"Cash invested ($, down + closing + rehab)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"annual_pretax_cashflow","label":"Annual pre-tax cash flow ($, can be negative)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}}],"citation":"Citation: cash-on-cash = annual_pretax_cashflow / cash_invested. Cash invested includes down payment + closing costs + immediate rehab; annual cash flow is NOI minus annual debt service minus capex reserve. Common-practice bands; not an agency-defined ratio. Lender / partner / asset class governs target range."},
  "category-deterioration": {"inputs":[{"key":"origin_category","label":"Origin category","kind":"select","options":[{"value":"cat1","label":"Category 1 (clean)"},{"value":"cat2","label":"Category 2 (gray)"},{"value":"cat3","label":"Category 3 (black)"}],"default":"cat1","attrs":null},{"key":"elapsed_hours","label":"Elapsed wet time (hours)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"72"}}],"citation":"Citation: Category-at-time-of-remediation principle (ANSI/IICRC S500), by name. Category is a professional determination made at the time of restoration, not by the source alone; elevated temperature and contact with contaminated materials accelerate the shift. The amplification window commonly cited is 48-72 hours under favorable conditions. When in doubt, the higher category is assumed."},
  "cattle-stocking-rate": {"inputs":[{"key":"animal_class","label":"Animal class","kind":"select","options":[{"value":"cow_calf","label":"Cow-calf pair (1.0 AU)"},{"value":"yearling","label":"Yearling (0.7 AU)"},{"value":"sheep","label":"Sheep (0.2 AU)"},{"value":"horse","label":"Horse (1.25 AU)"}],"default":"cow_calf","attrs":null}],"citation":"Citation: Per USDA NRCS National Range and Pasture Handbook Ch. 6 (stocking rate). available forage = production x area x utilization; AUMs = available / 780 lb (26 lb dry matter/day x 30 days per animal unit). Drought and climate adjustments are essential. Free at nrcs.usda.gov for the handbook."},
  "cavity-drying-system": {"inputs":[{"key":"affected_wall_ft","label":"Affected wall length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"32"}},{"key":"stud_spacing_in","label":"Stud spacing (in, on-center)","kind":"number","options":null,"default":16,"attrs":{"step":"any","min":"0","value":"16"}},{"key":"ports_per_bay","label":"Injection ports per stud bay","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1"}},{"key":"ports_per_system","label":"Ports a single air system serves","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0","value":"12"}}],"citation":"Citation: Bays-from-length geometry (ANSI/IICRC S500), by name. Port count, airflow per port, and ports per system are equipment-manufacturer specific; the bundled defaults are typical, not prescriptive. Respect cavity air-pressure direction and contamination - do not push Category 2/3 cavity air into clean spaces. The cavity-drying decision versus a flood cut follows S500."},
  "cctv-retention-days": {"inputs":[{"key":"disk_capacity_gb","label":"Usable disk capacity (GB)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"camera_count","label":"Camera count","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1"}},{"key":"bitrate_mbps","label":"Per-camera bitrate (Mbps)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"recording_mode","label":"Recording mode","kind":"select","options":[{"value":"continuous","label":"Continuous 24 h"},{"value":"motion","label":"Motion duty-cycle"}],"default":"continuous","attrs":null},{"key":"motion_duty_percent","label":"Motion duty-cycle (%)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","max":"100","value":"50"}}],"citation":"Citation: IP-video retention from available disk, camera count, bitrate, and recording hours (days = disk_GB / (cameras x bitrate x 0.45 x hours); 1 Mbps for 24 h is about 10.8 GB/day), per the standard NVR/VMS sizing practice (first-principles bitrate accounting); the H.264/H.265 bitrate estimates are scene- and vendor-specific and user-supplied. The VMS calculator and the installed cameras govern."},
  "cctv-storage": {"inputs":[{"key":"camera_count","label":"Camera count","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1"}},{"key":"bitrate_mbps","label":"Per-camera bitrate (Mbps)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"recording_mode","label":"Recording mode","kind":"select","options":[{"value":"continuous","label":"Continuous 24 h"},{"value":"motion","label":"Motion duty-cycle"}],"default":"continuous","attrs":null},{"key":"motion_duty_percent","label":"Motion duty-cycle (%)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","max":"100","value":"50"}},{"key":"retention_days","label":"Retention (days)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: IP-video storage and bandwidth from bitrate, recording hours, and retention (1 Mbps for 24 h is about 10.8 GB/day), per the standard NVR/VMS sizing practice (first-principles bitrate accounting); the H.264/H.265 bitrate estimates are scene- and vendor-specific and user-supplied. The VMS calculator and the installed cameras govern."},
  "ceiling-speaker-coverage": {"inputs":[{"key":"ceiling_ft","label":"Ceiling height (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"ear_ft","label":"Listener ear height (ft, seated ~4)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"coverage_deg","label":"Speaker coverage angle (deg, ~90)","kind":"number","options":null,"default":90,"attrs":{"step":"any","min":"0"}},{"key":"room_area_ft2","label":"Room area (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"layout","label":"Layout","kind":"select","options":[{"value":"edge_to_edge","label":"Edge-to-edge (minimum count)"},{"value":"minimum_overlap","label":"Minimum overlap (even coverage)"}],"default":"edge_to_edge","attrs":null}],"citation":"Citation: Ceiling speaker coverage: diameter = 2 x (ceiling - ear) x tan(angle/2); spacing = diameter (edge-to-edge) or 0.7 x diameter (minimum overlap, -6 dB); count = ceil(area / spacing^2). A layout aid; verify with the speaker's coverage angle at the design frequency and the target SPL."},
  "ceiling-speaker-coverage-angle": {"inputs":[{"key":"ceiling_ft","label":"Ceiling height (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"ear_ft","label":"Listener ear height (ft, seated ~4)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"target_diameter_ft","label":"Target coverage diameter / spacing (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Ceiling speaker coverage: diameter = 2 x (ceiling - ear) x tan(angle/2), solved for the angle: coverage angle = 2 x atan( diameter / (2 x (ceiling - ear)) ). A layout aid; verify with the speaker's coverage angle at the design frequency and the target SPL."},
  "ceiling-water-load": {"inputs":[{"key":"pooled_area_ft2","label":"Bulging / saturated ceiling area (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"avg_depth_in","label":"Average trapped water depth (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"threshold_psf","label":"Drain-first screen load (psf, editable)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}}],"citation":"Citation: Hydrostatic load load_psf = (depth_in/12) * 62.4, with water at ~62.4 lb/ft^3 and 7.48052 gal/ft^3. IICRC S500 safety practice, by name. The threshold is an editable drain-first screen, NOT a code capacity - the fastening, span, and a structural engineer govern."},
  "center-of-gravity-2point": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"two-scale-weigh","label":"Two-scale weigh"},{"value":"pick-point-from-cg","label":"Reading from known CG"}],"default":"two-scale-weigh","attrs":null},{"key":"reading_1_lb","label":"Reading at point 1 (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"reading_2_lb","label":"Reading at point 2 (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"span_ft","label":"Distance between points (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"total_weight_lb","label":"Total weight (lb, inverse)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"cg_from_1_ft","label":"CG from point 1 (ft, inverse)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}}],"citation":"Citation: Center of gravity from a two-point weigh by moment balance (x = S2*L / (S1+S2)), per the standard rigging practice in the ASME B30.9 / ITI rigging references, by name; first-principles statics. A field aid - the lift plan, the rated rigging, and the qualified rigger / lift director govern."},
  "cfm-per-ton": {"inputs":[{"key":"tons","label":"Tons","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"climate","label":"Climate","kind":"select","options":[{"value":"standard","label":"Standard (400 CFM/ton)"},{"value":"humid","label":"Humid (350 CFM/ton)"},{"value":"dry","label":"Dry (450 CFM/ton)"}],"default":"standard","attrs":null}],"citation":"Citation: Standard 400 CFM per ton with 350 for humid climates and 450 for dry climates."},
  "cg-load-share": {"inputs":[{"key":"total_weight_lb","label":"Total load weight (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"span_in","label":"Span between pick points (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"cg_from_p1_in","label":"Distance from pick 1 to CG (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}}],"citation":"Citation: ASME B30.9 (Slings) and ITI rigging practice by name. load_p1 = W x (span - d1) / span; the pick nearest the CG carries more. Estimate - the head rigger and the load weight govern."},
  "chain-lever-hoist": {"inputs":[{"key":"load_lb","label":"Load (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"rated_wll_lb","label":"Hoist rated WLL (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"mech_adv","label":"Mechanical advantage","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"efficiency","label":"Drivetrain efficiency","kind":"number","options":null,"default":0.85,"attrs":{"step":"any","min":"0","value":"0.85"}},{"key":"lift_ft","label":"Lift distance (ft)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: ASME B30.16 (Overhead Hoists) and ASME B30.21 (Lever Hoists) by name. hand pull = load / (mechanical advantage x efficiency); hand-chain travel = lift x mechanical advantage. Estimate - the rated WLL is the ceiling."},
  "change-order-markup": {"inputs":[{"key":"direct_cost_usd","label":"Added direct cost (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"overhead_pct","label":"Overhead markup (%)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0"}},{"key":"profit_pct","label":"Profit markup (%)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0"}},{"key":"current_contract_usd","label":"Current contract total (USD, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Change-order pricing with overhead and profit (construction estimating practice / AIA G701): price = direct cost x (1 + overhead%) x (1 + profit%), the standard compounded markup (the additive direct x (1 + OH% + profit%) is slightly less). The contract's general conditions set the allowed markup and method. A pricing aid; the contract terms and owner approval govern."},
  "channel-froude-number": {"inputs":[{"key":"b_ft","label":"Channel width b (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"q_cfs","label":"Discharge Q (cfs)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"y_ft","label":"Flow depth y (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: open-channel Froude number Fr = V/sqrt(g D) (g = 32.2, D = y rectangular), the subcritical/critical/supercritical regimes, and the rectangular critical depth yc = (q^2/g)^(1/3), as compiled in Chow, by name. Rectangular section; normal depth and hydraulic jump are separate. A design aid; the engineer of record governs."},
  "channel-normal-depth": {"inputs":[{"key":"b_ft","label":"Channel width b (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"q_cfs","label":"Discharge Q (cfs)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"n","label":"Manning roughness n","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"s_slope","label":"Channel slope S (ft/ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Manning normal depth from Q = (1.486/n) A R^(2/3) S^(1/2) for a rectangular section (A = b y, R = A/(b + 2y)), solved by bisection, with the slope class from yc = (q^2/g)^(1/3), as compiled in Chow, by name. Prismatic rectangular channel, uniform flow; trapezoidal sections and backwater profiles are separate. A design aid; the engineer of record governs."},
  "char-depth-capacity": {"inputs":[{"key":"exposure_min","label":"Fire exposure (minutes)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"nominal_width_in","label":"Member width b (in, actual)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"5.5"}},{"key":"nominal_depth_in","label":"Member depth d (in, actual)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"9.5"}},{"key":"faces_across_width","label":"Charred faces across the width","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"0","value":"2"}},{"key":"faces_across_depth","label":"Charred faces across the depth","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1"}},{"key":"char_rate_in_hr","label":"Nominal char rate (in/hr)","kind":"number","options":null,"default":1.5,"attrs":{"step":"any","min":"0","value":"1.5"}},{"key":"zero_strength_in","label":"Zero-strength layer (in)","kind":"number","options":null,"default":0.2,"attrs":{"step":"any","min":"0","value":"0.2"}}],"citation":"Citation: AWC National Design Specification one-dimensional char model (about 1.5 in/hr nominal) plus a heat-degraded zero-strength layer, by name. Screens the residual BENDING section only; a structural engineer governs connections, splitting, char-line judgment, and the load path. This is a keep-or-replace screen, not a stamped calculation."},
  "check-dam-spacing": {"inputs":[{"key":"dam_height_ft","label":"Effective dam height, crest above channel (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"channel_slope_pct","label":"Channel longitudinal slope (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"reach_length_ft","label":"Channel reach to protect (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: crest-to-toe spacing identity by name. spacing = dam effective height / channel slope (the toe of each upper dam at the crest of the next); dams = ceil(reach / spacing). Small channels and swales only."},
  "chiller-tons": {"inputs":[{"key":"fluid","label":"Fluid","kind":"select","options":[{"value":"water","label":"Water (500)"},{"value":"glycol_30","label":"30% propylene glycol"},{"value":"glycol_50","label":"50% propylene glycol"}],"default":"water","attrs":null}],"citation":"Citation: Q (BTU/hr) = GPM x factor x delta-T; tons = Q / 12000. The water factor 500 = 60 min/hr x 8.33 lb/gal x 1 BTU/lb-F (first-principles fluid energy balance). Glycol factors per ASHRAE Fundamentals 2021 Ch. 31 (secondary coolants). Free at ashrae.org for the TOC."},
  "chipper-debris": {"inputs":[{"key":"green_weight_lb","label":"Green weight to chip (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"chip_density_lcy","label":"Chip bulk density (lb/loose cy)","kind":"number","options":null,"default":550,"attrs":{"step":"any","min":"0","value":"550"}},{"key":"box_capacity_cy","label":"Chip box / dump capacity (loose cy)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: first-principles green-weight to loose-chip-volume conversion by name. chip volume = green weight / chip density; loads = ceil(chip volume / box). The scale ticket governs the density."},
  "chlorine-cylinder-withdrawal": {"inputs":[{"key":"container_type","label":"Container type","kind":"select","options":[{"value":"cylinder","label":"150-lb cylinder (~40 lb/day)"},{"value":"ton","label":"1-ton container (~400 lb/day)"}],"default":"cylinder","attrs":null},{"key":"room_temp_f","label":"Chlorine room temperature (F)","kind":"number","options":null,"default":70,"attrs":{"step":"any","value":"70"}}],"citation":"Citation: gas chlorine container withdrawal rate (The Chlorine Institute; state operator training), by name. Per-container ceiling ~40 lb/day (150-lb cylinder) or ~400 lb/day (1-ton) at ~70 F, derated in a colder room; containers = ceil(feed / per-container). The withdrawal rate is a temperature-dependent latent-heat ceiling - pulling too fast frosts the container. Exceeding it forces a manifold or evaporator. The Chlorine Institute guidance and the manufacturer chart govern."},
  "circle-from-3-points": {"inputs":[{"key":"x1","label":"Point 1 x","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"y1","label":"Point 1 y","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"x2","label":"Point 2 x","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"y2","label":"Point 2 y","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"x3","label":"Point 3 x","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"y3","label":"Point 3 y","kind":"number","options":null,"default":0,"attrs":{"step":"any"}}],"citation":"Citation: First-principles geometry. The circle through three non-collinear points is the triangle's circumcircle: the center is the circumcenter (intersection of the perpendicular bisectors), the radius the distance to any point. Public-domain method (as in Machinery's Handbook coordinate geometry, by name). Take the three points as far apart on the arc as practical."},
  "circular-arc": {"inputs":[{"key":"chord_in","label":"Chord / span (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"rise_in","label":"Rise at midspan (sagitta, in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: First-principles circle geometry. Radius from a chord and rise R = (chord^2/4 + rise^2)/(2 x rise); central angle = 2 x acos((R - rise)/R); arc length = R x angle. Public-domain layout method (the sagitta / middle-ordinate relation) as in Machinery's Handbook (Industrial Press), by name."},
  "circular-arc-rise-from-radius": {"inputs":[{"key":"chord_in","label":"Chord / span (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"radius_in","label":"Radius (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: First-principles circle geometry. Rise from a chord and radius R = (chord^2/4 + rise^2)/(2 rise) solved for the rise: rise = R - sqrt(R^2 - (chord/2)^2); central angle = 2 x asin((chord/2)/R); arc length = R x angle. Public-domain layout method (the sagitta / middle-ordinate relation) as in Machinery's Handbook (Industrial Press), by name."},
  "cistern-storage-days": {"inputs":[{"key":"usable_storage_gal","label":"Usable storage (gal)","kind":"number","options":null,"default":2500,"attrs":{"step":"any","min":"0","value":"2500"}},{"key":"daily_demand_gpd","label":"Daily demand (gpd)","kind":"number","options":null,"default":150,"attrs":{"step":"any","min":"0","value":"150"}},{"key":"target_days","label":"Target reserve (days, for required volume)","kind":"number","options":null,"default":30,"attrs":{"step":"any","min":"0","value":"30"}}],"citation":"Citation: storage-reserve mass balance by name. reserve days = usable storage / daily demand; required volume = daily demand x target days. Use usable storage and a peak (not average) demand; local rainfall or source yield and the AHJ govern."},
  "cleanout-layout": {"inputs":[{"key":"horizontal_run_ft","label":"Horizontal drain run (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"max_spacing_ft","label":"Maximum cleanout spacing (ft; IPC 100)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0"}},{"key":"direction_changes","label":"Changes of horizontal direction over 45 degrees","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}},{"key":"changes_grouped_away","label":"Of those, how many are grouped away (0 = let the 40 ft cap decide)","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}},{"key":"stack_count","label":"Waste or soil stacks","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}},{"key":"pipe_size_in","label":"Cleanout / pipe size (in)","kind":"number","options":null,"default":4,"attrs":{"step":"any","min":"0"}},{"key":"clear_space_in","label":"Clear space at the opening (in)","kind":"number","options":null,"default":18,"attrs":{"step":"any","min":"0"}},{"key":"crawl_height_in","label":"Crawl-space pathway height (in; 0 = not in a crawl space)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: IPC 708 - horizontal drains provided with cleanouts located not more than 100 ft apart; a cleanout where a horizontal drainage pipe, building drain, or building sewer has a change of horizontal direction greater than 45 degrees, with the allowance that where more than one such change occurs within 40 ft of developed length the cleanout at the first change serves all of them; a cleanout at the base of each waste or soil stack; a clear space of not less than 18 in at the opening of cleanouts 6 in and smaller; and, where a cleanout is in a crawl space, an unobstructed pathway height of not less than 24 in. Larger cleanouts carry their own clearance requirement, not checked here. Also not checked: cleanout size relative to the pipe, fittings or fixtures serving as cleanouts, the building drain and sewer junction, manholes, cleanout orientation, concealed piping and access covers, or material and threads. A screen; the adopted code and the AHJ govern."},
  "closing-costs": {"inputs":[{"key":"purchase_price","label":"Purchase price ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"loan_amount","label":"Loan amount ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"transfer_tax_rate_pct","label":"State/local transfer tax rate (percent of price)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"5","value":"0"}},{"key":"note_rate_pct","label":"Note rate (percent; for prepaid interest)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"30","value":"0"}}],"citation":"Citation: CFPB Loan Estimate (Form H-24) and Closing Disclosure (Form H-25), 12 CFR Part 1026 Subpart C (TILA-RESPA Integrated Disclosure rule). Line-item categories and section labels (A, B, C, E, F, G, H) per the CFPB published forms. Rates and dollar ranges are common-case midpoints; the actual Loan Estimate from the lender is the value of record. Free at consumerfinance.gov."},
  "coating-coverage-dft": {"inputs":[{"key":"vol_solids_pct","label":"Volume solids (%, from the data sheet)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"dft_mils","label":"Target dry-film thickness (mils)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"area_ft2","label":"Area to coat (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"loss_pct","label":"Application loss (%, spray ~35)","kind":"number","options":null,"default":35,"attrs":{"step":"any","min":"0","value":"35"}}],"citation":"Citation: SSPC / AMPP PA 2 (dry-film thickness) and the 1604 ft^2-mil/gal coverage constant by name. theoretical = 1604 x volume-solids / DFT; practical applies the loss factor; WFT = DFT / volume-solids. The product data sheet governs."},
  "coax-rg-loss": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"loss","label":"Loss over a run"},{"value":"max-run","label":"Max run for a target level"}],"default":"loss","attrs":null},{"key":"loss_per_100ft_db","label":"Loss per 100 ft (dB)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"6"}},{"key":"length_ft","label":"Run length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"source_level","label":"Source level (dBmV/dBm, optional)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"target_level","label":"Target level (max-run mode)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}}],"citation":"Citation: Coaxial-cable attenuation from the per-100-ft loss at frequency (loss = per-100-ft x length/100), per the cable manufacturer's published loss curves (Belden / CommScope) and the standard CATV/CCTV/SDI practice, by name; first-principles. The per-100-ft loss is type- and frequency-specific and user-supplied or a flagged default; the manufacturer's datasheet governs."},
  "codon-table": {"inputs":[{"key":"sequence_type","label":"Sequence type","kind":"select","options":[{"value":"rna","label":"RNA (ACGU)"},{"value":"dna","label":"DNA (ACGT, translated by T->U)"}],"default":null,"attrs":null}],"citation":"Citation: Standard genetic code (universal). Mitochondrial and a handful of bacterial / protozoan codes differ at specific codons and are NOT covered by this tile. The amino-acid three-letter / one-letter codes follow IUPAC-IUB nomenclature. Reading frame starts at position 1 of the entered sequence; this tile does not search for an internal AUG."},
  "cogo-forward-point": {"inputs":[{"key":"start_n","label":"Start northing N (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"start_e","label":"Start easting E (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"azimuth_deg","label":"Azimuth (deg, clockwise from north)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"360"}},{"key":"distance_ft","label":"Distance (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: coordinate geometry forward locate - latitude (delta N) = D cos(Az), departure (delta E) = D sin(Az), with the azimuth measured clockwise from north; N2 = N1 + delta N, E2 = E1 + delta E. First-principles latitude/departure per the standard route-surveying references (Ghilani & Wolf; FM 5-233), by name. For a quadrant bearing (N45E) convert to azimuth first (the azimuth-bearing-conversion tile does the quadrant conversion; the bearing-conversion tile handles magnetic declination). A computational aid; the project control and datum govern."},
  "cogo-inverse-locate": {"inputs":[{"key":"start_n","label":"Start northing N1 (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"5000"}},{"key":"start_e","label":"Start easting E1 (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"5000"}},{"key":"end_n","label":"End northing N2 (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"5141.42"}},{"key":"end_e","label":"End easting E2 (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"5141.42"}}],"citation":"Citation: coordinate geometry inverse - distance = sqrt(dN^2 + dE^2), azimuth = atan2(dE, dN) clockwise from north, dN = N2-N1, dE = E2-E1. First-principles latitude/departure per the standard route-surveying references (Ghilani & Wolf; FM 5-233), by name. The exact inverse of cogo-forward-point. Plane geometry - no curvature or grid scale factor; the project control and datum govern."},
  "coil-face-area": {"inputs":[{"key":"cfm","label":"Airflow (cfm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"2000"}},{"key":"target_fpm","label":"Target face velocity (fpm, default 500)","kind":"number","options":null,"default":500,"attrs":{"step":"any","min":"0","value":"500"}}],"citation":"Citation: Required coil face area = CFM / target face velocity (the inverse of face velocity = CFM / area), sized to the ~500 fpm wet-coil moisture-carryover limit (ASHRAE / coil-selection practice). A selection aid; the coil manufacturer's rated face velocity governs."},
  "coil-face-velocity": {"inputs":[{"key":"cfm","label":"Airflow (cfm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"2000"}},{"key":"face_width_in","label":"Coil face width (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"24"}},{"key":"face_height_in","label":"Coil face height (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"18"}},{"key":"threshold_fpm","label":"Carryover threshold (fpm, default 500)","kind":"number","options":null,"default":500,"attrs":{"step":"any","min":"0","value":"500"}}],"citation":"Citation: Cooling-coil face velocity = CFM / coil face area, with the ~500 fpm moisture-carryover limit for a wet coil (ASHRAE / coil-selection practice). Above the threshold a wet coil blows condensate past the drain pan. A selection aid; the coil manufacturer's rated face velocity governs."},
  "coil-length": {"inputs":[{"key":"outside_diameter_in","label":"Coil outside diameter OD (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"inside_diameter_in","label":"Core / mandrel diameter ID (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"material_thickness_in","label":"Material thickness t (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Coil / roll stock length from the annulus identity L = pi (OD^2 - ID^2) / (4 t), for coil outside diameter OD, core diameter ID, and material thickness t (same units). First-principles. A layout aid; measure or weigh to confirm before a critical cut."},
  "combustion-air": {"inputs":[{"key":"btu_input","label":"Appliance BTU input","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"room_volume_ft3","label":"Room volume (ft^3)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: per IMC 2021 §304 (combustion air). 50 ft^3 per 1000 BTU/hr by volume; outdoor opening 1 in^2 per 4000 BTU/hr or the larger indoor opening 1 in^2 per 1000 BTU/hr. This is the FREE AREA; each opening's smallest dimension must also be at least 3 in (IFGC 304.6 -- a long narrow opening is blocked by leaves and lint), which a free-area figure cannot enforce. AHJ governs. Free at codes.iccsafe.org."},
  "combustion-air-max-input": {"inputs":[{"key":"room_volume_ft3","label":"Room volume (ft^3)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: per IMC 2021 §304 (combustion air), the standard volume method solved for input. A space is adequate by volume at 50 ft^3 per 1000 BTU/hr, so the max appliance input is (room volume / 50) * 1000; above it, combustion-air openings are required. AHJ governs. Free at codes.iccsafe.org."},
  "combustion-lambda": {"inputs":[{"key":"fuel","label":"Fuel","kind":"select","options":[{"value":"natural_gas","label":"Natural gas (AFR 17.2)"},{"value":"propane","label":"Propane (AFR 15.5)"},{"value":"oil2","label":"#2 fuel oil (AFR 14.5)"}],"default":"natural_gas","attrs":null}],"citation":"Notice: A tuning aid, not a certified combustion test; the analyzer, the appliance, and the manufacturer instructions govern. Citation: combustion-analysis practice lambda and air-fuel ratio, by name. lambda = 20.9 / (20.9 - O2); excess_air = (lambda - 1) x 100; AFR_actual = lambda x AFR_stoich (17.2 natural gas, 15.5 propane, 14.5 #2 oil, by mass). Lambda is the same physics as excess air (lambda = 1 + excess_air/100), shown the way the instrument displays it. The oxygen form assumes complete combustion; sample dry, air-free oxygen in the flue."},
  "commercial-lighting-load": {"inputs":[{"key":"floor_area_ft2","label":"Gross floor area (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"5000"}},{"key":"unit_load_va_ft2","label":"Unit load (VA/ft^2, Table 220.12)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"3"}},{"key":"receptacle_count","label":"General-use receptacle straps","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0","value":"60"}},{"key":"supply_v","label":"Supply voltage (V)","kind":"number","options":null,"default":208,"attrs":{"step":"any","min":"0","value":"208"}}],"citation":"Citation: NEC 2023 Table 220.12 (general-lighting unit load), 220.14(I) (180 VA per receptacle strap), and 220.44 (receptacle demand factor over 10 kVA). The 125% continuous factor is applied at the OCPD; the energy code may set the lighting load. The AHJ governs. Free at nfpa.org/freeaccess."},
  "commission-split": {"inputs":[{"key":"sale_price","label":"Sale price ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"total_commission_percent","label":"Total commission (% of sale)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"20","value":"5"}},{"key":"side_share_percent","label":"This side's share of gross (% of total commission)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"100","value":"50"}},{"key":"brokerage_split_to_agent_percent","label":"Brokerage split (agent share of this side, %)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"100","value":"80"}},{"key":"brokerage_flat_fee","label":"Brokerage flat fee per transaction ($, optional)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: Three-stage commission flow per standard residential-brokerage practice. (1) sale_price * total_commission_percent = gross. (2) gross * side_share = listing or selling side. (3) side * brokerage_split = agent pre-fee; minus flat / desk / franchise fee = agent net. The actual percentages are set by the brokerage and the buyer-broker agreement; this tile is a what-if cross-check."},
  "compaction-roller-production": {"inputs":[{"key":"drum_width_ft","label":"Compacting drum width (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"speed_mph","label":"Roller speed (mph)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"lift_in","label":"Compacted lift thickness (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"passes","label":"Passes to reach spec density","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"efficiency","label":"Job efficiency","kind":"number","options":null,"default":0.75,"attrs":{"step":"any","min":"0","value":"0.75"}}],"citation":"Citation: roller production identity by name. compacted cy/hr = 16.3 x width x speed x lift x efficiency / passes, where 16.3 = 5280 / (12 x 27) folds the mile, the inch, and the cubic yard; area/hr = width x speed x 5280 x efficiency / passes."},
  "composite-curve-number": {"inputs":[{"key":"connection","label":"Impervious connection","kind":"select","options":[{"value":"connected","label":"Directly connected"},{"value":"unconnected","label":"Unconnected (drains over pervious)"}],"default":"connected","attrs":null}],"citation":"Citation: NRCS TR-55 composite curve number for impervious area (Urban Hydrology for Small Watersheds, Chapter 2, figures 2-3 and 2-4): connected CNc = CNp + (Pimp/100)(98 - CNp); unconnected (total impervious under 30%) CNc = CNp + (Pimp/100)(98 - CNp)(1 - 0.5 R). A public USDA/NRCS document; the pervious CN (from land cover and hydrologic soil group, Table 2-2) is user-supplied. A design aid; the local drainage manual and the engineer of record govern."},
  "compressed-air-pressure-drop": {"inputs":[{"key":"scfm","label":"Airflow (scfm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"100"}},{"key":"pipe_id_in","label":"Pipe inside diameter (in, actual ID)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"1.049"}},{"key":"length_ft","label":"Run length incl. fitting equiv. (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"100"}},{"key":"line_pressure_psig","label":"Line pressure (psig)","kind":"number","options":null,"default":100,"attrs":{"step":"any","value":"100"}},{"key":"air_temp_f","label":"Air temperature (F)","kind":"number","options":null,"default":68,"attrs":{"step":"any","value":"68"}},{"key":"roughness_ft","label":"Pipe roughness (ft)","kind":"number","options":null,"default":0.00015,"attrs":{"step":"any","value":"0.00015"}}],"citation":"Citation: Darcy-Weisbach pressure drop dP = f (L/D) rho V^2 / (2 gc) with the friction factor from the Colebrook-White relation, air density at line conditions from the ideal gas law rho = P_abs x 144 / (R_air T) with R_air = 53.35 ft-lbf/lb-R, and the standard-to-actual volume conversion Q_actual = scfm x (14.7/P_abs) x (T/528 R) from the same gas law. Air dynamic viscosity is taken as the standard 1.81e-5 Pa-s at 68 F converted to imperial units. No empirical compressed-air constant is used. Isothermal single-phase flow; the inlet density is used throughout, which is conservative. Fitting equivalent lengths must be added to the run length by the user."},
  "compression-ratio-refrig": {"inputs":[{"key":"suction_psig","label":"Suction pressure (psig)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"discharge_psig","label":"Discharge pressure (psig)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"atmospheric_psia","label":"Atmospheric pressure (psia)","kind":"number","options":null,"default":14.696,"attrs":{"step":"any","min":"0","value":"14.696"}}],"citation":"Citation: Refrigeration compression ratio = absolute discharge pressure / absolute suction pressure (gauge + atmospheric) - per the ASHRAE Handbook Refrigeration compressor-performance fundamentals, by name; first-principles. Use the site atmospheric pressure at altitude for accuracy; about 10:1 is the single-stage concern threshold. The compressor manufacturer's operating envelope governs."},
  "compressor-short-cycle": {"inputs":[{"key":"system_type","label":"System type","kind":"select","options":[{"value":"single","label":"Single-stage"},{"value":"two_stage","label":"Two-stage"},{"value":"inverter","label":"VRF / inverter"}],"default":"single","attrs":null}],"citation":"Citation: cycle rate N = N_max x 4 x X x (1 - X) where X is the runtime (load) fraction (the ASHRAE/AHRI part-load cycling model, peaking at 50% load); on-time = X x 60 / N. Minimum runtime and pressure-equalization delays per the Copeland Application Engineering Bulletin 17-1226 and ASHRAE Fundamentals 2021. Per-manufacturer guidance governs inverter systems. Free at copeland.com/literature."},
  "compressor-volumetric-efficiency": {"inputs":[{"key":"clearance_ratio","label":"Clearance ratio (~0.03-0.06)","kind":"number","options":null,"default":0.045,"attrs":{"step":"any","min":"0","value":"0.045"}},{"key":"suction_pressure_psia","label":"Suction pressure (psia)","kind":"number","options":null,"default":70,"attrs":{"step":"any","min":"0","value":"70"}},{"key":"discharge_pressure_psia","label":"Discharge pressure (psia)","kind":"number","options":null,"default":300,"attrs":{"step":"any","min":"0","value":"300"}},{"key":"polytropic_exponent","label":"Polytropic exponent n (~1.11 R-22)","kind":"number","options":null,"default":1.11,"attrs":{"step":"any","min":"0","value":"1.11"}}],"citation":"Citation: reciprocating compressor clearance volumetric efficiency (ASHRAE Refrigeration / Dossat clearance re-expansion), by name. VE = 1 + C - C x (Pd/Ps)^(1/n); C = clearance ratio (~0.03-0.06), n = polytropic exponent (~1.11 R-22, 1.16 R-410A). Clearance VE only -- superheat, leakage, and valve drop lower the actual VE further. The rated capacity at the operating condition governs."},
  "concrete": {"inputs":[{"key":"shape","label":"Shape","kind":"select","options":[{"value":"slab","label":"Slab"},{"value":"footing","label":"Footing"},{"value":"column","label":"Column"},{"value":"footing_with_stem","label":"Footing with stem"}],"default":null,"attrs":null},{"key":"waste_factor","label":"Waste factor (0-1)","kind":"number","options":null,"default":0.1,"attrs":{"step":"any","min":"0","max":"1","value":"0.10"}}],"citation":"Citation: Geometric volume divided by 27 (cubic feet per cubic yard)."},
  "condensate-return-sizing": {"inputs":[{"key":"condensate_lbhr","label":"Condensate load to the return (lb/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"flash_fraction","label":"Flash fraction at return pressure (0-1)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"1"}},{"key":"spec_vol_ft3lb","label":"Flash-steam specific volume at return pressure (ft3/lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"vel_ceiling_fpm","label":"Return velocity ceiling (ft/min)","kind":"number","options":null,"default":4000,"attrs":{"step":"any","min":"0","value":"4000"}}],"citation":"Citation: Condensate return sized for the flash steam - flash = load x flash_fraction; volumetric flow = flash x specific_volume / 60; required area = flow / velocity ceiling, then the smallest Sch 40 nominal whose ID clears the required diameter - first-principles continuity, with the return-velocity ceiling (~4,000 to 5,000 ft/min, lower than a supply main) per ASHRAE / Spirax Sarco return-sizing practice, by name. The return is sized for the flash, not the liquid; a wet, dry, or vacuum return and any lift each change the scheme, which the engineer of record governs."},
  "conductor-short-circuit-withstand": {"inputs":[{"key":"area_cmil","label":"Conductor area (circular mils)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"fault_current_a","label":"Available fault current (A, symmetrical)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"clearing_time_s","label":"Clearing time (s)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.1"}},{"key":"material","label":"Material","kind":"select","options":[{"value":"copper","label":"Copper (K=0.0297, B=234)"},{"value":"aluminum","label":"Aluminum (K=0.0125, B=228)"}],"default":"copper","attrs":null},{"key":"t_initial_c","label":"Initial temperature (deg C)","kind":"number","options":null,"default":75,"attrs":{"step":"any","value":"75"}},{"key":"t_final_c","label":"Insulation short-circuit limit (deg C)","kind":"number","options":null,"default":250,"attrs":{"step":"any","value":"250"}}],"citation":"Citation: ICEA P-32-382 / Onderdonk adiabatic short-circuit withstand (public-domain): (I/A)^2 t = K log10((T2+B)/(T1+B)); copper K=0.0297/B=234, aluminum K=0.0125/B=228. A thermal-withstand screen, not a substitute for the device time-current curve or an engineered study."},
  "conduit-expansion-max-run": {"inputs":[{"key":"temp_change_f","label":"Temperature swing (deg F)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"coeff_in_per_in_f","label":"PVC coefficient (in/in/deg-F)","kind":"number","options":null,"default":0.0000338,"attrs":{"step":"any","min":"0","value":"0.0000338"}},{"key":"trigger_in","label":"Fitting trigger (in)","kind":"number","options":null,"default":0.25,"attrs":{"step":"any","min":"0","value":"0.25"}}],"citation":"Citation: NEC 2023 352.44 (expansion fittings for rigid PVC conduit), solved for the run length. L_max = trigger / (coefficient x 12 x temperature swing); the bundled 3.38e-5 in/in/deg-F PVC coefficient underlies NEC Table 352.44. The AHJ and the manufacturer govern. Free read-only at nfpa.org/freeaccess."},
  "conduit-fill": {"inputs":[{"key":"conduit","label":"Conduit type","kind":"select","options":[{"value":"EMT","label":"EMT"},{"value":"PVC_40","label":"PVC Schedule 40"},{"value":"RMC","label":"RMC"}],"default":null,"attrs":null}],"citation":"Citation: per NEC 2023 Chapter 9, Table 4 (conduit areas) and Chapter 9, Table 5 (conductor areas). Fill thresholds 53% (1 conductor), 31% (2 conductors), 40% (>= 3 conductors). AHJ governs. Free at nfpa.org/freeaccess."},
  "conduit-jam-ratio": {"inputs":[{"key":"conduit_id_in","label":"Conduit inside diameter (in, NEC Ch.9 Table 4)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"conductor_od_in","label":"Conductor outside diameter (in, Table 5)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"n_conductors","label":"Number of conductors","kind":"number","options":null,"default":3,"attrs":{"step":"1","min":"1"}}],"citation":"Citation: conduit jam ratio = conduit ID / conductor OD; jamming risk for exactly three same-size conductors when the ratio is ~2.8-3.2, a widely-referenced NEC Chapter 9 pulling guideline (Table 4 conduit ID, Table 5 conductor OD). A caution, not a code limit; the NEC and the AHJ govern."},
  "conduit-nipple-60-fill": {"inputs":[{"key":"conduit_area_sqin","label":"Conduit total area (sq in, Table 4)","kind":"number","options":null,"default":0.864,"attrs":{"step":"any","min":"0","value":"0.864"}},{"key":"conductor_area_sqin","label":"Each conductor area (sq in, Table 5)","kind":"number","options":null,"default":0.0211,"attrs":{"step":"any","min":"0","value":"0.0211"}},{"key":"conductor_count","label":"Conductor count","kind":"number","options":null,"default":20,"attrs":{"step":"1","min":"1","value":"20"}}],"citation":"Citation: conduit nipple 60% fill, NEC Chapter 9 Note 4, by name. A nipple <= 24 in between enclosures may fill to 60% (vs 40%/31%/53% normal). fill% = count x conductor area / conduit total area (Table 4 conduit area, Table 5 conductor area). Note 4 also exempts nipples from the 310.15(C)(1) ampacity adjustment. The exact table areas and the AHJ govern."},
  "conduit-saddle": {"inputs":[{"key":"mode","label":"Saddle type","kind":"select","options":[{"value":"three-point","label":"Three-point"},{"value":"four-point","label":"Four-point"}],"default":"three-point","attrs":null},{"key":"preset","label":"Bend preset (center/outer)","kind":"select","options":[{"value":"45/22.5","label":"45/22.5 deg"},{"value":"60/30","label":"60/30 deg"}],"default":"45/22.5","attrs":null}],"citation":"Citation: Conduit saddle bending follows the field multipliers and shrink rules taught in the electrical apprenticeship and documented in Ugly's Electrical References and NECA conduit-bending guidance by name. Bender deduct and shoe figures are tool-specific - confirm against your bender. See the cable-bend-radius tile for minimum conductor bend radius. The AHJ governs."},
  "conduit-thermal-expansion": {"inputs":[{"key":"run_length_ft","label":"Straight run between anchors (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"temp_change_f","label":"Temperature swing (deg F)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"coeff_in_per_in_f","label":"PVC coefficient (in/in/deg-F)","kind":"number","options":null,"default":0.0000338,"attrs":{"step":"any","min":"0","value":"0.0000338"}},{"key":"trigger_in","label":"Fitting trigger (in)","kind":"number","options":null,"default":0.25,"attrs":{"step":"any","min":"0","value":"0.25"}}],"citation":"Citation: NEC 2023 352.44 (expansion fittings for rigid PVC conduit). delta_L = coefficient x length x temperature swing; the bundled 3.38e-5 in/in/deg-F PVC coefficient underlies NEC Table 352.44. A fitting is required at the 1/4-inch trigger. The AHJ and the manufacturer govern. Free read-only at nfpa.org/freeaccess."},
  "cone-flat-pattern": {"inputs":[{"key":"base_radius_in","label":"Base radius (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"height_in","label":"Vertical height (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Radial-line cone development (sheet-metal layout): slant height L = sqrt(r^2 + h^2), flat-pattern sector radius = L, sweep angle = 360 x r / L. Add seam/lap and bend allowance. A layout aid; verify against a test piece."},
  "confidence-interval": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"proportion","label":"Proportion (binomial)"},{"value":"mean","label":"Mean (z-interval)"}],"default":null,"attrs":null},{"key":"n","label":"Sample size n","kind":"number","options":null,"default":null,"attrs":{"step":"1","min":"1"}},{"key":"proportion","label":"Sample proportion (0 to 1)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"1"}},{"key":"mean","label":"Sample mean (mean mode)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"sd","label":"Sample SD (mean mode)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"confidence_pct","label":"Confidence level","kind":"select","options":[{"value":"80","label":"80%"},{"value":"90","label":"90%"},{"value":"95","label":"95%"},{"value":"98","label":"98%"},{"value":"99","label":"99%"}],"default":null,"attrs":null}],"citation":"Citation: Wald confidence interval. For a proportion: phat +/- z * sqrt(phat * (1-phat) / n). For a mean: xbar +/- z * (sd / sqrt(n)). z critical values from the standard normal: 80% = 1.2816, 90% = 1.6449, 95% = 1.96, 98% = 2.3263, 99% = 2.5758. The Wald interval under-covers when n*phat < 10 (use Wilson or Clopper-Pearson) and is z-based for the mean (use a t-interval for small n with unknown sigma)."},
  "contents-packout-inventory": {"inputs":[{"key":"floor_area_ft2","label":"Affected floor area (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"200"}},{"key":"contents_ft3_per_ft2","label":"Contents volume per floor area (ft^3/ft^2)","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"0","value":"2"}},{"key":"box_volume_ft3","label":"Usable volume per box (ft^3)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","value":"3"}},{"key":"stacking_factor","label":"Warehouse stacking allowance","kind":"number","options":null,"default":1.5,"attrs":{"step":"any","min":"0","value":"1.5"}},{"key":"truck_volume_ft3","label":"Box-truck cargo volume (ft^3)","kind":"number","options":null,"default":1000,"attrs":{"step":"any","min":"0","value":"1000"}}],"citation":"Citation: Volume-based pack-out estimating method (restoration estimating practice; ANSI/IICRC S500/S700), by name. The actual inventory and the box mix GOVERN; the densities are starting rules of thumb. This is an estimating screen."},
  "copper-resistance": {"inputs":[{"key":"material","label":"Material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":null,"attrs":null},{"key":"length_ft","label":"Length (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"temperature_C","label":"Temperature (C)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}}],"citation":"Citation: R(T) = rho_0 * L / A * (1 + alpha * (T - 20)). Resistivity and temperature coefficient from NIST tables."},
  "cost-of-waiting": {"inputs":[{"key":"principal","label":"Principal (loan amount, $)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"current_rate_percent","label":"Current rate (percent)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"30"}},{"key":"future_rate_percent","label":"Future rate (percent)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"30"}},{"key":"term_years","label":"Term (years)","kind":"number","options":null,"default":null,"attrs":{"step":"1","min":"1","max":"50","value":"30"}}],"citation":"Citation: Standard mortgage amortization at two rates. No forecasting model; the user supplies both rates. The 'cost of waiting' framing is a sales tool; actual outcomes depend on future home prices, inflation, opportunity cost of down payment, and personal cash flow. This tile is a sanity check, not a recommendation."},
  "crane-ground-bearing": {"inputs":[{"key":"reaction_lb","label":"Worst-corner reaction (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"bearing_area_ft2","label":"Float / pad / track contact area (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"allowable_psf","label":"Allowable soil bearing (psf)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: OSHA 29 CFR 1926 Subpart CC and the manufacturer's outrigger-reaction chart by name. gbp = reaction / area; required area = reaction / allowable. Estimate - a geotech source and a qualified person govern."},
  "crane-load-radius-boom": {"inputs":[{"key":"boom_length_ft","label":"Boom length (ft)","kind":"number","options":null,"default":30,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"boom_angle_deg","label":"Boom angle from horizontal (deg)","kind":"number","options":null,"default":60,"attrs":{"step":"any","min":"0","value":"60"}},{"key":"boom_foot_offset_ft","label":"Boom-foot offset from center pin (ft)","kind":"number","options":null,"default":4,"attrs":{"step":"any","min":"0","value":"4"}},{"key":"boom_foot_height_ft","label":"Boom-foot height (ft)","kind":"number","options":null,"default":6,"attrs":{"step":"any","min":"0","value":"6"}},{"key":"target_radius_ft","label":"Target load radius (ft)","kind":"number","options":null,"default":25,"attrs":{"step":"any","min":"0","value":"25"}}],"citation":"Citation: crane load radius and boom-tip height from boom geometry, by name. radius = boom-foot offset + boom length x cos(angle); tip height = boom-foot height + boom length x sin(angle); angle for a target radius = acos((target - offset)/length). Boom geometry only (no deflection/stretch/out-of-level, which increase the real radius). The load chart, load-moment indicator, and qualified operator govern."},
  "crane-net-capacity": {"inputs":[{"key":"gross_chart_lb","label":"Gross chart capacity at radius (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"hook_block_lb","label":"Hook block / overhaul ball (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"jib_attach_lb","label":"Erected jib / extension (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"wire_rope_lb","label":"Wire-rope deduction (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"below_hook_lb","label":"Below-the-hook gear (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"load_weight_lb","label":"Load weight (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: OSHA 29 CFR 1926.1417(o) deduction stack and ASME B30.5 by name. net = gross - hook block - jib - wire rope; percent = (load + below-hook) / net. Estimate - the manufacturer's load chart governs."},
  "crane-outrigger-reaction": {"inputs":[{"key":"gross_load_kip","label":"Gross suspended load (kip)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"counterweight_kip","label":"Counterweight (kip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"load_radius_ft","label":"Load radius R (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"cw_radius_ft","label":"Counterweight radius Rc (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"outrigger_spread_ft","label":"Outrigger spread (ft, center to center)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Crane load-moment method / SAE J1063 stability, by name. even = (W + Wc)/4; overturning M = W R - Wc Rc; R_max = even + M/(sqrt(2) spread). The maximum outrigger reaction is not a quarter of the total - over a corner the overturning concentrates into one diagonal outrigger. A wider spread lowers it. A planning estimate feeding crane-ground-bearing; the crane load-moment chart and outrigger reaction data govern."},
  "crane-power-line-clearance": {"inputs":[{"key":"option","label":"Which option","kind":"select","options":[{"value":"default","label":"Default clearance (voltage not determined)"},{"value":"table-a","label":"Table A (voltage determined)"},{"value":"deenergized","label":"Deenergized and visibly grounded"}],"default":"default","attrs":null},{"key":"voltage_kv","label":"Line voltage (kV; 0 = not determined)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"actual_clearance_ft","label":"Actual clearance held (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"boom_length_ft","label":"Boom length (ft; 0 to skip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: OSHA 29 CFR 1926.1408, a US federal regulation in the public domain. For power lines up to 350 kV the employer must either confirm from the utility owner or operator that the line has been deenergized and visibly grounded at the worksite; or ensure that no part of the equipment, load line, or load - including rigging and lifting accessories - gets closer than 20 feet to the line while implementing the encroachment-prevention measures of paragraph (b); or determine the line's voltage and use the Table A minimum clearance distance while implementing those same measures. Table A: up to 50 kV, 10 ft; over 50 to 200 kV, 15 ft; over 200 to 350 kV, 20 ft; over 350 to 500 kV, 25 ft; over 500 to 750 kV, 35 ft; over 750 to 1,000 kV, 45 ft; over 1,000 kV, as established by the utility owner or operator or a registered professional engineer who is a qualified person with respect to electrical power transmission and distribution. Not checked: the encroachment-prevention measures themselves, the planning meeting and work-zone identification, assembly and disassembly near power lines, travel with no load, or the utility's voltage confirmation. A screen, not a lift plan; Subpart CC, the utility, and the qualified person govern."},
  "crown-pruning-dose": {"inputs":[{"key":"live_foliage","label":"Live crown / foliage before pruning (ft^2 or %)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"removed_foliage","label":"Foliage proposed for removal (same units)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"15"}},{"key":"maturity_class","label":"Maturity class","kind":"select","options":[{"value":"young","label":"Young (~15% cap)"},{"value":"mature","label":"Mature (25% cap)"},{"value":"over-mature","label":"Over-mature (~10% cap)"},{"value":"stressed","label":"Stressed (0% cap)"}],"default":"mature","attrs":null}],"citation":"Citation: ANSI A300 Part 1 live-crown removal limit (ISA Best Management Practices), by name. removal_pct = removed / live x 100, compared to the class cap: mature <= 25% in a single season, young ~15%, over-mature ~10%, stressed 0%. The 25% is the mature maximum, not a target; lion's-tailing violates A300 even under the percent cap. A planning aid; a qualified arborist governs."},
  "curve-deflection-stakeout": {"inputs":[{"key":"mode","label":"Definition mode","kind":"select","options":[{"value":"radius","label":"By radius (ft)"},{"value":"degree","label":"By degree of curve"}],"default":null,"attrs":null}],"citation":"Citation: deflection-angle curve stakeout - deflection from the back tangent delta = (l / 2R)(180/pi) deg, sub-chord c = 2R sin(l / 2R), arc definition D = 5729.58 / R. First-principles route surveying per FM 5-233 Construction Surveying and AASHTO A Policy on Geometric Design (the Green Book), by name. Simple circular curve, no spiral/superelevation transition. A computational aid; the design of record governs."},
  "curve-grade-scaler": {"inputs":[{"key":"method","label":"Method","kind":"select","options":[{"value":"flat","label":"Flat add (raw + k)"},{"value":"sqrt","label":"Square-root (10 x sqrt(raw))"},{"value":"linear","label":"Linear rescale to target mean"}],"default":"flat","attrs":null}],"citation":"Citation: Standard psychometric score-scaling methods (public): flat add, square-root, and linear rescale-to-target-mean. Estimate only - the instructor's gradebook and academic-integrity policy govern final grades."},
  "cutting-fluid-concentration": {"inputs":[{"key":"brix_reading","label":"Refractometer Brix","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"refractometer_factor","label":"Refractometer factor","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"sump_volume_gal","label":"Sump volume (gal)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"target_pct","label":"Target concentration (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Metalworking-fluid refractometer method (concentration % = Brix x factor; factor and range off the coolant data sheet, by name)."},
  "cylinder-storage-separation": {"inputs":[{"key":"separation_ft","label":"Distance between oxygen and fuel gas or combustibles (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"barrier_present","label":"Barrier between them?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":"no","attrs":null},{"key":"barrier_height_ft","label":"Barrier height (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"barrier_noncombustible","label":"Barrier is noncombustible?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":"no","attrs":null},{"key":"barrier_rating_hr","label":"Barrier fire-resistance rating (hours)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"cylinders_upright","label":"Cylinders secured upright?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":"yes","attrs":null},{"key":"valve_caps_secured","label":"Valve protection caps in place and secured?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":"yes","attrs":null}],"citation":"Citation: OSHA 29 CFR 1926.350, a US federal regulation in the public domain. 'Oxygen cylinders in storage shall be separated from fuel-gas cylinders or combustible materials (especially oil or grease), a minimum distance of 20 feet (6.1 m) or by a noncombustible barrier at least 5 feet (1.5 m) high having a fire-resistance rating of at least one-half hour.' 'Compressed gas cylinders shall be secured in an upright position at all times except, if necessary, for short periods of time while cylinders are actually being hoisted or carried.' 'Valve protection caps shall be in place and secured.' Not checked: cylinders in use rather than in storage; acetylene-specific storage and the waiting period after a cylinder has been on its side; regulator, hose, and torch condition; flashback arrestors; prohibited hoisting methods; transport in enclosed vehicles; indoor storage quantity limits; or NFPA 55 and state rules, which are often stricter. A screen, not a gas-storage plan; 1926.350, the gas supplier, and the AHJ govern."},
  "dc-shunt-sizing": {"inputs":[{"key":"rated_current_a","label":"Rated current (A)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"rated_millivolt","label":"Rated output (mV at rated current)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}},{"key":"measured_millivolt","label":"Measured output (mV)","kind":"number","options":null,"default":25,"attrs":{"step":"any","min":"0","value":"25"}}],"citation":"Citation: DC current-shunt sizing (Ohm's law), by name. R = rated_mV/1000 / rated_A; current = rated_A x (measured_mV / rated_mV); dissipation at rating = rated_A x rated_mV/1000. Derate to ~2/3 for continuous use; sense at the potential terminals. The shunt accuracy class and the meter range/calibration govern."},
  "debt-yield": {"inputs":[{"key":"mode","label":"Solve for","kind":"select","options":[{"value":"yield","label":"Debt yield (from a loan amount)"},{"value":"maxloan","label":"Max loan (from a target debt yield)"}],"default":"yield","attrs":null}],"citation":"Citation: Debt yield = NOI / loan amount, a lender's return if it took the property back on day one. It ignores the interest rate, amortization, and cap rate, which is why it became the binding loan-sizing constraint in tight credit; typical minimums run 8-10%. The lender governs the required floor."},
  "dechlorination-dose": {"inputs":[{"key":"chlorine_residual_mg_l","label":"Chlorine residual to remove (mg/L)","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"0","value":"2"}},{"key":"flow_mgd","label":"Flow (MGD)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"stoich_ratio","label":"Stoich ratio (mg reagent / mg Cl2)","kind":"number","options":null,"default":1.46,"attrs":{"step":"any","min":"0","value":"1.46"}},{"key":"purity_pct","label":"Reagent purity (percent)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}}],"citation":"Citation: dechlorination chemical dose (stoichiometry + the pounds formula), by name. reagent dose (mg/L) = ratio x chlorine residual; feed (lb/day) = dose x flow (MGD) x 8.34 / (purity/100). Ratio (mg reagent / mg Cl2): SO2 ~0.9-1.0, metabisulfite 1.34, bisulfite 1.46, sulfite 1.77, thiosulfate ~0.56. The discharge permit, the reagent assay, and the state primacy agency govern."},
  "decibel-converter": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"power-ratio","label":"Power ratio (10 log)"},{"value":"voltage-ratio","label":"Voltage/pressure ratio (20 log)"},{"value":"reference-level","label":"Reference level (back-solve linear)"},{"value":"combine","label":"Combine incoherent sources"}],"default":null,"attrs":null},{"key":"ref_type","label":"Reference type","kind":"select","options":[{"value":"dBu","label":"dBu (0.775 V)"},{"value":"dBV","label":"dBV (1 V)"},{"value":"dBSPL","label":"dBSPL (20 uPa)"}],"default":null,"attrs":null}],"citation":"Citation: Per ANSI S1.1 acoustical-terminology decibel definitions (power 10log, field-quantity 20log) and the standard reference levels (dBu 0.775 V, dBV 1 V, dBSPL 20 uPa), by name; public. Complements spl-distance."},
  "degree-day-energy": {"inputs":[{"key":"ua_btuhf","label":"Heat-loss coefficient UA (Btu/h-F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"hdd","label":"Heating degree-days (base 65 F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"eff","label":"System efficiency (AFUE or COP)","kind":"number","options":null,"default":0.8,"attrs":{"step":"any","min":"0"}},{"key":"fuel","label":"Fuel","kind":"select","options":[{"value":"gas","label":"Gas (therms)"},{"value":"oil","label":"Fuel oil (gal)"},{"value":"electric","label":"Electric (kWh)"}],"default":"gas","attrs":null},{"key":"price","label":"Fuel unit price ($/unit, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: degree-day annual heating energy Q = 24 x HDD x UA (base-65 degF), fuel = Q/efficiency, with 1 therm = 100,000 Btu / 1 gal oil ~ 138,500 Btu / 1 kWh = 3,412 Btu, ASHRAE degree-day / RESNET basis, by name. Steady-state, no gains, heating only. An estimate, not a calibrated model."},
  "dehumidifier": {"inputs":[{"key":"room_cubic_feet","label":"Room volume (ft^3)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"water_class","label":"Water class","kind":"select","options":[{"value":"1","label":"Class 1"},{"value":"2","label":"Class 2"},{"value":"3","label":"Class 3"},{"value":"4","label":"Class 4"}],"default":"2","attrs":null}],"citation":"Citation: AHAM rating method (80 F / 60 percent RH) and an engineering field method scaled by job conditions. References IICRC S500."},
  "dehumidifier-derate": {"inputs":[{"key":"aham_pints_per_day","label":"Nameplate AHAM rating (pints/day)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"130"}},{"key":"derate_factor","label":"Derate factor (0-1, off the unit's curve)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","min":"0","max":"1","value":"0.5"}},{"key":"required_pints_per_day","label":"Required removal (pints/day)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: IICRC S500 cautions that the AHAM nameplate (a high-grain-depression test condition) overstates field output as the chamber dries, by name. effective = nameplate * derate; the derate is read off the unit's published performance curve at the measured chamber GPP. The curve and psychrometric reality govern; this carries the multiplication and the count."},
  "delta-wye-line-phase": {"inputs":[{"key":"configuration","label":"Connection","kind":"select","options":[{"value":"wye","label":"Wye (star)"},{"value":"delta","label":"Delta"}],"default":"wye","attrs":null},{"key":"line_voltage_v","label":"Line-to-line voltage (V)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"line_current_a","label":"Line current (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"power_factor","label":"Power factor (0-1)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","max":"1","value":"1"}}],"citation":"Citation: first-principles three-phase winding relations. Wye: V_line = root-3 x V_phase, I_line = I_phase. Delta: V_line = V_phase, I_line = root-3 x I_phase. S = root-3 x V_line x I_line. The equipment nameplate governs the connection."},
  "desiccant-airflow-sizing": {"inputs":[{"key":"required_pints_per_day","label":"Water-removal demand (pints/day)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"design_grain_depression","label":"Design grain depression (grains/lb across the wheel)","kind":"number","options":null,"default":60,"attrs":{"step":"any","min":"0","value":"60"}},{"key":"nameplate_process_cfm","label":"Candidate unit process airflow (cfm)","kind":"number","options":null,"default":2000,"attrs":{"step":"any","min":"0","value":"2000"}}],"citation":"Citation: Psychrometric mass balance, desiccant process-airflow method, by name (IICRC S500). process_cfm = lb/hr * 7000 / (4.5 * depression), with 4.5 = 60 min/hr * 0.075 lb/ft^3 standard air, 7000 grains/lb, 1.043 lb/pint. The manufacturer's performance map and chamber conditions govern the achievable depression; reactivation exhaust air must be ducted outside."},
  "dewatering-rate": {"inputs":[{"key":"pit_len_ft","label":"Pit length at water surface (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"pit_wid_ft","label":"Pit width at water surface (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"drawdown_ft","label":"Drawdown depth (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"drawdown_min","label":"Time to draw down (min)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"inflow_gpm","label":"Steady inflow / seepage (gpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"safety_pct","label":"Pump-sizing margin (%)","kind":"number","options":null,"default":25,"attrs":{"step":"any","min":"0","value":"25"}}],"citation":"Citation: first-principles volume / pumping rate by name. drawdown gallons = length x width x depth x 7.48052; pump = drawdown / time + inflow; sized = pump x (1 + margin). The inflow must be estimated from a pumping test."},
  "dilution": {"inputs":[{"key":"concentrate_percent","label":"Concentrate strength (%)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"100"}},{"key":"target_percent","label":"Target strength (%)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"100"}},{"key":"final_volume","label":"Final volume","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: V_concentrate = V_final * C_target / C_concentrate; V_diluent = V_final - V_concentrate."},
  "disinfectant-dwell": {"inputs":[{"key":"product_class","label":"Product class","kind":"select","options":[{"value":"quat","label":"Quaternary ammonium (quat)"},{"value":"ahp","label":"Accelerated hydrogen peroxide (AHP)"},{"value":"bleach","label":"Sodium hypochlorite (bleach solution)"},{"value":"phenolic","label":"Phenolic"},{"value":"botanical","label":"Botanical / thymol"}],"default":"quat","attrs":null}],"citation":"Citation: Antimicrobial contact-time principle (ANSI/IICRC S500 and S520), by name. Antimicrobials are EPA-registered pesticides whose label is the legal authority (FIFRA); the ranges shown are guidance and the specific product label governs the exact dwell. The surface must stay visibly wet for the full contact time, and disinfection requires pre-cleaning because product cannot penetrate soil."},
  "dozer-production": {"inputs":[{"key":"blade_cap_lcy","label":"Heaped blade capacity (loose cy)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"push_dist_ft","label":"One-way push distance (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"push_speed_fpm","label":"Loaded push speed (ft/min)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"return_speed_fpm","label":"Empty return speed (ft/min)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"fixed_min","label":"Fixed gear-shift time (min)","kind":"number","options":null,"default":0.05,"attrs":{"step":"any","min":"0","value":"0.05"}},{"key":"eff_min_per_hr","label":"Working minutes per hour","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}}],"citation":"Citation: Caterpillar Performance Handbook slot-dozing cycle-time production method by name. cycle = push/push-speed + push/return-speed + fixed; cycles/hr = working minutes / cycle; production = blade capacity x cycles/hr."},
  "dp-level-hydrostatic": {"inputs":[{"key":"measured_pressure_psi","label":"Measured pressure (psi)","kind":"number","options":null,"default":4.33,"attrs":{"step":"any","min":"0","value":"4.33"}},{"key":"specific_gravity","label":"Fluid specific gravity","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1.0"}},{"key":"max_level_ft","label":"Full-span (max) level (ft)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}}],"citation":"Citation: hydrostatic DP level transmitter (head to level), by name. P = 0.433 x SG x H (psi), so level H = P / (0.433 x SG); 0.433 psi/ft is water at ~60 F. Full-span (URV) = 0.433 x SG x max level. Assumes an open (vented) tank, tap at zero level, no elevation/suppression; a wet leg or elevated tap needs zero suppression/elevation set at calibration. The transmitter range and calibration govern."},
  "drainage-invert": {"inputs":[{"key":"invert_in_ft","label":"Invert-in elevation (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"slope","label":"Slope","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"slope_units","label":"Slope units","kind":"select","options":[{"value":"in_per_ft","label":"in/ft"},{"value":"percent","label":"%"}],"default":"in_per_ft","attrs":null},{"key":"run_ft","label":"Run length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"pipe_od_in","label":"Pipe OD (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"surface_out_ft","label":"Downstream surface elevation (ft, optional)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"min_cover_ft","label":"Minimum cover (ft, optional)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: invert-out = invert-in - slope x run; cover = surface - (invert-out + OD). Slope minimums per IPC 2021 Section 704; minimum cover, frost depth, and live-load bury are set by the adopted code and the engineer/survey of record."},
  "dry-time-projection": {"inputs":[{"key":"current_mc_pct","label":"Current moisture content (percent)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"28"}},{"key":"goal_mc_pct","label":"Goal moisture content (percent)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"daily_drop_pct","label":"Drop over the last 24 hours (points)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"4"}}],"citation":"Citation: Linear-trend completion projection (ANSI/IICRC S500), by name. Drying is non-linear and slows as it approaches the goal, so a constant-rate projection is a planning estimate that runs optimistic near the end. The drying-log boundary readings and the restorer's daily monitoring govern the actual endpoint; the dry standard is the unaffected reference, not an absolute number."},
  "dryer-demand-220-54": {"inputs":[{"key":"num_dryers","label":"Number of dryers","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1","value":"4"}},{"key":"nameplate_w","label":"Each dryer nameplate (W)","kind":"number","options":null,"default":5000,"attrs":{"step":"any","min":"0","value":"4500"}},{"key":"supply_v","label":"Service voltage (V)","kind":"number","options":null,"default":240,"attrs":{"step":"any","min":"0","value":"240"}}],"citation":"Citation: NEC 2023 220.54 and Table 220.54 (household electric clothes dryers). Each dryer counts at the larger of 5,000 W or nameplate; the Table 220.54 demand factor applies once there are five or more. The AHJ-adopted edition governs. Free at nfpa.org/freeaccess."},
  "drying-balance": {"inputs":[{"key":"evap_load_ppd","label":"Evaporation load (pints/day, from evaporation-load)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"200"}},{"key":"installed_ppd","label":"Installed dehu capacity (pints/day; field, not AHAM)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"260"}},{"key":"target_margin","label":"Target capacity-to-load ratio","kind":"number","options":null,"default":1.2,"attrs":{"step":"any","min":"0","value":"1.2"}}],"citation":"Citation: Balanced-drying-system principle (ANSI/IICRC S500), by name. A balanced system keeps installed dehumidification at or above the evaporation load with margin. Field capacity is below the AHAM nameplate as grain depression falls; the restorer's daily monitoring governs equipment adjustments."},
  "drying-goal": {"inputs":[{"key":"outdoor_temperature_F","label":"Outdoor temperature (F)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"outdoor_RH_percent","label":"Outdoor RH (percent)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"100"}},{"key":"indoor_temperature_F","label":"Indoor temperature (F)","kind":"number","options":null,"default":70,"attrs":{"step":"any","value":"72"}},{"key":"margin_GPP","label":"Margin (GPP below outdoor)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}}],"citation":"Citation: Standard restoration rule of thumb. Target indoor GPP at least 5 to 10 grains below outdoor GPP for effective drying."},
  "drywell-infiltration": {"inputs":[{"key":"runoff_volume_ft3","label":"Runoff (storage) volume (ft^3)","kind":"number","options":null,"default":200,"attrs":{"step":"any","min":"0","value":"200"}},{"key":"void_ratio","label":"Aggregate void ratio (~0.35)","kind":"number","options":null,"default":0.35,"attrs":{"step":"any","min":"0","value":"0.35"}},{"key":"trench_depth_ft","label":"Trench/pit depth (ft)","kind":"number","options":null,"default":4,"attrs":{"step":"any","min":"0","value":"4"}},{"key":"infiltration_rate_in_hr","label":"Soil infiltration rate (in/hr, perc test)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","min":"0","value":"0.5"}}],"citation":"Citation: dry well / infiltration trench (soakaway) sizing, by name. excavation = runoff / void ratio; footprint = excavation / depth; draindown ~ 12 x depth x void / infiltration rate. Void from the aggregate (~0.35 open stone), infiltration from a field perc test (not a default), runoff from the design storm. An overflow path is required; the perc test, the stormwater code, and the AHJ / geotech govern."},
  "dti": {"inputs":[{"key":"gross_monthly_income","label":"Gross monthly income ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"housing_payment","label":"Housing payment (PITI + HOA, $)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"other_monthly_debts","label":"Other monthly debts ($, car / cards / student / etc.)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: Front-end DTI = housing payment / gross monthly income. Back-end DTI = (housing + other debts) / gross monthly income. Conventional thresholds per FNMA Single-Family Selling Guide §B3-6-02 (typical 36/45, up to 50 with compensating factors). FHA per Handbook 4000.1 §II.A.5 (default 31/43). VA per Lenders Handbook M26-7 (back-end 41, no front-end limit). Lender governs final underwriting."},
  "duct-static-regain": {"inputs":[{"key":"upstream_velocity_fpm","label":"Upstream velocity (fpm)","kind":"number","options":null,"default":2000,"attrs":{"step":"any","min":"0","value":"2000"}},{"key":"downstream_velocity_fpm","label":"Downstream velocity (fpm)","kind":"number","options":null,"default":1500,"attrs":{"step":"any","min":"0","value":"1500"}},{"key":"recovery_factor","label":"Recovery factor (0-1, ~0.75)","kind":"number","options":null,"default":0.75,"attrs":{"step":"any","min":"0","value":"0.75"}}],"citation":"Citation: duct static-regain method, by name (SMACNA / ASHRAE Fundamentals). VP = (V/4005)^2 in w.c. (standard air); static regain = R x (VP_upstream - VP_downstream), recovery factor R ~ 0.75 (0.5-0.9). The 4005 constant assumes standard air (altitude/temperature shift it); the fitting quality sets R, and SMACNA/ASHRAE and the engineer govern."},
  "duct-transition-length": {"inputs":[{"key":"large_dim_in","label":"Large end dimension (in)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"small_dim_in","label":"Small end dimension (in)","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"slope_deg","label":"Transition slope (deg per side)","kind":"number","options":null,"default":15,"attrs":{"step":"any","min":"0","value":"15"}}],"citation":"Citation: duct transition length by name. concentric length = ((large - small)/2) / tan(slope); eccentric length = (large - small) / tan(slope). SMACNA keeps the slope near 15 degrees per side (~4:1) to limit turbulence; the SMACNA standards and the pressure loss govern."},
  "dump-truck-loads": {"inputs":[{"key":"total_lcy","label":"Total loose volume to haul (cy)","kind":"number","options":null,"default":625,"attrs":{"step":"any","min":"0","value":"625"}},{"key":"box_vol_cy","label":"Heaped box capacity (cy)","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"weight_limit_lb","label":"Legal payload weight limit (lb)","kind":"number","options":null,"default":40000,"attrs":{"step":"any","min":"0","value":"40000"}},{"key":"material_density_lb_per_lcy","label":"Loose material density (lb/cy)","kind":"number","options":null,"default":2800,"attrs":{"step":"any","min":"0","value":"2800"}}],"citation":"Citation: governing-payload identity by name. weight-limited volume = weight limit / density; payload = min(weight-limited, box); loads = ceil(total / payload). The box capacity comes from the truck; the legal payload comes from the axle and GVW limits."},
  "dust-control-water": {"inputs":[{"key":"length_ft","label":"Watered length (ft)","kind":"number","options":null,"default":2000,"attrs":{"step":"any","min":"0","value":"2000"}},{"key":"width_ft","label":"Watered width (ft)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"rate_gal_per_sy","label":"Application rate (gal/sy)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","min":"0","value":"0.5"}},{"key":"truck_cap_gal","label":"Water truck capacity (gal)","kind":"number","options":null,"default":4000,"attrs":{"step":"any","min":"0","value":"4000"}},{"key":"applications_per_day","label":"Passes per day (count)","kind":"number","options":null,"default":6,"attrs":{"step":"any","min":"0","value":"6"}}],"citation":"Citation: watering identity by name. gallons per application = area (sy) x rate (gal/sy); area = length x width / 9; trips = ceil(gallons / truck capacity). The rate and frequency come from the site's fugitive-dust plan and AHJ air permit."},
  "economic-insulation-thickness": {"inputs":[{"key":"delta_t_f","label":"Temperature difference (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"250"}},{"key":"bare_r_value","label":"Bare surface R-value (film, ~0.5)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","value":"0.5"}},{"key":"k_btu_in","label":"Insulation k (BTU-in/hr-ft^2-F)","kind":"number","options":null,"default":0.27,"attrs":{"step":"any","value":"0.27"}},{"key":"operating_hours","label":"Operating hours (h/yr)","kind":"number","options":null,"default":8000,"attrs":{"step":"any","value":"8000"}},{"key":"energy_cost_per_mmbtu","label":"Energy cost ($/MMBtu)","kind":"number","options":null,"default":12,"attrs":{"step":"any","value":"12"}},{"key":"system_efficiency","label":"System efficiency (0-1)","kind":"number","options":null,"default":0.8,"attrs":{"step":"any","value":"0.8"}},{"key":"installed_cost_per_in_sf","label":"Installed cost ($ per in per ft^2)","kind":"number","options":null,"default":3,"attrs":{"step":"any","value":"3"}},{"key":"life_years","label":"Service life (years)","kind":"number","options":null,"default":10,"attrs":{"step":"any","value":"10"}},{"key":"discount_rate","label":"Discount rate (0.08 = 8%, 0 = straight line)","kind":"number","options":null,"default":0.08,"attrs":{"step":"any","value":"0.08"}}],"citation":"Citation: economic (least-cost) insulation thickness. Total annual cost = energy through the assembly plus the annualized installed cost of the insulation: energy $ = dT/(R0 + t/k) x hours x $/MMBtu / (1e6 x efficiency), capital $ = price per inch per ft^2 x t x CRF, with the capital recovery factor CRF = i/(1-(1+i)^-n). Setting the derivative to zero gives the closed form t_opt = k(sqrt(C/(k x price x CRF)) - R0) where C = dT x hours x $/MMBtu / (1e6 x efficiency); this was verified against a brute-force scan. A COST optimum, not a performance requirement - it is thinner than a surface-temperature or condensation limit would require, and those are separate tiles. Flat-surface geometry; a pipe optimum runs thicker because curvature adds area with each inch. Installed cost, fuel price, and the owner's hurdle rate govern."},
  "economizer-enthalpy-changeover": {"inputs":[{"key":"mode","label":"Changeover type","kind":"select","options":[{"value":"differential_enthalpy","label":"Differential enthalpy (accounts for humidity)"},{"value":"fixed_drybulb","label":"Fixed dry-bulb setpoint"}],"default":"differential_enthalpy","attrs":null}],"citation":"Citation: Economizer high-limit changeover (ASHRAE 90.1 6.5.1.1.3): differential-enthalpy enables free cooling when outdoor enthalpy < return enthalpy (accounts for latent load); fixed-dry-bulb enables below a dry-bulb setpoint. A control aid; the 90.1 high-limit for the climate zone and the equipment sequence govern."},
  "edm-slope-reduction": {"inputs":[{"key":"angle_mode","label":"Angle type","kind":"select","options":[{"value":"zenith","label":"Zenith angle (from vertical, 90 = level)"},{"value":"vertical","label":"Vertical angle (from horizontal, 0 = level)"}],"default":null,"attrs":null},{"key":"slope_distance_ft","label":"Slope distance S (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"250"}},{"key":"angle_deg","label":"Angle (deg)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"86"}},{"key":"hi_ft","label":"Instrument height HI (ft, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"hr_ft","label":"Reflector/rod height HR (ft, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}}],"citation":"Citation: EDM / total-station slope reduction by right-triangle trigonometry - horizontal H = S sin(Z) = S cos(a), vertical V = S cos(Z) = S sin(a), where Z is the zenith angle (from vertical) and a the vertical angle (from horizontal); ground-to-ground elevation difference = V + instrument height - reflector height. Standard plane-survey reduction per Ghilani, Elementary Surveying, by name. No curvature/refraction or grid scale factor. A computational aid; the project control governs."},
  "egc-parallel-raceways": {"inputs":[{"key":"ocpd_A","label":"Overcurrent device rating (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"400"}},{"key":"raceway_count","label":"Number of parallel raceways","kind":"number","options":null,"default":2,"attrs":{"step":"1","min":"2","value":"2"}},{"key":"material","label":"Conductor material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":"copper","attrs":null}],"citation":"Citation: NEC 250.122(F), equipment grounding conductors for conductors in parallel, by section number. Where circuit conductors are paralleled in separate raceways, a full-size EGC sized from Table 250.122 to the rating of the circuit's overcurrent device is required in EACH raceway - the EGC is not divided among the parallel sets. The table lookup is delegated to this catalog's existing egc-sizing model rather than duplicated. EDITION NOTE: this is the 2023-and-earlier rule; the 2026 NEC revises 250.122(F) so the EGC in each raceway need not exceed the largest ungrounded conductor in that raceway. 250.122(B) proportional upsizing and the 250.122(A) never-larger-than-the-circuit-conductors limit still apply. The NEC as adopted and the AHJ govern."},
  "egc-sizing": {"inputs":[{"key":"ocpd_A","label":"OCPD rating (A)","kind":"number","options":null,"default":null,"attrs":{"step":"1","min":"0"}},{"key":"material","label":"EGC material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":null,"attrs":null}],"citation":"Citation: per NEC 2023 Table 250.122 (EGC size by upstream OCPD). AHJ governs. Free at nfpa.org/freeaccess."},
  "egc-upsize-proportional": {"inputs":[{"key":"base_egc_cmil","label":"Base EGC area (cmil, per 250.122)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"base_phase_cmil","label":"Base (minimum) phase area (cmil)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"installed_phase_cmil","label":"Installed phase area (cmil)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: NEC 2023 250.122(B) (increase in size of equipment grounding conductors). ratio = max(1, installed phase cmil / base phase cmil); upsized EGC = base EGC x ratio. Base EGC (250.122 table) and base phase area are user-supplied; the EGC need not exceed the ungrounded conductors. The AHJ governs. Free read-only at nfpa.org/freeaccess."},
  "elevation-pressure-loss": {"inputs":[{"key":"mode","label":"Input mode","kind":"select","options":[{"value":"floors","label":"Number of floors"},{"value":"feet","label":"Elevation change (ft)"}],"default":"floors","attrs":null},{"key":"direction","label":"Direction","kind":"select","options":[{"value":"up","label":"Up (loss)"},{"value":"down","label":"Down (gain)"}],"default":"up","attrs":null}],"citation":"Citation: Hydrostatic head 0.434 psi/ft (public). Fire-ground '5 psi per floor' standpipe approximation per IFSTA Pumping Apparatus Driver/Operator and the NFPA 14 design basis, by name. Feeds the pump discharge pressure tiles; distinct from pdp / standpipe-pdp which bundle friction and nozzle pressure."},
  "envelope-conduction-load": {"inputs":[{"key":"area_ft2","label":"Opaque surface area (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"1000"}},{"key":"u_factor","label":"Assembly U-factor (Btu/h/ft^2/F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.05"}},{"key":"cltd_f","label":"Sol-air CLTD (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"70"}}],"citation":"Citation: ASHRAE / ACCA Manual J opaque-envelope cooling load Q = U x A x CLTD, the CLTD being the sol-air cooling-load temperature difference (by name). The sol-air CLTD comes from the ASHRAE/ACCA table for the surface type, color, orientation, and design day; the U-factor is the whole-assembly value. One cooling-load component, not a Manual J."},
  "equal-spacing": {"inputs":[{"key":"mode","label":"Solve for","kind":"select","options":[{"value":"max-gap","label":"Count from a maximum gap"},{"value":"count","label":"Gap from a desired count"}],"default":"max-gap","attrs":null}],"citation":"Citation: Equal-spacing layout - N items of width w in a run R have N+1 equal gaps of (R - N x w)/(N+1) and a center-to-center pitch of gap + w; in max-gap mode the smallest N whose gap stays at or below the limit is ceil((R - gmax)/(w + gmax)) - first-principles arithmetic, public domain. The gap limit (for example the IRC R312.1.3 4-inch-sphere guard rule) is user-supplied; the adopted code governs."},
  "equipment-heat-load": {"inputs":[{"key":"total_equipment_watts","label":"Total equipment draw (watts)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"4000"}},{"key":"target_temp_rise_f","label":"Acceptable temperature rise (degF)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"exhaust_cfm","label":"Ventilation / AC airflow (cfm, 0 = sealed)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"600"}}],"citation":"Citation: Watt-to-heat conversion (3.412 BTU/hr per watt) and the 1.08 standard-air sensible-heat relation (ANSI/IICRC S500), by name. Every watt of equipment draw becomes sensible heat in the chamber; an overheated chamber leaves the efficient-evaporation band. Envelope losses and the building HVAC govern; this is a screen."},
  "equipment-hourly-rate": {"inputs":[{"key":"purchase","label":"Purchase price ($)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"salvage","label":"Salvage value ($)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"life_hr","label":"Useful life (hours)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"annual_hr","label":"Hours operated per year","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"iit_pct","label":"Interest+insurance+tax (%/yr of avg value)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"fuel_gph","label":"Fuel burn (gal/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"fuel_price","label":"Fuel price ($/gal)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"maint_hr","label":"Maintenance ($/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"wear_hr","label":"Tires/wear ($/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: equipment owning + operating hourly rate (CAT / AED cost-recovery method): owning = (purchase - salvage)/life + IIT% x avg value / annual hours; operating = fuel + maintenance + wear per hour. The owner's actual costs, financing, and utilization govern."},
  "erosion-blanket-coverage": {"inputs":[{"key":"area_sf","label":"Slope area to cover (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"overlap_pct","label":"Side/end overlap allowance (%)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"roll_width_ft","label":"Blanket roll width (ft)","kind":"number","options":null,"default":8,"attrs":{"step":"any","min":"0","value":"8"}},{"key":"roll_length_ft","label":"Blanket roll length (ft)","kind":"number","options":null,"default":112.5,"attrs":{"step":"any","min":"0","value":"112.5"}},{"key":"staples_per_sy","label":"Staples per square yard","kind":"number","options":null,"default":1.5,"attrs":{"step":"any","min":"0","value":"1.5"}}],"citation":"Citation: lapped-roll takeoff identity by name. rolls = ceil(area x (1 + overlap) / roll area); staples = ceil(area (sy) x staples per sy). The manufacturer's guide sets the overlap and staple pattern."},
  "ev-charge-cost": {"inputs":[{"key":"battery_capacity_kwh","label":"Battery capacity (kWh)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"75"}},{"key":"start_soc_pct","label":"Start state of charge (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"100","value":"20"}},{"key":"target_soc_pct","label":"Target state of charge (%)","kind":"number","options":null,"default":80,"attrs":{"step":"any","min":"0","max":"100","value":"80"}},{"key":"electricity_rate","label":"Electricity rate ($/kWh)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.15"}},{"key":"efficiency_pct","label":"Charging efficiency (%)","kind":"number","options":null,"default":88,"attrs":{"step":"any","min":"0","max":"100","value":"88"}},{"key":"miles_per_kwh","label":"Vehicle efficiency (mi/kWh, 0 = skip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"3.5"}}],"citation":"Citation: EV charge-cost-at-the-meter model. energy to battery = capacity x (target - start); grid energy = energy / efficiency (the meter draws more than the pack stores, because AC Level 2 loses about 10-15% to the onboard rectifier and thermal load); cost = grid energy x rate; cost per stored kWh = rate / efficiency. Ignores tiered, time-of-use, and demand pricing. A planning estimate; the local tariff governs."},
  "ev-charge-time": {"inputs":[{"key":"battery_capacity_kwh","label":"Battery capacity (kWh)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"75"}},{"key":"start_soc_pct","label":"Start state of charge (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"100","value":"20"}},{"key":"target_soc_pct","label":"Target state of charge (%)","kind":"number","options":null,"default":80,"attrs":{"step":"any","min":"0","max":"100","value":"80"}},{"key":"evse_power_kw","label":"EVSE output power (kW)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"11.5"}},{"key":"onboard_charger_kw","label":"Vehicle onboard charger (kW, 0 = DC fast)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"7.7"}},{"key":"efficiency_pct","label":"Charging efficiency (%)","kind":"number","options":null,"default":88,"attrs":{"step":"any","min":"0","max":"100","value":"88"}}],"citation":"Citation: AC Level 2 charge time (SAE J1772 onboard-charger limit): energy = capacity x (target - start); charge power = min(EVSE, onboard charger); time = energy / (power x efficiency). AC is capped by the onboard charger; DC fast charging tapers and is not this model. A planning estimate; the vehicle's charging curve governs."},
  "ev-dcfc-time": {"inputs":[{"key":"usable_capacity_kwh","label":"Usable capacity (kWh)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"60"}},{"key":"start_soc_pct","label":"Start state of charge (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"100","value":"10"}},{"key":"target_soc_pct","label":"Target state of charge (%)","kind":"number","options":null,"default":80,"attrs":{"step":"any","min":"0","max":"100","value":"100"}},{"key":"charger_power_kw","label":"Charger rated power (kW)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"150"}},{"key":"acceptance_kw","label":"Vehicle peak DC acceptance (kW)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"100"}}],"citation":"Citation: DC fast-charge CC-CV taper model. cc_power = min(charger, vehicle acceptance); three constant-power bands (0-80% at full power, 80-90% at ~50%, 90-100% at ~25%); per-band time = energy / (cc_power x band_fraction). DC fast charging holds constant power only to ~80% and then tapers to protect the cells, so the naive energy / rated-power estimate under-predicts a to-full session. A planning estimate; the vehicle's charging curve governs."},
  "ev-range-per-hour": {"inputs":[{"key":"evse_power_kw","label":"EVSE power (kW, e.g. 7.7)","kind":"number","options":null,"default":7.7,"attrs":{"step":"any","min":"0","value":"7.7"}},{"key":"charge_efficiency","label":"Charge efficiency (0-1, ~0.88)","kind":"number","options":null,"default":0.88,"attrs":{"step":"any","min":"0","value":"0.88"}},{"key":"vehicle_efficiency_mi_per_kwh","label":"Vehicle efficiency (mi/kWh)","kind":"number","options":null,"default":3.5,"attrs":{"step":"any","min":"0","value":"3.5"}},{"key":"target_range_mi","label":"Target range to add (mi)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}}],"citation":"Citation: EV range added per hour of AC charging, by name. range/hr = EVSE power (kW) x charge efficiency x vehicle efficiency (mi/kWh); hours = target range / range per hr. Steady AC Level 2; the vehicle's onboard-charger limit caps the AC rate (see ev-charge-time), DC fast charging tapers, and the actual efficiency governs."},
  "evaporative-cooler-effectiveness": {"inputs":[{"key":"dry_bulb_F","label":"Entering dry-bulb (F)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"95"}},{"key":"wet_bulb_F","label":"Entering wet-bulb (F)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"65"}},{"key":"effectiveness","label":"Pad saturation effectiveness (0-1)","kind":"number","options":null,"default":0.85,"attrs":{"step":"any","min":"0","max":"1","value":"0.85"}}],"citation":"Citation: direct-evaporative (swamp) cooler leaving dry-bulb T_out = T_db - saturation_effectiveness x (T_db - T_wb), the standard ASHRAE Fundamentals saturation-effectiveness relation. Pad effectiveness ~0.80-0.90 for rigid media, less for aspen; the leaving air rides the constant-wet-bulb line so its RH is high. Direct single-stage only. A shop estimate; the equipment data govern."},
  "evaporative-cooling": {"inputs":[{"key":"evaporation_rate_lb_hr","label":"Evaporation rate (lb/hr)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"hfg_btu_per_lb","label":"Latent heat (BTU/lb)","kind":"number","options":null,"default":null,"attrs":null}],"citation":"Citation: Q = m_dot * h_fg with h_fg of water ~ 1054 BTU/lb at typical evaporation conditions."},
  "excavation": {"inputs":[{"key":"length_ft","label":"Length (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"width_ft","label":"Width (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"depth_ft","label":"Depth (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"side_slope_angle_deg","label":"Side-slope angle (deg, 90 = vertical)","kind":"number","options":null,"default":90,"attrs":{"step":"any","min":"1","max":"90","value":"90"}}],"citation":"Citation: Frustum volume V = D/3 * (A1 + A2 + sqrt(A1*A2)). Set-back per side = D / tan(angle)."},
  "expansion-guide-spacing": {"inputs":[{"key":"pipe_od_in","label":"Pipe OD (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"d1_mult","label":"First-guide multiplier (D)","kind":"number","options":null,"default":4,"attrs":{"step":"any","min":"0","value":"4"}},{"key":"d2_mult","label":"Second-guide multiplier (D)","kind":"number","options":null,"default":14,"attrs":{"step":"any","min":"0","value":"14"}}],"citation":"Citation: Expansion-joint guide placement - the first guide within d1_mult (4) pipe diameters of the joint, the second within d2_mult (14) diameters of the first, per the Expansion Joint Manufacturers Association (EJMA) standard and the manufacturer installation guides, by name. The 4D/14D rule places the first two guides; intermediate guide spacing beyond the second comes from the EJMA table or the pipe-column stability calc (user-supplied / manufacturer). This places the planning guides, it does not design the anchor loads; the anchor and joint selection govern."},
  "expansion-tank": {"inputs":[{"key":"system_volume_gal","label":"System water volume (gal)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"fill_temperature_F","label":"Fill temp (F)","kind":"number","options":null,"default":60,"attrs":{"step":"any","value":"60"}},{"key":"max_temperature_F","label":"Max water temp (F)","kind":"number","options":null,"default":200,"attrs":{"step":"any","value":"200"}},{"key":"fill_pressure_psi","label":"Fill pressure (psi)","kind":"number","options":null,"default":12,"attrs":{"step":"any","value":"12"}},{"key":"relief_pressure_psi","label":"Relief pressure (psi)","kind":"number","options":null,"default":30,"attrs":{"step":"any","value":"30"}}],"citation":"Citation: V_tank = V_sys * ((rho_cold/rho_hot) - 1) / (1 - (P_i/P_f)) using public expansion-tank derivation. Water densities interpolated from public engineering tables."},
  "extinguisher-coverage": {"inputs":[{"key":"floor_area_sf","label":"Floor area (sq ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"hazard_class","label":"Hazard class","kind":"select","options":[{"value":"A","label":"Class A - ordinary combustibles (75 ft)"},{"value":"B","label":"Class B - flammable liquids (enter 30 or 50 ft)"},{"value":"K","label":"Class K - cooking media (30 ft)"}],"default":"A","attrs":null},{"key":"travel_distance_ft","label":"Travel distance for Class B (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"area_cap_sf","label":"Area cap per extinguisher (sq ft; NFPA 11,250)","kind":"number","options":null,"default":11250,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: NFPA 10 - a maximum travel distance to a Class A extinguisher of 75 ft at all hazard levels, a maximum travel distance of 30 ft for Class K, a Class B travel distance of 30 or 50 ft depending on the extinguisher's B rating and the hazard level (entered, not assumed), and the 6.1.3.3 ceiling of 11,250 sq ft of coverage per extinguisher. The square-grid relation area = 2 x travel^2 is geometry, not a code value, and it reproduces the 11,250 exactly at 75 ft. Travel distance is measured along the PATH OF TRAVEL, not in a straight line, so the grid figure is an open-floor best case. The extinguisher RATING is a separate determination from NFPA 10's maximum-area-per-unit-of-A table by hazard classification, which is not reproduced here. Class D travel distances are not shipped. Also not checked: mounting height, signage, obstruction, inspection intervals, or whether extinguishers are required at all. A planning aid, not a fire-protection design; NFPA 10 as adopted and the AHJ govern."},
  "fan-motor-max-airflow": {"inputs":[{"key":"power_basis","label":"Power basis","kind":"select","options":[{"value":"motor","label":"Motor (nameplate) HP"},{"value":"brake","label":"Brake HP"}],"default":"motor","attrs":null}],"citation":"Citation: AMCA / ASHRAE fan-power relation solved for airflow: CFM_max = 6356 x BHP x fan efficiency / TSP, from BHP = (CFM x SP) / (6356 x eta) (public). A motor (nameplate) HP converts to brake HP with the drive efficiency. Estimate; the fan curve and motor data govern. TSP must be total (external + internal)."},
  "fan-sheave-for-target-cfm": {"inputs":[{"key":"current_cfm","label":"Current airflow (cfm, measured)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"8000"}},{"key":"target_cfm","label":"Target airflow (cfm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"9600"}},{"key":"current_fan_rpm","label":"Current fan speed (rpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"700"}},{"key":"motor_rpm","label":"Motor speed (rpm)","kind":"number","options":null,"default":1750,"attrs":{"step":"any","value":"1750"}},{"key":"drive_sheave_in","label":"Current drive (motor) sheave pitch dia (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"4"}},{"key":"current_bhp","label":"Current brake horsepower (0 = skip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"3"}},{"key":"motor_hp","label":"Motor nameplate hp (0 = skip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"5"}},{"key":"current_sp_inwg","label":"Current static pressure (in w.c., 0 = skip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"1.5"}}],"citation":"Citation: fan affinity laws (AMCA / ASHRAE Handbook - Fundamentals) solved for the DRIVE sheave rather than for a known speed: Q scales with rpm, so the required fan speed is the current speed times the airflow ratio; on a belt drive fan rpm = motor rpm x (drive sheave / driven sheave), so with the fan sheave fixed the required drive sheave scales with the same ratio. Static pressure follows the square and brake horsepower the CUBE, so the motor check is the point: a 20% airflow increase is a 73% horsepower increase. Pitch diameter, not outside diameter; sheaves come in fixed increments. Same fan on the same system curve. Verify airflow after the change; the fan curve and equipment ratings govern."},
  "fastener-pullout": {"inputs":[{"key":"fastener_type","label":"Fastener type","kind":"select","options":[{"value":"nail","label":"Nail"},{"value":"screw","label":"Screw"}],"default":null,"attrs":null},{"key":"penetration_in","label":"Penetration into receiving member (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Withdrawal capacity W = G^2.5 * D * 1380 (lb per inch of penetration), where G is wood specific gravity and D is fastener shank diameter."},
  "feed-conversion-ratio": {"inputs":[{"key":"initial_weight_lb","label":"Initial weight (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"650"}},{"key":"final_weight_lb","label":"Final weight (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"1250"}},{"key":"days_on_feed","label":"Days on feed","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"200"}},{"key":"total_feed_lb","label":"Total feed fed, as-fed (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"3900"}}],"citation":"Citation: livestock production metrics - average daily gain ADG = (final - initial weight)/days, and feed conversion ratio FCR = total feed / total gain (lb feed per lb gain). Standard USDA / land-grant extension animal-science definitions, by name. Enter feed on the as-fed basis (standard); a lower FCR is more efficient. A benchmarking aid; the ration and environment govern."},
  "feed-for-surface-finish": {"inputs":[{"key":"finish_basis","label":"Finish basis","kind":"select","options":[{"value":"ra","label":"Ra (arithmetic average)"},{"value":"rt","label":"Rt (peak-to-valley)"}],"default":"ra","attrs":null}],"citation":"Citation: theoretical surface roughness solved for feed: f = sqrt(8 x nose_radius x Rt), from Rt = f^2 / (8 x r), Ra ~= Rt / 4 - first-principles scallop geometry as in Machinery's Handbook (Industrial Press), by name; public domain. The measured finish is rougher than this theoretical value, so leave margin."},
  "felling-notch-hinge": {"inputs":[{"key":"cut_dia_in","label":"Diameter at the felling cut (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"notch_pct","label":"Notch depth (% of diameter)","kind":"number","options":null,"default":22,"attrs":{"step":"any","min":"0","value":"22"}},{"key":"open_face","label":"Open-face angle target (deg)","kind":"number","options":null,"default":70,"attrs":{"step":"any","min":"0","value":"70"}}],"citation":"Citation: ANSI Z133-2017 (Arboricultural Operations) open-face felling practice by name. notch depth ~20-25% of diameter, hinge thickness ~10%, hinge width ~80%, open face 70 deg or more. A qualified faller governs."},
  "fertigation-injection-rate": {"inputs":[{"key":"product_rate_gal_per_acre","label":"Product rate (gal/acre)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"area_acres","label":"Area (acres)","kind":"number","options":null,"default":40,"attrs":{"step":"any","min":"0","value":"40"}},{"key":"set_time_hours","label":"Irrigation set time (hours)","kind":"number","options":null,"default":6,"attrs":{"step":"any","min":"0","value":"6"}}],"citation":"Citation: fertigation / chemigation injection rate, by name. total product = rate (gal/acre) x acres; injection rate = total / set hours. Start after the system is pressurized, flush at the end; an EPA-required anti-siphon/check-valve/interlock package must protect the water source (chemigation rules). The product label (FIFRA), the state chemigation rules, and a drawdown calibration govern."},
  "fiber-loss-budget": {"inputs":[{"key":"length_m","label":"Link length (m)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"attenuation_db_km","label":"Attenuation (dB/km)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"connector_count","label":"Connector pairs","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}},{"key":"loss_per_connector_db","label":"Loss per connector (dB)","kind":"number","options":null,"default":0.75,"attrs":{"step":"any","min":"0","value":"0.75"}},{"key":"splice_count","label":"Splices","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}},{"key":"loss_per_splice_db","label":"Loss per splice (dB)","kind":"number","options":null,"default":0.3,"attrs":{"step":"any","min":"0","value":"0.3"}},{"key":"max_channel_loss_db","label":"Max channel loss (dB)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Optical link loss budget - fiber attenuation plus connector and splice losses against the application's maximum channel loss - per the TIA-568 / TIA-526 fiber-test methods and the IEEE 802.3 channel-loss limits, by name; first-principles. Attenuation coefficients and component losses are user-supplied; the OTDR/power-meter field test governs the certified link."},
  "fiber-max-length": {"inputs":[{"key":"max_channel_loss_db","label":"Max channel loss (dB)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"attenuation_db_km","label":"Attenuation (dB/km)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"connector_count","label":"Connector pairs","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}},{"key":"loss_per_connector_db","label":"Loss per connector (dB)","kind":"number","options":null,"default":0.75,"attrs":{"step":"any","min":"0","value":"0.75"}},{"key":"splice_count","label":"Splices","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}},{"key":"loss_per_splice_db","label":"Loss per splice (dB)","kind":"number","options":null,"default":0.3,"attrs":{"step":"any","min":"0","value":"0.3"}}],"citation":"Citation: optical link loss budget solved for length: len_max = 1000 x (max_channel_loss - connector_loss - splice_loss) / attenuation, per TIA-568 / TIA-526 fiber-test methods and IEEE 802.3 channel-loss limits, by name. Component losses user-supplied; the OTDR/power-meter field test governs the certified link."},
  "filter-pressure-drop": {"inputs":[{"key":"filter_type","label":"Filter class","kind":"select","options":[{"value":"merv8","label":"MERV 8"},{"value":"merv11","label":"MERV 11"},{"value":"merv13","label":"MERV 13"},{"value":"merv16","label":"MERV 16"},{"value":"hepa","label":"HEPA"}],"default":"merv13","attrs":null}],"citation":"Citation: face velocity = CFM / face area; pressure drop scales ~linearly with face velocity (Darcy regime), dp(V) = dp_ref x V / 300 fpm; fan power (kW) = (CFM x dp_in_wc / 6356) / fan efficiency x 0.7457. Clean / change-out drops are representative cut-sheet values; the MERV rating is per ASHRAE 52.2-2017 and the actual filter's cut sheet governs the drop. Free at ashrae.org for the ASHRAE 52.2 TOC."},
  "fire-alarm-nac-voltage-drop": {"inputs":[{"key":"nominal_voltage_v","label":"Panel nominal voltage (V)","kind":"number","options":null,"default":24,"attrs":{"step":"any","min":"0","value":"24"}},{"key":"total_current_a","label":"Total appliance current at EOL (A)","kind":"number","options":null,"default":0.8,"attrs":{"step":"any","min":"0","value":"0.8"}},{"key":"run_length_ft","label":"Run length (ft, one way)","kind":"number","options":null,"default":250,"attrs":{"step":"any","min":"0","value":"250"}},{"key":"resistance_per_1000ft","label":"Conductor resistance (ohm/1000 ft)","kind":"number","options":null,"default":2.525,"attrs":{"step":"any","min":"0","value":"2.525"}},{"key":"device_min_v","label":"Device minimum voltage (V)","kind":"number","options":null,"default":16,"attrs":{"step":"any","min":"0","value":"16"}}],"citation":"Citation: fire-alarm NAC end-of-line voltage drop by name (NFPA 72). CUSTV = 0.85 x nominal; loop R = 2 x length x (ohm/1000 ft)/1000 (Class B out-and-back, NEC Ch 9 Table 8); V_EOL = CUSTV - I x loop R, must be >= the device's listed minimum. The panel voltage, appliance draws, and the wire table govern."},
  "firewood-cord": {"inputs":[{"key":"length_ft","label":"Stack length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"8"}},{"key":"height_ft","label":"Stack height (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"4"}},{"key":"depth_ft","label":"Stack depth / log length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"4"}}],"citation":"Citation: a full (standard) cord = 128 stacked cubic feet (a 4 x 4 x 8 ft rick); cords = length x height x depth / 128. Per NIST Handbook 130, Uniform Regulation for the Method of Sale of Commodities - firewood is sold by the cord, not 'face cord' or 'rick'. Stacked volume includes air gaps. A measurement aid; the state weights-and-measures office governs."},
  "fixture-clearance-check": {"inputs":[{"key":"center_to_left_in","label":"Centerline to the left obstruction (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"center_to_right_in","label":"Centerline to the right obstruction (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"front_clearance_in","label":"Clearance in front (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"adjacent_center_in","label":"Adjacent fixture center to center (in; 0 = none)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"fixture_count","label":"Fixtures in the row","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1"}},{"key":"compartment_width_in","label":"Compartment width (in; 0 = not a compartment)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"compartment_depth_in","label":"Compartment depth (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"min_side_in","label":"Minimum side clearance (in; IPC 15)","kind":"number","options":null,"default":15,"attrs":{"step":"any","min":"0"}},{"key":"min_center_in","label":"Minimum center to center (in; IPC 30)","kind":"number","options":null,"default":30,"attrs":{"step":"any","min":"0"}},{"key":"min_front_in","label":"Minimum front clearance (in; IPC 21)","kind":"number","options":null,"default":21,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: IPC 405.3.1 - a water closet, urinal, lavatory, or bidet not set closer than 15 in from its center to any side wall, partition, vanity, or other obstruction; adjacent fixtures not closer than 30 in center to center where no partition separates them; not less than 21 in of clearance in front to any wall, fixture, or door; and water-closet compartments not less than 30 in wide by 60 in deep for floor-mounted closets. The derived minimum wall-to-wall width for a row of n fixtures is 2 x 15 + (n - 1) x 30. All minimums are editable inputs because state and local amendments exist. These are the PLUMBING minimums, not an accessible layout: ANSI A117.1 and the ADA Standards require substantially more, including a different centerline range, a defined clear floor space, and grab-bar blocking. A screen, not a code-official determination; the adopted code and the AHJ govern."},
  "flange-bolt-torque": {"inputs":[{"key":"bolt_diameter_in","label":"Bolt nominal diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.75"}},{"key":"thread_series","label":"Thread series","kind":"select","options":[{"value":"UNC","label":"UNC (coarse)"},{"value":"8UN","label":"8UN (large flange)"}],"default":"UNC","attrs":null},{"key":"bolt_count","label":"Bolt count","kind":"number","options":null,"default":8,"attrs":{"step":"1","min":"2","value":"8"}},{"key":"tensile_area_in2","label":"Tensile area (in^2, optional override)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"target_percent_yield","label":"Target preload (% of yield)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}},{"key":"yield_ksi","label":"Bolt yield (ksi, B7 = 105)","kind":"number","options":null,"default":105,"attrs":{"step":"any","min":"0","value":"105"}},{"key":"nut_factor_k","label":"Nut factor K","kind":"number","options":null,"default":0.18,"attrs":{"step":"any","min":"0","value":"0.18"}}],"citation":"Citation: Bolt-preload torque by the short-form T = K*D*F and the cross/star tightening sequence, per ASME PCC-1 Guidelines for Pressure Boundary Bolted Flange Joint Assembly and the ASME B16.5 flange classes, by name; the nut factor K, gasket seating stress, and target preload are joint- and lubricant-specific and user-supplied. A computational aid - the assembly procedure, gasket manufacturer, and the engineer of record govern the installed torque."},
  "flash-steam-pct": {"inputs":[{"key":"hf_high","label":"Liquid enthalpy hf at high pressure (Btu/lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"hf_low","label":"Liquid enthalpy hf at low pressure (Btu/lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"hfg_low","label":"Latent heat hfg at low pressure (Btu/lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Flash steam fraction = (hf_high - hf_low) / hfg_low - the sensible-heat surplus a condensate carries across a pressure drop re-boils a fraction back to steam - first-principles steam thermodynamics, by name. Enthalpies are read from the ASME saturated-water steam tables at the two pressures. This is the thermodynamic-ideal fraction; trap subcooling and line losses move the field value, and a flash-recovery vessel is sized from the manufacturer's data."},
  "flexible-pipe-deflection": {"inputs":[{"key":"cover_ft","label":"Soil cover over the pipe (ft)","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"soil_density_pcf","label":"Backfill density (pcf)","kind":"number","options":null,"default":120,"attrs":{"step":"any","min":"0","value":"120"}},{"key":"deflection_lag","label":"Deflection lag factor DL","kind":"number","options":null,"default":1.5,"attrs":{"step":"any","min":"0","value":"1.5"}},{"key":"bedding_constant","label":"Bedding constant K","kind":"number","options":null,"default":0.1,"attrs":{"step":"any","min":"0","value":"0.1"}},{"key":"pipe_stiffness_psi","label":"Pipe stiffness PS (psi)","kind":"number","options":null,"default":46,"attrs":{"step":"any","min":"0","value":"46"}},{"key":"soil_modulus_psi","label":"Modulus of soil reaction E' (psi)","kind":"number","options":null,"default":1000,"attrs":{"step":"any","min":"0","value":"1000"}},{"key":"allowable_pct","label":"Allowable deflection (%)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}}],"citation":"Citation: Modified Iowa (Spangler) deflection identity by name. deflection % = DL x K x Wc / (0.149 x PS + 0.061 x E') x 100, where Wc = cover x density / 144. E' (soil support) is the field-controllable variable; the pipe manufacturer and engineer govern the limit."},
  "float-method-flow": {"inputs":[{"key":"float_distance_ft","label":"Float travel distance (ft)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"travel_time_s","label":"Travel time (s)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"channel_width_ft","label":"Channel width (ft)","kind":"number","options":null,"default":4,"attrs":{"step":"any","min":"0","value":"4"}},{"key":"mean_depth_ft","label":"Mean depth (ft)","kind":"number","options":null,"default":1.5,"attrs":{"step":"any","min":"0","value":"1.5"}},{"key":"float_coefficient","label":"Float coefficient (0-1, ~0.85)","kind":"number","options":null,"default":0.85,"attrs":{"step":"any","min":"0","value":"0.85"}}],"citation":"Citation: float (velocity-area) open-channel flow method, by name. Q = C x surface velocity x cross-sectional area; surface velocity = distance / time, area = width x mean depth. C ~0.85 converts surface to mean velocity (0.8 rough to ~0.9 smooth). A rough field estimate; a permit-compliance flow needs a calibrated meter, and the metering standard governs."},
  "flow-continuity": {"inputs":[{"key":"V1_fps","label":"Upstream velocity (ft/s)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"D1_in","label":"Upstream diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"D2_in","label":"Downstream diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: continuity V2 = V1 (D1/D2)^2 from Q = A V constant for an incompressible fluid, first-principles. Reducing the pipe accelerates the flow; expanding it slows it. The code velocity limits and the engineer of record govern."},
  "flue-gas-combustion-eff": {"inputs":[{"key":"fuel","label":"Fuel","kind":"select","options":[{"value":"natural_gas","label":"Natural gas"},{"value":"propane","label":"Propane (LPG)"},{"value":"oil2","label":"#2 fuel oil"}],"default":"natural_gas","attrs":null},{"key":"air_temp_f","label":"Combustion-air temperature (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"70"}}],"citation":"Notice: A tuning aid, not a certified combustion test or an AFUE rating; the analyzer, the appliance, and the manufacturer instructions govern. Citation: Siegert stack-loss method (DIN combustion-analysis practice as implemented by flue-gas analyzers), by name. CO2 = CO2max x (1 - O2 / 20.9); qA_pct = dT_C x (A1 / CO2 + B) with dT_C = (T_stack_F - T_air_F) x 5/9; eff_net = 100 - qA; eff_gross ~ eff_net x LHV/HHV. Constants (A1 / B / CO2max / LHV-HHV): natural gas 0.37 / 0.009 / 11.7% / 0.902, propane 0.475 / 0.000 / 13.7% / 0.920, #2 oil 0.50 / 0.007 / 15.4% / 0.939. The net figure is the European convention; US analyzers display the gross (HHV) basis, and the conversion here is approximate. Sample dry in the undiluted flue before the draft hood; a condensing appliance recovers latent heat this stack loss counts as lost."},
  "fluoride-feed-dose": {"inputs":[{"key":"target_dose_mg_l","label":"Target fluoride (mg/L)","kind":"number","options":null,"default":0.7,"attrs":{"step":"any","min":"0","value":"0.7"}},{"key":"raw_fluoride_mg_l","label":"Raw background fluoride (mg/L)","kind":"number","options":null,"default":0.1,"attrs":{"step":"any","min":"0","value":"0.1"}},{"key":"flow_mgd","label":"Flow (MGD)","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"0","value":"2"}},{"key":"afi_fraction","label":"Available fluoride ion (0-1): FSA 0.792, NaF 0.452, Na2SiF6 0.607","kind":"number","options":null,"default":0.792,"attrs":{"step":"any","min":"0","max":"1","value":"0.792"}},{"key":"purity_fraction","label":"Purity / solution strength (0-1)","kind":"number","options":null,"default":0.25,"attrs":{"step":"any","min":"0","max":"1","value":"0.25"}}],"citation":"Citation: fluoride feed dose (available-fluoride-ion pounds formula), by name. feed lb/day = (target - raw) x flow MGD x 8.34 / (AFI x purity). AFI: fluorosilicic acid 0.792, sodium fluoride 0.452, sodium fluorosilicate 0.607. US PHS target 0.7 mg/L. The daily lab checks, the SDWA maximum, the product assay, and the state fluoridation program govern."},
  "foam": {"inputs":[{"key":"fire_area_ft2","label":"Fire area (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"application_rate_gpm_per_ft2","label":"Application rate (gpm/ft^2)","kind":"number","options":null,"default":0.1,"attrs":{"step":"any","min":"0","value":"0.10"}},{"key":"foam_percentage","label":"Foam concentrate (percent)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","max":"10","value":"3"}},{"key":"duration_min","label":"Duration (min)","kind":"number","options":null,"default":15,"attrs":{"step":"any","min":"0","value":"15"}}],"citation":"Citation: Foam volume = area * application rate * foam percentage * duration. Application rate from departmental SOP."},
  "foam-max-coverage-area": {"inputs":[{"key":"available_concentrate_gal","label":"Available concentrate (gal)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"application_rate_gpm_per_ft2","label":"Application rate (gpm/ft^2)","kind":"number","options":null,"default":0.1,"attrs":{"step":"any","min":"0","value":"0.10"}},{"key":"foam_percentage","label":"Foam concentrate (percent)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","max":"10","value":"3"}},{"key":"duration_min","label":"Duration (min)","kind":"number","options":null,"default":15,"attrs":{"step":"any","min":"0","value":"15"}}],"citation":"Citation: Foam concentrate = area * application rate * foam percentage * duration, solved for the area: max area = concentrate / (rate * pct * duration). Application rate and duration from the fuel type and departmental SOP."},
  "forklift-capacity-derate": {"inputs":[{"key":"rated_cap_lb","label":"Rated capacity (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"rated_lc_in","label":"Rated load center (in)","kind":"number","options":null,"default":24,"attrs":{"step":"any","min":"0","value":"24"}},{"key":"actual_lc_in","label":"Actual load center (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"load_lb","label":"Load to handle (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: ASME B56.1 (Powered Industrial Trucks) and the truck data plate by name. net capacity = rated x rated load center / actual load center. Estimate - the capacity plate is the legal rating."},
  "friction-loss": {"inputs":[{"key":"method","label":"Method","kind":"select","options":[{"value":"hazen-williams","label":"Hazen-Williams (water)"},{"value":"darcy-weisbach","label":"Darcy-Weisbach (water)"}],"default":null,"attrs":null},{"key":"length_ft","label":"Length (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"flow_gpm","label":"Flow (gpm)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Hazen-Williams (1905, public domain). IPC 2021 referenced for application. Darcy-Weisbach with Colebrook-White for general fluid use. Free at codes.iccsafe.org."},
  "gas-altitude-derate": {"inputs":[{"key":"nameplate_input_btuh","label":"Nameplate input (BTU/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"elevation_ft","label":"Installation elevation (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"derate_pct_per_1000","label":"Derate (% per 1000 ft)","kind":"number","options":null,"default":4,"attrs":{"step":"any","min":"0","value":"4"}},{"key":"threshold_ft","label":"Derate threshold (ft)","kind":"number","options":null,"default":2000,"attrs":{"step":"any","min":"0","value":"2000"}}],"citation":"Citation: NFPA 54 (National Fuel Gas Code) / IFGC high-altitude provision (by name, not reproduced). The 4-percent-per-1000-ft-above-2000-ft derate is the common editable convention; the exact basis varies by edition and AHJ. Field orifice drilling is generally prohibited - use a listed manufacturer kit. Free read-only at nfpa.org/freeaccess."},
  "gas-appliance-connection": {"inputs":[{"key":"appliance","label":"Appliance","kind":"select","options":[{"value":"furnace","label":"Furnace"},{"value":"water-heater","label":"Water heater"},{"value":"boiler","label":"Boiler"},{"value":"range","label":"Range / cooking appliance"},{"value":"dryer","label":"Clothes dryer"},{"value":"illuminating","label":"Illuminating appliance"},{"value":"decorative-vented","label":"Decorative appliance in a vented fireplace"},{"value":"gas-fireplace","label":"Gas fireplace"},{"value":"outdoor-grill","label":"Outdoor grill"},{"value":"other","label":"Other"}],"default":"furnace","attrs":null},{"key":"shutoff_same_room","label":"Shutoff in the same room?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":"yes","attrs":null},{"key":"shutoff_distance_ft","label":"Shutoff distance to the appliance (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"shutoff_upstream","label":"Shutoff upstream of the connector?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":"yes","attrs":null},{"key":"trap_present","label":"Sediment trap installed?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":"yes","attrs":null},{"key":"trap_in_appliance","label":"Trap built into the appliance?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":"no","attrs":null},{"key":"connector_length_ft","label":"Connector overall length (ft; 0 = hard piped)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: IFGC 409.5 - the appliance shutoff valve located in the same room as the appliance, within 6 ft of it, and installed upstream of the union, connector, or quick-disconnect device it serves, with shutoff valves serving movable appliances such as cooking appliances and clothes dryers considered accessible where installed behind them. IFGC 408.4 - where a sediment trap is not incorporated as part of the appliance, a sediment trap installed downstream of the appliance shutoff valve as close to the inlet of the appliance as practical, with illuminating appliances, ranges, clothes dryers, decorative vented appliances for installation in vented fireplaces, gas fireplaces, and outdoor grills excepted. IFGC 411.1.3.1 - connectors with an overall length not to exceed 3 ft, except range and domestic clothes dryer connectors at 6 ft. Not checked: connector listing and type, connectors passing through building elements, connector reuse, upstream piping size and pressure, clearances, venting, combustion air, CSST bonding, leak testing, or fuel and altitude approval. A screen; the adopted code, the appliance listing, and the AHJ govern."},
  "gas-appliance-demand": {"inputs":[{"key":"fuel","label":"Fuel","kind":"select","options":[{"value":"natural_gas","label":"Natural gas (~1,000 BTU/ft^3)"},{"value":"propane","label":"Propane (~2,516 BTU/ft^3)"}],"default":"natural_gas","attrs":null},{"key":"heating_value","label":"Heating value override (BTU/ft^3, optional)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: IFGC 2021 Section 402 / NFPA 54 (National Fuel Gas Code) by name. cfh = total connected BTU/hr / heating value; default heating values (1,000 BTU/ft^3 natural gas, 2,516 BTU/ft^3 propane) are editable."},
  "gas-fuel-conversion": {"inputs":[{"key":"appliance_input_btuh","label":"Appliance input (BTU/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"100000"}},{"key":"hv_from","label":"From heating value (BTU/cf)","kind":"number","options":null,"default":1030,"attrs":{"step":"any","min":"0","value":"1030"}},{"key":"hv_to","label":"To heating value (BTU/cf)","kind":"number","options":null,"default":2500,"attrs":{"step":"any","min":"0","value":"2500"}},{"key":"sg_from","label":"From specific gravity","kind":"number","options":null,"default":0.6,"attrs":{"step":"any","min":"0","value":"0.60"}},{"key":"sg_to","label":"To specific gravity","kind":"number","options":null,"default":1.52,"attrs":{"step":"any","min":"0","value":"1.52"}},{"key":"p_from","label":"From manifold pressure (in w.c.)","kind":"number","options":null,"default":3.5,"attrs":{"step":"any","min":"0","value":"3.5"}},{"key":"p_to","label":"To manifold pressure (in w.c.)","kind":"number","options":null,"default":11,"attrs":{"step":"any","min":"0","value":"11.0"}}],"citation":"Citation: first-principles orifice flow Q ~ A x sqrt(P / SG) holding appliance input, with cfh = input / heating value (public). The default NG/LP heating values (1030/2500 BTU/cf), specific gravities (0.60/1.52), and manifold pressures (3.5/11.0 in. w.c.) are editable. Field orifice drilling is generally prohibited - use a listed conversion kit; the manufacturer and AHJ govern."},
  "gas-leak-hole-diameter": {"inputs":[{"key":"leak_rate_cfh","label":"Measured leak rate (ft^3/hr)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"upstream_psi","label":"Upstream gauge pressure (psi)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"gas","label":"Gas","kind":"select","options":[{"value":"natural_gas","label":"Natural gas"},{"value":"propane","label":"Propane"}],"default":null,"attrs":null},{"key":"c","label":"Discharge coefficient","kind":"number","options":null,"default":0.7,"attrs":{"step":"any","min":"0","max":"1","value":"0.7"}}],"citation":"Citation: d = sqrt( 4 Q / (3550 * c * pi * sqrt(dP / SG)) ), the orifice-flow leak approximation Q = 3550 c A sqrt(dP/SG) solved for the diameter. An estimate of the effective hole size, not a code leak-test method. Estimation only."},
  "gas-leak-rate": {"inputs":[{"key":"orifice_diameter_in","label":"Orifice diameter (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"upstream_psi","label":"Upstream gauge pressure (psi)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"gas","label":"Gas","kind":"select","options":[{"value":"natural_gas","label":"Natural gas"},{"value":"propane","label":"Propane"}],"default":null,"attrs":null},{"key":"c","label":"Discharge coefficient","kind":"number","options":null,"default":0.7,"attrs":{"step":"any","min":"0","max":"1","value":"0.7"}}],"citation":"Citation: Q = 3550 * c * A * sqrt(dP / SG). Orifice flow approximation for a small gas leak. Estimation only."},
  "gas-pipe-sizing": {"inputs":[{"key":"btu_load","label":"BTU load (BTU/hr)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"length_ft","label":"Pipe length (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"gas","label":"Gas","kind":"select","options":[{"value":"natural_gas","label":"Natural gas"},{"value":"propane","label":"Propane"}],"default":null,"attrs":null},{"key":"dP_in_wc","label":"Allowable pressure drop (in w.c.)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","min":"0","value":"0.5"}}],"citation":"Citation: per IFGC 2021 Table 402.4 (NFPA 54). Spitzglass low-pressure gas formula Q = 3550 * sqrt(d^5 * dP / (SG * L * (1 + 3.6/d + 0.03*d))), the diameter-correction term included as the tile computes it. AHJ governs. Free at codes.iccsafe.org."},
  "gear-chordal-thickness": {"inputs":[{"key":"diametral_pitch","label":"Diametral pitch Pd (teeth/in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"teeth","label":"Number of teeth N","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"3","value":"40"}}],"citation":"Citation: gear-tooth caliper chordal dimensions for a 20-degree full-depth involute spur gear - chordal tooth thickness tc = (N/Pd) sin(90/N deg), chordal addendum ac = 1/Pd + (N/(2Pd))(1 - cos(90/N deg)), the standard Machinery's Handbook / AGMA gear-tooth-caliper method. Standard tooth, no profile shift or backlash allowance. A shop inspection aid; the gear drawing and AGMA govern."},
  "gear-identification": {"inputs":[{"key":"teeth","label":"Number of teeth N (counted)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"outside_dia_in","label":"Measured outside diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Spur gear identification (diametral-pitch system, 20-degree full-depth involute; AGMA / Machinery's Handbook), the inverse of OD = (N+2)/Pd: Pd = (N+2)/OD, pitch dia = N/Pd, module = 25.4/Pd, snapped to the nearest standard Pd. A shop aid; confirm against the gear drawing or a gear gauge."},
  "gear-mph-rpm": {"inputs":[{"key":"solve_for","label":"Solve for","kind":"select","options":[{"value":"mph","label":"MPH"},{"value":"rpm","label":"RPM"}],"default":"mph","attrs":null}],"citation":"Citation: Classical drivetrain kinematics; SAE J267 metric tire-size convention for decoding a tire code to diameter, by name. Pure geometry, public. Geometric (no-slip) speed - ignores tire and torque-converter slip. Consistent with the tire-gearing decoder."},
  "gear-undercut-backlash": {"inputs":[{"key":"pressure_angle_deg","label":"Pressure angle (deg)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0"}},{"key":"teeth","label":"Number of teeth N","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"1"}},{"key":"addendum_coefficient","label":"Addendum coefficient (1.0 full, 0.8 stub)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0"}},{"key":"center_distance_change_in","label":"Center-distance increase (in, 0 = skip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"diametral_pitch","label":"Diametral pitch (teeth/in, 0 = skip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: involute gear geometry. The undercut limit is Nmin = 2k / sin^2(pressure angle), where k is the addendum coefficient (1.0 full depth, 0.8 stub) - it reproduces the standard published minimums of 32 teeth at 14.5 degrees, 18 at 20 degrees, and 12 at 25 degrees. Backlash from opening the center distance is B = 2 x (center-distance change) x tan(pressure angle), because the flanks separate along the line of action. Standard proportions with no profile shift assumed; profile shift (long-addendum pinion) is the usual fix for an undercut pinion and changes both results. A shop aid; the gear drawing and the AGMA standard govern."},
  "geothermal-loop": {"inputs":[{"key":"heating_btu","label":"Heating design (BTU/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"cooling_btu","label":"Cooling design (BTU/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"soil","label":"Soil class","kind":"select","options":[{"value":"sand","label":"Sand"},{"value":"clay","label":"Clay"},{"value":"rock","label":"Rock"}],"default":"clay","attrs":null},{"key":"loop_type","label":"Loop type","kind":"select","options":[{"value":"vertical","label":"Vertical"},{"value":"horizontal","label":"Horizontal"}],"default":"vertical","attrs":null}],"citation":"Notice: Simplified estimate. A code-compliant ground-loop design requires a full IGSHPA procedure. Citation: BTU per linear foot benchmarks from public DOE technical reports."},
  "glycol-mix": {"inputs":[{"key":"system_volume_gal","label":"System volume (gal)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"target_burst_F","label":"Target protection (F)","kind":"number","options":null,"default":32,"attrs":{"step":"any"}},{"key":"glycol_type","label":"Glycol type","kind":"select","options":[{"value":"propylene","label":"Propylene (food/HVAC)"},{"value":"ethylene","label":"Ethylene (industrial)"}],"default":"propylene","attrs":null},{"key":"protection_mode","label":"Protection mode","kind":"select","options":[{"value":"freeze","label":"Freeze (full flow protection)"},{"value":"burst","label":"Burst (line-rupture only, less glycol)"}],"default":"freeze","attrs":null}],"citation":"Citation: Manufacturer freeze-point curves (Dow Dowfrost / Dowtherm). Attribution included with output."},
  "grab-bar-layout": {"inputs":[{"key":"bar_height_in","label":"Bar height to the top of the gripping surface (in)","kind":"number","options":null,"default":34,"attrs":{"step":"any","min":"0"}},{"key":"side_bar_length_in","label":"Side-wall bar length (in)","kind":"number","options":null,"default":42,"attrs":{"step":"any","min":"0"}},{"key":"side_bar_from_rear_in","label":"Side bar distance from the rear wall (in)","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0"}},{"key":"rear_bar_length_in","label":"Rear-wall bar length (in)","kind":"number","options":null,"default":36,"attrs":{"step":"any","min":"0"}},{"key":"rear_toward_side_in","label":"Rear bar reach toward the side wall (in)","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0"}},{"key":"rear_toward_open_in","label":"Rear bar reach toward the open side (in)","kind":"number","options":null,"default":24,"attrs":{"step":"any","min":"0"}},{"key":"load_lb","label":"Design load (lbf; ADA 250)","kind":"number","options":null,"default":250,"attrs":{"step":"any","min":"0"}},{"key":"standoff_in","label":"Standoff from the wall to the bar centerline (in)","kind":"number","options":null,"default":1.5,"attrs":{"step":"any","min":"0"}},{"key":"fastener_spacing_in","label":"Flange fastener spacing (in; 0 to skip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: 2010 ADA Standards for Accessible Design - 609.4, grab bars installed in a horizontal position 33 in minimum and 36 in maximum above the finish floor measured to the top of the gripping surface; 604.5.1, a side-wall grab bar 42 in minimum long located 12 in maximum from the rear wall, and a rear-wall grab bar 36 in minimum long extending at least 12 in from the water closet centerline toward the side wall and at least 24 in toward the open side; 609.8, grab bars and their mounting sustaining 250 lbf. Prying moment and fastener force are statics from the standoff and flange geometry, not code values. Standard water-closet configuration only: ambulatory stalls, bathtubs, and roll-in and transfer showers have their own layouts under 604.8, 607, and 608. Clear floor space, the 16-18 in centerline, seat height, gripping diameter, and the 1-1/2 in clearance behind the bar are not checked. The 2010 ADA Standards and ANSI A117.1 differ in places; a screen, not a certification of accessibility - the adopted standard and the AHJ govern."},
  "grain-bin-height-for-capacity": {"inputs":[{"key":"target_bushels","label":"Target capacity (bushels)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"12875"}},{"key":"diameter_ft","label":"Bin diameter (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"peak_height_ft","label":"Roof/peak cone height (ft, 0 = flat)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"8"}},{"key":"packing_factor","label":"Packing factor","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1.0"}}],"citation":"Citation: bin geometry solved for the wall height: eave = (target_ft3/packing - roof_cone_ft3) / floor_area, from bushels = (area x eave + cone) x packing x 0.8036 (1 bushel = 1.2445 ft^3). A geometric fill volume; the bin manufacturer's rated capacity and the structure govern."},
  "grease-interceptor-flow-capacity": {"inputs":[{"key":"interceptor_volume_gal","label":"Interceptor volume (gal)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"retention_minutes","label":"Retention time (min)","kind":"number","options":null,"default":30,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"loading_factor","label":"Loading factor","kind":"number","options":null,"default":1.25,"attrs":{"step":"any","min":"0","value":"1.25"}}],"citation":"Citation: per IPC 2021 Table 1003.2 and PDI G101 by name, the sizing relation volume = peak_flow x retention x loading solved for the flow: peak_flow = volume / (retention x loading). Compare to the connected fixtures' DFU peak flow. AHJ governs. Free at codes.iccsafe.org."},
  "grease-trap": {"inputs":[{"key":"peak_flow_gpm","label":"Peak fixture flow (gpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"retention_minutes","label":"Retention time (min)","kind":"number","options":null,"default":30,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"loading_factor","label":"Loading factor","kind":"number","options":null,"default":1.25,"attrs":{"step":"any","min":"0","value":"1.25"}}],"citation":"Citation: per IPC 2021 Table 1003.2 and PDI G101 by name. Volume = peak_flow * retention * loading_factor. AHJ governs. Free at codes.iccsafe.org."},
  "grid-to-ground": {"inputs":[{"key":"grid_distance_ft","label":"Grid (map) distance (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"10000"}},{"key":"grid_scale_factor","label":"Grid scale factor (near 1.0)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"0.9999"}},{"key":"ellipsoid_height_ft","label":"Ellipsoid height h = H + N (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"5280"}}],"citation":"Citation: state-plane grid-to-ground reduction - elevation factor EF = R/(R+h), R = 20,906,000 ft (NGS mean earth radius), combined factor CF = grid-scale-factor x EF, ground = grid / CF. Standard NGS/NOAA State Plane Coordinate System practice, by name. The grid scale factor is a projection value near 1.0; h is the ELLIPSOID height (orthometric H + geoid N). A computational aid; the published control governs."},
  "grille-face-velocity": {"inputs":[{"key":"mode","label":"Solve for","kind":"select","options":[{"value":"size","label":"Required grille size (from a target velocity)"},{"value":"velocity","label":"Face velocity (from a gross grille size)"}],"default":"velocity","attrs":null}],"citation":"Citation: Grille/register sizing from the free area: face velocity V = cfm / (gross area x free-area ratio), or the required gross area = cfm / (target velocity x ratio). Supply grilles run about 400-700 fpm, returns slower (quieter), which is why a return is larger than a supply for the same airflow. The manufacturer's published free-area ratio and throw data govern the selection."},
  "grinding-wheel-rpm": {"inputs":[{"key":"wheel_diameter_in","label":"Wheel diameter (in)","kind":"number","options":null,"default":7,"attrs":{"step":"any","min":"0","value":"7"}},{"key":"rated_max_sfpm","label":"Wheel rated max speed (SFPM)","kind":"number","options":null,"default":6500,"attrs":{"step":"any","min":"0","value":"6500"}},{"key":"grinder_rpm","label":"Grinder speed (RPM)","kind":"number","options":null,"default":3450,"attrs":{"step":"any","min":"0","value":"3450"}}],"citation":"Citation: surface speed identity by name. SFPM = pi x wheel diameter (in) x RPM / 12; max RPM = rated SFPM x 12 / (pi x diameter). Per ANSI B7.1; the wheel blotter rating and the machine nameplate govern -- never exceed the wheel's rated speed."},
  "groove-weld-length-for-load": {"inputs":[{"key":"applied_load_lb","label":"Applied load (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"weld_type","label":"Weld type","kind":"select","options":[{"value":"PJP","label":"PJP (partial penetration)"},{"value":"CJP","label":"CJP (complete penetration)"}],"default":"PJP","attrs":null},{"key":"effective_throat_in","label":"Effective throat (in, PJP)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"base_thickness_in","label":"Thinner part thickness (in, CJP)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"electrode","label":"Electrode (FEXX)","kind":"select","options":[{"value":"E60","label":"E60"},{"value":"E70","label":"E70"},{"value":"E80","label":"E80"},{"value":"E90","label":"E90"},{"value":"E100","label":"E100"},{"value":"E110","label":"E110"}],"default":"E70","attrs":null},{"key":"method","label":"Method","kind":"select","options":[{"value":"ASD","label":"ASD (allowable)"},{"value":"LRFD","label":"LRFD (design)"}],"default":"ASD","attrs":null}],"citation":"Citation: Groove weld (CJP / PJP) shear capacity (AISC 360 Table J2.5 weld-metal shear 0.60*FEXX on the effective throat; ASD 0.30*FEXX, LRFD 0.75*0.60*FEXX) solved for the length: L = load / (stress_ksi x 1000 x throat), per AWS D1.1 and AISC 360 §J2, by name. The WPS, inspector, and engineer of record govern."},
  "groove-weld-strength": {"inputs":[{"key":"weld_type","label":"Weld type","kind":"select","options":[{"value":"PJP","label":"PJP (partial penetration)"},{"value":"CJP","label":"CJP (complete penetration)"}],"default":"PJP","attrs":null},{"key":"effective_throat_in","label":"Effective throat (in, PJP)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"base_thickness_in","label":"Thinner part thickness (in, CJP)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"length_in","label":"Weld length (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"electrode","label":"Electrode (FEXX)","kind":"select","options":[{"value":"E60","label":"E60"},{"value":"E70","label":"E70"},{"value":"E80","label":"E80"},{"value":"E90","label":"E90"},{"value":"E100","label":"E100"},{"value":"E110","label":"E110"}],"default":"E70","attrs":null},{"key":"method","label":"Method","kind":"select","options":[{"value":"ASD","label":"ASD (allowable)"},{"value":"LRFD","label":"LRFD (design)"}],"default":"ASD","attrs":null},{"key":"applied_load_lb","label":"Applied load (lb, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Groove weld (CJP / PJP) shear capacity - the AISC 360 Table J2.5 weld-metal shear strength 0.60*FEXX on the effective throat (ASD allowable 0.30*FEXX, LRFD design 0.75*0.60*FEXX) - per AWS D1.1 Structural Welding Code and AISC 360 §J2, by name; first-principles. A CJP weld with matching filler develops the base metal in tension/compression; the PJP effective throat is read off the qualified WPS. The WPS, inspector, and engineer of record govern. Complements the fillet-weld-strength tile."},
  "gross-rent-multiplier": {"inputs":[{"key":"rent_basis","label":"Rent basis","kind":"select","options":[{"value":"annual","label":"Annual"},{"value":"monthly","label":"Monthly"}],"default":"annual","attrs":null}],"citation":"Citation: Standard income-approach screening metric (gross rent / gross income multiplier) per the Appraisal Institute's The Appraisal of Real Estate income approach, by name; USPAP governs the appraiser's value opinion. Distinct from cap-rate-dscr, which uses NOI, not gross rent. Screening only."},
  "grounding-electrode": {"inputs":[{"key":"electrode_type","label":"Electrode type","kind":"select","options":[{"value":"driven_rod","label":"Driven rod (Dwight 1936)"},{"value":"ring","label":"Buried ring (IEEE 142 §4.2.2)"},{"value":"plate","label":"Buried plate (IEEE 142 §4.2.3)"},{"value":"ufer","label":"Concrete-encased / Ufer (IEEE 142 §4.2.4)"}],"default":"driven_rod","attrs":null}],"citation":"Citation: Per IEEE 142-2007 (Green Book) §4. Dwight (1936) closed-form for driven rods. NEC 2023 §250.53 governs adoption. Soil resistivity varies seasonally; field megger reading is the authoritative value at the time of inspection. Free at standards.ieee.org for IEEE bibliographic data."},
  "grounding-electrode-conductor": {"inputs":[{"key":"service_kcmil","label":"Largest ungrounded service conductor (kcmil)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"material","label":"Service / GEC material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":"copper","attrs":null},{"key":"electrode_type","label":"Electrode type","kind":"select","options":[{"value":"rod-pipe-plate","label":"Rod / pipe / plate"},{"value":"concrete-encased","label":"Concrete-encased (Ufer)"},{"value":"ground-ring","label":"Ground ring"},{"value":"water-pipe-or-steel","label":"Water pipe / building steel"}],"default":"rod-pipe-plate","attrs":null}],"citation":"Citation: NEC 250.66 grounding-electrode-conductor sizing with the 250.66(A)-(C) electrode caps (by section; only the threshold-to-size mapping is encoded, not a reproduced table). The AHJ-adopted edition governs. Free read-only at nfpa.org/freeaccess."},
  "growing-degree-days": {"inputs":[{"key":"method","label":"Method","kind":"select","options":[{"value":"standard","label":"Standard"},{"value":"modified","label":"Modified (cap/floor)"}],"default":"standard","attrs":null}],"citation":"Citation: Per the USDA / NWS growing-degree-day method and McMaster & Wilhelm (1997), 'Growing degree-days: one equation, two interpretations,' Agric. & Forest Meteorology 87, by name. Corn 50/86 F base/cutoff is the land-grant extension convention. Free at university extension sites."},
  "growth-projected-count": {"inputs":[{"key":"initial_count","label":"Initial count or OD (N0)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"100000"}},{"key":"doubling_time","label":"Doubling time (h)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"8"}},{"key":"elapsed_time","label":"Elapsed time (h)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"24"}}],"citation":"Citation: Standard exponential-growth kinetics, Td = t x ln(2) / ln(N/N0) solved for N: N = N0 x 2^(t / Td); doublings = t / Td; fold = 2^(t / Td). Holds only in log (exponential) phase; a projection past stationary phase over-predicts. If N is an optical density, the ratio assumes OD stays proportional to cell count. The culture, medium, and conditions govern."},
  "guy-wire-tension": {"inputs":[{"key":"horizontal_load_lb","label":"Horizontal load at top (lb)","kind":"number","options":null,"default":500,"attrs":{"step":"any","min":"0","value":"500"}},{"key":"attachment_height_ft","label":"Guy attachment height (ft)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"anchor_lead_ft","label":"Anchor lead distance (ft)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}}],"citation":"Citation: guy-wire / down-guy tension and mast download, by name. theta = atan(height/lead); guy tension = H / cos(theta); mast download (and anchor uplift) = H x tan(theta). Single-guy statics only (real rigs balance multiple guys, mast wind/weight, pretension). The pole class, anchor capacity, guy grade, and the engineer / NESC / RUS govern."},
  "hanger-rod-sizing": {"inputs":[{"key":"load_lb","label":"Operating load per hanger (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"temp_derate","label":"Temperature derate factor (1.0 at ambient)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","max":"1","value":"1"}}],"citation":"Citation: Minimum hanger rod = smallest carbon-steel threaded rod whose MSS SP-58 maximum safe load (at or below 650F) clears the applied load after the temperature derate - by name. The bundled loads (3/8 in 610 lb, 1/2 in 1130 lb, ...) are the standard's carbon-steel values; above 650F apply the standard's derate curve (user factor for an off-table temperature). The engineer of record and the standard's current edition govern the final selection."},
  "hardwood-floor-drying-mat": {"inputs":[{"key":"floor_area_ft2","label":"Wet hardwood floor area (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"120"}},{"key":"mat_coverage_ft2","label":"Coverage per mat (ft^2)","kind":"number","options":null,"default":6,"attrs":{"step":"any","min":"0","value":"6"}},{"key":"mats_per_unit","label":"Mats per suction unit","kind":"number","options":null,"default":16,"attrs":{"step":"any","min":"0","value":"16"}}],"citation":"Citation: Hardwood floor drying-mat system sizing (ANSI/IICRC S500 Class 4 specialty drying), by name. The mat-system manufacturer's coverage and unit ratings GOVERN; subfloor construction and finish affect feasibility. A sizing screen."},
  "haul-cycle-production": {"inputs":[{"key":"truck_cap_lcy","label":"Truck capacity (loose cy)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"load_min","label":"Loader fill time (min)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"haul_min","label":"Loaded haul time (min)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"dump_min","label":"Dump / maneuver time (min)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"return_min","label":"Empty return time (min)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"spot_min","label":"Spot time (min)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","min":"0","value":"0.5"}},{"key":"eff_min_per_hr","label":"Working minutes per hour","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}}],"citation":"Citation: Caterpillar Performance Handbook cycle-time production method by name. cycle = load + haul + dump + return + spot; loads/hr = working minutes / cycle; trucks = ceil(cycle / load time)."},
  "haul-road-resistance": {"inputs":[{"key":"gvw_lb","label":"Gross vehicle weight, loaded (lb)","kind":"number","options":null,"default":150000,"attrs":{"step":"any","min":"0","value":"150000"}},{"key":"grade_pct","label":"Road grade (%, negative downhill)","kind":"number","options":null,"default":5,"attrs":{"step":"any","value":"5"}},{"key":"rolling_resistance_pct","label":"Rolling resistance (%)","kind":"number","options":null,"default":4,"attrs":{"step":"any","value":"4"}}],"citation":"Citation: resistance identity by name. total resistance (%) = grade + rolling resistance; required rimpull = total resistance x GVW; 20 lb/ton per 1%. The manufacturer's rimpull-speed curve gives the available rimpull in gear."},
  "haversine": {"inputs":[{"key":"lat1","label":"Lat 1","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"lon1","label":"Lon 1","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"lat2","label":"Lat 2","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"lon2","label":"Lon 2","kind":"number","options":null,"default":null,"attrs":{"step":"any"}}],"citation":"Citation: Haversine formula. Earth radius 3958.8 mi / 6371.0088 km. Initial bearing from atan2."},
  "hay-dry-matter": {"inputs":[{"key":"bale_weight_lb","label":"Bale weight, as-baled (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"1200"}},{"key":"moisture_pct","label":"Measured moisture (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"22"}},{"key":"target_moisture_pct","label":"Target moisture (%)","kind":"number","options":null,"default":15,"attrs":{"step":"any","min":"0","value":"15"}},{"key":"safe_threshold_pct","label":"Safe-storage ceiling (%)","kind":"number","options":null,"default":18,"attrs":{"step":"any","min":"0","value":"18"}}],"citation":"Citation: first-principles dry-matter balance with USDA NRCS / land-grant extension safe-storage guidance (by name). Dry matter = weight x (1 - moisture); weight at target = dry matter / (1 - target). Safe ceiling ~18% large / 20% small (editable). The producer and extension govern."},
  "hdd-pullback": {"inputs":[{"key":"eff_weight_plf","label":"Effective pipe weight in fluid (lb/ft)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"length_ft","label":"Bore / pull length (ft)","kind":"number","options":null,"default":800,"attrs":{"step":"any","min":"0","value":"800"}},{"key":"friction_coeff","label":"Friction coefficient","kind":"number","options":null,"default":0.3,"attrs":{"step":"any","min":"0","value":"0.3"}},{"key":"bend_factor","label":"Pull-path bend factor","kind":"number","options":null,"default":1.5,"attrs":{"step":"any","min":"0","value":"1.5"}},{"key":"fluid_drag_lb","label":"Hydrokinetic drag allowance (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"pipe_safe_pull_lb","label":"Pipe safe pull strength (lb, 0 = skip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"20000"}}],"citation":"Citation: simplified pullback identity by name (ASTM F1962 basis). pullback (lb) = friction x effective weight x length x bend factor + fluid drag. A first-order estimate; the drilling contractor and rig thrust govern."},
  "heat-trace-sizing": {"inputs":[{"key":"pipe_ft","label":"Pipe run length (ft)","kind":"number","options":null,"default":150,"attrs":{"step":"any","min":"0","value":"150"}},{"key":"allowance_pct","label":"Support / spiral allowance (percent)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"num_valves","label":"Valves and flanges (count)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1"}},{"key":"valve_allow_ft","label":"Cable allowance per valve (ft)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","value":"3"}},{"key":"rated_w_per_ft","label":"Cable rated wattage (W/ft)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"voltage","label":"Supply voltage (V)","kind":"number","options":null,"default":120,"attrs":{"step":"any","min":"0","value":"120"}},{"key":"breaker_a","label":"Circuit breaker rating (A)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}}],"citation":"Citation: heat-trace identity by name. cable = pipe x (1 + allowance) + valves x allowance; watts = rated W/ft x cable; amps = watts / voltage. Continuous load must stay under 80% of the breaker. The manufacturer's tables and max circuit length govern."},
  "hemocytometer": {"inputs":[{"key":"total_cells_counted","label":"Total cells counted","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}},{"key":"squares_counted","label":"Squares counted","kind":"number","options":null,"default":4,"attrs":{"step":"1","min":"1"}},{"key":"dilution_factor","label":"Dilution factor","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0"}},{"key":"dead_cells","label":"Dead cells (optional, trypan blue)","kind":"number","options":null,"default":null,"attrs":{"step":"1","min":"0"}}],"citation":"Citation: standard Neubauer hemocytometer; each large square = 0.1 uL. cells/mL = (avg/sq) * 1e4 * dilution."},
  "henderson-hasselbalch": {"inputs":[{"key":"pKa","label":"pKa","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"target_pH","label":"Target pH","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"total_buffer_concentration","label":"Total buffer concentration (M)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"total_volume","label":"Total volume (L)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Henderson-Hasselbalch pH = pKa + log10([A-]/[HA]). First principles."},
  "hepa-filter-life": {"inputs":[{"key":"cfm","label":"CFM","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"hours_per_day","label":"Hours per day","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"24","value":"24"}},{"key":"particulate_category","label":"Particulate category","kind":"select","options":[{"value":"low","label":"Low (light dust)"},{"value":"medium","label":"Medium (typical remediation)"},{"value":"high","label":"High (heavy demolition)"}],"default":"medium","attrs":null},{"key":"capacity_grams","label":"Filter capacity (g)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"1500"}},{"key":"job_days","label":"Job duration (days, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"filter_cost_usd","label":"Filter cost ($, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Estimated days = filter capacity (g) / (CFM * hours/day * loading rate). Loading rates from typical commercial HEPA pre-filter behavior."},
  "hiking-time": {"inputs":[{"key":"distance","label":"Horizontal distance","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"distance_unit","label":"Distance unit","kind":"select","options":[{"value":"mi","label":"Miles"},{"value":"km","label":"Kilometres"}],"default":"km","attrs":null},{"key":"ascent","label":"Total ascent (climb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"ascent_unit","label":"Ascent unit","kind":"select","options":[{"value":"ft","label":"Feet"},{"value":"m","label":"Metres"}],"default":"m","attrs":null},{"key":"speed","label":"Flat pace (per hour, blank = 3 mph or 5 km/h)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"factor","label":"Terrain / fatigue factor","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1"}}],"citation":"Citation: Naismith's rule (W. W. Naismith, 1892) for hill-walking time - horizontal distance / pace plus 1 hour per 600 m of ascent - by name; first-principles plus the canonical ascent rate, public domain. A planning estimate; the terrain / fatigue factor and the leader's judgment govern."},
  "hood-exhaust": {"inputs":[{"key":"hood_type","label":"Type I hood type (ignored for Type II)","kind":"select","options":[{"value":"wall-canopy","label":"Wall-canopy"},{"value":"single-island","label":"Single-island canopy"},{"value":"double-island","label":"Double-island canopy"},{"value":"backshelf","label":"Backshelf"},{"value":"proximity","label":"Proximity"},{"value":"pass-over","label":"Pass-over"}],"default":"wall-canopy","attrs":null},{"key":"hood_class","label":"Hood class","kind":"select","options":[{"value":"I","label":"Type I (grease, hot)"},{"value":"II","label":"Type II (vapor only)"}],"default":"I","attrs":null},{"key":"duty","label":"Cooking-appliance duty","kind":"select","options":[{"value":"light","label":"Light (steam, oven)"},{"value":"medium","label":"Medium (range, fryer)"},{"value":"heavy","label":"Heavy (charbroiler, wok)"},{"value":"extra-heavy","label":"Extra-heavy (solid-fuel, mesquite)"}],"default":"medium","attrs":null}],"citation":"Citation: Per IMC 2021 §507.13 (Type I grease hoods) and §507.20 (Type II vapor-only hoods). Duty multipliers (200 / 300 / 400 / 550 cfm/ft for wall-canopy) are formula coefficients per the published IMC. NFPA 96-2024 governs grease-handling exhaust system design. Makeup air per IMC 508. AHJ governs final equipment selection. Free at codes.iccsafe.org for IMC TOC and at nfpa.org/freeaccess for NFPA 96 TOC."},
  "horizontal-curve": {"inputs":[{"key":"mode","label":"Definition mode","kind":"select","options":[{"value":"radius","label":"By radius (ft)"},{"value":"degree","label":"By degree of curve"}],"default":null,"attrs":null},{"key":"pi_station_ft","label":"PI station (ft, optional)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"5000"}}],"citation":"Citation: Circular-curve geometry per AASHTO A Policy on Geometric Design of Highways and Streets (the Green Book) and FM 5-233 Construction Surveying, using first-principles trigonometry with the arc definition D = 5729.58 / R. The design of record and engineer of record govern."},
  "horizontal-sightline-offset": {"inputs":[{"key":"mode","label":"Solve for","kind":"select","options":[{"value":"M","label":"Sightline offset M (from sight distance)"},{"value":"maxS","label":"Max sight distance S (from cleared offset)"}],"default":null,"attrs":null}],"citation":"Citation: AASHTO horizontal sightline offset (middle ordinate) per A Policy on Geometric Design of Highways and Streets (the Green Book): M = R (1 - cos(28.65 S / R)) with R to the inside-lane centerline (the vehicle's path); the inverse S = (R/28.65) arccos(1 - M/R). Assumes a continuous obstruction along the curve. A design aid, not a substitute for a licensed civil engineer's design."},
  "hos-math": {"inputs":[{"key":"profile","label":"Profile","kind":"select","options":[{"value":"property_70_8","label":"Property 70/8"},{"value":"property_60_7","label":"Property 60/7"},{"value":"passenger_70_7","label":"Passenger 60/7"}],"default":"property_70_8","attrs":null},{"key":"weekly_on_duty_used_hr","label":"Weekly on-duty already used (hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Notice: Math aid for personal verification. The ELD on the truck is the legal record. Citation: per FMCSA 49 CFR 395 (Hours of Service). Free at ecfr.gov."},
  "hp-from-torque": {"inputs":[{"key":"solve_for","label":"Solve for","kind":"select","options":[{"value":"hp","label":"Horsepower"},{"value":"torque","label":"Torque"},{"value":"rpm","label":"RPM"}],"default":"hp","attrs":null}],"citation":"Citation: Classical definition of mechanical power (Watt's 33,000 ft-lb/min); SAE J1349 engine-power rating, by name. The constant 5252 is a pure derivation, fully public. Torque and HP are equal at 5252 RPM by definition."},
  "hx-lmtd-ntu": {"inputs":[{"key":"config","label":"Flow configuration","kind":"select","options":[{"value":"counterflow","label":"Counter-flow"},{"value":"parallel","label":"Parallel-flow"}],"default":"counterflow","attrs":null}],"citation":"Citation: LMTD = (dT1 - dT2) / ln(dT1/dT2); Q = C x delta-T with C = GPM x fluid factor; UA = Q / LMTD; effectiveness = Q / (C_min x (Th_in - Tc_in)); NTU = UA / C_min. Per the TEMA standards and standard heat-transfer texts (Incropera, Cengel). Free at tema.org for the standards TOC."},
  "hydrant-available-flow": {"inputs":[{"key":"static_psi","label":"Static pressure (psi)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"residual_psi","label":"Residual pressure while flowing (psi)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"qf_gpm","label":"Test flow QF (gpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: NFPA 291 (Fire Flow Testing and Marking of Hydrants) -- rated flow at 20 psi QR = QF x (hr/hf)^0.54 with hf = static - residual and hr = static - 20, and the AA/A/B/C color classes (>= 1500 / 1000 / 500 / < 500 gpm). A field estimate at one location and time; the water authority's flow data govern."},
  "hydrant-flow": {"inputs":[{"key":"pitot_psi","label":"Pitot pressure (psi)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"outlet_diameter_in","label":"Outlet diameter (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"2.5"}},{"key":"c","label":"Coefficient of discharge","kind":"number","options":null,"default":0.9,"attrs":{"step":"any","min":"0","max":"1","value":"0.9"}}],"citation":"Citation: Q = 29.83 * c * d^2 * sqrt(P). c is the coefficient of discharge (typical 0.9 round-and-smooth)."},
  "hydraulic-cylinder": {"inputs":[{"key":"direction","label":"Direction","kind":"select","options":[{"value":"extend","label":"Extend (full bore)"},{"value":"retract","label":"Retract (annulus)"}],"default":"extend","attrs":null}],"citation":"Citation: First-principles fluid power per NFPA T2.13.7 cylinder definitions: F = P * A, with A the full bore on extension and the bore-minus-rod annulus on retraction; v = (GPM * 231) / (60 * A). AHJ and machine design govern. Free at nfpa.com for the NFPA fluid-power table of contents."},
  "hydraulic-jump": {"inputs":[{"key":"b_ft","label":"Channel width b (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"q_cfs","label":"Discharge Q (cfs)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"y1_ft","label":"Upstream (supercritical) depth y1 (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Belanger sequent depth y2 = (y1/2)(sqrt(1 + 8 Fr1^2) - 1) and the energy loss dE = (y2 - y1)^3/(4 y1 y2) for a rectangular channel, g = 32.2 ft/s^2, as compiled in Chow, by name. Supercritical upstream (Fr1 > 1); the tailwater must supply the sequent depth. A design aid; the engineer of record governs."},
  "hydronic-fill-pressure": {"inputs":[{"key":"height_ft","label":"Height fill-to-highest-point (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"margin_psi","label":"Top-of-system margin (psi, default 4)","kind":"number","options":null,"default":4,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Hydronic fill pressure by static height: fill = height / 2.31 + margin (2.31 ft of water = 1 psi), a common margin ~4 psi to keep the top of the loop above atmospheric. The expansion-tank pre-charge matches the fill; the relief valve sits well above. A design aid; the manufacturer's instructions govern."},
  "hydronic-injection-mixing": {"inputs":[{"key":"secondary_gpm","label":"Secondary loop flow (gpm)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"secondary_supply_f","label":"Secondary supply temp (F)","kind":"number","options":null,"default":110,"attrs":{"step":"any","value":"110"}},{"key":"secondary_return_f","label":"Secondary return temp (F)","kind":"number","options":null,"default":90,"attrs":{"step":"any","value":"90"}},{"key":"primary_supply_f","label":"Primary supply temp (F)","kind":"number","options":null,"default":180,"attrs":{"step":"any","value":"180"}}],"citation":"Citation: hydronic injection-mixing loop flow (primary/secondary energy balance), by name. injection gpm = secondary gpm x (secondary supply - secondary return) / (primary supply - secondary return). Sizes the injection flow; a variable-speed injection pump or modulating valve, boiler protection, and the heat loss govern the design."},
  "hydronic-system-volume": {"inputs":[{"key":"pipe_length_ft","label":"Total pipe length (ft)","kind":"number","options":null,"default":500,"attrs":{"step":"any","min":"0","value":"500"}},{"key":"gal_per_ft","label":"Gallons per foot (gal/ft)","kind":"number","options":null,"default":0.023,"attrs":{"step":"any","min":"0","value":"0.023"}},{"key":"terminal_gal","label":"Terminal / emitter volume (gal)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"8"}},{"key":"boiler_tank_gal","label":"Boiler + buffer tank volume (gal)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"glycol_fraction","label":"Glycol fraction (0-1)","kind":"number","options":null,"default":0.3,"attrs":{"step":"any","min":"0","value":"0.30"}}],"citation":"Citation: volume identity by name. system = pipe length x gallons per foot + terminals + boiler; glycol = system x fraction; water = system - glycol. The gallons per foot comes from the pipe size (3/4 in ~0.023 gal/ft)."},
  "hydroseed-mix": {"inputs":[{"key":"area_ac","label":"Area to hydroseed (acres)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"seed_rate_lb_ac","label":"Seed rate (lb/acre)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"mulch_rate_lb_ac","label":"Mulch rate (lb/acre)","kind":"number","options":null,"default":2000,"attrs":{"step":"any","min":"0","value":"2000"}},{"key":"tackifier_rate_lb_ac","label":"Tackifier rate (lb/acre)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}},{"key":"tank_gal","label":"Hydroseeder tank capacity (gal)","kind":"number","options":null,"default":3000,"attrs":{"step":"any","min":"0","value":"3000"}},{"key":"max_load_lb_per_gal","label":"Max solids loading (lb/gal)","kind":"number","options":null,"default":0.4,"attrs":{"step":"any","min":"0","value":"0.4"}}],"citation":"Citation: slurry loading identity by name. solids = area x (seed + mulch + tackifier rates); tanks = ceil(solids / (tank gallons x max loading)). The spec / agronomist sets the rates; the loading is the machine's agitation limit."},
  "hydrostatic-test": {"inputs":[{"key":"working_pressure_psi","label":"Working pressure (psi)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"system_volume_gal","label":"System volume (gal)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"material","label":"System type","kind":"select","options":[{"value":"water","label":"Water (1.5x)"},{"value":"fuel_gas","label":"Fuel gas (1.25x)"}],"default":"water","attrs":null}],"citation":"Citation: Public engineering practice. Default multipliers 1.5 for water, 1.25 for fuel gas. Hold-time scales with system volume."},
  "hydroxyl-sizing": {"inputs":[{"key":"structure_volume_ft3","label":"Structure volume (ft^3)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"12000"}},{"key":"unit_coverage_ft3","label":"Coverage per generator (ft^3/unit)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"6000"}},{"key":"expected_days","label":"Anticipated continuous run time (days)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","value":"3"}}],"citation":"Citation: Volume-and-coverage sizing (ANSI/IICRC S700), by name. Hydroxyl generators are safe for occupied spaces but work more slowly than ozone, commonly running continuously for several days. Coverage ratings and run times are manufacturer-specific. Severe odor still requires source removal and cleaning first. The manufacturer and S700 govern."},
  "indirect-evaporative-cooling": {"inputs":[{"key":"dry_bulb_F","label":"Entering product dry-bulb (F)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"95"}},{"key":"secondary_wet_bulb_F","label":"Secondary-stream wet-bulb (F)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"65"}},{"key":"effectiveness","label":"Indirect effectiveness (0-1, ~0.5-0.75)","kind":"number","options":null,"default":0.65,"attrs":{"step":"any","min":"0","max":"1","value":"0.65"}}],"citation":"Citation: indirect-evaporative cooler leaving dry-bulb T_out = T_ent - indirect_effectiveness x (T_ent - T_wb,secondary), the ASHRAE Handbook (HVAC Systems & Equipment, Ch. 41) sensible-effectiveness relation. The product air is cooled sensibly (no added moisture) toward the secondary stream's wet-bulb; indirect effectiveness ~0.5-0.75. A shop estimate; the equipment data govern."},
  "injector-size": {"inputs":[{"key":"hp","label":"Target horsepower (hp)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"bsfc","label":"BSFC (lb/hp-h; 0.50 NA, 0.55-0.65 boost)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","min":"0"}},{"key":"n_cyl","label":"Number of injectors","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"1"}},{"key":"duty","label":"Maximum duty cycle (0-1)","kind":"number","options":null,"default":0.8,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: fuel injector flow lb/h = HP x BSFC / (n_cyl x duty), BSFC ~0.50 NA / 0.55-0.65 boosted, the 80% maximum duty cycle, and lb/h x 10.5 = cc/min for gasoline, by name. Port injection, entered BSFC. A tuning aid; the measured fueling governs."},
  "insulation-resistance-pi": {"inputs":[{"key":"ir_30s_mohm","label":"IR at 30 seconds (Mohm)","kind":"number","options":null,"default":800,"attrs":{"step":"any","min":"0","value":"800"}},{"key":"ir_1min_mohm","label":"IR at 1 minute / 60 s (Mohm)","kind":"number","options":null,"default":1040,"attrs":{"step":"any","min":"0","value":"1040"}},{"key":"ir_10min_mohm","label":"IR at 10 minutes (Mohm)","kind":"number","options":null,"default":4160,"attrs":{"step":"any","min":"0","value":"4160"}}],"citation":"Citation: insulation-resistance polarization index (PI) and dielectric absorption ratio (DAR), by name (IEEE 43). DAR = IR(60s)/IR(30s); PI = IR(10min)/IR(1min). PI < 1 dangerous, 1-2 questionable, 2-4 good, > 4 excellent; DAR < 1.25 marginal, 1.4+ good. Temperature-correct to a common base; on very-high-IR epoxy windings PI loses meaning. The baseline trend and OEM criteria govern."},
  "insulation-thickness-for-heat-loss": {"inputs":[{"key":"od_in","label":"Pipe outer diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"2"}},{"key":"k_value","label":"Insulation k (BTU-in/hr-ft2-F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.25"}},{"key":"hot_f","label":"Hot surface temp (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"200"}},{"key":"amb_f","label":"Ambient temp (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"70"}},{"key":"target_q_per_ft_btuh","label":"Target heat loss (BTU/hr per ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"40"}}],"citation":"Citation: Fourier conduction through a cylindrical shell (public heat-transfer formula) solved for the thickness: thickness = (od/2) x (exp(2*pi*(k/12)*(hot - amb)/q) - 1); insulation k-values per ASHRAE Fundamentals / ASTM C335, by name (user-supplied). Targets a heat-loss budget, not a surface temperature. k is at the mean insulation temperature; conduction only (ignores the outer air film, so conservative)."},
  "internal-heat-gains": {"inputs":[{"key":"occupants","label":"Occupants","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"6"}},{"key":"sens_per_person","label":"Sensible per person (Btu/h)","kind":"number","options":null,"default":245,"attrs":{"step":"any","min":"0","value":"245"}},{"key":"lat_per_person","label":"Latent per person (Btu/h)","kind":"number","options":null,"default":200,"attrs":{"step":"any","min":"0","value":"200"}},{"key":"lighting_w","label":"Lighting power (W)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"800"}},{"key":"equipment_w","label":"Equipment power (W)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"1200"}},{"key":"use_factor","label":"Use factor (0-1)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1.0"}}],"citation":"Citation: ASHRAE / ACCA Manual J internal-gain method (by name): occupant sensible and latent from the activity table, lighting and equipment at 3.412 Btu/h per watt, scaled by the use factor. Recessed lighting on a return plenum delivers part of its heat to the plenum. One cooling-load component, not a Manual J."},
  "inventory-turnover": {"inputs":[{"key":"cogs","label":"COGS (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"beginning_inventory","label":"Beginning inventory (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"ending_inventory","label":"Ending inventory (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"period_days","label":"Period days","kind":"number","options":null,"default":365,"attrs":{"step":"1","min":"1"}},{"key":"industry_key","label":"Industry (for comparison)","kind":"select","options":[{"value":"","label":"(none)"}],"default":null,"attrs":null}],"citation":"Citation: turnover = COGS / avg inventory; DSI = period_days / turnover. Industry medians from U.S. Census ARTS / SBA, year stamped."},
  "iron-manganese-chlorine-dose": {"inputs":[{"key":"fe_mgl","label":"Iron Fe (mg/L)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","value":"3.0"}},{"key":"mn_mgl","label":"Manganese Mn (mg/L)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","min":"0","value":"0.5"}},{"key":"extra_demand_mgl","label":"Other chlorine demand (mg/L)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","min":"0","value":"0.5"}},{"key":"target_residual_mgl","label":"Target free residual (mg/L)","kind":"number","options":null,"default":0.3,"attrs":{"step":"any","min":"0","value":"0.3"}},{"key":"flow_mgd","label":"Flow (MGD)","kind":"number","options":null,"default":0.05,"attrs":{"step":"any","min":"0","value":"0.05"}}],"citation":"Citation: iron/manganese chlorine-oxidation stoichiometry by name (AWWA / Ten States). 0.62 mg Cl2 per mg Fe, 1.30 mg Cl2 per mg Mn, plus other demand and the target residual; lb/day = dose x flow(MGD) x 8.34. Jar tests, pH, and the state primacy agency govern."},
  "joist-deflection": {"inputs":[{"key":"uniform_load_plf","label":"Uniform load (plf)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"span_ft","label":"Span (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"E_psi","label":"E (psi)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"I_in4","label":"I (in^4)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: delta = 5 * w * L^4 / (384 * E * I) for a uniformly loaded simply supported beam."},
  "knurl-blank-diameter": {"inputs":[{"key":"target_diameter_in","label":"Target diameter (in)","kind":"number","options":null,"default":0.75,"attrs":{"step":"any","min":"0","value":"0.75"}},{"key":"knurl_tpi","label":"Knurl pitch (TPI)","kind":"number","options":null,"default":21,"attrs":{"step":"any","min":"0","value":"21"}}],"citation":"Citation: knurl tracking rule by name. A circular-pitch (TPI) knurl tracks cleanly when the blank circumference is a whole number of teeth: teeth = round(pi x D x TPI); blank diameter = teeth / (pi x TPI)."},
  "lab-dilution": {"inputs":[{"key":"c1","label":"Stock C1","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"v1","label":"Stock V1","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"c2","label":"Final C2","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"v2","label":"Final V2","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"mode","label":"Mode","kind":"select","options":[{"value":"single","label":"Single (solve missing)"},{"value":"serial","label":"Serial"}],"default":"single","attrs":null},{"key":"steps","label":"Serial steps","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1"}},{"key":"dilution_factor","label":"Dilution factor (>1)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"1.001"}}],"citation":"Citation: C1V1 = C2V2 dilution form. Serial mode applies the dilution factor at each step."},
  "labor-burden-rate": {"inputs":[{"key":"wage","label":"Base wage ($/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"payroll_pct","label":"Payroll tax (%, FICA+FUTA/SUTA)","kind":"number","options":null,"default":9.15,"attrs":{"step":"any","min":"0"}},{"key":"wc_pct","label":"Workers' comp (% of wage)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"liab_pct","label":"General liability (% of wage)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"benefits","label":"Benefits ($/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"productivity","label":"Productive/billable fraction (%)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","max":"100"}}],"citation":"Citation: fully-burdened labor rate = (wage + payroll% + WC% + liability% + benefits) / productive fraction, standard contractor bid-rate estimating. Payroll ~9.15% (FICA 7.65 + FUTA/SUTA). The payroll service, insurer rates, and fringe package govern."},
  "langelier-index": {"inputs":[{"key":"temp_unit","label":"Temp unit","kind":"select","options":[{"value":"F","label":"Fahrenheit"},{"value":"C","label":"Celsius"}],"default":"C","attrs":null}],"citation":"Citation: Langelier (1936) saturation index as standardized in Standard Methods for the Examination of Water and Wastewater (APHA/AWWA/WEF) and AWWA practice, by name; method cited, not reproduced. The user supplies measured water-quality values. LSI predicts tendency, not rate."},
  "layout-squaring": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"find-diagonal","label":"Find diagonal"},{"value":"check-square","label":"Check square"}],"default":null,"attrs":null}],"citation":"Citation: The Pythagorean 3-4-5 right-angle layout method (public) and the standard foundation and deck squaring technique. A layout aid, not a substitute for a transit or string-line."},
  "leach-field-aggregate": {"inputs":[{"key":"num_trenches","label":"Number of trenches","kind":"number","options":null,"default":3,"attrs":{"step":"1","min":"0","value":"3"}},{"key":"trench_length_ft","label":"Trench length (ft)","kind":"number","options":null,"default":60,"attrs":{"step":"any","min":"0","value":"60"}},{"key":"trench_width_in","label":"Trench width (in)","kind":"number","options":null,"default":24,"attrs":{"step":"any","min":"0","value":"24"}},{"key":"stone_depth_in","label":"Stone depth (in)","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"waste_pct","label":"Waste allowance (%)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}}],"citation":"Citation: drainrock identity by name. stone = trenches x length x width x depth / 27; tons = stone x drainrock unit weight (~1.4 ton/cy). The trench dimensions come from the AHJ-approved septic design; the required length is septic-drainfield."},
  "leveling-curvature-refraction": {"inputs":[{"key":"sight_distance_ft","label":"Sight distance (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"2000"}}],"citation":"Citation: combined earth curvature-and-refraction correction h_cr = 0.0206 K^2 ft, K the sight distance in thousands of feet (curvature 0.0239 K^2 minus refraction 0.0033 K^2); equivalently 0.574 M^2 with M in miles. Standard leveling reduction per Ghilani, Elementary Surveying, by name. Assumes a refraction coefficient k ~ 0.14. A computational aid; the project procedure governs."},
  "lifting-lug-design": {"inputs":[{"key":"applied_load_kip","label":"Applied load (kip)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"plate_thick_in","label":"Plate thickness t (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"hole_dia_in","label":"Hole diameter Dh (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"pin_dia_in","label":"Pin diameter Dp (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"edge_dist_in","label":"Hole-center to edge a (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"plate_width_in","label":"Plate width at hole w (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"fy_ksi","label":"Yield Fy (ksi)","kind":"number","options":null,"default":36,"attrs":{"step":"any","min":"0","value":"36"}},{"key":"fu_ksi","label":"Ultimate Fu (ksi)","kind":"number","options":null,"default":58,"attrs":{"step":"any","min":"0","value":"58"}},{"key":"design_factor","label":"Design factor Nd","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"1","value":"2.0"}}],"citation":"Citation: ASME BTH-1 Section 3-3.3 pin-connected plates (lifting lug / padeye): bearing = 1.25 Fy Dp t/Nd; net tension = Fu(w-Dh)t/Nd; double-plane shear tear-out = 0.70 Fu(2t(a+Dp/2-Dh/2))/Nd; governing = the minimum. The four modes trade off through hole placement - a lug sized for gross tension alone can tear out at the pin. Nd depends on the BTH-1 design category and service class. ASME BTH-1 and the engineer of record govern."},
  "lighting-beam": {"inputs":[{"key":"beam_angle_deg","label":"Beam angle (full cone, deg)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"180"}},{"key":"throw_distance","label":"Throw distance","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"distance_unit","label":"Distance unit","kind":"select","options":[{"value":"ft","label":"Feet"},{"value":"m","label":"Metres"}],"default":"ft","attrs":null},{"key":"source","label":"Intensity source","kind":"select","options":[{"value":"candela","label":"Center-beam intensity (candela)"},{"value":"lumens","label":"Total output (lumens) + beam angle"}],"default":"candela","attrs":null},{"key":"candela","label":"Center-beam intensity (candela)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"lumens","label":"Luminous flux (lumens)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: First-principles theatrical photometry - beam diameter = 2 x throw x tan(beam angle / 2); center illuminance by the inverse-square law E = candela / distance^2 (the form fixture photometric charts publish, e.g. ETC / manufacturer cut sheets), by name; public domain. The architectural lumen-method room average is a separate tile (lux-to-footcandle)."},
  "lighting-retrofit-savings": {"inputs":[{"key":"fixtures","label":"Fixtures retrofitted","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"watts_existing","label":"Existing watts/fixture","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"128"}},{"key":"watts_new","label":"New watts/fixture","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"44"}},{"key":"annual_hours","label":"Annual operating hours","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"4000"}},{"key":"rate_kwh","label":"Energy rate ($/kWh)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.12"}},{"key":"demand_per_kw_mo","label":"Demand charge ($/kW-month, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"install_cost","label":"Installed cost ($, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"8000"}}],"citation":"Citation: energy-and-demand lighting-savings method kWh_saved = fixtures x (W_old - W_new)/1000 x hours, demand savings at $/kW-month x 12, simple payback = cost / annual savings (by name). Burn hours are the actual operating hours; demand savings apply only to the peak-coincident reduction. A simple payback, not a life-cycle analysis."},
  "lighting-throw-for-pool": {"inputs":[{"key":"target_pool_diameter","label":"Target beam (pool) diameter","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"beam_angle_deg","label":"Beam angle (full cone, deg)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"180"}},{"key":"distance_unit","label":"Distance unit","kind":"select","options":[{"value":"ft","label":"Feet"},{"value":"m","label":"Metres"}],"default":"ft","attrs":null}],"citation":"Citation: first-principles theatrical photometry solved for throw: throw = D / (2 x tan(beam angle / 2)), from beam diameter = 2 x throw x tan(beam angle / 2); public domain. The illuminance still falls with the square of the throw (check the lighting-beam tile). A wider beam reaches the same pool from a shorter throw."},
  "linear-system-2x2": {"inputs":[{"key":"a1","label":"a1 (coefficient of x in row 1)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"1"}},{"key":"b1","label":"b1 (coefficient of y in row 1)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"0"}},{"key":"c1","label":"c1 (constant in row 1)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"0"}},{"key":"a2","label":"a2 (coefficient of x in row 2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"0"}},{"key":"b2","label":"b2 (coefficient of y in row 2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"1"}},{"key":"c2","label":"c2 (constant in row 2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"0"}}],"citation":"Citation: Cramer's rule for a 2x2 linear system. det = a1*b2 - a2*b1. If det != 0: unique solution x = (c1*b2 - c2*b1)/det, y = (a1*c2 - a2*c1)/det. If det = 0 and the row constants are proportional, the system has infinitely many solutions (same line); otherwise no solution (parallel lines). Standard linear algebra; covered in any high-school algebra II / pre-calculus text."},
  "livestock-water-requirement": {"inputs":[{"key":"method","label":"Method","kind":"select","options":[{"value":"table","label":"Temperature table (interpolate)"},{"value":"intake","label":"Intake ratio (water per DMI)"}],"default":"table","attrs":null},{"key":"water_per_dmi","label":"Water per lb DMI (gal-lb basis)","kind":"number","options":null,"default":3.5,"attrs":{"step":"any","min":"0","value":"3.5"}}],"citation":"Citation: Per NRC Nutrient Requirements of Beef Cattle / Dairy Cattle water-intake guidance and the USDA NRCS National Range and Pasture Handbook water section, by name; per-class gallon breakpoints user-supplied (table values, not reproduced). Distinct from thi-livestock. Free NRCS guidance at nrcs.usda.gov."},
  "loader-production": {"inputs":[{"key":"bucket_cap_lcy","label":"Heaped bucket capacity (loose cy)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"fill_factor","label":"Bucket fill factor","kind":"number","options":null,"default":0.95,"attrs":{"step":"any","min":"0","value":"0.95"}},{"key":"cycle_min","label":"Dig-dump cycle time (min)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"eff_min_per_hr","label":"Working minutes per hour","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}},{"key":"hours_per_day","label":"Productive hours per day","kind":"number","options":null,"default":8,"attrs":{"step":"any","min":"0","value":"8"}}],"citation":"Citation: Caterpillar Performance Handbook cycle-time production method by name. production = bucket payload x cycles per hour; payload = rated capacity x fill factor; cycles/hr = working minutes / cycle time."},
  "loan-payment": {"inputs":[{"key":"principal","label":"Principal","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"apr_percent","label":"APR (%)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"term_months","label":"Term (months)","kind":"number","options":null,"default":null,"attrs":{"step":"1","min":"1"}}],"citation":"Citation: payment = P*r / (1 - (1+r)^-n) with r = APR/12."},
  "log-limb-weight": {"inputs":[{"key":"butt_dia_in","label":"Butt (large end) diameter (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"top_dia_in","label":"Top (small end) diameter (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"length_ft","label":"Length (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"species","label":"Species (green density)","kind":"select","options":[{"value":"red_oak","label":"Red oak (64)"},{"value":"white_oak","label":"White oak (62)"},{"value":"sugar_maple","label":"Sugar maple (58)"},{"value":"ash","label":"Ash (48)"},{"value":"elm","label":"Elm (54)"},{"value":"hickory","label":"Hickory (63)"},{"value":"douglas_fir","label":"Douglas-fir (44)"},{"value":"southern_pine","label":"Southern pine (52)"},{"value":"eastern_white_pine","label":"Eastern white pine (36)"},{"value":"cottonwood","label":"Cottonwood (49)"},{"value":"generic_hardwood","label":"Generic hardwood (58)"},{"value":"generic_softwood","label":"Generic softwood (45)"}],"default":"generic_hardwood","attrs":null}],"citation":"Citation: USDA FPL Wood Handbook green density by species by name. Frustum volume = (pi/3) x length x (r1^2 + r1 r2 + r2^2); weight = volume x green density. Weigh or over-estimate when in doubt."},
  "loop-signal-scaling": {"inputs":[{"key":"signal_ma","label":"Loop signal (mA)","kind":"number","options":null,"default":12,"attrs":{"step":"any","value":"12"}},{"key":"range_low","label":"Range low (value at 4 mA)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"0"}},{"key":"range_high","label":"Range high (value at 20 mA)","kind":"number","options":null,"default":100,"attrs":{"step":"any","value":"100"}}],"citation":"Citation: 4-20 mA current-loop (live-zero) signal scaling, by name; ANSI/ISA-50.00.01 analog signal ranges and NAMUR NE43 fault levels. percent = (mA - 4)/16 x 100; value = range_low + percent/100 x (range_high - range_low). Linear scaling only (a DP-flow transmitter is square-root); the transmitter's range and calibration govern."},
  "loop-voltage-budget": {"inputs":[{"key":"supply_v","label":"Loop supply (Vdc)","kind":"number","options":null,"default":24,"attrs":{"step":"any","min":"0","value":"24"}},{"key":"transmitter_min_v","label":"Transmitter minimum voltage (V)","kind":"number","options":null,"default":10.5,"attrs":{"step":"any","min":"0","value":"10.5"}},{"key":"load_resistance_ohms","label":"Load / sense resistor (ohms)","kind":"number","options":null,"default":250,"attrs":{"step":"any","min":"0","value":"250"}},{"key":"wire_resistance_ohms","label":"Wire + barrier resistance (ohms)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}}],"citation":"Citation: loop-powered (2-wire) 4-20 mA transmitter voltage budget, by name. Max total loop resistance = (supply - transmitter minimum) / 0.020 A; voltage at the transmitter = supply - 0.020 x (load + wire + barrier resistance), which must exceed the transmitter's compliance (lift-off) voltage at the 20 mA worst case. The transmitter datasheet's compliance voltage and the barrier burden govern."},
  "ltv": {"inputs":[{"key":"loan_amount","label":"Loan amount ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"value","label":"Property value ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: LTV = loan amount / value (appraised or purchase, whichever is less, per FNMA Single-Family Selling Guide §B2-1.1-01). PMI generally required at LTV > 80 percent for conventional conforming loans; FHA programs cap LTV at 96.5 percent for purchase. Lender governs final underwriting; appraiser governs final value."},
  "lux-to-footcandle": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"convert","label":"Convert lux <-> footcandle"},{"value":"room","label":"Room average (lumen method)"}],"default":"convert","attrs":null}],"citation":"Citation: Per the IES Lighting Handbook lumen method and the exact 1 footcandle = 10.764 lux conversion (1 ft^2 = 0.092903 m^2). The room method returns an AVERAGE maintained illuminance, not a point value. Pairs with the lighting-density tile. Public photometric relations."},
  "lv-cable-pull-footage": {"inputs":[{"key":"drops","label":"Number of cable drops","kind":"number","options":null,"default":48,"attrs":{"step":"any","min":"0","value":"48"}},{"key":"avg_run_ft","label":"Average run length (ft)","kind":"number","options":null,"default":120,"attrs":{"step":"any","min":"0","value":"120"}},{"key":"slack_ft","label":"Service-loop / dressing slack per drop (ft)","kind":"number","options":null,"default":15,"attrs":{"step":"any","min":"0","value":"15"}},{"key":"box_ft","label":"Cable box / spool length (ft)","kind":"number","options":null,"default":1000,"attrs":{"step":"any","min":"0","value":"1000"}}],"citation":"Citation: footage takeoff identity by name. total = drops x (average run + slack); boxes = ceil(total / box length). The slack covers service loops and rack dressing; each run is length-limited by structured-cabling-channel."},
  "machining-time": {"inputs":[{"key":"feed_mode","label":"Feed entry","kind":"select","options":[{"value":"rpm-ipr","label":"Spindle speed (RPM) x feed/rev (IPR)"},{"value":"direct","label":"Feed rate directly (IPM)"}],"default":"rpm-ipr","attrs":null}],"citation":"Citation: Cutting time as cut distance / feed rate, with feed rate = RPM x IPR - first-principles arithmetic as in Machinery's Handbook (Industrial Press), by name; public domain. Include tool approach and overtravel in the cut length."},
  "mad-irrigation-trigger": {"inputs":[{"key":"field_capacity","label":"Field capacity (in/in, e.g. 0.30)","kind":"number","options":null,"default":0.3,"attrs":{"step":"any","min":"0","value":"0.30"}},{"key":"wilting_point","label":"Wilting point (in/in, e.g. 0.12)","kind":"number","options":null,"default":0.12,"attrs":{"step":"any","min":"0","value":"0.12"}},{"key":"root_depth_in","label":"Root depth (in)","kind":"number","options":null,"default":24,"attrs":{"step":"any","min":"0","value":"24"}},{"key":"mad_fraction","label":"MAD fraction (0-1, ~0.5)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","min":"0","value":"0.5"}},{"key":"etc_in_day","label":"Crop use ETc (in/day)","kind":"number","options":null,"default":0.25,"attrs":{"step":"any","min":"0","value":"0.25"}}],"citation":"Citation: available-water / management-allowed-depletion irrigation scheduling (FAO-56 / NRCS Irrigation Guide), by name. TAW = (field capacity - wilting point) x root depth; RAW = MAD x TAW; interval = RAW / ETc. MAD ~0.5 (0.3-0.6 by crop). The field-measured soil moisture, the actual root depth and ETc, and the agronomist govern."},
  "manual-j-cooling": {"inputs":[{"key":"wall_area_ft2","label":"Above-grade wall area (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"window_area_ft2","label":"Window area (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"ceiling_area_ft2","label":"Ceiling area (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"insulation_level","label":"Insulation level","kind":"select","options":[{"value":"poor","label":"Poor"},{"value":"average","label":"Average"},{"value":"good","label":"Good"}],"default":"average","attrs":null},{"key":"window_type","label":"Window type","kind":"select","options":[{"value":"single","label":"Single pane"},{"value":"double","label":"Double pane"},{"value":"triple","label":"Triple pane"}],"default":"double","attrs":null},{"key":"occupants","label":"Occupants","kind":"number","options":null,"default":2,"attrs":{"step":"1","min":"0","value":"2"}},{"key":"outdoor_design_F","label":"Outdoor design temp (F)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"indoor_design_F","label":"Indoor design temp (F)","kind":"number","options":null,"default":75,"attrs":{"step":"any","value":"75"}},{"key":"outdoor_RH_percent","label":"Outdoor RH (percent)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","max":"100","value":"50"}}],"citation":"Citation: Simplified screening estimate from envelope conductance, infiltration, internal gains, solar, and latent loads. Code-compliant load calc requires ACCA Manual J (8th ed.). Licensed HVAC designer and AHJ govern. Free at codes.iccsafe.org for IMC references."},
  "manual-j-heating": {"inputs":[{"key":"wall_area_ft2","label":"Above-grade wall area (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"window_area_ft2","label":"Window area (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"ceiling_area_ft2","label":"Ceiling area (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"insulation_level","label":"Insulation level","kind":"select","options":[{"value":"poor","label":"Poor"},{"value":"average","label":"Average"},{"value":"good","label":"Good"}],"default":"average","attrs":null},{"key":"window_type","label":"Window type","kind":"select","options":[{"value":"single","label":"Single pane"},{"value":"double","label":"Double pane"},{"value":"triple","label":"Triple pane"}],"default":"double","attrs":null},{"key":"outdoor_design_F","label":"Outdoor design temp (F)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"indoor_design_F","label":"Indoor design temp (F)","kind":"number","options":null,"default":70,"attrs":{"step":"any","value":"70"}}],"citation":"Citation: Simplified screening estimate from envelope conductance and infiltration. Code-compliant load calc requires ACCA Manual J (8th ed.). Licensed HVAC designer and AHJ govern. Free at codes.iccsafe.org for IMC references."},
  "manure-application-rate": {"inputs":[{"key":"form","label":"Manure form","kind":"select","options":[{"value":"solid","label":"Solid (lb/ton -> ton/acre)"},{"value":"liquid","label":"Liquid (lb/1,000 gal -> 1,000 gal/acre)"}],"default":"solid","attrs":null}],"citation":"Citation: Nutrient-based manure rate per USDA NRCS Code 590 (Nutrient Management) and land-grant manure-management guidance: available nutrient per unit = total nutrient x first-year availability; application rate = crop requirement / available per unit. Solid manure is ton/acre, liquid is 1,000 gal/acre. The rate is set by the most limiting of N or P2O5 under the farm's nutrient-management plan; a manure test and the plan govern."},
  "markup": {"inputs":[{"key":"cost","label":"Cost ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"mode","label":"Mode","kind":"select","options":[{"value":"markup_percent","label":"Markup percent"},{"value":"margin_percent","label":"Margin percent"},{"value":"selling_price","label":"Selling price"}],"default":null,"attrs":null},{"key":"value","label":"Value","kind":"number","options":null,"default":null,"attrs":{"step":"any"}}],"citation":"Citation: markup = profit / cost; margin = profit / selling price. Bidirectional."},
  "mass-moles": {"inputs":[{"key":"mass_g","label":"Mass (g, leave 0 to solve)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"moles","label":"Moles (leave 0 to solve)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"molecular_weight","label":"Molecular weight (g/mol)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: moles = mass / molecular weight. First principles."},
  "material-cost": {"inputs":[{"key":"unit_price","label":"Unit price ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"quantity","label":"Quantity","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"tax_rate_percent","label":"Tax rate (percent)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"20","value":"0"}},{"key":"delivery_fee","label":"Delivery fee ($)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: subtotal = price * quantity; total = subtotal * (1 + tax) + delivery."},
  "material-removal-rate": {"inputs":[{"key":"mode","label":"Operation","kind":"select","options":[{"value":"milling","label":"Milling (WOC, DOC, feed IPM)"},{"value":"turning","label":"Turning (SFM, DOC, feed IPR)"},{"value":"drilling","label":"Drilling (drill dia, feed IPM)"}],"default":"milling","attrs":null}],"citation":"Citation: Material removal rate as the swept volume per unit time (milling WOC x DOC x feed; turning 12 x SFM x DOC x feed/rev; drilling (pi x D^2 / 4) x feed) - first-principles geometry as in Machinery's Handbook (Industrial Press), by name; public domain."},
  "max-circuit-length-for-vd": {"inputs":[{"key":"source_voltage_v","label":"Source voltage (V)","kind":"number","options":null,"default":120,"attrs":{"step":"any","min":"0","value":"120"}},{"key":"target_vd_pct","label":"Target voltage drop (%)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","value":"3"}},{"key":"current_a","label":"Load current (A)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"conductor_cmil","label":"Conductor size (circular mils)","kind":"number","options":null,"default":6530,"attrs":{"step":"any","min":"0","value":"6530"}},{"key":"k_constant","label":"K (12.9 Cu, 21.2 Al)","kind":"number","options":null,"default":12.9,"attrs":{"step":"any","min":"0","value":"12.9"}},{"key":"phases","label":"Phases (1 or 3)","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1","value":"1"}}],"citation":"Citation: maximum one-way circuit length for a voltage-drop target, by name. L = VD_target x cmil / (factor x K x I); factor = 2 single-phase / sqrt(3) three-phase; K = 12.9 Cu / 21.2 Al ohm-cmil/ft; VD_target = target% x source V. DC-resistance drop only (reactance adds on larger conductors); the 3%/5% figures are NEC recommendations. The conductor must still pass the 310.16 ampacity check; the AHJ governs."},
  "max-wind-speed-for-lift": {"inputs":[{"key":"max_swing_deg","label":"Max allowable swing (deg, ~5 planning)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"load_weight_lb","label":"Load weight (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"sail_area_ft2","label":"Projected sail area (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"shape_coef","label":"Shape coefficient (flat panel ~1.2-2.0)","kind":"number","options":null,"default":1.6,"attrs":{"step":"any","min":"0","value":"1.6"}}],"citation":"Citation: ASCE velocity-pressure q = 0.00256 V^2 and the swing relation swing = atan(wind force / weight) solved for the wind speed, V = sqrt(weight x tan(swing) / (0.00256 x area x shape)); OSHA 1926 Subpart CC by name. Estimate - the manufacturer's in-service wind limit governs."},
  "mean-piston-speed": {"inputs":[{"key":"stroke_in","label":"Crankshaft stroke (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"rpm","label":"Engine speed (rpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: mean piston speed MPS = 2 x stroke x RPM (= stroke_in x RPM / 6 ft/min) and the practical regime bands (street/endurance under ~4,000, performance 4,000-4,500, race over 4,500 ft/min), per the engine-building references, by name. Average, not peak. A shop aid; the component ratings govern."},
  "medgas-demand": {"inputs":[{"key":"stations","label":"Stations (outlets / inlets)","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}},{"key":"per_station_scfm","label":"Per-station design flow (scfm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"diversity","label":"Diversity (simultaneous-use) factor, 0-1","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","max":"1","value":"0.25"}}],"citation":"Citation: Medical-gas demand - connected flow = stations x per-station design flow, system design flow = connected x diversity (simultaneous-use) factor, per NFPA 99 Health Care Facilities Code (medical gas and vacuum systems), with ASSE 6010 for the installer qualification, by name. The per-station design flows and diversity factors are read from the adopted NFPA 99 edition and the facility's equipment list (user-supplied here); a medical-gas verifier and the AHJ govern. This gives the design flow that feeds pipe sizing, not the system design itself - a demand aggregation, not a med-gas system stamp."},
  "metal-weight": {"inputs":[{"key":"shape","label":"Shape","kind":"select","options":[{"value":"plate","label":"Plate / sheet"},{"value":"round-bar","label":"Round bar"},{"value":"square-bar","label":"Square bar"},{"value":"hex-bar","label":"Hex bar"},{"value":"round-tube","label":"Round tube"},{"value":"rect-tube","label":"Rectangular tube"},{"value":"angle","label":"Angle"},{"value":"flat-bar","label":"Flat bar"}],"default":null,"attrs":null}],"citation":"Citation: First-principles weight = volume x density. Densities are published nominal values for common alloys (a small bundled public reference) or user-supplied. Mill certs and actual alloy temper govern."},
  "microinverter-branch-count": {"inputs":[{"key":"branch_ocpd_a","label":"Branch OCPD (A)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"unit_max_current_a","label":"Microinverter max AC current (A)","kind":"number","options":null,"default":1.21,"attrs":{"step":"any","min":"0","value":"1.21"}}],"citation":"Citation: max microinverters per AC branch by name (NEC 705.60 / 690.8(B) / 240.4). N = floor(branch OCPD x 0.80 / unit max continuous AC current) -- the combined continuous output cannot exceed 80% of the branch OCPD. The datasheet and the adopted NEC edition govern."},
  "mileage-cost": {"inputs":[{"key":"round_trip_miles","label":"Round-trip miles","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"mpg","label":"MPG","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"fuel_price_per_gallon","label":"Fuel price ($/gal)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"irs_rate_per_mile","label":"IRS rate ($/mi)","kind":"number","options":null,"default":null,"attrs":null}],"citation":"Citation: gallons = miles / mpg; cost = gallons * price; reimbursement = miles * IRS standard rate."},
  "min-bend-radius": {"inputs":[{"key":"thickness_in","label":"Plate / sheet thickness (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"elongation_pct","label":"Elongation in 2 in (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: published forming-limit relation R_min = T x (50 / %elongation - 1), by name. The mill certificate, the bend orientation relative to the rolling direction, and a test bend govern; this is a screen."},
  "min-conductor-for-vd": {"inputs":[{"key":"phase","label":"Phase","kind":"select","options":[{"value":"single","label":"Single phase"},{"value":"three","label":"Three phase"}],"default":"single","attrs":null},{"key":"material","label":"Material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":"copper","attrs":null},{"key":"current_A","label":"Load current (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"length_ft","label":"One-way run length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"source_voltage_V","label":"Source voltage (V)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"120"}},{"key":"target_percent","label":"Target drop (%)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","value":"3"}}],"citation":"Citation: first-principles I x R voltage drop (K = copper 12.9 / aluminum 21.2 ohm-cmil/ft at 75 C) solved for the smallest standard conductor at or below the target percent; the NEC FPN 3%/5% figures are advisory. Verify ampacity (310.16) and 110.14(C) terminations separately. Free read-only at nfpa.org/freeaccess."},
  "mixed-water-temp": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"find-blend","label":"Find blended temperature"},{"value":"find-mix-ratio","label":"Find mix ratio for a target"},{"value":"find-hot-flow","label":"Find hot flow for a target"}],"default":"find-blend","attrs":null},{"key":"hot_temp_F","label":"Hot supply temp (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"cold_temp_F","label":"Cold supply temp (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"hot_gpm","label":"Hot flow (gpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"cold_gpm","label":"Cold flow (gpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"target_temp_F","label":"Target delivered temp (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}}],"citation":"Citation: First-principles mixing energy balance for blending hot and cold potable water (T_blend = (Qh*Th + Qc*Tc)/(Qh+Qc)); the delivery-temperature limits follow the ASSE 1017 (master tempering) and ASSE 1016/1070 (point-of-use scald-guard) device standards and the IPC/UPC scald provisions, by name. The listed mixing valve and the AHJ govern the installed setpoint."},
  "molarity-dilution": {"inputs":[{"key":"c1","label":"C1 (M, leave 0 to solve)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"v1","label":"V1 (L, leave 0 to solve)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"c2","label":"C2 (M, leave 0 to solve)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"v2","label":"V2 (L, leave 0 to solve)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: dilution formula C1V1 = C2V2. First principles."},
  "mold": {"inputs":[{"key":"rh_percent","label":"Relative humidity (percent)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"100"}},{"key":"temperature_F","label":"Temperature (F)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"hours_elevated","label":"Hours of elevated humidity","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Public mold-growth research literature summarized in original plain English. Risk increases with sustained elevated RH on a food source."},
  "mold-cleaning-labor": {"inputs":[{"key":"affected_sf","label":"Cleanable affected surface (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"500"}},{"key":"production_sf_per_hr","label":"Production rate (ft^2/hr per pass)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"passes","label":"Cleaning passes (vac / wipe / vac)","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"1","value":"2"}},{"key":"crew_size","label":"Crew size","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"0","value":"2"}}],"citation":"Citation: Source-removal multi-pass cleaning labor method (ANSI/IICRC S520), by name. The Condition, substrate, and access GOVERN the production rate; non-cleanable porous materials are removed, not cleaned. A labor screen."},
  "mortgage-point-breakeven": {"inputs":[{"key":"loan_amount","label":"Loan amount ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"base_rate_pct","label":"Base rate, no points (percent)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"30"}},{"key":"points_rate_pct","label":"Rate with points (percent)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"30"}},{"key":"point_cost_pct","label":"Total point cost (percent of loan)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"1"}},{"key":"term_years","label":"Term (years)","kind":"number","options":null,"default":null,"attrs":{"step":"1","min":"1","max":"50","value":"30"}},{"key":"holding_years","label":"Expected holding period (years)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: First-principles amortization (monthly P&I = (P * r) / (1 - (1 + r)^-n)). Break-even months = up-front point cost / monthly payment savings. Points are reported on the CFPB Loan Estimate / Closing Disclosure (12 CFR 1026.37-38). One point typically costs 1 percent of the loan; the actual buy-down per point varies by lender and market. Lender governs the rate sheet."},
  "mortgage-reserves": {"inputs":[{"key":"piti_monthly","label":"Monthly PITI ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"reserves_months","label":"Reserves required (months)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"6"}},{"key":"liquid_assets","label":"Liquid assets after closing ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"retirement_balance","label":"Vested retirement balance ($, optional)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"retirement_allowable_pct","label":"Retirement allowable (percent)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"100","value":"60"}}],"citation":"Citation: Reserves = PITI * required months, measured against eligible post-closing liquid assets plus an allowable fraction of vested retirement (Fannie Mae Selling Guide B3-4.1-01 / B3-4.3-03; Freddie Mac Single-Family Seller/Servicer Guide 5501.2). Required months vary by loan type and program (conventional 0-6, jumbo 6-12, investment 6+). Lender governs the final requirement and which assets count."},
  "motor-acceleration-time": {"inputs":[{"key":"inertia_lbft2","label":"Total inertia WK^2 (lb-ft^2)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"speed_change_rpm","label":"Speed change (rpm)","kind":"number","options":null,"default":1750,"attrs":{"step":"any","min":"0","value":"1750"}},{"key":"net_accel_torque_lbft","label":"Avg net accelerating torque (lb-ft)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}}],"citation":"Citation: motor across-the-line acceleration time by name. t = WK^2 x dN / (308 x T_net), the rotational F = m x a, with WK^2 the reflected inertia (lb-ft^2), dN the speed change (rpm), and T_net the average net accelerating torque (lb-ft). The motor's speed-torque and thermal-limit curves and the reflected load inertia govern."},
  "motor-branch-protection": {"inputs":[{"key":"flc_a","label":"Motor full-load current FLC (A, from Table 430.247-250)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"28"}},{"key":"device_type","label":"Protective device type","kind":"select","options":[{"value":"inverse-time breaker","label":"Inverse-time breaker (250%)"},{"value":"dual-element/time-delay fuse","label":"Dual-element / time-delay fuse (175%)"},{"value":"nontime-delay fuse","label":"Nontime-delay fuse (300%)"},{"value":"instantaneous-trip breaker","label":"Instantaneous-trip breaker (800%)"}],"default":"inverse-time breaker","attrs":null}],"citation":"Citation: NEC 2023 430.52 and Table 430.52 (branch-circuit short-circuit and ground-fault protection) with 430.110 (disconnect ampere rating). Sized on the table FLC (430.6(A)); overload is separate (430.32). The AHJ governs. Free at nfpa.org/freeaccess."},
  "motor-capacitor-max": {"inputs":[{"key":"v_ll","label":"Motor line-to-line voltage (V)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"480"}},{"key":"i_noload_a","label":"No-load (magnetizing) current (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"8"}},{"key":"safety_factor","label":"Safety factor (default 0.90)","kind":"number","options":null,"default":0.9,"attrs":{"step":"any","min":"0","value":"0.90"}}],"citation":"Citation: NEMA MG-1 / IEEE 18 - a motor-terminal capacitor must stay below the magnetizing (no-load) kVAR = sqrt(3) x V x I_no-load / 1000, with a safety margin (default 0.90), to avoid self-excitation overvoltage. The manufacturer's max-kVAR table governs."},
  "motor-operating-cost": {"inputs":[{"key":"hp","label":"Rated horsepower","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"efficiency_pct","label":"Full-load efficiency (%)","kind":"number","options":null,"default":93,"attrs":{"step":"any","min":"0","max":"100","value":"93"}},{"key":"load_factor_pct","label":"Average load (% of rated)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"hours_per_year","label":"Run hours per year","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"rate_usd_per_kwh","label":"Energy rate ($/kWh)","kind":"number","options":null,"default":0.12,"attrs":{"step":"any","min":"0","value":"0.12"}}],"citation":"Citation: first-principles input_kW = HP x 0.746 x load / efficiency, then annual kWh x rate. The 0.746 kW/HP is the mechanical-to-electrical conversion; the result is the energy-charge component only and excludes demand / time-of-use / power-factor penalties. The utility tariff governs the bill."},
  "motor-overload-sizing": {"inputs":[{"key":"fla_A","label":"Nameplate full-load current FLA (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"sf","label":"Marked service factor (blank if unmarked)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"rise_C","label":"Marked temperature rise (degC, blank if unmarked)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: NEC 2023 430.32(A)(1) running-overload sizing on the nameplate FLA (125% for marked SF >= 1.15 or rise <= 40 degC, else 115%) with the 430.32(C) 140%/130% will-not-start ceiling, by name. The separate device from the 430.52 branch protection. The AHJ governs."},
  "motor-pole-identification": {"inputs":[{"key":"rated_rpm","label":"Nameplate full-load speed (rpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"1750"}},{"key":"line_freq_hz","label":"Line frequency (Hz)","kind":"number","options":null,"default":60,"attrs":{"step":"any","min":"0","value":"60"}}],"citation":"Citation: first-principles AC-machine relation Ns = 120 x f / P inverted to identify the poles - pole-pairs = round(60 x f / rpm), poles = 2 x pole-pairs, then Ns = 120 x f / poles and slip = (Ns - rpm)/Ns. The motor nameplate and the manufacturer govern the rated full-load speed."},
  "motor-rms-hp": {"inputs":[{"key":"hp_run","label":"Working (run) load (HP)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"run_time_s","label":"Run time (s)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"hp_idle","label":"Idle / light load (HP)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"idle_time_s","label":"Idle / rest time (s)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"cooling_factor","label":"Idle cooling factor (3 stopped, 2 unloaded)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"1","value":"3"}}],"citation":"Citation: motor RMS horsepower for a duty-cycle load (NEMA MG-1 duty-cycle / RMS-horsepower sizing method), by name. HP_rms = sqrt( (HP_run^2 x t_run + HP_idle^2 x t_idle) / (t_run + t_idle / K) ); the idle time is divided by the cooling factor K (~3 stopped, ~2 unloaded). Sizes the thermal duty only -- check the peak against breakdown torque separately. The motor's thermal-damage curve, service factor, and the manufacturer's duty rating govern."},
  "motor-run-hours-for-budget": {"inputs":[{"key":"hp","label":"Rated horsepower","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"efficiency_pct","label":"Full-load efficiency (%)","kind":"number","options":null,"default":93,"attrs":{"step":"any","min":"0","max":"100","value":"93"}},{"key":"load_factor_pct","label":"Average load (% of rated)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"rate_usd_per_kwh","label":"Energy rate ($/kWh)","kind":"number","options":null,"default":0.12,"attrs":{"step":"any","min":"0","value":"0.12"}},{"key":"cost_budget_usd","label":"Annual energy budget ($)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: first-principles run-hours = budget / (input_kW x rate), input_kW = HP x 0.746 x load / efficiency. The 0.746 kW/HP is the mechanical-to-electrical conversion; the result is the energy-charge component only and excludes demand / time-of-use / power-factor penalties. The utility tariff governs the bill."},
  "motor-synchronous-speed-slip": {"inputs":[{"key":"line_freq_hz","label":"Line frequency (Hz)","kind":"number","options":null,"default":60,"attrs":{"step":"any","min":"0","value":"60"}},{"key":"poles","label":"Poles (even integer)","kind":"number","options":null,"default":4,"attrs":{"step":"2","min":"2","value":"4"}},{"key":"rated_rpm","label":"Nameplate full-load speed (rpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: first-principles AC-machine relation Ns = 120 x f / P and slip = (Ns - rpm) / Ns; rotor (slip) frequency = slip x f. The motor nameplate and the manufacturer govern the rated full-load speed."},
  "motor-unbalance-derate": {"inputs":[{"key":"v_ab","label":"Line voltage A-B (V)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"460"}},{"key":"v_bc","label":"Line voltage B-C (V)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"455"}},{"key":"v_ca","label":"Line voltage C-A (V)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"450"}}],"citation":"Citation: NEMA MG-1 motor derating for voltage unbalance, by name - unbalance = max deviation from the average voltage divided by the average; the derate factor is read off the MG-1 curve (1% -> ~0.98, 5% -> ~0.75). Above 5% the motor should not be operated. The manufacturer and MG-1 govern."},
  "multi-load-vd": {"inputs":[{"key":"material","label":"Conductor material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":"copper","attrs":null},{"key":"source_voltage_V","label":"Source voltage (V)","kind":"number","options":null,"default":120,"attrs":{"step":"any","min":"0","value":"120"}}],"citation":"Citation: Cumulative I*R drop accumulated per segment using single-phase round-trip resistance per the Voltage Drop helper. See docs/derivations.md."},
  "multi-motor-feeder": {"inputs":[{"key":"largest_flc_a","label":"Largest motor FLC (A, table value)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"sum_other_flc_a","label":"Sum of other motor FLCs (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"largest_branch_ocpd_a","label":"Largest motor branch OCPD (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: NEC 2023 430.24 (feeder conductor = 1.25 x largest FLC + sum of others) and 430.62 (feeder OCPD <= largest branch OCPD + sum of others, next standard size down). Full-load currents are the NEC table values (430.248/430.250), user-supplied; the tile bundles no FLC table. The AHJ governs. Free read-only at nfpa.org/freeaccess."},
  "mwbc-voltage-drop": {"inputs":[{"key":"awg","label":"Conductor size (AWG)","kind":"select","options":[{"value":"14","label":"14 AWG"},{"value":"12","label":"12 AWG"},{"value":"10","label":"10 AWG"},{"value":"8","label":"8 AWG"},{"value":"6","label":"6 AWG"}],"default":"12","attrs":null},{"key":"material","label":"Conductor material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":"copper","attrs":null},{"key":"one_way_length_ft","label":"One-way circuit length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"load_a_amps","label":"Leg A load (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"16"}},{"key":"load_b_amps","label":"Leg B load (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"4"}},{"key":"source_volts","label":"Source volts, line to neutral","kind":"number","options":null,"default":120,"attrs":{"step":"any","min":"0","value":"120"}},{"key":"temperature_C","label":"Conductor temperature (C)","kind":"number","options":null,"default":75,"attrs":{"step":"any","value":"75"}}],"citation":"Citation: circuit analysis of a 120/240 V three-wire multiwire branch circuit. The two hots are out of phase and share a neutral carrying the difference of the leg currents, so with equal conductors of one-way resistance R the drops are VD_A = R(2 I_A - I_B) and VD_B = R(2 I_B - I_A). Balanced loading collapses to R x I - half the drop of a two-wire circuit, because the neutral carries nothing - and heavy unbalance drives the lighter leg's drop negative, a real neutral shift that raises it above nominal. Conductor resistance is computed from the entered size, material, and temperature by this catalog's own resistance model, not a recalled table; DC resistance only, ignoring AC reactance and power factor. NEC 210.4(B) requires a common disconnect, and the neutral must be pigtailed so removing a device cannot open it. The NEC as adopted and the AHJ govern."},
  "nam-sizing": {"inputs":[{"key":"room_volume_ft3","label":"Room volume (ft^3)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"target_ach","label":"Target air changes per hour","kind":"number","options":null,"default":6,"attrs":{"step":"any","min":"0","value":"6"}}],"citation":"Citation: Required CFM = room volume * ACH / 60. Typical NAM unit sizes 500 / 1000 / 2000 CFM (manufacturer technical bulletins)."},
  "nozzle-flow-pressure": {"inputs":[{"key":"rated_gpm","label":"Tip rated flow (gpm)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"rated_psi","label":"Rated pressure (psi)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"new_psi","label":"Operating pressure (psi)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"target_gpm","label":"Target flow (gpm, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: nozzle-flow square-root relation Q proportional to sqrt(pressure) (standard spray-nozzle hydraulics), by name, and USDA / land-grant extension sprayer-calibration guidance. The product label is the law (FIFRA); your state lead agency governs. Pressure is a fine-tuning lever; change tips to change the rate."},
  "nucleic-acid-a260": {"inputs":[{"key":"na_type","label":"Nucleic-acid type","kind":"select","options":[{"value":"dsDNA","label":"Double-stranded DNA (factor 50)"},{"value":"ssDNA","label":"Single-stranded DNA (factor 33)"},{"value":"oligo","label":"Oligo (factor 33)"},{"value":"RNA","label":"RNA (factor 40)"}],"default":"dsDNA","attrs":null}],"citation":"Citation: Standard spectrophotometric nucleic-acid quantitation (Beer-Lambert at 260 nm); concentration = A260 x factor x dilution, factor 50 (dsDNA) / 33 (ssDNA, oligo) / 40 (RNA) ug/mL per A260; purity = A260 / A280. The factor is an empirical mass coefficient, not molar, and differs by strandedness. A 260/280 below ~1.8 (DNA) or ~2.0 (RNA) flags protein/phenol carryover. Assumes a clean 1 cm path and a blanked instrument. The sample and instrument govern."},
  "oil-water-separator-sizing": {"inputs":[{"key":"flow_gpm","label":"Design flow (gpm)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}},{"key":"oil_sg","label":"Oil specific gravity","kind":"number","options":null,"default":0.85,"attrs":{"step":"any","min":"0","value":"0.85"}},{"key":"droplet_micron","label":"Design droplet (micron)","kind":"number","options":null,"default":150,"attrs":{"step":"any","min":"0","value":"150"}},{"key":"water_viscosity_cp","label":"Water viscosity (cP)","kind":"number","options":null,"default":1.1,"attrs":{"step":"any","min":"0","value":"1.1"}}],"citation":"Citation: gravity oil/water separator surface area by name (API 421). rise velocity Vt = g(rho_w - rho_o)d^2/(18 mu) (Stokes); horizontal area = 1.2 x Q / Vt. A screen; API 421, the manufacturer, and the engineer / AHJ govern the separator and discharge."},
  "open-delta-transformer": {"inputs":[{"key":"transformer_kva_each","label":"Transformer rating, each (kVA)","kind":"number","options":null,"default":25,"attrs":{"step":"any","min":"0","value":"25"}},{"key":"required_load_kva","label":"Required three-phase load (kVA)","kind":"number","options":null,"default":40,"attrs":{"step":"any","min":"0","value":"40"}}],"citation":"Citation: open-delta (V-V) transformer bank capacity, by name. available 3-phase kVA = sqrt(3) x one unit; each unit carries load / sqrt(3); bank utilization capped at 86.6% of the two installed, and 57.7% of the closed-delta three-unit bank. The nameplate kVA and impedance, the load balance and power factor, and the utility govern."},
  "orifice-diameter-for-flow": {"inputs":[{"key":"q_cfs","label":"Target discharge (cfs)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"h_ft","label":"Head to orifice center (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"cd","label":"Discharge coefficient Cd","kind":"number","options":null,"default":0.6,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: inverse orifice sizing A = Q / (Cd sqrt(2 g h)), d = sqrt(4 A / pi), g = 32.2 ft/s^2, Cd ~ 0.6 sharp-edged, head to the centroid, by name. Small orifice, steady head; the falling-head time-to-drain is separate. A design aid; the engineer of record governs."},
  "orifice-flow": {"inputs":[{"key":"d_in","label":"Orifice diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"h_ft","label":"Head to orifice center (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"cd","label":"Discharge coefficient Cd","kind":"number","options":null,"default":0.6,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: orifice discharge Q = Cd A sqrt(2 g h), g = 32.2 ft/s^2, Cd ~ 0.6 sharp-edged, head to the centroid, by name. Small orifice, steady head; the falling-head time-to-drain is separate. A design aid; the engineer of record governs."},
  "outdoor-air-mix": {"inputs":[{"key":"return_T_F","label":"Return air temp (F)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"return_RH_percent","label":"Return RH (%)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"100"}},{"key":"outdoor_T_F","label":"Outdoor air temp (F)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"outdoor_RH_percent","label":"Outdoor RH (%)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"100"}},{"key":"oa_fraction","label":"OA fraction (0-1)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"1"}}],"citation":"Citation: Mixed air dry-bulb is OA_fraction-weighted; mixed humidity ratio is mass-weighted via the psychrometric helpers."},
  "outdoor-reset-ratio": {"inputs":[{"key":"supply_design_f","label":"Design supply temp (F, at design OA)","kind":"number","options":null,"default":180,"attrs":{"step":"any","value":"180"}},{"key":"supply_min_f","label":"Minimum supply temp (F, at no-heat OA)","kind":"number","options":null,"default":80,"attrs":{"step":"any","value":"80"}},{"key":"oa_design_f","label":"Design outdoor temp (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"0"}},{"key":"oa_noheat_f","label":"No-heat outdoor temp (F)","kind":"number","options":null,"default":65,"attrs":{"step":"any","value":"65"}},{"key":"oa_current_f","label":"Current outdoor temp (F)","kind":"number","options":null,"default":30,"attrs":{"step":"any","value":"30"}}],"citation":"Citation: outdoor reset curve by name. reset ratio = (design supply - min supply) / (no-heat OA - design OA); supply target = min supply + ratio x (no-heat OA - current OA), clamped to the min/design supply. The control manual and the building heat loss govern."},
  "overflow-scupper-sizing": {"inputs":[{"key":"length_in","label":"Scupper opening width (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"head_in","label":"Head above scupper invert (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Overflow scupper as a rectangular weir Q = 3.33 L H^1.5 (cfs, feet), contracted 3.33 (L - 0.2 H) H^1.5 (IPC 1108 secondary drainage / FM Global). Head at the blocked-primary condition. A design aid; the plumbing code and roof-loading check govern."},
  "overhead-recovery-rate": {"inputs":[{"key":"annual_overhead","label":"Annual overhead ($)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"basis","label":"Recovery basis","kind":"select","options":[{"value":"per-hour","label":"Per billable hour ($/hr)"},{"value":"markup","label":"Markup on direct cost (%)"}],"default":"per-hour","attrs":null},{"key":"billable_hours","label":"Annual billable hours","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"annual_direct","label":"Annual direct cost ($)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"job_direct","label":"Job direct cost ($, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: overhead recovery = annual overhead / billable hours ($/hr) or / annual direct cost (% markup), standard contractor cost-recovery. Every billed hour or direct dollar carries its share. The contractor's books and billable volume govern."},
  "overtime": {"inputs":[{"key":"total_hours","label":"Total hours","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"regular_rate","label":"Regular rate ($/hr)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"overtime_multiplier","label":"OT multiplier","kind":"number","options":null,"default":1.5,"attrs":{"step":"any","min":"0","value":"1.5"}},{"key":"double_time_multiplier","label":"Double-time multiplier","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"0","value":"2.0"}},{"key":"double_time_threshold_hr","label":"Double-time threshold (hr)","kind":"number","options":null,"default":60,"attrs":{"step":"any","min":"0","value":"60"}}],"citation":"Citation: 40 hr regular; OT 1.5x to double-time threshold; double-time 2.0x beyond."},
  "oxyfuel-cutting-gas": {"inputs":[{"key":"oxygen_cfh","label":"Cutting-oxygen flow (cfh)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"fuel_cfh","label":"Preheat fuel-gas flow (cfh)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"cut_length_in","label":"Total cut length (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"cut_speed_ipm","label":"Travel speed (ipm)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"oxygen_cyl_ft3","label":"Oxygen per cylinder (ft3)","kind":"number","options":null,"default":244,"attrs":{"step":"any","min":"0","value":"244"}},{"key":"fuel_cyl_ft3","label":"Fuel per cylinder (ft3)","kind":"number","options":null,"default":330,"attrs":{"step":"any","min":"0","value":"330"}}],"citation":"Citation: torch maker's tip charts, by name. Cut time = length / speed; gas used = flow x cut time / 60. Oxygen does the cutting and runs out first. Compressed-gas, flashback, and hot-work hazards govern; follow the equipment maker's instructions and your site's hot-work permit."},
  "ozone-shock-treatment": {"inputs":[{"key":"structure_volume_ft3","label":"Volume to deodorize (ft^3 = area x ceiling height)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"8000"}},{"key":"rated_volume_per_unit","label":"Generator rated treatable volume (ft^3)","kind":"number","options":null,"default":2000,"attrs":{"step":"any","min":"0","value":"2000"}},{"key":"treatment_time_hr","label":"Shock duration (hours)","kind":"number","options":null,"default":24,"attrs":{"step":"any","min":"0","value":"24"}},{"key":"aeration_min","label":"Minimum ventilate-before-reentry (minutes)","kind":"number","options":null,"default":120,"attrs":{"step":"any","min":"0","value":"120"}}],"citation":"Citation: Volume-based ozone deodorization sizing (ANSI/IICRC S700) and the 0.1 ppm OSHA ozone limit, by name. DANGER: ozone is a respiratory toxin - the space must be unoccupied, sealed, and aired below 0.1 ppm before reentry; a hydroxyl generator is the occupied-space alternative. This sizes equipment; it is not authority to run ozone in an occupied space."},
  "paint-coverage": {"inputs":[{"key":"area_ft2","label":"Area (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"coats","label":"Coats","kind":"number","options":null,"default":2,"attrs":{"step":"1","min":"1","value":"2"}},{"key":"surface_porosity","label":"Surface porosity","kind":"select","options":[{"value":"smooth","label":"Smooth"},{"value":"textured","label":"Textured"},{"value":"rough","label":"Rough"}],"default":"smooth","attrs":null}],"citation":"Citation: gallons = area / (coverage * surface_factor). 350 ft^2/gal smooth, 250 textured, 175 rough."},
  "payroll-withholding": {"inputs":[{"key":"gross_per_period","label":"Gross wages this period (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"pay_frequency","label":"Pay frequency","kind":"select","options":[{"value":"weekly","label":"Weekly"},{"value":"biweekly","label":"Biweekly"},{"value":"semimonthly","label":"Semimonthly"},{"value":"monthly","label":"Monthly"}],"default":"biweekly","attrs":null},{"key":"filing_status","label":"Filing status","kind":"select","options":[{"value":"single","label":"Single (illustrative)"}],"default":"single","attrs":null},{"key":"ytd_ss_wages","label":"YTD wages subject to SS (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: IRS Publication 15-T percentage method (illustrative single-filer brackets bundled). FICA per FICA at 6.2% / 1.45% / 0.9% Additional."},
  "pdp": {"inputs":[{"key":"nozzle_pressure_psi","label":"Nozzle pressure (psi)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"friction_loss_psi","label":"Total friction loss (psi)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"elevation_ft","label":"Elevation change (ft up positive)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"0"}},{"key":"appliance_loss_psi","label":"Appliance loss (psi)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: per NFPA 13-2022 §8.3 (pressure calculations). PDP = nozzle pressure + friction loss + elevation + appliance loss. Elevation applies the NFA / IFSTA fire-ground shortcut of 0.5 psi/ft, NOT the exact 0.434 psi/ft water column -- it runs about 15% high by design; the elevation-pressure-loss tile shows both side by side. AHJ governs. Free at nfpa.org/freeaccess."},
  "per-diem": {"inputs":[{"key":"type","label":"Type","kind":"select","options":[{"value":"lodging","label":"Lodging"},{"value":"m_and_ie","label":"M&IE"}],"default":"lodging","attrs":null}],"citation":"Citation: GSA-published per-diem rates (U.S. government publication)."},
  "pex-homerun-takeoff": {"inputs":[{"key":"fixtures","label":"Total fixtures","kind":"number","options":null,"default":8,"attrs":{"step":"1","min":"0","value":"8"}},{"key":"hot_fixtures","label":"Fixtures needing hot","kind":"number","options":null,"default":6,"attrs":{"step":"1","min":"0","value":"6"}},{"key":"avg_run_ft","label":"Average home-run length (ft)","kind":"number","options":null,"default":35,"attrs":{"step":"any","min":"0","value":"35"}},{"key":"waste_pct","label":"Waste allowance (%)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}}],"citation":"Citation: takeoff identity by name. cold ports = fixtures; hot ports = hot fixtures; tubing = (cold + hot) x average run x (1 + waste). Home-run plumbing runs one line per fixture from a central manifold."},
  "pf-correction": {"inputs":[{"key":"kW","label":"Real power (kW)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"pf1","label":"Existing PF (0-1)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"1"}},{"key":"pf2","label":"Target PF (0-1)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"1"}},{"key":"system_V","label":"System voltage (V)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"phase","label":"Phase","kind":"select","options":[{"value":"single","label":"Single phase"},{"value":"three","label":"Three phase"}],"default":"single","attrs":null}],"citation":"Citation: kVAR = kW * (tan(acos(PF1)) - tan(acos(PF2))). Capacitance from Q = V^2 * 2*pi*f*C at 60 Hz."},
  "pid-tuning-ziegler-nichols": {"inputs":[{"key":"ultimate_gain_ku","label":"Ultimate gain Ku (gain at steady oscillation)","kind":"number","options":null,"default":4,"attrs":{"step":"any","min":"0","value":"4"}},{"key":"ultimate_period_tu_sec","label":"Ultimate period Tu (s, oscillation period)","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"0","value":"2"}}],"citation":"Citation: Ziegler-Nichols closed-loop (ultimate-sensitivity) PID tuning, by name. PID: Kp = 0.6 Ku, Ti = 0.5 Tu, Td = 0.125 Tu; PI: Kp = 0.45 Ku, Ti = Tu/1.2; P: Kp = 0.5 Ku. Ku/Tu are the gain and period at the stability limit. Aggressive (quarter-amplitude decay); a starting point, not a final tune. The process, the controller algorithm form, and the technician govern."},
  "pipe-bedding-backfill": {"inputs":[{"key":"trench_width_ft","label":"Trench width (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"pipe_od_in","label":"Pipe outside diameter (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"bedding_depth_in","label":"Bedding depth below pipe (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"cover_ft","label":"Cover above pipe (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"length_ft","label":"Run length (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"stone_density_tcy","label":"Stone density (tons/cy)","kind":"number","options":null,"default":1.4,"attrs":{"step":"any","min":"0","value":"1.4"}}],"citation":"Citation: ASTM D2321 (installation of thermoplastic pipe) and the municipal bedding detail by name. bedding / embedment / backfill volumes from trench and pipe dimensions; embedment excludes the pipe's own volume. The approved detail governs."},
  "pipe-cold-spring": {"inputs":[{"key":"material","label":"Material (sets coefficient)","kind":"select","options":[{"value":"steel","label":"Carbon steel A53"},{"value":"copper","label":"Copper Type L"},{"value":"ductile_iron","label":"Ductile iron"},{"value":"aluminum","label":"Aluminum 6061"},{"value":"pvc","label":"PVC Sch 80"},{"value":"cpvc","label":"CPVC"},{"value":"pex","label":"PEX"}],"default":"steel","attrs":null},{"key":"run_length_ft","label":"Run length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"install_temp_f","label":"Install temperature (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"operating_temp_f","label":"Operating temperature (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"cold_spring_percent","label":"Cold-spring factor (%)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","max":"100","value":"50"}}],"citation":"Citation: Pipe cold spring (cut-short) - the run is cut short by a fraction of the computed free thermal growth dL = alpha * L * dT and sprung into place at the install temperature, lowering the hot anchor and nozzle reactions - per ASME B31.1 Power Piping §119 / B31.9 Building Services Piping, by name; first-principles linear expansion. Cold spring does not reduce the cyclic stress range (B31.1 §119.10); B31.1 credits two-thirds of the cold spring in the reaction. The piping engineer governs the flexibility analysis."},
  "pipe-filled-support-load": {"inputs":[{"key":"od_in","label":"Outside diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"wall_in","label":"Wall thickness (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"pipe_density","label":"Pipe material density (lb/ft3; steel 490)","kind":"number","options":null,"default":490,"attrs":{"step":"any","min":"0","value":"490"}},{"key":"fluid_density","label":"Fluid density (lb/ft3; water 62.4)","kind":"number","options":null,"default":62.4,"attrs":{"step":"any","min":"0","value":"62.4"}},{"key":"insul_thk_in","label":"Insulation thickness (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"insul_density","label":"Insulation density (lb/ft3)","kind":"number","options":null,"default":6,"attrs":{"step":"any","min":"0","value":"6"}},{"key":"spacing_ft","label":"Hanger spacing (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Operating support load = (empty pipe + contained fluid + insulation) weight per foot x hanger spacing - first-principles cross-section x density, the MSS SP-58 operating support load, by name. Bundled pipe weights are nominal mill values and water is taken at 62.4 lb/ft^3; a hot or dense fluid changes the contents weight, and concentrated loads (valves, flanges) are added separately. Feeds the hanger-rod sizing."},
  "pipe-fitting-takeout": {"inputs":[{"key":"reference","label":"Reference dimension","kind":"select","options":[{"value":"center-to-center","label":"Center-to-center"},{"value":"face-to-face","label":"Face-to-face"}],"default":"center-to-center","attrs":null},{"key":"dimension_in","label":"Run dimension (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"takeout_a_in","label":"Take-out end A (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"takeout_b_in","label":"Take-out end B (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"makeup_a_in","label":"Make-up / weld gap end A (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"makeup_b_in","label":"Make-up / weld gap end B (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Fitting take-out / make-up cut-length layout as taught in NCCER Pipefitting and the standard fitter's references, by name; first-principles. Fitting take-out and thread make-up are product- and schedule-specific and user-supplied; confirm against your fittings and the spool drawing. Cross-links rolling-offset and conduit-offset."},
  "pipe-flotation": {"inputs":[{"key":"pipe_od_in","label":"Pipe outside diameter (in)","kind":"number","options":null,"default":48,"attrs":{"step":"any","min":"0","value":"48"}},{"key":"pipe_weight_plf","label":"Empty pipe weight (lb/ft)","kind":"number","options":null,"default":200,"attrs":{"step":"any","min":"0","value":"200"}},{"key":"backfill_weight_plf","label":"Resisting backfill weight (lb/ft)","kind":"number","options":null,"default":900,"attrs":{"step":"any","min":"0","value":"900"}},{"key":"target_fs","label":"Target factor of safety","kind":"number","options":null,"default":1.5,"attrs":{"step":"any","min":"0","value":"1.5"}},{"key":"water_unit_wt_pcf","label":"Water unit weight (pcf)","kind":"number","options":null,"default":62.4,"attrs":{"step":"any","min":"0","value":"62.4"}}],"citation":"Citation: Archimedes flotation identity by name. uplift (lb/ft) = water unit weight x pi/4 x OD^2; FS = resisting weight / uplift. Submerged backfill counts only its buoyant weight; the design engineer governs."},
  "pipe-insulation-for-condensation": {"inputs":[{"key":"pipe_od_in","label":"Pipe OD (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"1"}},{"key":"pipe_temp_F","label":"Cold-pipe surface temp (F)","kind":"number","options":null,"default":40,"attrs":{"step":"any","value":"40"}},{"key":"ambient_F","label":"Ambient dry-bulb (F)","kind":"number","options":null,"default":75,"attrs":{"step":"any","value":"75"}},{"key":"ambient_rh_pct","label":"Ambient RH (%, design-day)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"1","max":"99","value":"50"}},{"key":"k_btu_in_per_hr_ft2_F","label":"Insulation k (BTU-in/hr-ft^2-F)","kind":"number","options":null,"default":0.27,"attrs":{"step":"any","value":"0.27"}},{"key":"outside_film_coeff_btu_hr_ft2_F","label":"Outside film coeff (BTU/hr-ft^2-F)","kind":"number","options":null,"default":1.65,"attrs":{"step":"any","value":"1.65"}}],"citation":"Citation: minimum condensation-control thickness for a cold pipe: the outer-surface energy balance h (2 pi r2/12)(Tamb - Tdp) = 2 pi k (Tdp - Tpipe)/ln(r2/r1), solved for the radius where the jacket sits exactly at the ambient dew point (dew point from the saturation-vapor-pressure psychrometrics this catalog already pins). The industry practice is to round UP to the next stock wall: a surface at the dew point is on the edge of sweating. Assumes still air and an intact vapor retarder; design-day RH governs, not the average. Manufacturer condensation tables (e.g. the insulation maker's design guide) and the mechanical code govern - a sizing aid, not a substitute for them."},
  "pipe-insulation-takeoff": {"inputs":[{"key":"pipe_ft","label":"Pipe run length (ft)","kind":"number","options":null,"default":250,"attrs":{"step":"any","min":"0","value":"250"}},{"key":"waste_pct","label":"Waste allowance (percent)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"num_fittings","label":"Ells / tees / valves (count)","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"fitting_allow_ft","label":"Insulation allowance per fitting (ft)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1"}},{"key":"section_len_ft","label":"Insulation section length (ft)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","value":"3"}},{"key":"insul_od_in","label":"Insulation outside diameter (in)","kind":"number","options":null,"default":4.5,"attrs":{"step":"any","min":"0","value":"4.5"}}],"citation":"Citation: insulation-takeoff identity by name. cut = pipe x (1 + waste) + fittings x allowance; sections = ceil(cut / section length); jacket = pi x insulation OD x cut. The jacket area uses the insulation OD, not the pipe."},
  "pipe-miter-cut": {"inputs":[{"key":"total_angle_deg","label":"Total turn angle (deg)","kind":"number","options":null,"default":90,"attrs":{"step":"any","min":"0","max":"180"}},{"key":"pieces","label":"Number of pieces (>= 2)","kind":"number","options":null,"default":2,"attrs":{"step":"1","min":"2"}},{"key":"outside_diameter_in","label":"Pipe outside diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"centerline_radius_in","label":"Centerline radius (in, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Multi-piece (lobster-back) miter-elbow geometry - the per-cut miter angle A/(2*(n-1)) and the OD*tan(theta) cutback - as taught in NCCER Pipefitting and the standard fabrication references, by name; first-principles geometry. The welding procedure, the bevel, and the engineer of record govern the fabricated fitting."},
  "pipe-pressure-rating": {"inputs":[{"key":"od_in","label":"Outside diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"wall_in","label":"Nominal wall (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"allow_stress","label":"Allowable stress S at temperature (psi)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"joint_factor","label":"Joint factor E (seamless = 1.0)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","max":"1","value":"1"}},{"key":"y_coeff","label":"y-coefficient (ferritic <= 900F = 0.4)","kind":"number","options":null,"default":0.4,"attrs":{"step":"any","value":"0.4"}},{"key":"mill_tol_frac","label":"Mill under-tolerance fraction","kind":"number","options":null,"default":0.125,"attrs":{"step":"any","min":"0","value":"0.125"}},{"key":"allowance_in","label":"Corrosion + threading allowance A (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"design_p","label":"Design pressure (psi, required-wall mode)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"mode","label":"Mode","kind":"select","options":[{"value":"allowable_pressure","label":"Allowable pressure from wall"},{"value":"required_wall","label":"Required wall from pressure"}],"default":"allowable_pressure","attrs":null}],"citation":"Citation: ASME B31.1 Power Piping internal-pressure design - allowable pressure P = 2 S E (t - A) / (D - 2 y (t - A)); minimum wall t = P D / (2 (S E + P y)) + A - by name (B31.3 Process Piping uses the same form with its own allowables). The allowable stress S, joint efficiency E, and y-coefficient are read from the applicable code edition's tables for the specific material and temperature. This is a design screen, not a stamped calculation; the engineer of record and the AHJ govern."},
  "pipe-purge-volume": {"inputs":[{"key":"pipe_id_in","label":"Pipe inside diameter (in)","kind":"number","options":null,"default":2.067,"attrs":{"step":"any","min":"0","value":"2.067"}},{"key":"length_ft","label":"Run length (ft)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"air_changes","label":"Volume changes to sweep","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"flow_scfh","label":"Purge gas flow (scfh)","kind":"number","options":null,"default":60,"attrs":{"step":"any","min":"0","value":"60"}}],"citation":"Citation: purge identity by name. pipe volume = pi/4 x ID^2 x length; purge volume = pipe volume x air changes; time = purge volume / flow. A nitrogen purge while brazing keeps scale and oxidation out of the line."},
  "pipe-spacing-rack": {"inputs":[{"key":"pipe_od_in","label":"Pipe outside diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"insulation_thickness_in","label":"Insulation thickness (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"clearance_in","label":"Clearance gap (in)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1"}},{"key":"pipe_count","label":"Number of pipes","kind":"number","options":null,"default":2,"attrs":{"step":"1","min":"1","value":"2"}},{"key":"rack_width_in","label":"Rack / strut width (in, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Insulated parallel-pipe rack spacing - center-to-center = insulated OD + clearance, bundle width = n * insulated OD + (n-1) * clearance - first-principles geometry; the insulated outside diameter follows the ASTM C585 nominal pipe-insulation dimensions, by name. The clearance allowance and the hanger / support span (MSS SP-58) are separate checks; the mechanical contractor governs the rack layout."},
  "pipe-support-spacing": {"inputs":[{"key":"material","label":"Pipe material","kind":"select","options":[{"value":"copper","label":"Copper tube"},{"value":"steel","label":"Steel"},{"value":"cpvc","label":"CPVC"},{"value":"pvc","label":"PVC"},{"value":"pex","label":"PEX"},{"value":"cast_iron","label":"Cast iron"}],"default":"copper","attrs":null},{"key":"pipe_size","label":"Nominal pipe size (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"run_length","label":"Horizontal run to support (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"orientation","label":"Orientation","kind":"select","options":[{"value":"horizontal","label":"Horizontal"},{"value":"vertical","label":"Vertical"}],"default":"horizontal","attrs":null}],"citation":"Citation: IPC 2021 Table 308.5 (hanger spacing) and MSS SP-58 by name; the spacing table ships as editable breakpoints by material and size. hangers = ceil(run / max_spacing) + 1."},
  "pipe-velocity": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"velocity-from-flow","label":"Velocity from flow"},{"value":"max-flow-for-velocity","label":"Max flow for a velocity"}],"default":"velocity-from-flow","attrs":null},{"key":"flow_gpm","label":"Flow (gpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"diameter_in","label":"Inside diameter (in, actual bore)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"material","label":"Material","kind":"select","options":[{"value":"copper","label":"Copper (Type L)"},{"value":"cpvc","label":"CPVC"},{"value":"pex","label":"PEX"},{"value":"steel","label":"Steel (Sch 40)"}],"default":"copper","attrs":null},{"key":"service","label":"Water service","kind":"select","options":[{"value":"hot","label":"Hot (lower copper ceiling)"},{"value":"cold","label":"Cold"}],"default":"hot","attrs":null},{"key":"target_velocity_fps","label":"Target velocity (ft/s, max-flow mode)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Pipe-flow velocity from continuity (v = 0.4085*gpm/d^2) and the copper erosion-corrosion velocity limits (about 5 ft/s hot, 8 ft/s cold) per the Copper Development Association / ASTM and ASPE plumbing-design guidance, by name; first-principles. Pairs with pipe-sizing and friction-loss. Actual inside diameter, not nominal, governs."},
  "piti": {"inputs":[{"key":"principal","label":"Principal (loan amount, $)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"apr_percent","label":"APR (percent)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"30"}},{"key":"term_years","label":"Term (years)","kind":"number","options":null,"default":null,"attrs":{"step":"1","min":"1","max":"50","value":"30"}},{"key":"annual_property_tax","label":"Annual property tax ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"annual_insurance","label":"Annual insurance premium ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"monthly_hoa","label":"Monthly HOA ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"monthly_pmi","label":"Monthly PMI ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: Standard mortgage amortization. Monthly P&I = (P * r) / (1 - (1 + r)^-n) where r = APR/12 and n = term months. Tax and insurance are annual line items spread monthly. HOA and PMI pass through from the user's line items. Lender governs final underwriting and the actual PMI rate."},
  "poe-budget": {"inputs":[{"key":"poe_class","label":"PoE class","kind":"select","options":[{"value":"af","label":"802.3af Type 1 (15.4 W)"},{"value":"at","label":"802.3at Type 2 (30 W)"},{"value":"bt3","label":"802.3bt Type 3 (60 W)"},{"value":"bt4","label":"802.3bt Type 4 (90 W)"}],"default":"at","attrs":null},{"key":"category","label":"Cable category","kind":"select","options":[{"value":"Cat5e","label":"Cat5e"},{"value":"Cat6","label":"Cat6"},{"value":"Cat6A","label":"Cat6A"}],"default":"Cat6","attrs":null},{"key":"run_length_ft","label":"Run length (ft)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"ambient_C","label":"Ambient temp (C)","kind":"number","options":null,"default":25,"attrs":{"step":"any","value":"25"}}],"citation":"Citation: IEEE 802.3 PoE classes (cited by name only). Cable resistance from manufacturer category benchmarks; copper alpha 0.00393 per K applied for ambient correction."},
  "polygon-miter": {"inputs":[{"key":"size_mode","label":"Size given as","kind":"select","options":[{"value":"side","label":"Side length (each piece)"},{"value":"flats","label":"Across flats (face-to-face width)"},{"value":"corners","label":"Across corners (point-to-point)"}],"default":"side","attrs":null}],"citation":"Citation: Regular-polygon frame geometry - each joint is mitered at 180/N degrees off square, the interior angle is (N-2) x 180/N, and the side relates to the across-flats width by s = flats x tan(180/N) and the across-corners diameter by s = corners x sin(180/N) - first-principles trigonometry, public domain. Reproduces the known miters (square 45, hexagon 30, octagon 22.5). Cut a scrap test joint and allow for blade kerf."},
  "pool-chlorine-dose": {"inputs":[{"key":"ppm","label":"Target free-chlorine rise (ppm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"gallons","label":"Pool volume (gallons)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"product","label":"Product","kind":"select","options":[{"value":"cal-hypo-65","label":"Cal-hypo 65% (granular)"},{"value":"liquid-12.5","label":"Liquid chlorine 12.5%"},{"value":"dichlor-56","label":"Dichlor 56%"},{"value":"trichlor-90","label":"Trichlor 90%"},{"value":"custom","label":"Custom (enter %)"}],"default":"cal-hypo-65","attrs":null},{"key":"avail","label":"Available chlorine (%, custom only)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"100"}}],"citation":"Citation: free-chlorine dose = ppm x (gallons/1,000,000) x 8.34 lb, divided by the product available-chlorine fraction; liquid ~10 lb/gal. Product strengths: liquid 12.5%, cal-hypo 65%, dichlor 56%, trichlor 90%. Dose to a target and retest; the product label governs."},
  "pool-interior-finish-volume": {"inputs":[{"key":"length_ft","label":"Pool length (ft)","kind":"number","options":null,"default":30,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"width_ft","label":"Pool width (ft)","kind":"number","options":null,"default":15,"attrs":{"step":"any","min":"0","value":"15"}},{"key":"avg_depth_ft","label":"Average depth (ft)","kind":"number","options":null,"default":5.5,"attrs":{"step":"any","min":"0","value":"5.5"}},{"key":"shell_thickness_in","label":"Gunite shell thickness (in)","kind":"number","options":null,"default":8,"attrs":{"step":"any","min":"0","value":"8"}},{"key":"plaster_thickness_in","label":"Plaster thickness (in)","kind":"number","options":null,"default":0.375,"attrs":{"step":"any","min":"0","value":"0.375"}},{"key":"waste_pct","label":"Gunite waste allowance (%)","kind":"number","options":null,"default":15,"attrs":{"step":"any","min":"0","value":"15"}}],"citation":"Citation: interior-finish identity by name. interior = length x width + 2 x (length + width) x average depth; gunite = interior x shell / 27 x (1 + waste); plaster = interior x plaster / 27."},
  "pool-tile-coping-perimeter": {"inputs":[{"key":"length_ft","label":"Pool length (ft)","kind":"number","options":null,"default":32,"attrs":{"step":"any","min":"0","value":"32"}},{"key":"width_ft","label":"Pool width (ft)","kind":"number","options":null,"default":16,"attrs":{"step":"any","min":"0","value":"16"}},{"key":"tile_length_in","label":"Waterline tile length (in)","kind":"number","options":null,"default":6,"attrs":{"step":"any","min":"0","value":"6"}},{"key":"courses","label":"Waterline tile courses","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1"}},{"key":"coping_length_in","label":"Coping unit length (in)","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"waste_pct","label":"Waste allowance (%)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}}],"citation":"Citation: perimeter-takeoff identity by name. perimeter = 2 x (length + width); tiles = ceil(perimeter / tile length x courses x (1 + waste)); coping = ceil(perimeter / coping length x (1 + waste))."},
  "pool-turnover": {"inputs":[{"key":"chlorine_type","label":"Chlorine product","kind":"select","options":[{"value":"cal_hypo","label":"Cal-hypo (65%)"},{"value":"trichlor","label":"Trichlor (90%)"},{"value":"liquid_bleach","label":"Liquid bleach (12.5%)"}],"default":"cal_hypo","attrs":null}],"citation":"Citation: required flow = pool volume / (turnover hours x 60); chlorine product = volume x ppm x 8.34 / 1,000,000 / available-chlorine fraction. Per the NSPF Certified Pool Operator Handbook (2022) and ANSI/APSP/ICC 11. NSPF governs operator certification; AHJ governs adopted code. Free at phta.org for the APSP-11 TOC."},
  "pool-volume": {"inputs":[{"key":"shape","label":"Pool shape","kind":"select","options":[{"value":"rectangle","label":"Rectangle (L x W)"},{"value":"round","label":"Round (diameter)"},{"value":"oval","label":"Oval (L x W)"}],"default":"rectangle","attrs":null},{"key":"length_ft","label":"Length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"width_ft","label":"Width (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"diameter_ft","label":"Diameter (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"shallow_ft","label":"Shallow-end depth (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"deep_ft","label":"Deep-end depth (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: pool water volume - gallons = surface area x average depth x 7.48052 gal/ft^3, average depth = (shallow + deep)/2. Rectangle area = L x W, round = pi (D/2)^2, oval = (pi/4) L x W. First-principles geometry with the standard 7.48052 gal/ft^3 conversion, per the NSPF CPO Handbook pool-volume method, by name. A field estimate; a metered fill or plan takeoff is more exact."},
  "porta-wrap-friction": {"inputs":[{"key":"load_lb","label":"Load-side tension (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"mu","label":"Rope-on-device friction coefficient","kind":"number","options":null,"default":0.2,"attrs":{"step":"any","min":"0","value":"0.20"}},{"key":"wraps","label":"Wraps to highlight","kind":"number","options":null,"default":3,"attrs":{"step":"1","min":"0","value":"3"}}],"citation":"Citation: capstan / Euler-Eytelwein friction equation and ANSI Z133-2017 by name. hold force = load x exp(-mu x wraps x 2pi). The load side is the dynamic tension under control, not the static weight."},
  "power-distro": {"inputs":[{"key":"phase","label":"Phase","kind":"select","options":[{"value":"three","label":"3-phase"},{"value":"single","label":"1-phase"}],"default":"three","attrs":null}],"citation":"Citation: First-principles AC power (P = V*I*PF; 3-phase adds sqrt(3)). The NEC continuous-load 80% rule and temporary-power Articles 520/525, by name; a qualified electrician and the AHJ govern temporary power. Distinct from neutral-imbalance. Free read-only at nfpa.org/freeaccess."},
  "power-factor-billing-savings": {"inputs":[{"key":"real_power_kw","label":"Billed real power (kW)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"400"}},{"key":"pf_existing","label":"Existing power factor (0-1)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.78"}},{"key":"pf_target","label":"Target power factor (0-1)","kind":"number","options":null,"default":0.95,"attrs":{"step":"any","min":"0","value":"0.95"}},{"key":"demand_per_kva_mo","label":"Demand charge ($/kVA-month)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"8"}},{"key":"capacitor_cost","label":"Capacitor-bank cost ($, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"5685"}}],"citation":"Citation: power-triangle demand-billing method kVA = kW / pf, kVAR = kW x (tan(acos pf_old) - tan(acos pf_new)), demand savings = kVA reduction x $/kVA-month x 12 (by name). Enter the effective $/kVA-month for the tariff. Diminishing returns above ~0.9; a billing estimate, not a rate-tariff analysis."},
  "power-triangle": {"inputs":[{"key":"sign","label":"Reactive sign","kind":"select","options":[{"value":"lagging","label":"Lagging (inductive)"},{"value":"leading","label":"Leading (capacitive)"}],"default":"lagging","attrs":null}],"citation":"Citation: First-principles AC power triangle: kVA^2 = kW^2 + kVAR^2; PF = kW / kVA; theta = arccos(PF). IEEE 1459 defines apparent, real, and reactive power; this tile handles the sinusoidal case. Free at standards.ieee.org for the IEEE 1459 abstract."},
  "ppe": {"inputs":[{"key":"category","label":"Water category","kind":"select","options":[{"value":"1","label":"Category 1"},{"value":"2","label":"Category 2"},{"value":"3","label":"Category 3"}],"default":null,"attrs":null}],"citation":"Citation: Typical PPE selection per OSHA general duty considerations and IICRC S500 (referenced, not reproduced)."},
  "pressure-tank-drawdown": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"find-drawdown","label":"Find drawdown from a tank"},{"value":"size-the-tank","label":"Size the tank for a drawdown"}],"default":"find-drawdown","attrs":null},{"key":"tank_volume_gal","label":"Tank total volume (gal)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"cut_in_psi","label":"Cut-in pressure (psi)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"cut_out_psi","label":"Cut-out pressure (psi)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"precharge_psi","label":"Precharge (psi, default cut-in - 2)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"pump_gpm","label":"Pump capacity (gpm, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"target_drawdown_gal","label":"Target drawdown (gal, size mode)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Pressure-tank drawdown from Boyle's law on the diaphragm air charge (drawdown = V * (Ppre_abs/Pin_abs - Ppre_abs/Pout_abs)) the worst-case cycle rate (maximum cycling occurs when demand is half the pump output, giving a minimum period of 4 x drawdown / pump_gpm, i.e. 15 x pump_gpm / drawdown cycles per hour), and the anti-short-cycle minimum-runtime rule (about 1 min per run), per the published pump/tank engineering practice (Amtrol/WellMate and the WQA references), by name; first-principles gas law. The pump manufacturer's minimum runtime and the installed precharge govern."},
  "primer-tm": {"inputs":[{"key":"method","label":"Method","kind":"select","options":[{"value":"auto","label":"Auto (Wallace <=14 nt, else GC%)"},{"value":"wallace","label":"Wallace 2(A+T)+4(G+C)"},{"value":"gc","label":"Basic GC%"}],"default":"auto","attrs":null}],"citation":"Citation: Per Wallace R.B. et al., Nucleic Acids Research 6 (1979), for the short-oligo rule and Marmur & Doty, J Mol Biol 5 (1962) / standard molecular-biology references for the GC% formula, by name. Complements the pcr-master-mix tile. Nearest-neighbor (SantaLucia) thermodynamics is the modern gold standard. Free abstracts at pubmed.ncbi.nlm.nih.gov."},
  "property-tax": {"inputs":[{"key":"assessed_value","label":"Assessed value ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"mill_rate","label":"Mill rate (mills; 1 mill = $1 per $1000)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"homestead_exemption","label":"Homestead / senior exemption ($, optional)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: 1 mill = $1 tax per $1,000 of assessed value. Annual tax = (assessed_value - exemption) * mill_rate / 1000. Mill rate is set by the local taxing authority; assessed value is set by the county / municipal assessor. Many jurisdictions also publish an 'effective rate' percent; this tile derives that from the inputs for cross-check."},
  "pulling-tension": {"inputs":[{"key":"cable_weight_lb_per_ft","label":"Cable weight (lb/ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"run_length_ft","label":"Total run length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"lubricant","label":"Lubricant","kind":"select","options":[{"value":"dry","label":"Dry (mu 0.50)"},{"value":"wax","label":"Wax (mu 0.35)"},{"value":"polymer","label":"Polymer (mu 0.20)"}],"default":"polymer","attrs":null},{"key":"straight_run_ft","label":"Straight run before bends (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Capstan equation T_out = T_in * exp(mu * theta) accumulated per bend; sidewall pressure approximated as T / R. See docs/derivations.md."},
  "pulse-flowmeter-k-factor": {"inputs":[{"key":"frequency_hz","label":"Output frequency (Hz = pulses/sec)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"k_factor_pulses_per_gal","label":"K-factor (pulses per gallon)","kind":"number","options":null,"default":200,"attrs":{"step":"any","min":"0","value":"200"}}],"citation":"Citation: pulse-output flowmeter (turbine/paddlewheel/PD) K-factor scaling, by name. rate = frequency_Hz x 60 / K-factor (pulses per gallon); totalized volume = pulse count / K-factor. The K-factor is stamped on the meter or its calibration certificate; it drifts with viscosity and at low flow. The calibration cert, linear range, and fluid govern."},
  "punch-capacity": {"inputs":[{"key":"solve_for","label":"Solve for","kind":"select","options":[{"value":"thickness","label":"Max thickness (given a hole diameter)"},{"value":"diameter","label":"Max round-hole diameter (given a thickness)"}],"default":"thickness","attrs":null}],"citation":"Citation: punching force solved for capacity: max thickness = F / (pi x D x shear), max diameter = F / (pi x T x shear), from F = perimeter x thickness x shear strength (F = capacity_tons x 2000 lb) - first-principles as in Machinery's Handbook (Industrial Press), by name; public domain. The shear strength (~0.8 x UTS for mild steel) is user-supplied; keep press margin."},
  "punch-force": {"inputs":[{"key":"shape","label":"Hole shape","kind":"select","options":[{"value":"round","label":"Round (enter diameter)"},{"value":"rectangular","label":"Rectangular (enter two sides)"},{"value":"perimeter","label":"Enter cut perimeter directly"}],"default":"round","attrs":null}],"citation":"Citation: Punching force as sheared area times shear strength - F = perimeter x thickness x shear strength - first-principles as in Machinery's Handbook (Industrial Press), by name; public domain. The shear strength (~0.8 x UTS for mild steel) is user-supplied."},
  "pv-ac-output-circuit": {"inputs":[{"key":"ac_power_w","label":"Inverter AC power (W)","kind":"number","options":null,"default":9600,"attrs":{"step":"any","min":"0","value":"9600"}},{"key":"ac_voltage_v","label":"AC voltage (V, line-to-line)","kind":"number","options":null,"default":240,"attrs":{"step":"any","min":"0","value":"240"}},{"key":"phases","label":"Phases (1 or 3)","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1","value":"1"}}],"citation":"Citation: inverter AC output-circuit conductor and OCPD by name (NEC 690.8(B) / 705.60 / 240.4). I_cont = P / (V x [1 or sqrt(3)]); conductor and OCPD at 125% of I_cont, OCPD to the next standard size (240.6). Check the 705.12 busbar limit separately; the datasheet and NEC govern."},
  "pv-array-sizing": {"inputs":[{"key":"target_annual_kwh","label":"Target annual energy (kWh/yr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"12000"}},{"key":"psh","label":"Peak-sun-hours (kWh/m2/day)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"perf_ratio","label":"Performance ratio (0-1)","kind":"number","options":null,"default":0.77,"attrs":{"step":"any","min":"0","value":"0.77"}}],"citation":"Citation: NREL PVWatts energy model E = Pdc x PSH x 365 x PR solved for the array size, Pdc = E_target / (PSH x 365 x PR) (by name). The peak-sun-hours is the plane-of-array daily irradiation from NREL NSRDB / PVWatts for the site, tilt, and azimuth; the performance ratio (default 0.77, the PVWatts all-loss default) is the single biggest lever. A pre-design estimate, not a bankable production model."},
  "pv-ballast-weight": {"inputs":[{"key":"modules","label":"Module count","kind":"number","options":null,"default":30,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"module_wt_lb","label":"Module weight (lb)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}},{"key":"ballast_per_module_lb","label":"Ballast per module (lb)","kind":"number","options":null,"default":40,"attrs":{"step":"any","min":"0","value":"40"}},{"key":"racking_wt_lb","label":"Total racking weight (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"150"}},{"key":"array_area_sf","label":"Array footprint area (ft^2)","kind":"number","options":null,"default":630,"attrs":{"step":"any","min":"0","value":"630"}},{"key":"allowable_psf","label":"Allowable added pressure (psf)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}}],"citation":"Citation: load-screen identity by name. total = modules x (module weight + ballast) + racking; added pressure = total / array area. A dead-load screen, not a design; the PE-stamped ballast plan and the engineer govern."},
  "pv-cell-temperature-power": {"inputs":[{"key":"T_amb_C","label":"Ambient temperature (C)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"30"}},{"key":"G_wm2","label":"Plane-of-array irradiance (W/m^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"800"}},{"key":"NOCT_C","label":"NOCT (C, datasheet, default 45)","kind":"number","options":null,"default":45,"attrs":{"step":"any","min":"0","value":"45"}},{"key":"P_stc_W","label":"Module STC power (W)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"400"}},{"key":"gamma","label":"Power temp coefficient (%/C, e.g. -0.35)","kind":"number","options":null,"default":-0.35,"attrs":{"step":"any","value":"-0.35"}}],"citation":"Citation: PV NOCT cell-temperature model T_cell = T_amb + (NOCT - 20) x G/800 and the datasheet power temperature coefficient (about -0.35%/C for crystalline silicon), by name. Temperature derate only (no soiling/wiring/inverter/shading). A design aid; the module datasheet governs."},
  "pv-circuit-ampacity": {"inputs":[{"key":"module_isc_a","label":"Module Isc per source circuit (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"parallel_strings","label":"Parallel source circuits (strings)","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1","value":"2"}},{"key":"ocpd_a","label":"Series fuse / OCPD rating to check (A, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: NEC 2023 690.8(A)(1) (max current = Isc x strings x 125%) and 690.8(B)(1) (min ampacity = max current x 125%; the factors stack to 156% of Isc). Also size for 690.8(B)(2) after conditions of use and take the greater. The engineer governs. Free at nfpa.org/freeaccess."},
  "pv-energy-yield": {"inputs":[{"key":"dc_kw","label":"Array DC nameplate (kW)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"8"}},{"key":"psh","label":"Peak-sun-hours (kWh/m2/day)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"perf_ratio","label":"Performance ratio (0-1)","kind":"number","options":null,"default":0.77,"attrs":{"step":"any","min":"0","value":"0.77"}}],"citation":"Citation: NREL PVWatts energy model E = Pdc x PSH x 365 x PR, with specific yield = E / Pdc and capacity factor = E / (Pdc x 8760) (by name). The peak-sun-hours is the plane-of-array daily irradiation from NREL NSRDB / PVWatts for the site, tilt, and azimuth; the performance ratio (default 0.77, the PVWatts all-loss default) is the single biggest lever. A pre-design estimate, not a bankable production model."},
  "pv-interconnection-busbar": {"inputs":[{"key":"method","label":"Interconnection method","kind":"select","options":[{"value":"opposite_end_load_side","label":"Load-side breaker, opposite end from main (120% rule)"},{"value":"load_side_other","label":"Load-side, other position / line-tap (100% rule)"},{"value":"supply_side_tap","label":"Supply-side tap (NEC 705.11; not a busbar rule)"}],"default":"opposite_end_load_side","attrs":null}],"citation":"Citation: Per NEC 2023 Article 705 (Interconnected Electric Power Production Sources). 705.12(B)(3) governs load-side interconnection (the 120% busbar allowance for a breaker at the opposite end of the busbar from the main); 705.11 governs supply-side connections. 'Opposite end of busbar' is a code term of art the AHJ inspector verifies at the panel. AHJ governs. Free at nfpa.org/freeaccess for the NEC table of contents."},
  "pv-inverter-ratio": {"inputs":[{"key":"dc_kw","label":"Array DC nameplate (kW)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"8"}},{"key":"ac_kw","label":"Inverter AC rating (kW)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"6.6"}},{"key":"inv_eff","label":"Inverter peak efficiency (0-1)","kind":"number","options":null,"default":0.96,"attrs":{"step":"any","min":"0","value":"0.96"}}],"citation":"Citation: inverter loading ratio ILR = Pdc / Pac and NREL inverter-sizing guidance; clipping begins where the array DC output exceeds Pac / inverter efficiency (by name). The cost-optimal 1.1-1.3 band shifts with irradiance, equipment price, and energy value; an accurate annual clipping loss needs an 8760-hour simulation. A sizing sanity check, not a clipping-loss model."},
  "pv-max-ambient-for-power": {"inputs":[{"key":"target_power_W","label":"Target power (W)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"358"}},{"key":"P_stc_W","label":"Module STC power (W)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"400"}},{"key":"G_wm2","label":"Plane-of-array irradiance (W/m^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"800"}},{"key":"NOCT_C","label":"NOCT (C, datasheet, default 45)","kind":"number","options":null,"default":45,"attrs":{"step":"any","min":"0","value":"45"}},{"key":"gamma","label":"Power temp coefficient (%/C, e.g. -0.35)","kind":"number","options":null,"default":-0.35,"attrs":{"step":"any","value":"-0.35"}}],"citation":"Citation: PV NOCT cell-temperature model and the datasheet power temperature coefficient (about -0.35%/C for crystalline silicon), by name, solved for the ambient: T_cell = 25 + (P/P_stc - 1) x 100/gamma, T_amb = T_cell - (NOCT - 20) x G/800. Temperature derate only (no soiling/wiring/inverter/shading). A design aid; the module datasheet governs."},
  "pv-rail-clamp-takeoff": {"inputs":[{"key":"rows","label":"Module rows","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"0","value":"2"}},{"key":"modules_per_row","label":"Modules per row","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"module_width_ft","label":"Module width along the rail (ft)","kind":"number","options":null,"default":3.42,"attrs":{"step":"any","min":"0","value":"3.42"}},{"key":"gap_ft","label":"Module-to-module gap (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"rails_per_row","label":"Rails per row","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"0","value":"2"}},{"key":"rail_stock_ft","label":"Rail stock length (ft)","kind":"number","options":null,"default":14,"attrs":{"step":"any","min":"0","value":"14"}}],"citation":"Citation: racking-takeoff identity by name. run = modules x (width + gap); rail = rows x rails x run; mid clamps = rails x rows x (modules - 1); end clamps = 2 x rails x rows; splices = (ceil(run / stock) - 1) x rails x rows."},
  "pv-row-shade-angle": {"inputs":[{"key":"module_length_ft","label":"Module slope length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"6.5"}},{"key":"tilt_deg","label":"Array tilt (degrees)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"row_pitch_ft","label":"Available row pitch (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"12"}}],"citation":"Citation: NREL / Sandia PV row-spacing geometry solved for the profile angle: prof = atan(L sin(tilt) / (pitch - L cos(tilt))) (by name). With the pitch fixed by the roof, this is the lowest sun elevation the layout stays shade-free to; compare it to the winter-design sun elevation. Assumes due-south rows and a level field."},
  "pv-row-spacing": {"inputs":[{"key":"module_length_ft","label":"Module slope length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"6.5"}},{"key":"tilt_deg","label":"Array tilt (degrees)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"profile_angle_deg","label":"Min solar profile angle (degrees)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"22"}}],"citation":"Citation: NREL / Sandia PV array row-spacing geometry pitch = L x cos(tilt) + L x sin(tilt) / tan(profile angle), GCR = L / pitch (by name). The minimum profile angle is the winter-design sun elevation (from latitude or solar-times). Assumes due-south rows and a level field. A layout geometry, not an annual shading-loss model."},
  "pv-string-fusing": {"inputs":[{"key":"Isc_A","label":"Module Isc (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"max_fuse_A","label":"Module max series fuse (A, from label)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"n_strings","label":"Paralleled source circuits","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1","value":"4"}}],"citation":"Citation: NEC 690.9(B) PV source-circuit overcurrent: OCPD >= 1.56 x Isc (1.25 x 1.25), rounded up to a 240.6(A) standard rating, checked against the module label maximum series fuse; fuses required with 3+ paralleled source circuits (690.9(A)), by name. A design aid; the NEC and the AHJ govern."},
  "pv-string-sizing": {"inputs":[{"key":"module_voc_V","label":"Module Voc (V)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"module_vmp_V","label":"Module Vmp (V)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"voc_temp_coeff_pct_per_C","label":"Voc temp coeff (% per C, magnitude)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"record_low_C","label":"Record low temp (C)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"record_high_C","label":"Record high temp (C)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"inverter_mppt_min_V","label":"Inverter MPPT min (V)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"inverter_mppt_max_V","label":"Inverter MPPT max (V)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"inverter_vdc_max_V","label":"Inverter Vdc max (V)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Cold-temperature Voc inflation (V_oc_cold = V_oc * (1 + |coeff| * (25 - T_low) / 100)) and warm-temperature Vmp depression (V_mp_warm = V_mp * (1 - |coeff| * (T_high - 25) / 100)). See docs/derivations.md."},
  "quadratic-formula": {"inputs":[{"key":"a","label":"a (quadratic coefficient)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"1"}},{"key":"b","label":"b (linear coefficient)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"0"}},{"key":"c","label":"c (constant)","kind":"number","options":null,"default":null,"attrs":{"step":"any","value":"0"}}],"citation":"Citation: Standard quadratic formula. For ax^2 + bx + c = 0 the roots are (-b +/- sqrt(b^2 - 4ac)) / (2a); the discriminant b^2 - 4ac signs the root type (positive = two real, zero = one real double, negative = complex conjugate pair). The vertex is at x = -b/(2a)."},
  "radial-chip-thinning": {"inputs":[{"key":"ae_in","label":"Radial width of cut ae (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"d_in","label":"Cutter diameter D (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"fz_target","label":"Target chip load fz (in/tooth)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: radial chip thinning factor RCTF = 1/(2 sqrt((ae/D) - (ae/D)^2)) for ae < D/2, the compensated feed fz_prog = fz_target x RCTF, RCTF = 1.0 at half immersion and above, per the modern milling / Machinery's Handbook references, by name. Radial thinning only. A shop aid; the tool maker's chip load governs."},
  "radiant-floor-output": {"inputs":[{"key":"mode","label":"Solve for","kind":"select","options":[{"value":"surface_to_q","label":"Output from a surface temperature"},{"value":"q_to_surface","label":"Surface temperature for a target output"}],"default":"surface_to_q","attrs":null}],"citation":"Citation: Radiant floor heat output q = 2 x (T_surface - T_room)^1.1 Btu/hr-ft^2 (ASHRAE / radiant-panel practice), with the ~85 F mean-surface comfort limit (~39 Btu/hr-ft^2 in a 70 F room). A design aid; the panel manufacturer's ratings govern."},
  "radiant-loop-sizing": {"inputs":[{"key":"floor_area_ft2","label":"Heated floor area (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"spacing_in","label":"Tube on-center spacing (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"9"}},{"key":"load_btuhr","label":"Design heat load (Btu/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"max_loop_ft","label":"Max loop length (ft)","kind":"number","options":null,"default":300,"attrs":{"step":"any","min":"0","value":"300"}},{"key":"design_dt","label":"Supply-to-return delta-T (F)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}}],"citation":"Citation: Radiant floor loop sizing - tube footage = area x 12 / spacing; loops = ceil(footage / max loop length); flow GPM = Q / (500 x delta-T), split across the loops - first-principles, with the radiant-panel practice per ASHRAE HVAC Systems and Equipment (radiant panel chapter) and the Radiant Panel Association, by name. The manufacturer's tubing tables and the room-by-room heat loss govern the final layout; this sizes footage, loops, and flow from a uniform load, not the panel surface-temperature or downward-loss design."},
  "radiator-edr-output": {"inputs":[{"key":"edr_sqft","label":"Connected EDR (sq ft)","kind":"number","options":null,"default":320,"attrs":{"step":"any","min":"0","value":"320"}},{"key":"system_k","label":"EDR constant (240 steam, 150 hot water)","kind":"number","options":null,"default":240,"attrs":{"step":"any","min":"0","value":"240"}},{"key":"pickup_factor","label":"Boiler pickup factor (0.33 steam, 0.15 HW)","kind":"number","options":null,"default":0.33,"attrs":{"step":"any","min":"0","value":"0.33"}}],"citation":"Citation: radiator EDR to heat output, Hydronics Institute / I=B=R basis, by name. Q = EDR x k; k = 240 BTU/hr per sq ft (steam, 215 F / 70 F room), 150 (hot water, 170 F avg). Gross boiler = net x (1 + pickup); I=B=R pickup ~0.33 steam, ~0.15 hot water; select by NET rating. The radiator EDR, the real piping/pickup, and the boiler's I=B=R rating govern."},
  "rafter": {"inputs":[{"key":"horizontal_span_ft","label":"Horizontal span (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"pitch_rise_per_12","label":"Pitch (rise per 12)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"overhang_ft","label":"Overhang (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: per IRC 2021 Table R802.5.1 (rafter spans). Rafter = horizontal span * sqrt(1 + (rise/run)^2) by Pythagoras. AHJ governs. Free at codes.iccsafe.org."},
  "range-demand-220-55": {"inputs":[{"key":"num_ranges","label":"Number of ranges (equal rating)","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1","value":"1"}},{"key":"nameplate_kw","label":"Each range nameplate (kW)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"supply_v","label":"Service voltage (V)","kind":"number","options":null,"default":240,"attrs":{"step":"any","min":"0","value":"240"}}],"citation":"Citation: NEC 2023 Table 220.55 Column C and its Notes (household electric ranges, wall ovens, counter cooktops). One 12 kW range demands 8 kW, not 12; a range over 12 kW gets a 5%-per-kW Column C increase (Note 1). The AHJ-adopted edition governs. Free at nfpa.org/freeaccess."},
  "rcf-rpm": {"inputs":[{"key":"rotor_radius_mm","label":"Rotor radius (mm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"rpm","label":"RPM (leave 0 to solve)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"rcf","label":"RCF (g, leave 0 to solve)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: RCF (g) = 1.118e-5 * r(cm) * RPM^2. First principles."},
  "reaming-drill-allowance": {"inputs":[{"key":"reamer_diameter_in","label":"Finished reamer diameter (in)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","min":"0","value":"0.5"}},{"key":"allowance_override_in","label":"Allowance override (in, 0 = auto band)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: machine-reaming stock allowance by name. drill = reamer diameter - allowance; Machinery's Handbook diameter-band allowances (~0.010 under 1/4, 0.015 to 1/2, 0.020 to 1, 0.025 to 1-1/2, 0.030 to 2 in). The reamer maker's guidance and the material govern."},
  "rebar": {"inputs":[{"key":"length_ft","label":"Length (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"width_ft","label":"Width (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"spacing_in","label":"Spacing on center (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"1","value":"12"}},{"key":"edge_clearance_in","label":"Edge clearance (in)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","value":"3"}},{"key":"bar_size","label":"Bar size","kind":"select","options":[{"value":"#3","label":"#3"},{"value":"#4","label":"#4"},{"value":"#5","label":"#5"},{"value":"#6","label":"#6"}],"default":"#4","attrs":null}],"citation":"Citation: Rebar quantity from grid spacing minus edge clearances on both axes."},
  "reduced-voltage-starter": {"inputs":[{"key":"across_line_lrt_pct","label":"Across-the-line torque basis (%)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0"}},{"key":"starter_type","label":"Starter type","kind":"select","options":[{"value":"autotransformer","label":"Autotransformer (line = tap^2)"},{"value":"wye-delta","label":"Wye-delta (fixed 1/3)"},{"value":"solid-state","label":"Solid-state / reactor (line = tap)"}],"default":"autotransformer","attrs":null},{"key":"tap_fraction","label":"Tap / voltage fraction (e.g. 0.65)","kind":"number","options":null,"default":0.65,"attrs":{"step":"any","min":"0","max":"1"}}],"citation":"Citation: reduced-voltage-starter current and torque (NEMA ICS 2; torque ~ voltage^2): autotransformer motor = tap x LRA, line = tap^2 x LRA, torque = tap^2 x LRT; wye-delta = 0.333x on current and torque; solid-state/reactor = tap x LRA on both with tap^2 x LRT. An autotransformer's line current is the tap squared. A design aid; the motor speed-torque curve and the load govern."},
  "reducer-offset": {"inputs":[{"key":"large_od_in","label":"Large-end OD (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"small_od_in","label":"Small-end OD (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"lay_length_in","label":"Lay length (in, B16.9 / fitting)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"type","label":"Reducer type","kind":"select","options":[{"value":"concentric","label":"Concentric (centerline)"},{"value":"eccentric-flat-bottom","label":"Eccentric flat-on-bottom (invert)"},{"value":"eccentric-flat-top","label":"Eccentric flat-on-top (crown)"}],"default":"concentric","attrs":null}],"citation":"Citation: Reducer centerline offset = (large OD - small OD) / 2, and which surface stays continuous by type - concentric holds the centerline, eccentric flat-on-bottom holds the invert, eccentric flat-on-top holds the crown - first-principles geometry, with the standard lay lengths per ASME B16.9 (bundled value entered by the user; a non-standard reducer overrides). Flat-on-bottom keeps a drain self-cleaning and flat-on-top keeps a pump suction free of air. The lay length is a fitting dimension, not a code minimum."},
  "reeving-parts-of-line": {"inputs":[{"key":"load_lb","label":"Load (lb)","kind":"number","options":null,"default":20000,"attrs":{"step":"any","min":"0","value":"20000"}},{"key":"parts_of_line","label":"Parts of line","kind":"number","options":null,"default":4,"attrs":{"step":"1","min":"1","value":"4"}},{"key":"sheave_efficiency","label":"Per-sheave efficiency (0.98 roller, 0.96 plain)","kind":"number","options":null,"default":0.98,"attrs":{"step":"any","min":"0","max":"1","value":"0.98"}}],"citation":"Citation: block-and-tackle reeving line pull, by name. pull = load x (1 - k) / (1 - k^N); reeving efficiency = load / (N x pull); k per-sheave ~0.98 roller / 0.96 plain. Steady hauling pull on the lead line only (not the inertia to start the load). The block/rope ratings, the sheave friction, and a qualified rigger and lift plan govern."},
  "refrigerant-charging": {"inputs":[{"key":"suction_pressure","label":"Suction pressure","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"suction_unit","label":"Suction unit","kind":"select","options":[{"value":"psig","label":"psig (gauge)"},{"value":"psia","label":"psia (absolute)"}],"default":"psig","attrs":null},{"key":"suction_line_temp_F","label":"Suction line T (°F)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"liquid_pressure","label":"Liquid pressure","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"liquid_unit","label":"Liquid unit","kind":"select","options":[{"value":"psig","label":"psig (gauge)"},{"value":"psia","label":"psia (absolute)"}],"default":"psig","attrs":null},{"key":"liquid_line_temp_F","label":"Liquid line T (°F)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}}],"citation":"Citation: Manufacturer-attributed P-T tables (data/hvac/refrigerant-pt-tables.json). psig is the gauge default; toggle to psia per input. Manufacturer typical 8-12 °F superheat / 8-15 °F subcool when no charging chart applies."},
  "refrigerant-lineset-charge-adjust": {"inputs":[{"key":"lineset_length_ft","label":"Actual line-set length (ft)","kind":"number","options":null,"default":60,"attrs":{"step":"any","min":"0","value":"60"}},{"key":"factory_charge_length_ft","label":"Factory pre-charge length (ft)","kind":"number","options":null,"default":15,"attrs":{"step":"any","min":"0","value":"15"}},{"key":"rate_oz_per_ft","label":"Charge rate (oz/ft)","kind":"number","options":null,"default":0.6,"attrs":{"step":"any","min":"0","value":"0.6"}}],"citation":"Citation: charge-adder identity by name. extra = max(0, actual line-set length - factory pre-charge length) x rate (oz/ft). The rate and factory length come from the nameplate; only the liquid line adds meaningful charge, and the total is weighed in."},
  "refrigeration-cop": {"inputs":[{"key":"h1_btulb","label":"Suction enthalpy h1 (Btu/lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"h2_btulb","label":"Discharge enthalpy h2 (Btu/lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"h4_btulb","label":"Evaporator-inlet enthalpy h4 (Btu/lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"tevap_f","label":"Evaporator saturation temp (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"tcond_f","label":"Condenser saturation temp (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}}],"citation":"Citation: cooling COP = (h1 - h4)/(h2 - h1), the Carnot limit COP_Carnot = T_evap/(T_cond - T_evap) in Rankine, the second-law efficiency COP/COP_Carnot, and EER = 3.412 x COP, by name. Enter the P-h enthalpies and saturation temperatures; no parasitic loads. An engineering aid; the property data govern."},
  "reineke-sdi": {"inputs":[{"key":"trees_per_acre","label":"Trees per acre (live stems)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"300"}},{"key":"qmd_in","label":"Quadratic mean diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"sdi_max","label":"Species maximum SDI (0 to skip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"400"}}],"citation":"Citation: Reineke Stand Density Index (Reineke 1933; USDA FS RMRS), by name. SDI = TPA x (QMD/10)^1.605; percent of max = SDI / SDI_max x 100. SDI uses the quadratic mean diameter (the diameter of the tree of average basal area), not the arithmetic mean; the 1.605 exponent is the empirical self-thinning slope; the maximum SDI is species-specific. A management aid; a qualified silvicultural prescription governs."},
  "relative-compaction": {"inputs":[{"key":"wet_pcf","label":"Field wet density (pcf)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"w_pct","label":"Field moisture content (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"max_pcf","label":"Proctor maximum dry density (pcf)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"spec_pct","label":"Required relative compaction (%)","kind":"number","options":null,"default":95,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: relative compaction RC = (gamma_d,field / gamma_d,max) x 100, field dry density gamma_d,field = gamma_wet / (1 + w), Proctor maximum from ASTM D698 / D1557, typical 90-95% specs, by name. Enter the Proctor maximum. A QC aid; the geotechnical spec governs."},
  "restrained-pipe-length": {"inputs":[{"key":"pipe_od_in","label":"Pipe outside diameter (in)","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"pressure_psi","label":"Design (test) pressure (psi)","kind":"number","options":null,"default":150,"attrs":{"step":"any","min":"0","value":"150"}},{"key":"bend_angle_deg","label":"Horizontal bend angle (deg)","kind":"number","options":null,"default":90,"attrs":{"step":"any","min":"0","value":"90"}},{"key":"unit_resistance_plf","label":"Soil resistance per foot (lb/ft)","kind":"number","options":null,"default":600,"attrs":{"step":"any","min":"0","value":"600"}}],"citation":"Citation: thrust / restrained-length identity by name. thrust (lb) = 2 x pressure x area x sin(bend/2); length each side (ft) = thrust / unit resistance. The unit resistance comes from the restraint manufacturer's tables (EBAA / AWWA M41)."},
  "resuspension-volume": {"inputs":[{"key":"mass_g","label":"Lyophilized mass (g)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"target_concentration","label":"Target concentration (g/L)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: volume = mass / target concentration. First principles."},
  "retainage-tracker": {"inputs":[{"key":"work_this_period_usd","label":"Work this period (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"retainage_pct","label":"Retainage rate (%)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","max":"100"}},{"key":"prior_retained_usd","label":"Prior retained (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Retainage on a progress payment (AIA G702 Application and Certificate for Payment / G703 Continuation Sheet): retention this period = work completed x retainage rate, net payment = work - retention, cumulative retention = prior + this period. A billing aid; the contract terms and the owner's certified payment govern."},
  "ripper-production": {"inputs":[{"key":"spacing_ft","label":"Shank spacing / pass width (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"penetration_ft","label":"Ripping depth (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"speed_fpm","label":"Ripping speed (ft/min)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"efficiency","label":"Job efficiency","kind":"number","options":null,"default":0.75,"attrs":{"step":"any","min":"0","value":"0.75"}}],"citation":"Citation: swept-prism production identity by name. production (bank cy/hr) = shank spacing x penetration x speed x 60 / 27 x efficiency, where 60 folds minutes to the hour and 27 the cubic yard."},
  "riprap-d50": {"inputs":[{"key":"velocity_fps","label":"Flow velocity against the stone (ft/s)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"specific_gravity","label":"Stone specific gravity Ss","kind":"number","options":null,"default":2.65,"attrs":{"step":"any","min":"0","value":"2.65"}},{"key":"turbulence_coeff","label":"Isbash turbulence coefficient C","kind":"number","options":null,"default":0.86,"attrs":{"step":"any","min":"0","value":"0.86"}},{"key":"safety_factor","label":"Safety factor SF","kind":"number","options":null,"default":1.2,"attrs":{"step":"any","min":"0","value":"1.2"}}],"citation":"Citation: Isbash riprap-sizing identity by name. D50 = SF x V^2 / (2 g C^2 (Ss - 1)), g = 32.2 ft/s^2; C ~ 0.86 high-turbulence, ~1.20 low-turbulence. A public-domain field estimate; the hydraulic engineer governs."},
  "riprap-tonnage": {"inputs":[{"key":"area_sf","label":"Plan area of the riprap layer (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"thickness_ft","label":"Layer thickness (ft, at least 1.5 x D50)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"unit_wt_pcf","label":"Stone unit weight (pcf)","kind":"number","options":null,"default":165,"attrs":{"step":"any","min":"0","value":"165"}}],"citation":"Citation: layer take-off identity by name. volume (cy) = area x thickness / 27; tons = area x thickness x unit weight / 2000. Order to the placed density (voids), not the solid rock."},
  "rlc-reactance-resonance": {"inputs":[{"key":"frequency_hz","label":"Frequency (Hz)","kind":"number","options":null,"default":60,"attrs":{"step":"any","min":"0","value":"60"}},{"key":"resistance_ohm","label":"Resistance R (ohms)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"inductance_h","label":"Inductance L (H)","kind":"number","options":null,"default":0.05,"attrs":{"step":"any","min":"0","value":"0.05"}},{"key":"capacitance_uf","label":"Capacitance C (uF)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}}],"citation":"Citation: series R-L-C reactance / impedance / resonance relations, by name. XL = 2 pi f L; XC = 1/(2 pi f C); Z = sqrt(R^2 + (XL - XC)^2); PF = R/Z; resonant f0 = 1/(2 pi sqrt(L C)). Single-frequency lumped-element steady state; a harmonic/transient study governs a power-system resonance."},
  "ro-recovery-concentration": {"inputs":[{"key":"feed_gpm","label":"Feed flow (gpm)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"permeate_gpm","label":"Permeate flow (gpm)","kind":"number","options":null,"default":7.5,"attrs":{"step":"any","min":"0","value":"7.5"}},{"key":"feed_tds_mgl","label":"Feed TDS (mg/L)","kind":"number","options":null,"default":500,"attrs":{"step":"any","min":"0","value":"500"}}],"citation":"Citation: RO mass balance by name (AMTA / AWWA membrane practice). recovery = permeate/feed; concentrate flow = feed - permeate; concentration factor CF = 1/(1-recovery); concentrate TDS ~ CF x feed TDS at high rejection. The membrane maker's projection and the state primacy agency govern."},
  "rock-construction-entrance": {"inputs":[{"key":"length_ft","label":"Entrance length (ft)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}},{"key":"width_ft","label":"Entrance width (ft)","kind":"number","options":null,"default":14,"attrs":{"step":"any","min":"0","value":"14"}},{"key":"depth_in","label":"Stone depth (in)","kind":"number","options":null,"default":6,"attrs":{"step":"any","min":"0","value":"6"}},{"key":"unit_wt_pcf","label":"Placed stone unit weight (pcf)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}}],"citation":"Citation: pad take-off identity by name. volume (cy) = length x width x depth/12 / 27; tons = length x width x depth/12 x placed unit weight / 2000. The general permit / AHJ sets the pad dimensions."},
  "rolled-blank": {"inputs":[{"key":"reference","label":"Diameter reference","kind":"select","options":[{"value":"od","label":"Outside diameter (OD)"},{"value":"id","label":"Inside diameter (ID)"}],"default":"od","attrs":null}],"citation":"Citation: Developed blank length to roll plate into a cylinder - L = pi x neutral-axis diameter, neutral axis at k x thickness from the inside (default k = 0.5 mid-thickness) - first-principles arc-length geometry as in Machinery's Handbook (Industrial Press), by name; public domain."},
  "roller-jack-force": {"inputs":[{"key":"load_lb","label":"Load on the skates (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"roll_coef","label":"Rolling coefficient (skate ~0.02-0.05)","kind":"number","options":null,"default":0.03,"attrs":{"step":"any","min":"0","value":"0.03"}},{"key":"incline_deg","label":"Incline (deg, 0 = level)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"skate_cap_lb","label":"Capacity of one skate (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: standard machinery-moving practice (rolling resistance + grade) by name. roll force = load x coefficient x cos(incline); grade force = load x sin(incline); breakaway = 1.5x steady. Estimate - verify the floor capacity."},
  "roof-drain-sizing": {"inputs":[{"key":"roof_area","label":"Roof area served (ft^2, horizontally projected)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"rainfall_rate","label":"Design rainfall, 100-yr / 1-hr (in/hr)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"drain_slope","label":"Horizontal storm-drain slope","kind":"select","options":[{"value":"1/8","label":"1/8 in per ft"},{"value":"1/4","label":"1/4 in per ft"},{"value":"1/2","label":"1/2 in per ft"}],"default":"1/4","attrs":null}],"citation":"Citation: IPC 2021 Section 1106 (Tables 1106.2 vertical conductors, 1106.3 horizontal storm drains, 1106.6 roof drains) by name; the capacity tables ship as editable conservative breakpoints, not a transcribed table. Storm flow gpm = area x rainfall x 0.0104."},
  "rooftop-temp-adder": {"inputs":[{"key":"measured_ambient_f","label":"Measured outdoor ambient (deg-F)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"height_above_roof_in","label":"Height above roof (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"base_ampacity_a","label":"Base ampacity (A, 90 C column)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: NEC 2023 310.15(B)(2) (raceways and cables exposed to sunlight on or above rooftops) - a 33 deg-C (60 deg-F) adder to the ambient where the raceway is less than 7/8 in above the roof, then the 90 C-column temperature correction. The AHJ-adopted NEC edition governs. Free at nfpa.org/freeaccess."},
  "rotary-phase-converter-sizing": {"inputs":[{"key":"largest_motor_hp","label":"Largest single motor (HP)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"total_running_hp","label":"Total HP running at once","kind":"number","options":null,"default":15,"attrs":{"step":"any","min":"0","value":"15"}},{"key":"start_factor","label":"Start factor (2 normal, 3 high-inertia)","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"1","value":"2"}}],"citation":"Citation: rotary phase converter idler sizing by name. idler HP = max(start factor x largest motor HP, total running HP); ~2x start factor for normal loads, 3x for high-inertia. The converter manufacturer's data and the motor locked-rotor current govern."},
  "rtd-resistance-to-temp": {"inputs":[{"key":"resistance_ohms","label":"Measured resistance (ohms)","kind":"number","options":null,"default":119.397,"attrs":{"step":"any","min":"0","value":"119.397"}},{"key":"r0_ohms","label":"R0 at 0 C (100 = Pt100, 1000 = Pt1000)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}}],"citation":"Citation: IEC 60751 platinum RTD (Callendar-Van Dusen) resistance-temperature relation, by name; standard coefficients A = 3.9083e-3, B = -5.775e-7 per C. R = R0(1 + A T + B T^2), solved for T (exact T >= 0 C; below 0 C drops the C-term, a close approximation). Assumes a lead-compensated (3/4-wire) reading; the sensor calibration and class govern."},
  "rusle-soil-loss": {"inputs":[{"key":"r_factor","label":"Rainfall-runoff erosivity R","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"k_factor","label":"Soil erodibility K","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"ls_factor","label":"Slope length-steepness LS","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"c_factor","label":"Cover-management C","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"p_factor","label":"Support-practice P","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"acres","label":"Disturbed area (acres)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: RUSLE identity by name (USDA public-domain). A = R x K x LS x C x P (tons/acre/yr); site loss = A x acres. Every factor is user-entered from the SWPPP designer or state guidance."},
  "sales-tax-compound": {"inputs":[{"key":"pre_tax","label":"Pre-tax amount (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"post_tax","label":"Post-tax amount (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"rate1_pct","label":"Rate 1 (state, percent)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"rate2_pct","label":"Rate 2 (local, percent)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: arithmetic. State and local rates supplied by user."},
  "sample-size-for-margin": {"inputs":[{"key":"proportion","label":"Planning proportion (0 to 1; use 0.5 for worst case)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"1"}},{"key":"target_moe","label":"Target margin of error (0 to 1)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"1"}},{"key":"confidence_pct","label":"Confidence level","kind":"select","options":[{"value":"80","label":"80%"},{"value":"90","label":"90%"},{"value":"95","label":"95%"},{"value":"98","label":"98%"},{"value":"99","label":"99%"}],"default":null,"attrs":null}],"citation":"Citation: sample size for a target margin of error on a proportion, the inverse of the Wald interval MOE = z * sqrt(p * (1-p) / n). Solving for n gives n = z^2 * p * (1-p) / E^2, rounded up. p = 0.5 is the conservative planning value (it maximizes p(1-p), so it gives the largest n and covers any true proportion). z critical values from the standard normal: 80% = 1.2816, 90% = 1.6449, 95% = 1.96, 98% = 2.3263, 99% = 2.5758. For small p or small n a Wilson or Clopper-Pearson design is more exact; this is the standard planning figure."},
  "scupper-width-for-flow": {"inputs":[{"key":"required_gpm","label":"Required overflow flow (gpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"head_in","label":"Head above scupper invert (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Overflow scupper as a rectangular weir Q = 3.33 L H^1.5 (cfs, feet) solved for the width: L = Q / (3.33 H^1.5) suppressed, L = Q / (3.33 H^1.5) + 0.2 H contracted (IPC 1108 secondary drainage / FM Global). Head at the blocked-primary condition. A design aid; the plumbing code and roof-loading check govern."},
  "se-tax": {"inputs":[{"key":"net_se_earnings","label":"Net SE earnings (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"w2_ss_wages","label":"W-2 wages already subject to SS (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"filing_status","label":"Filing status","kind":"select","options":[{"value":"single","label":"Single"},{"value":"mfj","label":"Married filing jointly"},{"value":"mfs","label":"Married filing separately"},{"value":"hoh","label":"Head of household"}],"default":"single","attrs":null}],"citation":"Citation: Schedule SE (Form 1040). Social Security wage base from SSA annual announcement; Additional Medicare 0.9% threshold from IRC 3101(b)(2)."},
  "sediment-basin-volume": {"inputs":[{"key":"disturbed_ac","label":"Disturbed drainage area (acres)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"storage_rule_cf_per_ac","label":"Required storage per acre (cf/acre)","kind":"number","options":null,"default":3600,"attrs":{"step":"any","min":"0","value":"3600"}},{"key":"basin_depth_ft","label":"Usable settling depth (ft)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","value":"3"}}],"citation":"Citation: sediment-basin storage identity by name. required volume = disturbed acres x per-acre storage rule (commonly ~3,600 cf/acre wet storage); surface area = volume / usable depth. The construction general permit or AHJ sets the per-acre rule."},
  "seer-eer": {"inputs":[{"key":"value","label":"Value","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"from","label":"From","kind":"select","options":[{"value":"EER","label":"EER"},{"value":"SEER","label":"SEER"},{"value":"SEER2","label":"SEER2"},{"value":"EER2","label":"EER2"}],"default":null,"attrs":null},{"key":"cooling_load_btu_hr","label":"Cooling load (BTU/hr, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"annual_hours","label":"Annual cooling hours (optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"electricity_rate","label":"Electricity rate ($/kWh, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: SEER and EER are rated under different conditions. The 1.12 conversion factor is an engineering approximation; actual values depend on the rating method."},
  "septic-dose-tank": {"inputs":[{"key":"daily_flow_gpd","label":"Design daily flow (gpd)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"doses_per_day","label":"Doses per day","kind":"number","options":null,"default":4,"attrs":{"step":"1","min":"0","value":"4"}},{"key":"drainback_gal","label":"Drainback (gal)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: USEPA Onsite Wastewater Treatment Systems Manual (EPA/625/R-00/008) and university onsite-wastewater extension low-pressure-pipe design guidance, by name. Net dose = daily flow / doses; the pump moves the net dose plus the drainback each cycle. Dose count, dose volume, and float settings on the permit drawing govern. Free at epa.gov/septic."},
  "septic-lpp-orifice": {"inputs":[{"key":"orifice_dia_in","label":"Orifice diameter (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0.25"}},{"key":"squirt_ft","label":"Squirt height (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"cd","label":"Discharge coefficient Cd","kind":"number","options":null,"default":0.6,"attrs":{"step":"any","min":"0","value":"0.6"}},{"key":"orifices_per_lateral","label":"Orifices per lateral","kind":"number","options":null,"default":null,"attrs":{"step":"1","min":"0"}},{"key":"num_laterals","label":"Number of laterals","kind":"number","options":null,"default":null,"attrs":{"step":"1","min":"0"}}],"citation":"Citation: orifice-discharge equation Q = 19.63 x Cd x d^2 x sqrt(h) (gpm, inches, feet) and university onsite-wastewater extension low-pressure-pipe design guidance, by name. Cd 0.6 gives the familiar 11.79 coefficient. Orifice size, spacing, and lateral layout come from the permitted onsite design."},
  "septic-lpp-squirt-head": {"inputs":[{"key":"per_orifice_gpm","label":"Target per-orifice discharge (gpm)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"orifice_dia_in","label":"Orifice diameter (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"cd","label":"Discharge coefficient","kind":"number","options":null,"default":0.6,"attrs":{"step":"any","min":"0","value":"0.6"}}],"citation":"Citation: LPP orifice discharge Q = 19.63 Cd d^2 sqrt(h) (Cd 0.6 gives the 11.79 coefficient) solved for the head: h = ( Q / (19.63 Cd d^2) )^2; squirt pressure = h x 0.433 psi/ft. Target squirt 2.5-5 ft (LPP). The permitted onsite design and the state primacy agency govern."},
  "septic-pumpout-interval": {"inputs":[{"key":"tank_gal","label":"Tank working volume (gal)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"people","label":"Household occupants","kind":"number","options":null,"default":null,"attrs":{"step":"1","min":"0"}},{"key":"accum_gal_pp_yr","label":"Accumulation (gal/person/yr)","kind":"number","options":null,"default":30,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"fill_fraction","label":"Fill fraction before pumping","kind":"number","options":null,"default":0.33,"attrs":{"step":"any","min":"0","value":"0.33"}}],"citation":"Citation: USEPA Onsite Wastewater Treatment Systems Manual (EPA/625/R-00/008) and university onsite-wastewater extension pumping-frequency guidance, by name. Years = (tank x fill fraction) / (people x accumulation per person per year). A sludge-judge measurement, not a calendar, governs. Free at epa.gov/septic."},
  "septic-tank": {"inputs":[{"key":"bedrooms","label":"Bedrooms","kind":"number","options":null,"default":null,"attrs":{"step":"1","min":"0"}},{"key":"gallons_per_day","label":"Daily flow gpd (overrides bedrooms if > 0)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: EPA Onsite Wastewater Treatment Manual (EPA/625/R-00/008). 150 gpd per bedroom rule of thumb; tank floor 1000 gal; tank gallons >= 2 * daily flow. State primacy agency governs final design. Free at epa.gov/septic."},
  "septic-tank-for-interval": {"inputs":[{"key":"target_years","label":"Target years between pump-outs","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"people","label":"Household occupants","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}},{"key":"accum_gal_pp_yr","label":"Accumulation (gal/person/yr)","kind":"number","options":null,"default":30,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"fill_fraction","label":"Fill fraction before pumping","kind":"number","options":null,"default":0.33,"attrs":{"step":"any","min":"0","value":"0.33"}}],"citation":"Citation: USEPA Onsite Wastewater Treatment Systems Manual (EPA/625/R-00/008) and university onsite-wastewater extension pumping-frequency guidance, by name (years = tank x fill / (people x accumulation), solved for the tank). State minimum tank sizes by bedroom count usually govern the actual tank. Free at epa.gov/septic."},
  "serial-dilution": {"inputs":[{"key":"starting_concentration","label":"Starting concentration","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"dilution_factor","label":"Dilution factor (>1)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"1.0001"}},{"key":"volume_per_tube","label":"Volume per tube (L)","kind":"number","options":null,"default":0.001,"attrs":{"step":"any","min":"0"}},{"key":"number_of_steps","label":"Number of steps","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1"}}],"citation":"Citation: serial dilution. First principles. Each step concentration = previous / dilution factor."},
  "service-conductor-sizing": {"inputs":[{"key":"service_A","label":"Service or main-feeder rating (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"material","label":"Conductor material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":"copper","attrs":null}],"citation":"Citation: NEC 2023 310.12(A)/(B) dwelling service/feeder 83% allowance (A_req = 0.83 x service rating, conductor from the Table 310.16 75 degC column; Table 310.12 tabulates 100 A -> #4 Cu, 200 A -> 2/0 Cu), by name. Single-phase 120/240 V dwelling only; adjustments and the neutral are separate. The AHJ governs."},
  "service-load": {"inputs":[{"key":"area_ft2","label":"Conditioned area (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"small_appliance_circuits","label":"Small-appliance circuits (min 2)","kind":"number","options":null,"default":2,"attrs":{"step":"1","min":"0","value":"2"}},{"key":"laundry_circuits","label":"Laundry circuits","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"0","value":"1"}},{"key":"fixed_appliances_W","label":"Fixed appliances total (W)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"range_W","label":"Range nameplate (W)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"dryer_W","label":"Dryer nameplate (W; 5000 minimum)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"hvac_cooling_W","label":"HVAC cooling (W)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"hvac_heating_W","label":"HVAC heating (W)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: per NEC 2023 §220.12 (general lighting 3 VA/ft^2), §220.42 (dwelling demand 3000 / 35% / 25% schedule), §220.82 (optional method). AHJ governs final service sizing. Free at nfpa.org/freeaccess."},
  "sewage-force-main-velocity": {"inputs":[{"key":"gpm","label":"Pump flow (gpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"id_in","label":"Force-main inside diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Sewage force-main velocity V = 0.4085 Q / d^2 (ft/s, gpm, in), with the ~2 ft/s minimum scour velocity to keep solids suspended (Ten States Standards). A design aid; the state design criteria and the pump curve govern."},
  "shackle-eyebolt-wll": {"inputs":[{"key":"leg_load_lb","label":"Leg load (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"rated_wll_lb","label":"Catalog WLL of the hardware (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"angle_deg","label":"Angle of pull off axis (deg)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"hardware","label":"Hardware","kind":"select","options":[{"value":"shackle","label":"Shackle (side load)"},{"value":"shoulder_eyebolt","label":"Shoulder eye bolt (angular pull)"}],"default":"shackle","attrs":null}],"citation":"Citation: ASME B30.26 (Rigging Hardware) and ASME B18.15 / manufacturer eye-bolt data by name; the angular derate curves ship as editable approximations. Estimate - the rating plate governs."},
  "shielding-gas-runtime": {"inputs":[{"key":"flow_cfh","label":"Gas flow (cfh)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"arc_on_min","label":"Arc-on time (min)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"cylinder_ft3","label":"Usable gas per cylinder (ft3)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"251"}},{"key":"gas_cost","label":"Cost per cylinder (optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: torch / regulator maker's flow charts and the AWS welding cost / consumable references, by name. Gas used = flow x arc-on / 60; runtime per cylinder = cylinder volume / flow. Compressed-gas and hot-work hazards govern; follow the equipment maker's instructions and your site's hot-work permit."},
  "shock-approach-boundary": {"inputs":[{"key":"nominal_v_ac","label":"Nominal voltage (phase-to-phase, AC)","kind":"select","options":[{"value":"<50 V","label":"<50 V"},{"value":"50-150 V","label":"50-150 V"},{"value":"151-750 V","label":"151-750 V (e.g. 480 V)"},{"value":"751-15,000 V","label":"751 V - 15 kV"}],"default":"151-750 V","attrs":null}],"citation":"Citation: NFPA 70E-2024 Table 130.4 (AC shock approach boundaries) - limited approach (movable vs fixed) and restricted approach by nominal voltage. Shock boundaries only; the arc-flash boundary is separate. The employer's electrical safety program and 70E govern. Free at nfpa.org/freeaccess."},
  "shower-compartment-check": {"inputs":[{"key":"width_in","label":"Finished interior width (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"depth_in","label":"Finished interior depth (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"base_min_area_sqin","label":"Base minimum area (sq in; IPC 900)","kind":"number","options":null,"default":900,"attrs":{"step":"any","min":"0"}},{"key":"base_min_dim_in","label":"Base minimum least dimension (in; IPC 30)","kind":"number","options":null,"default":30,"attrs":{"step":"any","min":"0"}},{"key":"exception_min_area_sqin","label":"Exception minimum area (sq in; IPC 1300)","kind":"number","options":null,"default":1300,"attrs":{"step":"any","min":"0"}},{"key":"exception_min_dim_in","label":"Exception minimum least dimension (in; IPC 25)","kind":"number","options":null,"default":25,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: IPC 417.4 - shower compartments not less than 900 sq in in interior cross-sectional area and not less than 30 in in least dimension, measured from the finished interior dimension at a height equal to the top of the threshold and at a point tangent to its centerline, exclusive of fixture valves, showerheads, soap dishes, and safety grab bars or rails, and continued to a height not less than 70 in above the shower drain outlet; with the exception permitting a least dimension of not less than 25 in where the compartment has not less than 1,300 sq in of cross-sectional area. Both conditions of a path must be met - area alone never settles it. Rectangular compartments only; a neo-angle or irregular stall needs the disc drawn on the plan. The door and its swing, the receptor and drain, waterproofing, the 70 in height, and accessible (ANSI A117.1 / ADA) stalls are not checked. All thresholds are editable inputs because local amendments exist. A screen, not a code-official determination; the adopted code and the AHJ govern."},
  "shr": {"inputs":[{"key":"sensible_btu_hr","label":"Sensible cooling load (BTU/hr)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"total_btu_hr","label":"Total cooling load (BTU/hr)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Sensible heat ratio = sensible cooling load / total cooling load."},
  "shrink-fit": {"inputs":[{"key":"nominal_dia_in","label":"Nominal fit diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"interference_in","label":"Diametral interference (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"clearance_in","label":"Assembly clearance (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.002"}},{"key":"alpha_per_f","label":"CTE (per degF)","kind":"number","options":null,"default":0.0000065,"attrs":{"step":"any","min":"0","value":"0.0000065"}},{"key":"ambient_f","label":"Ambient temperature (degF)","kind":"number","options":null,"default":70,"attrs":{"step":"any","value":"70"}}],"citation":"Citation: first-principles thermal-expansion relation delta_dia = alpha x dia x delta_T, with steel alpha about 6.5e-6 per degF, by name. The published alloy coefficient and a separate interference-pressure (Lame) check govern; this tile sizes only the assembly temperature."},
  "silt-fence-drainage": {"inputs":[{"key":"tributary_area_ac","label":"Drainage area behind the fence (acres)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"fence_length_ft","label":"Silt fence length provided (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"slope_length_ft","label":"Slope length behind the fence (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"max_slope_length_ft","label":"AHJ maximum slope length (ft)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}}],"citation":"Citation: silt-fence drainage-area guideline by name. required length = tributary acres x 400 (a quarter acre of drainage per 100 ft of fence); the AHJ-entered maximum slope length governs the spacing. Sheet flow only."},
  "sine-bar": {"inputs":[{"key":"solve_for","label":"Solve for","kind":"select","options":[{"value":"angle","label":"Angle from a gauge-block stack"},{"value":"stack","label":"Gauge-block stack for a target angle"}],"default":"angle","attrs":null}],"citation":"Citation: Sine bar angle setup - a bar of length L on a gauge-block stack of height H tilts to angle theta where sin(theta) = H / L, so theta = arcsin(H/L) and H = L x sin(theta) - first-principles trigonometry (the standard sine-bar / sine-plate relation as in Machinery's Handbook, by name). The gauge-block grade and surface-plate flatness govern the achievable accuracy."},
  "sling-d-d-efficiency": {"inputs":[{"key":"rated_wll_lb","label":"Catalog WLL, straight pull (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"bend_dia_in","label":"Bend diameter D (in) - pin / load","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"sling_dia_in","label":"Sling diameter d (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Wire Rope Technical Board Wire Rope Users Manual (D/d bend efficiency) and ASME B30.9 by name. ratio = bend diameter / sling diameter; the curve ships as editable breakpoints. Estimate - inspect every sling."},
  "slope-from-level": {"inputs":[{"key":"value","label":"Value","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"from","label":"From","kind":"select","options":[{"value":"degrees","label":"degrees"},{"value":"percent","label":"percent"},{"value":"in_per_ft","label":"in / ft"}],"default":null,"attrs":null}],"citation":"Citation: Bidirectional between degrees, percent, and inches per foot. Companion to utility 18."},
  "smoke-residue-method": {"inputs":[{"key":"residue_type","label":"Observed smoke residue","kind":"select","options":[{"value":"dry","label":"Dry (fast, hot fire)"},{"value":"wet","label":"Wet (slow, smoldering)"},{"value":"protein","label":"Protein (kitchen)"},{"value":"fueloil","label":"Fuel oil / puffback"},{"value":"synthetic","label":"Synthetic (plastics)"}],"default":"dry","attrs":null}],"citation":"Citation: Smoke residue type to cleaning method mapping (ANSI/IICRC S700), by name. A test-clean of an inconspicuous area GOVERNS the final method; solvent selection and substrate compatibility are the cleaner's call. This screen narrows the method, it is not a procedure."},
  "smooth-bore-diameter-for-flow": {"inputs":[{"key":"target_gpm","label":"Target flow (gpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"250"}},{"key":"nozzle_pressure_psi","label":"Nozzle pressure (psi)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}}],"citation":"Citation: IFSTA Pumping Apparatus Driver/Operator Handbook (by name, not reproduced) - smooth-bore discharge gpm = 29.7 x d^2 x sqrt(NP) solved for the diameter: d = sqrt( gpm / (29.7 x sqrt(NP)) ); reaction 1.57 x d^2 x NP. Standard nozzle pressure 50 psi handline / 80 psi master (editable). Incident command and the pump operator govern."},
  "smooth-bore-flow": {"inputs":[{"key":"bore_in","label":"Tip / bore diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"1.125"}},{"key":"nozzle_pressure_psi","label":"Nozzle pressure (psi)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}}],"citation":"Citation: IFSTA Pumping Apparatus Driver/Operator Handbook (by name, not reproduced) - smooth-bore discharge gpm = 29.7 x d^2 x sqrt(NP) and nozzle reaction 1.57 x d^2 x NP. Standard nozzle pressure 50 psi handline / 80 psi master (editable). Incident command and the pump operator govern."},
  "snow-load": {"inputs":[{"key":"Pg_psf","label":"Ground snow load Pg (psf)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"Ce","label":"Exposure factor Ce","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1.0"}},{"key":"Ct","label":"Thermal factor Ct","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1.0"}},{"key":"Is","label":"Importance factor Is","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1.0"}},{"key":"Cs","label":"Sloped-roof factor Cs","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1.0"}},{"key":"drift_upwind_length_ft","label":"Drift upwind fetch (ft, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Pf = 0.7 * Ce * Ct * Is * Pg per public ASCE 7 formula."},
  "softener-sizing": {"inputs":[{"key":"people","label":"Occupants","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"use_per_cap","label":"Water use per person (gal/day)","kind":"number","options":null,"default":75,"attrs":{"step":"any","min":"0","value":"75"}},{"key":"hardness_gpg","label":"Total hardness (grains/gal)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"iron_ppm","label":"Dissolved iron (ppm, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"capacity","label":"Usable resin capacity (grains)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"salt_per_regen","label":"Salt per regeneration (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: NSF/ANSI 44 and the Water Quality Association (WQA) hardness/iron-compensation practice by name. comp_hardness = hardness + iron x 4 gpg/ppm; grain_load = people x use x comp_hardness; 1 gpg = 17.1 ppm."},
  "soil-activity": {"inputs":[{"key":"ll","label":"Liquid limit LL (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"pl","label":"Plastic limit PL (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"clay_fraction_pct","label":"Clay fraction (% finer than 2 microns)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"100"}}],"citation":"Citation: Skempton (1953) soil activity A = PI / (percent clay finer than 2 microns), by name; classification A < 0.75 inactive, 0.75-1.25 normal, A > 1.25 active. PI = LL - PL (ASTM D4318); clay fraction from the hydrometer (ASTM D7928 / D422). A mineralogy / swell screen, not a heave calculation; the soil test data and the geotechnical engineer govern."},
  "soil-gradation-coefficients": {"inputs":[{"key":"d10_mm","label":"D10, effective size (mm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"d30_mm","label":"D30 (mm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"d60_mm","label":"D60 (mm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"pct_coarse_passing_no4","label":"Coarse fraction passing the #4 sieve (%, <= 50 = gravel)","kind":"number","options":null,"default":60,"attrs":{"step":"any","min":"0","max":"100","value":"60"}},{"key":"pct_fines","label":"Fines passing the #200 sieve (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"100","value":"0"}}],"citation":"Citation: ASTM D2487 (Unified Soil Classification System) gradation criteria and ASTM D6913 sieve analysis, by name: Cu = D60/D10, Cc = D30^2/(D10 x D60); well graded requires Cu >= 4 (gravel) or >= 6 (sand) AND 1 <= Cc <= 3. Fines under 5% let the gradation symbol govern, 5-12% takes a dual symbol, over 12% the fines govern (see atterberg-indices). The Hazen (1892) k = D10^2 cm/s estimate is shown with its validity range (Cu < 5, D10 0.1-3 mm, clean). Three curve points, not the full sieve analysis; the laboratory gradation report and the geotechnical engineer govern."},
  "soil-phase-relations": {"inputs":[{"key":"gamma_pcf","label":"Total (moist) unit weight (pcf)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"w_pct","label":"Water content (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"gs","label":"Specific gravity of solids Gs","kind":"number","options":null,"default":2.7,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: soil phase relations gamma_d = gamma/(1 + w), e = Gs gamma_w/gamma_d - 1, n = e/(1 + e), S = w Gs/e, with gamma_w = 62.4 pcf and Gs ~ 2.65-2.72, per Das / NAVFAC, by name. Enter Gs; fresh water. An engineering aid; the soil test data govern."},
  "soil-relative-density": {"inputs":[{"key":"field_wet_pcf","label":"Field density (pcf)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"w_pct","label":"Moisture content w (%, 0 = already dry)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"gamma_dmin_pcf","label":"Minimum index dry density, loosest (pcf)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"gamma_dmax_pcf","label":"Maximum index dry density, densest (pcf)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: relative density (density index) Dr = (e_max - e)/(e_max - e_min), reduced to its dry-density form Dr = gamma_d,max (gamma_d - gamma_d,min)/(gamma_d (gamma_d,max - gamma_d,min)) by substituting e = Gs gamma_w/gamma_d - 1, which cancels the specific gravity and the unit weight of water; the field dry density from gamma_d = gamma_wet/(1 + w). The minimum and maximum index dry densities come from the laboratory index-density tests for that soil and are entered, not bundled. The descriptive bands are terms in common use, not a code requirement. A QC aid; the project geotechnical specification and the testing agency govern."},
  "soil-resistivity-wenner": {"inputs":[{"key":"probe_spacing_ft","label":"Probe spacing a (ft)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"meter_resistance_ohm","label":"Earth-tester reading R (ohms)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}}],"citation":"Citation: Wenner 4-pin (four-electrode, equal-spacing) soil resistivity test, by name (IEEE 81 / ASTM G57). rho = 2 x pi x a x R with a the equal probe spacing (converted to meters) and R the earth-tester reading; result in ohm-m and ohm-cm. Assumes electrode depth small vs spacing. Resistivity varies with moisture/temperature/season; the IEEE 81 method and the engineer govern."},
  "soil-stabilization-quantity": {"inputs":[{"key":"application_pct","label":"Stabilizer content by dry soil weight (%)","kind":"number","options":null,"default":6,"attrs":{"step":"any","min":"0","value":"6"}},{"key":"soil_density_pcf","label":"Soil dry density (pcf)","kind":"number","options":null,"default":110,"attrs":{"step":"any","min":"0","value":"110"}},{"key":"depth_in","label":"Treatment depth (in)","kind":"number","options":null,"default":8,"attrs":{"step":"any","min":"0","value":"8"}},{"key":"area_sy","label":"Treated area (sy)","kind":"number","options":null,"default":10000,"attrs":{"step":"any","min":"0","value":"10000"}}],"citation":"Citation: stabilizer-quantity identity by name. spread (lb/sy) = percent/100 x density x depth/12 x 9; tons = spread x area / 2000. The application percent is by dry soil weight from the geotech's mix design."},
  "soil-swell-shrink": {"inputs":[{"key":"bank_cy","label":"Bank (in-place) volume (cy)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"swell_pct","label":"Swell when excavated (%)","kind":"number","options":null,"default":25,"attrs":{"step":"any","min":"0","value":"25"}},{"key":"shrink_pct","label":"Shrinkage when compacted (%)","kind":"number","options":null,"default":15,"attrs":{"step":"any","min":"0","value":"15"}}],"citation":"Citation: Caterpillar Performance Handbook soil-conversion method (swell / shrinkage / load factor) by name. loose = bank x (1 + swell/100); compacted = bank x (1 - shrink/100). The geotech report governs the percentages."},
  "solar-egc-690-45": {"inputs":[{"key":"ocpd_rating_a","label":"OCPD rating (A, 0 = no OCPD)","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0","value":"20"}},{"key":"pv_isc_a","label":"PV short-circuit current (A, used if no OCPD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"vd_upsized","label":"Conductors upsized for voltage drop?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":"no","attrs":null}],"citation":"Citation: NEC 2023 690.45 equipment grounding conductors for PV systems with Table 250.122: the EGC is sized from the governing overcurrent rating (or, where there is no OCPD, from the PV short-circuit current), never smaller than 14 AWG, and 690.45 waives the 250.122(B) proportional upsize so enlarging the circuit conductors for voltage drop does not enlarge the EGC. The NEC and the AHJ govern."},
  "solar-thermal-collector": {"inputs":[{"key":"optical_efficiency","label":"Optical efficiency (y-intercept, ~0.70)","kind":"number","options":null,"default":0.7,"attrs":{"step":"any","min":"0","max":"1","value":"0.70"}},{"key":"loss_coeff","label":"Loss coefficient (Btu/hr-ft^2-F, slope)","kind":"number","options":null,"default":0.85,"attrs":{"step":"any","min":"0","value":"0.85"}},{"key":"inlet_temp_f","label":"Fluid inlet temp (F)","kind":"number","options":null,"default":120,"attrs":{"step":"any","value":"120"}},{"key":"ambient_temp_f","label":"Ambient air temp (F)","kind":"number","options":null,"default":70,"attrs":{"step":"any","value":"70"}},{"key":"irradiance_btu","label":"Solar irradiance (Btu/hr-ft^2)","kind":"number","options":null,"default":300,"attrs":{"step":"any","min":"0","value":"300"}},{"key":"area_sqft","label":"Collector area (sq ft)","kind":"number","options":null,"default":40,"attrs":{"step":"any","min":"0","value":"40"}}],"citation":"Citation: solar thermal flat-plate collector output (ASHRAE 93 / Hottel-Whillier-Bliss efficiency line), by name. eta = optical efficiency - loss coeff x (inlet - ambient)/irradiance; useful heat = irradiance x eta x area. The SRCC-rated intercept and slope, the incidence angle, flow rate, and glazing govern."},
  "solder-joint-quantity": {"inputs":[{"key":"joints","label":"Joints to sweat","kind":"number","options":null,"default":200,"attrs":{"step":"any","min":"0","value":"200"}},{"key":"wire_in_per_joint","label":"Solder wire per joint (in)","kind":"number","options":null,"default":0.75,"attrs":{"step":"any","min":"0","value":"0.75"}},{"key":"wire_dia_in","label":"Solder wire diameter (in)","kind":"number","options":null,"default":0.125,"attrs":{"step":"any","min":"0","value":"0.125"}},{"key":"solder_density_lb_in3","label":"Solder density (lb/in^3)","kind":"number","options":null,"default":0.3,"attrs":{"step":"any","min":"0","value":"0.30"}},{"key":"spool_lb","label":"Spool weight (lb)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1"}}],"citation":"Citation: solder-weight identity by name. weight per inch = pi/4 x diameter^2 x density; solder = joints x wire per joint x weight per inch. The wire per joint is a field rule (~the pipe diameter in inches of 1/8 in wire); lead-free solder is ~0.30 lb/in^3."},
  "spanline-sag-for-tension": {"inputs":[{"key":"span_ft","label":"Horizontal span (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"load_lb_per_ft","label":"Uniform load along span (lb/ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"allowable_tension_lb","label":"Allowable tension (lb, WLL or anchor)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: shallow-cable parabola solved for the sag at a tension limit: d_min = w L^2 / (8 sqrt(T_allow^2 - (w L / 2)^2)), the inverse of T = w L^2 / (8 d) sqrt(1 + (4 d / L)^2). The allowable limits the SUPPORT (anchor) tension and must exceed the w L / 2 vertical reaction. Uniform load, level supports, sag under ~1/10 of the span. A planning screen; the WLL chart and the head rigger govern."},
  "spanline-sag-tension": {"inputs":[{"key":"span_ft","label":"Horizontal span (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"load_lb_per_ft","label":"Uniform load along span (lb/ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"sag_ft","label":"Sag at midspan (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: shallow-cable parabola H = w L^2 / (8 d), support tension T = H sqrt(1 + (4 d / L)^2), developed length L + 8 d^2 / (3 L), by name. Tension is inverse to the sag - a tight span multiplies the load. Uniform load, level supports, sag under ~1/10 of the span. A planning screen; the WLL chart and the head rigger govern."},
  "speaker-impedance": {"inputs":[{"key":"topology","label":"Wiring topology","kind":"select","options":[{"value":"parallel","label":"Parallel"},{"value":"series","label":"Series"},{"value":"series-parallel","label":"Series-parallel"}],"default":null,"attrs":null}],"citation":"Citation: Ohm's-law series/parallel impedance combination (public); the amplifier-minimum-load check follows the manufacturer's rated minimum (user-supplied). A nominal-impedance estimate, real loudspeaker impedance is frequency-dependent, the amp spec governs."},
  "specific-energy": {"inputs":[{"key":"b_ft","label":"Channel width b (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"q_cfs","label":"Discharge Q (cfs)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"y_ft","label":"Flow depth y (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: specific energy E = y + q^2/(2 g y^2), the rectangular critical depth yc = (q^2/g)^(1/3) with minimum specific energy Ec = 1.5 yc, and the alternate depth sharing the same E, as compiled in Chow, by name. Rectangular section; the alternate depth is the energy conjugate, not the momentum sequent depth of a jump. A design aid; the engineer of record governs."},
  "spindle-max-mrr": {"inputs":[{"key":"available_motor_hp","label":"Available motor horsepower (hp)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"unit_power_hp","label":"Unit power (hp per in3/min)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1.0"}},{"key":"efficiency_pct","label":"Spindle drive efficiency (%)","kind":"number","options":null,"default":80,"attrs":{"step":"any","min":"0","value":"80"}}],"citation":"Citation: first-principles specific-cutting-energy relation solved for the removal rate, max MRR = motor hp x efficiency / unit power, with Machinery's Handbook unit-power values (tabular reference), by name. The power (stall) limit only; depth/feed, tool strength, and rigidity are separate limits. The tool and machine govern the real cut."},
  "spindle-power-torque": {"inputs":[{"key":"mrr_in3_min","label":"Material removal rate (in3/min)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"unit_power_hp","label":"Unit power (hp per in3/min)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1.0"}},{"key":"efficiency_pct","label":"Spindle drive efficiency (%)","kind":"number","options":null,"default":80,"attrs":{"step":"any","min":"0","value":"80"}},{"key":"rpm","label":"Spindle speed (rpm)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: first-principles specific-cutting-energy relation with Machinery's Handbook unit-power values (tabular reference), by name. Cutting hp = MRR x unit power; motor hp = cutting hp / efficiency; torque = 5252 x cutting hp / rpm. The tool, sharpness, and machine govern the real cut."},
  "spoil-setback": {"inputs":[{"key":"trench_depth_ft","label":"Trench depth (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"spoil_height_ft","label":"Spoil pile height (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"repose_deg","label":"Angle of repose (deg)","kind":"number","options":null,"default":34,"attrs":{"step":"any","min":"0","value":"34"}},{"key":"min_setback_ft","label":"Code minimum setback (ft)","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"0","value":"2"}}],"citation":"Citation: OSHA 29 CFR 1926.651(j) (2 ft spoil setback) and Subpart P (protective systems) by name. base half-width = spoil height / tan(repose); setback = max(2 ft, trench depth). The competent person governs."},
  "spray-drift-buffer": {"inputs":[{"key":"base_buffer_ft","label":"Base buffer override (ft, 0 = use class)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"droplet_class","label":"Droplet class","kind":"select","options":[{"value":"very_coarse","label":"Very Coarse (base 5 ft)"},{"value":"coarse","label":"Coarse (base 10 ft)"},{"value":"medium","label":"Medium (base 20 ft)"},{"value":"fine","label":"Fine (base 40 ft)"}],"default":"medium","attrs":null},{"key":"wind_mph","label":"Wind speed (mph)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"boom_height_in","label":"Release height (in)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"ref_height_in","label":"Reference height (in)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0","value":"20"}}],"citation":"Citation: USDA / land-grant extension drift-management guidance and the EPA pesticide label / Worker Protection Standard (40 CFR 170), by name. The product label is the law (FIFRA); the label's mandatory buffer and wind limits govern. This is a relative planning aid, not the required buffer."},
  "sprayer-field-capacity": {"inputs":[{"key":"boom_width_ft","label":"Boom / swath width (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"speed_mph","label":"Ground speed (mph)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"field_efficiency_pct","label":"Field efficiency (%)","kind":"number","options":null,"default":70,"attrs":{"step":"any","min":"0","value":"70"}},{"key":"field_acres","label":"Field size (acres)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"tank_gal","label":"Tank capacity (gal)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"gpa","label":"Spray volume (GPA)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: USDA / land-grant extension sprayer field-efficiency guidance, by name. Theoretical acres/hr = boom width x speed / 8.25; effective applies the field efficiency. The product label is the law (FIFRA); your state lead agency governs."},
  "spreader-beam": {"inputs":[{"key":"load_lb","label":"Total load (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"bar_length_ft","label":"Bar length, pick to pick (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"top_height_ft","label":"Top point height above bar (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: ASME BTH-1 (Design of Below-the-Hook Lifting Devices) and ASME B30.20 by name. Spreader bar = axial compression, lifting beam = bending moment; top sling tension = (W/2)/sin(angle). Estimate - the rating plate governs."},
  "spreader-beam-min-height": {"inputs":[{"key":"load_lb","label":"Total load (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"bar_length_ft","label":"Bar length, pick to pick (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"sling_wll_lb","label":"Top sling WLL, each (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: ASME BTH-1 (Design of Below-the-Hook Lifting Devices) and ASME B30.20 by name; top sling tension = (W/2)/sin(angle) solved for the height: angle = asin( W / (2 x WLL) ), top = (bar/2) x tan(angle). Estimate - the rating plate governs."},
  "spur-gear-geometry": {"inputs":[{"key":"diametral_pitch","label":"Diametral pitch Pd (teeth/in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"teeth","label":"Number of teeth N","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"mating_teeth","label":"Mating gear teeth (optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Spur gear tooth proportions (diametral-pitch system, 20-degree full-depth involute; AGMA / Machinery's Handbook): pitch dia = N/Pd, OD = (N+2)/Pd, addendum = 1/Pd, dedendum = 1.25/Pd, whole depth = 2.25/Pd, root = (N-2.5)/Pd, center distance = (N1+N2)/(2 Pd). A shop aid; the gear drawing and AGMA standard govern."},
  "square-footage": {"inputs":[{"key":"shape","label":"Shape","kind":"select","options":[{"value":"rectangle","label":"Rectangle"},{"value":"triangle","label":"Triangle"},{"value":"trapezoid","label":"Trapezoid"},{"value":"circle","label":"Circle"}],"default":null,"attrs":null}],"citation":"Citation: Geometric area formulas for rectangle, triangle, trapezoid, and circle."},
  "stadia-distance": {"inputs":[{"key":"s_ft","label":"Stadia interval (upper - lower, ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"theta_deg","label":"Vertical angle from horizontal (deg, + up)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"k_f","label":"Stadia interval factor K","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0"}},{"key":"hi_ft","label":"Height of instrument (ft, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"rod_ft","label":"Rod center reading (ft, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"sta_elev","label":"Station elevation (ft, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}}],"citation":"Citation: stadia horizontal distance H = K s cos^2(theta), vertical V = (K s/2) sin(2 theta), elevation = HI + V - rod, K = 100, per the standard surveying references, by name. Internal-focusing instrument, no curvature/refraction. A computational aid; the instrument constants govern."},
  "stairs": {"inputs":[{"key":"total_rise_in","label":"Total rise (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"preferred_riser_height_in","label":"Preferred riser height (in)","kind":"number","options":null,"default":7.5,"attrs":{"step":"any","min":"4","max":"9","value":"7.5"}}],"citation":"Citation: per IRC 2021 §R311.7 (stair dimensions). Riser height = total rise / risers; default tread depth 10 in. AHJ governs final inspection. Free at codes.iccsafe.org."},
  "standby-battery-runtime": {"inputs":[{"key":"battery_ah","label":"Installed battery capacity (Ah)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"standby_current_a","label":"Standby (supervisory) current (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"alarm_current_a","label":"Alarm current (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"alarm_minutes","label":"Alarm period (min)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"derate","label":"Derate / aging factor","kind":"number","options":null,"default":1.2,"attrs":{"step":"any","min":"0","value":"1.2"}}],"citation":"Citation: secondary (standby) battery runtime for a fire-alarm or security control unit, the inverse of the sizing worksheet: Hs = (battery_Ah/derate - alarm_Ah) / standby_current, per NFPA 72 §10.6 (secondary power supply), by name. The AHJ-adopted NFPA 72 edition, the listed panel, and the battery manufacturer's derating govern."},
  "standby-battery-sizing": {"inputs":[{"key":"standby_current_a","label":"Standby (supervisory) current (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"standby_hours","label":"Standby period (h)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"24"}},{"key":"alarm_current_a","label":"Alarm current (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"alarm_minutes","label":"Alarm period (min)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"derate","label":"Derate / aging factor","kind":"number","options":null,"default":1.2,"attrs":{"step":"any","min":"0","value":"1.2"}}],"citation":"Citation: Secondary (standby) battery sizing for a fire-alarm or security control unit - standby amp-hours plus alarm amp-hours times the aging/derate factor - per NFPA 72 National Fire Alarm and Signaling Code §10.6 (secondary power supply) and the panel manufacturer's battery-calculation worksheet, by name. The AHJ-adopted NFPA 72 edition, the listed panel, and the battery manufacturer's derating govern."},
  "standing-water": {"inputs":[{"key":"area_ft2","label":"Affected area (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"depth_in","label":"Standing depth (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: 1 ft^3 = 7.48052 gal. gallons = area_ft^2 * depth_in / 12 * 7.48052. Water at 60 F ~ 62.4 lb/ft^3."},
  "steam-boiler-blowdown": {"inputs":[{"key":"steam_rate_lb_hr","label":"Steam rate (lb/hr)","kind":"number","options":null,"default":10000,"attrs":{"step":"any","min":"0","value":"10000"}},{"key":"feedwater_tds_ppm","label":"Feedwater TDS (ppm)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"max_boiler_tds_ppm","label":"Max boiler-water TDS (ppm)","kind":"number","options":null,"default":3500,"attrs":{"step":"any","min":"0","value":"3500"}}],"citation":"Citation: steam boiler surface blowdown by TDS mass balance (cycles of concentration), by name. CoC = boiler-water TDS limit / feedwater TDS; blowdown rate = steam rate x FW_TDS / (BW_limit - FW_TDS); blowdown % of feedwater = 1/CoC. Steam assumed TDS-free. The ASME / manufacturer TDS limits and the water-treatment program and a licensed operator govern."},
  "steam-pipe-velocity": {"inputs":[{"key":"steam_flow_lbhr","label":"Steam mass flow (lb/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"spec_vol_ft3lb","label":"Steam specific volume at pressure (ft3/lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"vel_ceiling_fpm","label":"Allowable velocity (ft/min)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"6000"}}],"citation":"Citation: Steam main sizing by continuity - req_area = (flow x specific_volume) / (velocity x 60), then the smallest Sch 40 nominal whose ID clears the required diameter - first-principles, with the recommended velocity band (supply mains ~6,000 to 12,000 ft/min) per ASHRAE Fundamentals / Systems, by name. The specific volume is read from the saturated-steam table at the line pressure. The velocity band is a recommendation, not a code limit; noise, erosion, and condensate reverse-flow bear on the choice, which the engineer of record governs."},
  "steam-trap-sizing": {"inputs":[{"key":"heat_duty_btuhr","label":"Heat duty served (Btu/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"hfg_btulb","label":"Latent heat hfg at pressure (Btu/lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"safety_factor","label":"Safety factor (2 typical, 3 warm-up)","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"1","value":"2"}}],"citation":"Citation: Condensate load = heat duty / latent heat; required trap capacity = load x safety factor (2x typical, 3x warm-up / modulating) - first-principles steam thermodynamics and the safety-factor practice, by name. The latent heat is read from the saturated-steam table at the operating pressure. The trap is selected from the manufacturer's capacity chart at the actual differential pressure the installation develops; warm-up, modulating, and stall conditions can demand a larger factor or a different trap type."},
  "stormwater-detention-volume": {"inputs":[{"key":"runoff_c","label":"Developed runoff coefficient C","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"intensity_in_hr","label":"Design rainfall intensity (in/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"area_ac","label":"Drainage area (acres)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"q_allow_cfs","label":"Allowable release (cfs)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"duration_min","label":"Storm duration (min)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Modified Rational detention volume: peak inflow Q_in = C i A (Rational method), storage = (Q_in - Q_allow) x duration x 60. The critical duration is found by searching the IDF curve for the largest volume. A design aid; the routing, the outlet, and the local drainage ordinance govern."},
  "straight-line-depreciation": {"inputs":[{"key":"cost","label":"Asset cost (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"salvage","label":"Salvage value (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"life_years","label":"Useful life (years)","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"1"}},{"key":"year_of_interest","label":"Year of interest","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1"}}],"citation":"Citation: IRS Publication 946 Chapter 1, Straight-Line Method. Cited by name."},
  "structured-cabling-channel": {"inputs":[{"key":"permanent_link_m","label":"Permanent-link length (m)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"cords_m","label":"Total patch + equipment cords (m)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"temp_c","label":"Installed cable temperature (deg C)","kind":"number","options":null,"default":20,"attrs":{"step":"any"}},{"key":"derate_per_c","label":"De-rate per deg C above 20 (0.004 UTP)","kind":"number","options":null,"default":0.004,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Structured cabling channel (TIA-568): 100 m total = 90 m permanent link + up to 10 m cords; above 20 deg C the max permanent link de-rates ~0.4%/deg C (UTP). Passes if the link is within its de-rated max and the channel is within 100 m. A design aid; the cable's published de-rating and the adopted TIA-568 edition govern."},
  "sump-basin-sizing": {"inputs":[{"key":"basin_dia","label":"Basin inside diameter (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"drawdown_in","label":"Drawdown band, pump-off to pump-on (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"inflow_gpm","label":"Design inflow (GPM)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"pump_gpm","label":"Pump discharge at system head (GPM)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"min_run_s","label":"Minimum acceptable run time (s)","kind":"number","options":null,"default":60,"attrs":{"step":"any","min":"0","value":"60"}}],"citation":"Citation: IPC 2021 Section 712 (Sumps and Ejectors) and the Hydraulic Institute pump-cycling guidance by name. drawdown_gal = (PI/4)(dia/12)^2 x (band/12) x 7.48 gal/ft^3; run and fill times are volume over rate."},
  "superelevation": {"inputs":[{"key":"mode","label":"Solve for","kind":"select","options":[{"value":"e","label":"Required superelevation e (from radius)"},{"value":"rmin","label":"Minimum radius R_min (from max bank)"}],"default":null,"attrs":null}],"citation":"Citation: AASHTO point-mass curve model e + f = V^2/(15 R) per A Policy on Geometric Design of Highways and Streets (the Green Book): required superelevation e = V^2/(15 R) - f, minimum radius R_min = V^2/(15(e_max + f)); the side-friction factor f is from the AASHTO design-speed table and decreases with speed. A design aid, not a substitute for a licensed civil engineer's geometric design."},
  "superheat-subcool": {"inputs":[{"key":"system_pressure_psig","label":"System pressure (psig)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"line_temperature_F","label":"Line temperature (F)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"mode","label":"Mode","kind":"select","options":[{"value":"superheat","label":"Superheat"},{"value":"subcool","label":"Subcool"}],"default":null,"attrs":null},{"key":"indoor_wet_bulb_F","label":"Indoor wet-bulb (F, fixed-orifice target)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"outdoor_dry_bulb_F","label":"Outdoor dry-bulb (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"target_subcool_F","label":"Target subcool (F, TXV/EEV)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Superheat = line temperature minus saturated temperature at suction pressure. Subcool = saturated temperature at liquid pressure minus liquid line temperature."},
  "supply-pressure-budget": {"inputs":[{"key":"street_pressure","label":"Street pressure (psi, use the low)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"fixture_height","label":"Critical fixture height above main (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"meter_loss","label":"Meter loss (psi)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"bfp_loss","label":"Backflow / softener / filter loss (psi)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"friction_loss","label":"Developed-length friction loss (psi)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"fixture_min","label":"Required fixture residual (psi)","kind":"number","options":null,"default":8,"attrs":{"step":"any","value":"8"}}],"citation":"Citation: IPC 2021 Section 604 and the ASPE Plumbing Engineering Design Handbook Vol. 2 by name. Elevation loss = 0.433 psi per foot of water column. Use the minimum recorded street pressure."},
  "surface-condensation-risk": {"inputs":[{"key":"air_temp_f","label":"Chamber air temp (degF)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"80"}},{"key":"air_rh_pct","label":"Chamber relative humidity (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"100","value":"50"}},{"key":"surface_temp_f","label":"Coldest surface temp (degF, IR read)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"50"}}],"citation":"Citation: Magnus dew-point relation and the keep-surfaces-above-dew-point rule (ANSI/IICRC S500), by name. The Magnus form is an approximation and the IR-read surface temperature GOVERNS; psychrometric is the chamber reference. A screen."},
  "tagline-force": {"inputs":[{"key":"lateral_force_lb","label":"Lateral force to resist (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"tagline_angle_deg","label":"Tag-line angle above horizontal (deg)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"per_person_lb","label":"Safe pull per handler (lb)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}}],"citation":"Citation: OSHA 1926 Subpart CC and standard rigging practice by name. tag tension = lateral force / cos(angle above horizontal); handlers = ceil(tension / per-person pull). Estimate - the lift director governs."},
  "tandem-lift-share": {"inputs":[{"key":"total_weight_lb","label":"Total load weight (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"span_in","label":"Span between crane picks (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"cg_from_c1_in","label":"Distance from crane 1 to CG (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"derate_pct","label":"Per-crane derate (percent)","kind":"number","options":null,"default":75,"attrs":{"step":"any","min":"0","value":"75"}},{"key":"c1_chart_lb","label":"Crane 1 net capacity (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"c2_chart_lb","label":"Crane 2 net capacity (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: ASME B30.5 and OSHA 1926 Subpart CC by name. Each crane's share is the cg-load-share statics; allowable = net chart x derate. Estimate - a designated lift director and an engineered plan govern."},
  "tank-drain-time": {"inputs":[{"key":"tank_area_ft2","label":"Tank cross-section area (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"d_in","label":"Orifice diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"cd","label":"Discharge coefficient Cd","kind":"number","options":null,"default":0.6,"attrs":{"step":"any","min":"0"}},{"key":"h1_ft","label":"Starting head above orifice (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"h2_ft","label":"Ending head above orifice (ft, 0 = empty)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: falling-head (Torricelli) drain time t = 2 A_t (sqrt(h1) - sqrt(h2)) / (Cd A_o sqrt(2 g)), g = 32.2 ft/s^2, Cd ~ 0.6 sharp-edged, prismatic tank, head above the orifice, by name. Integrates the orifice equation over the falling head; the flow slows as sqrt(h). A design aid; the engineer of record governs."},
  "tank-mix": {"inputs":[{"key":"product_unit","label":"Product unit","kind":"select","options":[{"value":"fl_oz","label":"fluid ounces (liquid)"},{"value":"pt","label":"pints (liquid)"},{"value":"qt","label":"quarts (liquid)"},{"value":"gal","label":"gallons (liquid)"},{"value":"oz","label":"ounces (dry)"},{"value":"lb","label":"pounds (dry)"}],"default":"fl_oz","attrs":null}],"citation":"Citation: The EPA pesticide label is the law (FIFRA); follow its rate, carrier volume, REI, and PPE. Tank-mix math first-principles: acres/tank = tank gal / GPA; product/tank = acres/tank x rate. NRCS Agronomy Technical Note 5 for spray calibration. The separate nozzle-output (GPA) calibration is the Chemical Application Rate (GPA) tile. Free at epa.gov/pesticide-labels."},
  "tank-volume": {"inputs":[{"key":"orientation","label":"Tank orientation","kind":"select","options":[{"value":"horizontal","label":"Horizontal cylinder"},{"value":"vertical","label":"Vertical cylinder"}],"default":"horizontal","attrs":null},{"key":"linear_unit","label":"Dimension unit","kind":"select","options":[{"value":"in","label":"Inches"},{"value":"ft","label":"Feet"}],"default":"in","attrs":null}],"citation":"Citation: First-principles tank gauging. Horizontal cylinder partial volume from the circular-segment area A = R^2*acos((R-h)/R) - (R-h)*sqrt(2Rh-h^2) times length; vertical cylinder V = pi*R^2*depth. Public-domain geometry; flat ends assumed (dished heads need a head-type correction). US gallons = in^3 / 231."},
  "tankless-gpm": {"inputs":[{"key":"kbtu_input","label":"Burner input (kBTU/hr)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"target_outlet_F","label":"Target outlet (F)","kind":"number","options":null,"default":110,"attrs":{"step":"any","min":"0","value":"110"}},{"key":"solve_for","label":"Solve for","kind":"select","options":[{"value":"gpm","label":"GPM from kBTU + dT"},{"value":"kbtu","label":"kBTU from GPM + dT"},{"value":"dt","label":"dT from kBTU + GPM"}],"default":"gpm","attrs":null},{"key":"target_gpm","label":"Target flow (gpm, for inverse)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"inlet_override_F","label":"Inlet override (F, winter worst-case; blank = zone)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: GPM = kBTU * 1000 / (8.33 * 60 * dT). 1 lb water requires 1 BTU per F; 1 gal water = 8.33 lb. Inlet temperatures by climate zone (NOAA design data)."},
  "tap-drill-size": {"inputs":[{"key":"thread_standard","label":"Thread standard","kind":"select","options":[{"value":"inch","label":"Inch (enter TPI; diameter in inches)"},{"value":"metric","label":"Metric (enter pitch in mm; diameter in mm)"}],"default":"inch","attrs":null}],"citation":"Citation: Tap drill for a target percent of full thread - % = 76.98 x (D_major - D_drill) x TPI for 60-degree threads, so D_drill = D_major - % / (76.98 x TPI) - first-principles thread geometry as in Machinery's Handbook (Industrial Press), by name; public domain. The named letter / number drill is a chart lookup; this reports the nearest 1/64 in fraction."},
  "taper-diameter": {"inputs":[{"key":"known_end","label":"Which end is known","kind":"select","options":[{"value":"large","label":"Large end"},{"value":"small","label":"Small end"}],"default":"large","attrs":null}],"citation":"Citation: Taper setup inverse - the missing end diameter = known -/+ (TPF/12) x L, and the compound angle per side = atan(TPF/24) - first-principles trigonometry as in Machinery's Handbook (Industrial Press), by name; public domain."},
  "taylor-tool-life": {"inputs":[{"key":"taylor_c","label":"Taylor C (sfm at 1-min life)","kind":"number","options":null,"default":300,"attrs":{"step":"any","min":"0","value":"300"}},{"key":"taylor_n","label":"Taylor exponent n (~0.125 HSS, ~0.25 carbide)","kind":"number","options":null,"default":0.2,"attrs":{"step":"any","min":"0","value":"0.2"}},{"key":"cutting_speed_sfm","label":"Cutting speed (sfm)","kind":"number","options":null,"default":200,"attrs":{"step":"any","min":"0","value":"200"}},{"key":"target_life_min","label":"Target tool life (min)","kind":"number","options":null,"default":15,"attrs":{"step":"any","min":"0","value":"15"}}],"citation":"Citation: Taylor tool-life equation V x T^n = C (F.W. Taylor), by name. Tool life T = (C/V)^(1/n); speed for a target life V = C / T^n. C = cutting speed (sfm) for 1-minute life, n = tool-material exponent (~0.1-0.15 HSS, 0.2-0.4 carbide). Base form (no feed/depth term); the insert maker's data and the tool/work/coolant combination govern."},
  "thermal-fog-deodorization": {"inputs":[{"key":"structure_volume_ft3","label":"Volume to treat (ft^3 = area x ceiling height)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"8000"}},{"key":"dose_oz_per_1000ft3","label":"Label dose rate (oz per 1,000 ft^3)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"treatments","label":"Fogging passes","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"1","value":"1"}}],"citation":"Citation: Volume-based fogging dosage (ANSI/IICRC S700) and the 128 fl oz/gal constant, by name. The product LABEL rate and dwell govern. A thermal fogger produces a HOT fog - the space is unoccupied and a fire watch applies; ULV is the cold alternative. Sizes quantity only."},
  "thermistor-beta-temp": {"inputs":[{"key":"resistance_ohms","label":"Measured resistance (ohms)","kind":"number","options":null,"default":10000,"attrs":{"step":"any","min":"0","value":"20000"}},{"key":"r0_ohms","label":"R0 at reference temp (ohms, e.g. 10000)","kind":"number","options":null,"default":10000,"attrs":{"step":"any","min":"0","value":"10000"}},{"key":"beta_k","label":"Beta B (K, e.g. 3950)","kind":"number","options":null,"default":3950,"attrs":{"step":"any","min":"0","value":"3950"}},{"key":"ref_temp_c","label":"Reference temp T0 in C (usually 25)","kind":"number","options":null,"default":25,"attrs":{"step":"any","value":"25"}}],"citation":"Citation: NTC thermistor beta (B-parameter) equation, by name. 1/T = 1/T0 + (1/B) ln(R/R0), temperatures in kelvin; R0 and B (e.g. 10 kohm at 25 C, B ~ 3950 K) come from the sensor datasheet. A two-point fit (accurate ~+/-0.2-1 C near T0); a wider span uses Steinhart-Hart. Distinct from a positive-coefficient platinum RTD. The datasheet R-T curve and tolerance govern."},
  "thi-livestock": {"inputs":[{"key":"unit","label":"Unit","kind":"select","options":[{"value":"F","label":"Fahrenheit"},{"value":"C","label":"Celsius"}],"default":"F","attrs":null},{"key":"ventilation","label":"Ventilation","kind":"select","options":[{"value":"closed","label":"Closed / housed"},{"value":"open","label":"Open / pasture"}],"default":"closed","attrs":null}],"citation":"Citation: Per USDA-ARS livestock heat-stress research publications and Kansas State University Cooperative Extension. Public domain. Free at usda.gov and at K-State Research and Extension."},
  "thinning-target-tpa": {"inputs":[{"key":"sdi_max","label":"Species maximum SDI","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"450"}},{"key":"target_pct","label":"Target percent of maximum (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"100","value":"35"}},{"key":"qmd_in","label":"Quadratic mean diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"current_tpa","label":"Current trees per acre (0 to skip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: Reineke Stand Density Index (Reineke 1933; USDA FS stocking-guide practice), by name. SDI_target = SDI_max x target% / 100; TPA_target = SDI_target / (QMD/10)^1.605; cut = max(0, current - target); BA_target = TPA_target x 0.005454 x QMD^2. The maximum SDI is species-specific; the management band runs ~35% to ~55-60% of it. Thinning from below raises the QMD, so the residual lands conservatively below the target. A management aid; a qualified silvicultural prescription governs."},
  "thread-measure-wire": {"inputs":[{"key":"thread_standard","label":"Thread standard","kind":"select","options":[{"value":"inch","label":"Inch (enter TPI)"},{"value":"metric","label":"Metric (enter pitch in mm)"}],"default":"inch","attrs":null}],"citation":"Citation: The three-wire measurement-over-wires method for 60-degree threads - best wire W = 0.57735 x P, M = E + 3W - 0.86603 x P - first-principles geometry as in Machinery's Handbook (Industrial Press), by name; public domain. The pitch diameter E is user-supplied (no thread-class table lookup)."},
  "thread-pitch": {"inputs":[{"key":"thread_standard","label":"Thread standard","kind":"select","options":[{"value":"inch","label":"Inch (UN/UNC/UNF: enter TPI)"},{"value":"metric","label":"Metric (ISO: enter pitch in mm)"}],"default":"inch","attrs":null}],"citation":"Citation: Thread pitch, lead, and 60-degree form - Unified (UN/UNC/UNF) inch and ISO metric threads share a 60-degree included angle; inch pitch P = 1 / TPI, metric pitch is the millimetre value (TPI = 25.4 / P), lead = pitch x starts, and the sharp-V fundamental height H = P x sqrt(3) / 2 - first-principles geometry as in Machinery's Handbook (Industrial Press), by name. The truncated thread depth and tap-drill size are thread-form- and class-specific and are not computed here."},
  "thread-pitch-dia-from-wires": {"inputs":[{"key":"thread_standard","label":"Thread standard","kind":"select","options":[{"value":"inch","label":"Inch (enter TPI)"},{"value":"metric","label":"Metric (enter pitch in mm)"}],"default":"inch","attrs":null}],"citation":"Citation: The three-wire method for 60-degree threads solved for the pitch diameter - E = M - 3W + 0.86603 x P, best wire W = 0.57735 x P - first-principles geometry as in Machinery's Handbook (Industrial Press), by name; public domain. Compare E to the thread-class limits."},
  "thread-single-depth": {"inputs":[{"key":"tpi","label":"Threads per inch (TPI)","kind":"number","options":null,"default":13,"attrs":{"step":"any","min":"0","value":"13"}}],"citation":"Citation: single-point thread cutting depth (60-degree UN external), by name. pitch = 1/TPI; external thread height = 0.6134 x pitch; compound infeed at 29.5 deg = depth / cos(29.5). Feed over several passes and verify with a gauge or the three-wire method. The thread standard, the tool geometry, and a thread gauge govern the finished part."},
  "three-phase": {"inputs":[{"key":"V_LL","label":"Line-to-line voltage (V)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"I_L","label":"Line current (A)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"pf","label":"Power factor","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","max":"1"}}],"citation":"Citation: Three-phase power equations. P = sqrt(3) * V_LL * I_L * pf; S = sqrt(3) * V_LL * I_L; Q = sqrt(S^2 - P^2)."},
  "three-point-bridle": {"inputs":[{"key":"apex_load_lb","label":"Apex load (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"e1_ft","label":"Leg 1 east offset (ft, - west)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"n1_ft","label":"Leg 1 north offset (ft, - south)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"r1_ft","label":"Leg 1 rise (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"e2_ft","label":"Leg 2 east offset (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"n2_ft","label":"Leg 2 north offset (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"r2_ft","label":"Leg 2 rise (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"e3_ft","label":"Leg 3 east offset (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"n3_ft","label":"Leg 3 north offset (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any"}},{"key":"r3_ft","label":"Leg 3 rise (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Entertainment rigging three-point bridle geometry (static 3-D resolution), by name. Li = sqrt(e^2 + n^2 + rise^2); ui = (e, n, rise)/Li; T1 u1 + T2 u2 + T3 u3 = (0, 0, W) solved by Cramer's rule. Physical only while every tension is positive (a rope can only pull - the apex must hang inside the triangle of its attachment points); an asymmetric hang splits the load far from evenly. The hardware ratings and a qualified rigger govern."},
  "thrust-block-max-pressure": {"inputs":[{"key":"bearing_area_ft2","label":"Bearing-face area (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"od_in","label":"Pipe outside diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"bend_deg","label":"Bend angle (deg)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"soil_bearing_psf","label":"Allowable soil bearing (psf)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: AWWA M41 (Ductile-Iron Pipe and Fittings) thrust-block method -- T = 2 P A sin(theta/2), Ab = T / soil, solved for the pressure: P = Ab x soil / (2 A sin(theta/2)). Compare against the test/surge pressure and a geotechnical soil-bearing value. Checks the bearing face only; the engineer of record governs the block design."},
  "thrust-block-sizing": {"inputs":[{"key":"pressure_psi","label":"Internal pressure (psi, test/surge)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"od_in","label":"Pipe outside diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"bend_deg","label":"Bend angle (deg)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"soil_bearing_psf","label":"Allowable soil bearing (psf)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: AWWA M41 (Ductile-Iron Pipe and Fittings) thrust-block method -- resultant thrust at a bend T = 2 P A sin(theta/2), bearing area Ab = T / (allowable soil bearing). Use the test/surge pressure and a geotechnical soil-bearing value. Sizes the bearing face only; the engineer of record governs the block design."},
  "time-and-materials": {"inputs":[{"key":"hours","label":"Hours","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"labor_rate_per_hour","label":"Labor rate ($/hr)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"material_cost","label":"Material cost ($)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"overhead_percent","label":"Overhead (percent)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"profit_percent","label":"Profit (percent)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: total = (hours * rate + material) * (1 + overhead) * (1 + profit)."},
  "time-of-concentration": {"inputs":[{"key":"l_ft","label":"Flow-path length L (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"s_slope","label":"Average slope S (ft/ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Kirpich (1940) time of concentration tc = 0.0078 L^0.77 S^(-0.385) (tc min, L ft, S ft/ft), as compiled in TR-55 / NRCS, by name. Single-segment estimate for the design storm duration; the paved/overland factor and the TR-55 three-segment sum are separate. A design aid; the engineer of record governs."},
  "tr55-detention-storage": {"inputs":[{"key":"rainfall_type","label":"Rainfall distribution","kind":"select","options":[{"value":"I","label":"Type I"},{"value":"IA","label":"Type IA"},{"value":"II","label":"Type II"},{"value":"III","label":"Type III"}],"default":"II","attrs":null}],"citation":"Citation: NRCS TR-55 Detention Storage sizing (Urban Hydrology for Small Watersheds, Chapter 6 with figure 6-1 and Appendix F Table F-2): Vs/Vr = C0 + C1 r + C2 r^2 + C3 r^3 with r = qo/qi, Vr = 53.33 Q Am (acre-ft), Vs = (Vs/Vr) Vr. A public USDA/NRCS document. An approximate preliminary single-stage size; the final basin comes from a stage-storage routing. The local drainage manual and the engineer of record govern."},
  "tr55-graphical-peak-discharge": {"inputs":[{"key":"rainfall_type","label":"Rainfall distribution","kind":"select","options":[{"value":"I","label":"Type I"},{"value":"IA","label":"Type IA"},{"value":"II","label":"Type II"},{"value":"III","label":"Type III"}],"default":"II","attrs":null}],"citation":"Citation: NRCS TR-55 Graphical Peak Discharge method (Urban Hydrology for Small Watersheds, Chapter 4 with Appendix F Table F-1 and Table 4-2): qp = qu Am Q Fp, with the unit peak discharge log10(qu) = C0 + C1 log10(Tc) + C2 (log10 Tc)^2 by rainfall type and Ia/P. A public USDA/NRCS document; Tc from Chapter 3, Q from the curve number (Chapter 2), Fp from Table 4-2. Valid for Tc 0.1 to 10 hr, Ia/P 0.1 to 0.5, and CN above 40. A design aid; the local drainage manual and the engineer of record govern."},
  "tr55-time-of-concentration": {"inputs":[{"key":"shallow_surface","label":"Shallow concentrated: surface","kind":"select","options":[{"value":"unpaved","label":"Unpaved (V = 16.13 sqrt s)"},{"value":"paved","label":"Paved (V = 20.33 sqrt s)"}],"default":"unpaved","attrs":null}],"citation":"Citation: NRCS TR-55 (Urban Hydrology for Small Watersheds, 1986) Chapter 3 velocity method: sheet-flow Tt = 0.007 (n L)^0.8 / (P2^0.5 s^0.4), shallow-concentrated V = 16.1345 sqrt(s) (unpaved) / 20.3282 sqrt(s) (paved), channel V = (1.49/n) R^(2/3) sqrt(s), Tt = L/(3600 V); Tc = sum. A public USDA/NRCS document. Sheet flow capped at 100 ft. The overland roughness and the 2-year 24-hour rainfall are user-supplied. A design aid; the local drainage manual and the engineer of record govern."},
  "tractor-ballast": {"inputs":[{"key":"power_hp","label":"Engine or PTO power (hp)","kind":"number","options":null,"default":180,"attrs":{"step":"any","min":"0","value":"180"}},{"key":"weight_to_power_ratio","label":"Weight-to-power ratio (lb/hp)","kind":"number","options":null,"default":125,"attrs":{"step":"any","min":"0","value":"125"}},{"key":"current_weight_lb","label":"Current tractor weight (lb)","kind":"number","options":null,"default":18000,"attrs":{"step":"any","min":"0","value":"18000"}}],"citation":"Citation: tractor ballasting rule by name. target weight = weight-to-power ratio x power (hp); ballast change = target - current. ASABE / operator's-manual guidance (~120-145 lb/hp for field draft, ~90-110 for transport; target 8-15% wheel slip). The operator's manual and implement govern."},
  "transformer-sizing": {"inputs":[{"key":"load_kW","label":"Load (kW)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"power_factor","label":"Power factor","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","max":"1","value":"1"}},{"key":"primary_V","label":"Primary voltage (V)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"secondary_V","label":"Secondary voltage (V)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"phase","label":"Phase","kind":"select","options":[{"value":"three","label":"Three"},{"value":"single","label":"Single"}],"default":"three","attrs":null}],"citation":"Citation: Apparent power S = P / pf; three-phase FLA = (S * 1000) / (sqrt(3) * V_LL); single-phase FLA = (S * 1000) / V."},
  "transformer-turns-ratio": {"inputs":[{"key":"primary_voltage_v","label":"Primary voltage Vp (V)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"secondary_voltage_v","label":"Secondary voltage Vs (V)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"secondary_current_a","label":"Secondary current Is (A, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"load_impedance_ohm","label":"Secondary / load impedance (ohm, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: ideal transformer identities a = Np/Ns = Vp/Vs = Is/Ip, impedance ratio Zp/Zs = a^2, by name; the lossless nameplate ratio (winding resistance and leakage reactance are the separate voltage-regulation tile). A design aid; the nameplate governs."},
  "trap-primer": {"inputs":[{"key":"zone","label":"Building zone","kind":"select","options":[{"value":"occupied","label":"Occupied space"},{"value":"mech_room","label":"Mechanical room"},{"value":"parking","label":"Parking structure"}],"default":"occupied","attrs":null},{"key":"prime_method","label":"Prime method","kind":"select","options":[{"value":"electronic","label":"Electronic (up to 4 drains)"},{"value":"pressure_drop","label":"Pressure-drop (up to 4 drains)"},{"value":"pump_discharge","label":"Pump-discharge (up to 4 drains)"},{"value":"manual","label":"Manual (1 drain)"}],"default":"electronic","attrs":null}],"citation":"Citation: primers = ceil(floor drains / drains-per-distribution-unit); annual water = drains x (oz per cycle / 128) x cycles per year. Per IPC 2021 §1002.4 (trap seals) with manufacturer flow rates from published cut sheets (Precision Plumbing Products / Sioux Chief / Mifab). AHJ governs. Free at codes.iccsafe.org."},
  "trap-speed-horsepower": {"inputs":[{"key":"weight_lb","label":"Vehicle weight incl. driver (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"trap_mph","label":"Quarter-mile trap speed (mph)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Hale's quarter-mile HP = weight x (mph/234)^3 and ET = 5.825 x (weight/HP)^(1/3), weight including driver (lb), mph the trap speed, per the drag-racing references, by name. Empirical fit, wheel power, not a dyno. A hobbyist estimate; the dyno governs."},
  "trapezoidal-channel-flow": {"inputs":[{"key":"bottom_width_ft","label":"Bottom width b (ft, 0 = V-ditch)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"side_slope_z","label":"Side slope z (z horizontal : 1 vertical)","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"0"}},{"key":"depth_ft","label":"Flow depth y (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"n","label":"Manning roughness n","kind":"number","options":null,"default":0.03,"attrs":{"step":"any","min":"0"}},{"key":"s_slope","label":"Channel slope S (ft/ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Manning uniform flow in a trapezoidal section - A = (b + z y) y, P = b + 2 y sqrt(1 + z^2), R = A/P, V = (1.486/n) R^(2/3) S^(1/2), Q = A V, with top width T = b + 2 z y, hydraulic depth D = A/T, and Fr = V / sqrt(g D) - as compiled in Chow, by name. Side slope z is horizontal per 1 vertical; a zero bottom width is a V-ditch. Prismatic channel, uniform flow, no freeboard allowance; backwater profiles and the inverse depth-for-a-flow problem are separate. A design aid; the engineer of record and the local drainage manual govern."},
  "tree-appraisal-ctla": {"inputs":[{"key":"dbh_in","label":"Trunk diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"24"}},{"key":"unit_cost_per_sq_in","label":"Unit tree cost ($ per sq in of trunk)","kind":"number","options":null,"default":60,"attrs":{"step":"any","min":"0","value":"60"}},{"key":"species_pct","label":"Species rating (%)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","max":"100","value":"80"}},{"key":"condition_pct","label":"Condition rating (%)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","max":"100","value":"70"}},{"key":"location_pct","label":"Location rating (%)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","max":"100","value":"75"}}],"citation":"Citation: the CTLA (Council of Tree and Landscape Appraisers) trunk formula method, by name: appraised value = unit tree cost x trunk cross-sectional area x species rating x condition rating x location rating. Trunk area is measured at 4.5 ft above grade for trunks over 12 in diameter, and at 1 ft above grade at or below 12 in. The unit cost and all three ratings are regional values from a plant appraisal committee guide and are entered here - no table is shipped, because a national default would be wrong everywhere. Single-stem trunks; multi-stem trees use a different area rule, and cost-of-cure or income approaches may fit better for very large or historic specimens. An estimating aid, not an appraisal - a defensible appraisal is a qualified appraiser's report."},
  "tree-height-clinometer": {"inputs":[{"key":"horizontal_distance_ft","label":"Horizontal distance to trunk (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"top_reading_pct","label":"Top reading (% slope, + above eye)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"58"}},{"key":"base_reading_pct","label":"Base reading (% slope, - below eye)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"-4"}}],"citation":"Citation: clinometer / percent-slope tree height H = D x (top% - base%)/100, both readings signed (+ above eye level, - below), standard USDA Forest Service mensuration / hypsometry, by name. Percent = 100 x tan(angle) for a degree-scale instrument. Assumes the top is above the base and D is the true horizontal distance. A field estimate; lean and a hidden top add error."},
  "tree-open-cavity": {"inputs":[{"key":"diameter_in","label":"Trunk diameter (in, inside bark)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"24"}},{"key":"shell_thick_in","label":"Sound-shell (wall) thickness (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"3"}},{"key":"opening_width_in","label":"Open cavity face width (in, 0 = closed hollow)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"8"}}],"citation":"Citation: Smiley & Fraedrich (1992) open-cavity strength-loss formula, by name. hollow_d = diameter - 2 x shell_thick; R = min(1, opening_width / (pi x diameter)); closed_loss = (hollow_d^3 / diameter^3) x 100 (Wagener closed hollow); open_loss = (hollow_d^3 + R x (diameter^3 - hollow_d^3)) / diameter^3 x 100. An open face makes the ring a broken tube, far weaker than a closed hollow; the formula collapses to Wagener at R = 0. The ISA 33% guide is a concern trigger, not a failure prediction."},
  "tree-rigging-shock": {"inputs":[{"key":"static_weight_lb","label":"Static weight of the piece (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"drop_ft","label":"Free-fall before the line tightens (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"rope_length_ft","label":"Rope in the system (ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"elong_pct","label":"Rope elongation at load (%, dynamic ~5-20)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}}],"citation":"Citation: arborist rigging dynamic-loading research (Detter / Rust / Donzelli) and ANSI Z133-2017 by name. peak = static x (1 + sqrt(1 + 2 x drop / rope stretch)). A floor estimate - a hard catch is worse."},
  "truck-off-tracking": {"inputs":[{"key":"turn_radius_ft","label":"Turn radius R (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"50"}},{"key":"wheelbase1_ft","label":"Tractor / unit wheelbase (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"wheelbase2_ft","label":"Trailer kingpin-to-axle (ft; 0 if single unit)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: AASHTO Green Book low-speed off-tracking OT = R - sqrt(R^2 - sum(L_i^2)), R the turn radius and L_i each unit's wheelbase (tractor wheelbase + trailer kingpin-to-axle for a combination), summed in quadrature. Steady-state low-speed value; high-speed off-tracking and swept-path width are separate. The design vehicle and the agency govern."},
  "truck-swept-path-width": {"inputs":[{"key":"turn_radius_ft","label":"Turn radius R (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"50"}},{"key":"wheelbase1_ft","label":"Tractor / unit wheelbase (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"wheelbase2_ft","label":"Trailer kingpin-to-axle (ft; 0 if single unit)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"40"}},{"key":"vehicle_width_ft","label":"Vehicle width (ft; ~8.5 legal max)","kind":"number","options":null,"default":8.5,"attrs":{"step":"any","min":"0","value":"8.5"}},{"key":"front_swingout_ft","label":"Front swing-out (ft; 0, or from the turning template)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: AASHTO Green Book swept-path width SPW = vehicle width + off-tracking (+ front swing-out), with OT = R - sqrt(R^2 - sum(L_i^2)) the low-speed off-tracking (R the turn radius, L_i each unit's wheelbase in quadrature). The roadway width a turning truck covers; high-speed off-tracking is separate. The design vehicle and the agency govern."},
  "trunk-decay-strength": {"inputs":[{"key":"diameter_in","label":"Trunk diameter outside bark (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"24"}},{"key":"shell_thick_in","label":"Sound-wood shell thickness (in, radial)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"4"}}],"citation":"Citation: hollow-trunk strength-loss screen (Wagener 1963; Smiley & Fraedrich 1992; Mattheck & Breloer t/R; ISA TRAQ), by name. hollow_d = D - 2t; loss% = (hollow_d^3 / D^3) x 100; t/R = t / (D/2), with the Mattheck concern trigger at t/R < 0.30. Strength loss goes as the cube of the hollow ratio (small until the hollow is large); an open cavity is far weaker. A screen, not a load rating; a qualified arborist and a TRAQ assessment govern."},
  "trunk-min-shell-thickness": {"inputs":[{"key":"diameter_in","label":"Trunk diameter outside bark (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"24"}},{"key":"allow_loss_pct","label":"Allowable strength loss (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"29.6"}}],"citation":"Citation: hollow-trunk strength-loss screen (Wagener 1963; Smiley & Fraedrich 1992; Mattheck & Breloer t/R; ISA TRAQ), by name, solved for the shell: t = (D/2) x (1 - (loss/100)^(1/3)), the inverse of loss% = ((D - 2t)/D)^3 x 100, with the Mattheck concern trigger at t/R < 0.30. Strength loss goes as the cube of the hollow ratio; an open cavity is far weaker. A screen, not a load rating; a qualified arborist and a TRAQ assessment govern."},
  "two-sample-t-test": {"inputs":[{"key":"tail","label":"Tail","kind":"select","options":[{"value":"two","label":"Two-sided"},{"value":"one","label":"One-sided"}],"default":"two","attrs":null}],"citation":"Citation: Per OpenIntro Statistics Chapter 7 (inference for numerical data, Welch's t) and the Welch-Satterthwaite df, by name; the t-CDF reuses the bundled special-function helper. Free at openintro.org."},
  "two-source-blend": {"inputs":[{"key":"flow1_gpm","label":"Source 1 flow (gpm)","kind":"number","options":null,"default":500,"attrs":{"step":"any","min":"0","value":"500"}},{"key":"conc1","label":"Source 1 concentration (mg/L)","kind":"number","options":null,"default":4,"attrs":{"step":"any","min":"0","value":"4"}},{"key":"flow2_gpm","label":"Source 2 flow (gpm)","kind":"number","options":null,"default":300,"attrs":{"step":"any","min":"0","value":"300"}},{"key":"conc2","label":"Source 2 concentration (mg/L)","kind":"number","options":null,"default":12,"attrs":{"step":"any","min":"0","value":"12"}},{"key":"target_conc","label":"Target concentration (mg/L)","kind":"number","options":null,"default":8,"attrs":{"step":"any","min":"0","value":"8"}}],"citation":"Citation: flow-weighted two-source water blend, by name. blended = (Q1 C1 + Q2 C2)/(Q1 + Q2); low-source fraction for a target = (Chigh - target)/(Chigh - Clow). A blending mass balance; the source concentrations vary, the SDWA MCL applies, and the state primacy agency and the operator's monitoring govern compliance."},
  "two-stroke-mix": {"inputs":[{"key":"fuel_unit","label":"Fuel unit","kind":"select","options":[{"value":"gallon","label":"US gallons"},{"value":"liter","label":"liters"}],"default":"gallon","attrs":null}],"citation":"Citation: Two-stroke fuel/oil mix - oil volume = fuel volume / ratio (gas:oil by volume); 1 US gallon = 128 fl oz, 1 fl oz = 29.5735 mL - first-principles volume arithmetic, public. Use the oil grade and ratio the equipment maker specifies; the equipment manual governs."},
  "two-stroke-mix-ratio-check": {"inputs":[{"key":"fuel_unit","label":"Fuel unit","kind":"select","options":[{"value":"gallon","label":"US gallons"},{"value":"liter","label":"liters"}],"default":"gallon","attrs":null}],"citation":"Citation: Two-stroke mix ratio check - ratio = fuel volume / oil volume (gas:oil by volume); 1 US gallon = 128 fl oz - first-principles volume arithmetic, the inverse of the two-stroke mix tile, public. Use the oil grade and ratio the equipment maker specifies; the equipment manual governs."},
  "ujoint-operating-angle": {"inputs":[{"key":"input_angle_deg","label":"Input (first) U-joint angle (deg)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}},{"key":"output_angle_deg","label":"Output (second) U-joint angle (deg)","kind":"number","options":null,"default":10,"attrs":{"step":"any","min":"0","value":"10"}}],"citation":"Citation: Cardan (Hooke) U-joint kinematics and the two-joint cancellation rule, by name. A single joint at angle b swings the output speed between cos(b) and 1/cos(b) of input (peak-to-peak = 1/cos(b) - cos(b)) twice per rev; a two-joint shaft cancels it only when both working angles are equal and the yokes are phased. Keep angles small; the manufacturer's rpm-vs-angle chart and the service manual govern."},
  "unit-cost-earthwork": {"inputs":[{"key":"equipment_rate_per_hr","label":"Equipment ownership + operating rate ($/hr)","kind":"number","options":null,"default":150,"attrs":{"step":"any","min":"0","value":"150"}},{"key":"operator_rate_per_hr","label":"Operator wage + burden ($/hr)","kind":"number","options":null,"default":65,"attrs":{"step":"any","min":"0","value":"65"}},{"key":"support_rate_per_hr","label":"Support equipment / labor ($/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"production_cy_per_hr","label":"Production rate (cy/hr)","kind":"number","options":null,"default":656,"attrs":{"step":"any","min":"0","value":"656"}},{"key":"total_cy","label":"Total quantity (cy, 0 = skip)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: unit-cost identity by name. unit cost ($/cy) = (equipment + operator + support hourly rates) / production per hour. The equipment rate is the ownership-plus-operating rate; the production comes from the production tiles."},
  "upgrade-roi": {"inputs":[{"key":"incremental_cost","label":"Incremental cost","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"annual_savings","label":"Annual savings","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"discount_rate_percent","label":"Discount rate (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"4"}},{"key":"years","label":"Years","kind":"number","options":null,"default":10,"attrs":{"step":"1","min":"1","value":"10"}}],"citation":"Citation: simple payback = cost / annual savings; NPV sums discounted savings minus cost."},
  "utm-conversion": {"inputs":[{"key":"direction","label":"Direction","kind":"select","options":[{"value":"latlon_to_utm","label":"Lat/Lon -> UTM"},{"value":"utm_to_latlon","label":"UTM -> Lat/Lon"}],"default":"latlon_to_utm","attrs":null},{"key":"lat_deg","label":"Latitude (deg)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"lon_deg","label":"Longitude (deg)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"zone","label":"UTM zone","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"1","max":"60"}},{"key":"hemisphere","label":"Hemisphere","kind":"select","options":[{"value":"N","label":"N"},{"value":"S","label":"S"}],"default":"N","attrs":null},{"key":"easting","label":"Easting (m)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"northing","label":"Northing (m)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Krueger / USGS public-domain UTM forward and inverse formulas. WGS84 datum."},
  "valve-authority": {"inputs":[{"key":"valve_pressure_drop_psi","label":"Valve pressure drop, fully open (psi)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"controlled_circuit_drop_psi","label":"Coil + variable piping drop (psi)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","value":"3"}}],"citation":"Citation: control valve authority (beta), by name. authority = valve open pressure drop / total drop across the variable branch (valve + coil/variable piping). Target beta >= 0.5 for a near-linear installed characteristic; below 0.25 is poor (resize the valve smaller). Separate from Cv flow sizing (valve-flow-coefficient). The design pressures, valve trim, and engineer/balancer govern."},
  "vav-box-airflow": {"inputs":[{"key":"zone_sensible_btuh","label":"Zone sensible load (Btu/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"12000"}},{"key":"supply_dt_f","label":"Supply-to-room deltaT (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"ventilation_cfm","label":"Ventilation minimum (cfm, ASHRAE 62.1)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"turndown","label":"Turndown fraction (default 0.30)","kind":"number","options":null,"default":0.3,"attrs":{"step":"any","min":"0","max":"1","value":"0.30"}}],"citation":"Citation: VAV box airflow limits: maximum = zone sensible / (1.08 x supply deltaT), minimum = max(ASHRAE 62.1 ventilation minimum, turndown x maximum). The 1.08 is the sensible-heat constant for standard air. A design aid; the box manufacturer's range and the ventilation calculation govern."},
  "vbelt-drive": {"inputs":[{"key":"belt_section","label":"Belt cross-section","kind":"select","options":[{"value":"A","label":"A"},{"value":"B","label":"B"},{"value":"C","label":"C"},{"value":"D","label":"D"},{"value":"3V","label":"3V"},{"value":"5V","label":"5V"},{"value":"8V","label":"8V"}],"default":"B","attrs":null}],"citation":"Citation: ratio = driver_rpm / driven_rpm = D_driven / D_driver; belt length L = 2C + (pi/2)(D1+D2) + (D2-D1)^2/(4C) per ANSI/RMA IP-20 / IP-22. HP-per-belt is a coarse planning default by cross-section; the manufacturer's speed-specific power table (Gates Industrial Drive Design Manual) and service-factor table govern the final selection. Free at gates.com/literature."},
  "vent-terminal-check": {"inputs":[{"key":"height_above_roof_in","label":"Height above the roof (in)","kind":"number","options":null,"default":6,"attrs":{"step":"any","min":"0"}},{"key":"snow_accumulation_in","label":"Anticipated snow accumulation (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"roof_other_use","label":"Roof used for anything but weather protection?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes - 7 ft applies"}],"default":"no","attrs":null},{"key":"design_temp_f","label":"97.5% outdoor design temperature (degF)","kind":"number","options":null,"default":20,"attrs":{"step":"any"}},{"key":"vent_diameter_in","label":"Vent diameter through the roof (in)","kind":"number","options":null,"default":2,"attrs":{"step":"any","min":"0"}},{"key":"increase_inside_envelope_in","label":"Size increase made this far inside the thermal envelope (in; 0 = none)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"horizontal_to_opening_ft","label":"Horizontal distance to the nearest door, openable window, or intake (ft)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0"}},{"key":"height_above_opening_ft","label":"Height above that opening (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: IPC 903.1 - open vent pipes extending through a roof terminated not less than 6 in above the roof or 6 in above the anticipated snow accumulation, whichever is greater, except not less than 7 ft where the roof is used for any purpose other than weather protection. IPC 903.1.1 - where the 97.5-percent value for outdoor design temperature is 0 degF or less, vent extensions through a roof or wall not less than 3 in in diameter, with any increase in the size of the vent made not less than 1 ft inside the thermal envelope of the building. IPC 903.2 - an open vent terminal not located directly beneath any door, openable window, or other air intake of the building or of an adjacent building, and not within 10 ft horizontally of such an opening unless it is 3 ft above it. Anticipated snow accumulation and the design temperature are local figures. Not checked: the vent SIZE from drainage fixture units and developed length, whether a vent is required, the branch below, flashing, wall terminations, or fuel-gas venting. A screen, not a code-official determination; the adopted code and the AHJ govern."},
  "vessel-head-volume": {"inputs":[{"key":"inside_diameter_in","label":"Inside diameter (in)","kind":"number","options":null,"default":48,"attrs":{"step":"any","min":"0","value":"48"}},{"key":"head_type","label":"Head type","kind":"select","options":[{"value":"elliptical","label":"2:1 semi-elliptical"},{"value":"fd","label":"ASME flanged & dished (approx)"},{"value":"hemispherical","label":"Hemispherical"}],"default":"elliptical","attrs":null},{"key":"straight_flange_in","label":"Straight flange (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: dished-head volume geometry by name. 2:1 semi-elliptical head = pi D^3/24; hemispherical = pi D^3/12; ASME flanged-and-dished (torispherical) ~ 0.0847 D^3 (standard crown/knuckle, approximate); straight flange = pi/4 D^2 x length. US gallons = in^3 / 231."},
  "vfd-energy-savings": {"inputs":[{"key":"full_load_kw","label":"Full-load motor input power (kW)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"20"}},{"key":"frac_a","label":"Bin A flow fraction (0-1)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1"}},{"key":"hours_a","label":"Bin A hours/yr","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"2000"}},{"key":"frac_b","label":"Bin B flow fraction (0-1)","kind":"number","options":null,"default":0.75,"attrs":{"step":"any","min":"0","value":"0.8"}},{"key":"hours_b","label":"Bin B hours/yr","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"3000"}},{"key":"frac_c","label":"Bin C flow fraction (0-1)","kind":"number","options":null,"default":0.5,"attrs":{"step":"any","min":"0","value":"0.6"}},{"key":"hours_c","label":"Bin C hours/yr","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"2000"}},{"key":"rate_kwh","label":"Energy rate ($/kWh)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.12"}}],"citation":"Citation: centrifugal affinity cube law P/P_full = (Q/Q_full)^3 and the US DOE motor/pump-system energy method (by name). The cube law holds on a friction-dominated system; the baseline is full-speed operation for the same hours. A screening estimate, not a metered M&V."},
  "voltage-drop-reactance": {"inputs":[{"key":"phase","label":"Phase","kind":"select","options":[{"value":"three","label":"Three-phase"},{"value":"single","label":"Single-phase"}],"default":"three","attrs":null}],"citation":"Citation: Vd = k * I * (R*cos(theta) + X*sin(theta)) * L / 1000, k = 2 single-phase / 1.732 three-phase. R and X per 1000 ft come from NEC 2023 Chapter 9 Table 9, selected by conductor size and conduit material (steel raceway raises X); enter them from your code book. NEC 210.19(A) Note 4 (3% branch) and 215.2(A)(1) Note 2 (5% total) set the advisory band. AHJ governs. Free at nfpa.org/freeaccess for the NEC table of contents."},
  "voltage-imbalance": {"inputs":[{"key":"V_a","label":"Line A voltage (V)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"V_b","label":"Line B voltage (V)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"V_c","label":"Line C voltage (V)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Percent imbalance = max(|V_i - V_avg|) / V_avg * 100 (NEMA MG-1 §14.36). Motor derate factor = 1 - (NEMA HP-derate %)/100 from the MG-1 derating table (~2% derate at 1% imbalance, 25% / do NOT operate at 5%)."},
  "volumetric-efficiency": {"inputs":[{"key":"cycle","label":"Cycle","kind":"select","options":[{"value":"four","label":"4-stroke"},{"value":"two","label":"2-stroke"}],"default":"four","attrs":null}],"citation":"Citation: Classical four-stroke airflow derivation; SAE engine-test conventions, by name. The 3456/1728 constants are pure unit derivations, public (in every engine-builder reference). VE above 100% is legitimate for forced induction."},
  "water-for-compaction": {"inputs":[{"key":"volume_bcy","label":"Lift volume, bank measure (cy)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"dry_density_pcf","label":"Maximum dry density, Proctor (pcf)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"omc_pct","label":"Optimum moisture content (%)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"field_pct","label":"Current field moisture (%)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: gravimetric water-content identity by name. water to add = (optimum - field)/100 x dry soil weight; dry weight = volume x 27 x dry density; gallons = pounds / 8.34 (weight of a gallon of water)."},
  "water-hammer-arrestor": {"inputs":[{"key":"wsfu","label":"Total fixture units (WSFU)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"length_ft","label":"Branch length (ft)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}},{"key":"internal_diameter_in","label":"Pipe internal diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"system_pressure_psi","label":"System pressure (psi, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: PDI WH-201 sizing method (the method, not the published text). Designation by fixture-unit totals."},
  "water-heater-input": {"inputs":[{"key":"heater_type","label":"Heater type","kind":"select","options":[{"value":"gas_atmospheric","label":"Gas, atmospheric (0.80)"},{"value":"gas_condensing","label":"Gas, condensing (0.94)"},{"value":"electric","label":"Electric (0.98)"}],"default":"gas_atmospheric","attrs":null}],"citation":"Citation: input = (recovery_gph x 8.33 x delta-T) / efficiency, from gph = (input BTU/hr x efficiency) / (8.33 x delta-T); electric kW = input / 3412. 8.33 BTU per gallon per degree F is first-principles water properties. Per DOE 10 CFR 430 and AHRI 1300. Free at energy.gov/eere and ahri.org."},
  "water-heater-recovery": {"inputs":[{"key":"heater_type","label":"Heater type","kind":"select","options":[{"value":"gas_atmospheric","label":"Gas, atmospheric (0.80)"},{"value":"gas_condensing","label":"Gas, condensing (0.94)"},{"value":"electric","label":"Electric (0.98)"}],"default":"gas_atmospheric","attrs":null}],"citation":"Citation: gph = (input BTU/hr x efficiency) / (8.33 x delta-T). 8.33 BTU per gallon per degree F is first-principles water properties. Per DOE 10 CFR 430 and AHRI 1300. First-hour rating = recovery + 70% of stored volume (DOE FHR convention). Free at energy.gov/eere and ahri.org."},
  "water-heater-storage-sizing": {"inputs":[{"key":"tank_gal","label":"Tank capacity (gal)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"50"}},{"key":"input_btuh","label":"Input rate (BTU/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"40000"}},{"key":"efficiency_pct","label":"Recovery efficiency (%)","kind":"number","options":null,"default":80,"attrs":{"step":"any","min":"0","value":"80"}},{"key":"rise_F","label":"Temperature rise (F)","kind":"number","options":null,"default":90,"attrs":{"step":"any","min":"0","value":"90"}},{"key":"usable_fraction","label":"Usable-storage fraction","kind":"number","options":null,"default":0.7,"attrs":{"step":"any","min":"0","value":"0.70"}},{"key":"peak_hour_gal","label":"Peak-hour demand (gal)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"80"}}],"citation":"Citation: first-principles recovery Q = 8.33 x gph x delta-T with the DOE/AHRI first-hour-rating definition (usable storage plus one hour of recovery), by name, not reproduced. The 8.33 lb/gal water constant and the default 0.70 usable-storage fraction are editable. The manufacturer's rated FHR on the EnergyGuide label and the AHJ govern."},
  "water-service-pressure-check": {"inputs":[{"key":"static_pressure_psi","label":"Static water pressure at the service (psi)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"min_fixture_pressure_psi","label":"Minimum pressure the fixtures need (psi)","kind":"number","options":null,"default":20,"attrs":{"step":"any","min":"0"}},{"key":"has_check_or_backflow","label":"Check valve or backflow preventer on the service?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":"no","attrs":null},{"key":"has_storage_water_heater","label":"Storage water heater?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":"yes","attrs":null},{"key":"expansion_control_present","label":"Thermal expansion control installed?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":"no","attrs":null},{"key":"prv_setpoint_psi","label":"PRV setpoint if one is fitted (psi; 0 = none)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: IPC 604.8 - static water pressure not greater than 80 psi, with an approved pressure-reducing valve conforming to ASSE 1003 or CSA B356 installed on the domestic water branch main or riser at the connection to the water service pipe where the main pressure exceeds it. IPC 607.3 - where a storage water heater is supplied with cold water that passes through a check valve, pressure-reducing valve, or backflow preventer, a thermal expansion control device connected to the cold water supply downstream of all such devices, and expansion tanks sized per the manufacturer so that system pressure does not exceed what 604.8 requires. Not checked: expansion tank size or precharge, per-fixture flow pressure and flow rate, pipe sizing and the friction, elevation, and meter losses between static and flowing pressure, seasonal pressure variation, PRV maintenance and failure modes, or the water heater's T and P relief and discharge piping. A screen; the adopted code, the device listings, and the AHJ govern."},
  "weir-flow": {"inputs":[{"key":"weir_type","label":"Weir type","kind":"select","options":[{"value":"vnotch90","label":"90-degree V-notch"},{"value":"rect_contracted","label":"Rectangular (contracted)"},{"value":"rect_suppressed","label":"Rectangular (suppressed)"}],"default":"vnotch90","attrs":null}],"citation":"Citation: Per the USBR Water Measurement Manual (public domain) - V-notch and Francis rectangular-weir equations and Kindsvater-Carter / Francis coefficients; the user confirms the calibrated weir coefficient. Requires a sharp-crested, ventilated, free-flow weir. Free at usbr.gov/tsc/techreferences/mands/wmm."},
  "weir-head-from-flow": {"inputs":[{"key":"weir_type","label":"Weir type","kind":"select","options":[{"value":"vnotch90","label":"90-degree V-notch"},{"value":"rect_contracted","label":"Rectangular (contracted)"},{"value":"rect_suppressed","label":"Rectangular (suppressed)"}],"default":"vnotch90","attrs":null}],"citation":"Citation: Per the USBR Water Measurement Manual (public domain) - the V-notch and Francis rectangular-weir equations solved for the head over the crest, the inverse of the weir-flow tile; the contracted weir is solved by fixed-point iteration. Requires a sharp-crested, ventilated, free-flow weir. Free at usbr.gov/tsc/techreferences/mands/wmm."},
  "weld-cost-per-foot": {"inputs":[{"key":"deposit_lb_per_ft","label":"Deposit per foot (lb/ft)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"deposition_eff_pct","label":"Deposition efficiency (%)","kind":"number","options":null,"default":95,"attrs":{"step":"any","min":"0","value":"95"}},{"key":"filler_cost_per_lb","label":"Filler cost ($/lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"deposition_rate_lb_hr","label":"Deposition rate (lb/hr)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"operating_factor_pct","label":"Operating factor (%)","kind":"number","options":null,"default":30,"attrs":{"step":"any","min":"0","value":"30"}},{"key":"labor_rate_per_hr","label":"Labor rate ($/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"gas_cost_per_ft","label":"Shielding-gas cost ($/ft, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0"}}],"citation":"Citation: AWS welding cost and consumable references, by name. Consumable per foot = deposit / efficiency; labor hr per foot = (deposit / deposition rate) / operating factor. Labor and the operating factor usually dominate, not the filler. AHJ and the licensed professional govern any bid."},
  "weld-dilution": {"inputs":[{"key":"A_base","label":"Melted base-metal (penetration) area (in^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"A_filler","label":"Filler (reinforcement) area (in^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: weld dilution = A_base / (A_base + A_filler), the standard welding-metallurgy definition (by name). Sets how far the base metal shifts the deposit chemistry; overlays are kept low-dilution. The WPS and the filler-metal data govern."},
  "weld-group-eccentric": {"inputs":[{"key":"load_lb","label":"In-plane load P (lb)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"ecc_in","label":"Eccentricity from centroid (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"weld_len_in","label":"Length of each vertical weld (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"separation_in","label":"Separation between welds (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"allow_per_16","label":"Allowable per 1/16 in leg (lb/in)","kind":"number","options":null,"default":928,"attrs":{"step":"any","min":"0","value":"928"}}],"citation":"Citation: AISC 360 / Steel Construction Manual Part 8 elastic (vector) method for eccentric weld groups, by name. Resultant = sqrt(f_tx2 + (f_d + f_ty)2); required leg = resultant / allowable. This is the conservative elastic method (not instantaneous-center), a screen; the engineer of record governs."},
  "weld-heat-input": {"inputs":[{"key":"process","label":"Process","kind":"select","options":[{"value":"SMAW","label":"SMAW"},{"value":"GMAW","label":"GMAW"},{"value":"FCAW","label":"FCAW"},{"value":"GTAW","label":"GTAW"},{"value":"SAW","label":"SAW"}],"default":null,"attrs":null},{"key":"wps_min_kj_in","label":"WPS min (kJ/in, optional)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"wps_max_kj_in","label":"WPS max (kJ/in, optional)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Per AWS D1.1 Structural Welding Code and ASME BPVC Section IX, the heat-input definition HI = (60 * V * I) / TS, by name, with an arc-efficiency factor by process. WPS/PQR ranges are user-supplied; the adopted code edition and the qualified WPS govern. Free overviews at aws.org."},
  "weld-metal-volume": {"inputs":[{"key":"joint_type","label":"Joint type","kind":"select","options":[{"value":"fillet","label":"Fillet (by leg)"},{"value":"groove","label":"Groove (by area)"}],"default":"fillet","attrs":null},{"key":"fillet_leg_in","label":"Fillet leg (in, fillet mode)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"groove_area_in2","label":"Weld area (in2, groove mode)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"length_in","label":"Total weld length (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"deposition_eff","label":"Deposition efficiency (0-1)","kind":"number","options":null,"default":0.9,"attrs":{"step":"any","min":"0","value":"0.90"}},{"key":"max_pass_area_in2","label":"Max single-pass area (in2)","kind":"number","options":null,"default":0.05,"attrs":{"step":"any","min":"0","value":"0.05"}}],"citation":"Citation: first-principles joint geometry and steel density (0.2836 lb/in3), by name. Deposit volume = weld area x length; equal-leg fillet area = leg2 / 2; filler purchased = deposit / deposition efficiency. The WPS and the fabricator's measured deposition efficiency govern."},
  "weld-passes-arc-time": {"inputs":[{"key":"A_groove","label":"Groove cross-sectional area (in^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"length_in","label":"Weld length (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"a_pass","label":"Area deposited per pass (in^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"dep_rate","label":"Deposition rate (lb/h)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"density","label":"Weld-metal density (lb/in^3, default 0.283)","kind":"number","options":null,"default":0.283,"attrs":{"step":"any","min":"0"}},{"key":"op_factor","label":"Operator/duty factor (0-1, optional)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"1"}}],"citation":"Citation: passes = ceil(groove area / area per pass); deposited weight = area x length x density (steel ~0.283 lb/in^3); arc time = weight / deposition rate; total = arc / operator factor. Standard welding-cost estimating (by name). The WPS and the shop's measured rates govern."},
  "weld-transverse-shrinkage": {"inputs":[{"key":"weld_area_in2","label":"Weld cross-section (in2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"thickness_in","label":"Plate thickness (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"weld_count","label":"Parallel welds pulling the dimension","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1","value":"1"}}],"citation":"Citation: Blodgett, Design of Welded Structures, transverse-shrinkage relation (shrink = 0.2 x A_w / t), by name. This is a screen; restraint, sequence, and a mock-up govern the actual movement, and longitudinal and angular distortion are out of scope."},
  "weld-travel-speed": {"inputs":[{"key":"V_volts","label":"Arc voltage (V)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"I_amps","label":"Welding current (A)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"eta","label":"Arc efficiency (0.8 GMAW, 0.65 GTAW, 0.9 SAW)","kind":"number","options":null,"default":0.8,"attrs":{"step":"any","min":"0","max":"1"}},{"key":"HI_kjin","label":"Target heat input (kJ/in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: heat input HI = (60 V I eta)/(1000 TS) solved for travel speed, per the AWS/ASME arc heat-input relation with the arc efficiency eta (0.8 GMAW, 0.65 GTAW, 0.9 SAW), by name. Travel at or above the result to stay at or under the target HI. The qualified WPS governs the allowable range."},
  "welder-arc-circuit-conductor": {"inputs":[{"key":"primary_current_a","label":"Nameplate primary current (A)","kind":"number","options":null,"default":40,"attrs":{"step":"any","min":"0","value":"40"}},{"key":"duty_pct","label":"Duty cycle (%)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}}],"citation":"Citation: arc-welder branch-circuit conductor and OCPD by name (NEC 630.11 / 630.12) for a TRANSFORMER or DC-RECTIFIER welder. I_eff = I_primary x sqrt(duty), the transformer/rectifier column of Table 630.11(A); a MOTOR-GENERATOR welder uses a different, higher column not modeled here. Conductor ampacity >= I_eff; OCPD <= 200% of the rated primary. The welder nameplate and the adopted NEC edition govern."},
  "welder-resistance-circuit-conductor": {"inputs":[{"key":"primary_current_a","label":"Nameplate primary current (A)","kind":"number","options":null,"default":100,"attrs":{"step":"any","min":"0","value":"100"}},{"key":"duty_pct","label":"Duty cycle (%)","kind":"number","options":null,"default":50,"attrs":{"step":"any","min":"0","value":"50"}}],"citation":"Citation: resistance-welder branch-circuit conductor and OCPD by name (NEC 630.31 / 630.32). conductor = primary x sqrt(duty) (630.31(A)(2)); OCPD <= 300% of the rated primary (630.32(A)). The welder nameplate and the adopted NEC edition govern."},
  "winch-drum-line-pull": {"inputs":[{"key":"rated_pull_lb","label":"Bare-drum rated pull (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"drum_dia_in","label":"Bare drum diameter (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"rope_dia_in","label":"Wire rope diameter (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"barrel_width_in","label":"Drum barrel width (in)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"target_layer","label":"Target layer (1 = bare)","kind":"number","options":null,"default":1,"attrs":{"step":"1","min":"1","value":"1"}}],"citation":"Citation: Wire-rope drum mechanics / SAE winch rating convention, by name. Dn = drum_dia + (2n - 1) x rope_dia; Pn = rated_pull x drum_dia / Dn; Vn = drum_speed x Dn / drum_dia; wraps_per_layer = floor(barrel_width / rope_dia). The rated pull is a bare-drum first-wrap figure that fades layer by layer (outer layers 30-40% weaker) as line speed rises in proportion. The winch manufacturer's layer ratings govern."},
  "winch-fleet-angle": {"inputs":[{"key":"lateral_offset","label":"Lateral offset (sheave groove to rope landing)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"lead_distance","label":"Lead distance (drum to sheave, same unit)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: winch drum fleet angle (Wire Rope Users Manual; ANSI E1.6 entertainment rigging): fleet_angle = atan(lateral_offset / lead_distance). The lateral offset is the sideways distance from the lead sheave's groove plane to where the rope lands on the drum (largest at the drum ends); the lead distance is the perpendicular distance from drum to sheave; any consistent unit works. Keep at or below 1.5 deg (grooved) / 2 deg (smooth); under ~0.5 deg the rope may pile up. A guideline; the equipment manufacturer governs."},
  "wind-on-load": {"inputs":[{"key":"sail_area_ft2","label":"Projected sail area (ft^2)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"wind_mph","label":"Sustained wind at the load (mph)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"shape_coef","label":"Shape coefficient (flat panel ~1.2-2.0)","kind":"number","options":null,"default":1.6,"attrs":{"step":"any","min":"0","value":"1.6"}},{"key":"load_weight_lb","label":"Load weight (lb)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: ASCE velocity-pressure constant q = 0.00256 V^2 (the same the wind-pressure tile uses) and OSHA 1926 Subpart CC by name. wind force = q x sail area x shape coefficient. Estimate - the in-service wind limit governs."},
  "wind-pressure": {"inputs":[{"key":"V_mph","label":"Basic wind speed (mph)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"exposure","label":"Exposure","kind":"select","options":[{"value":"B","label":"B"},{"value":"C","label":"C"},{"value":"D","label":"D"}],"default":"C","attrs":null},{"key":"Kz","label":"Kz (blank = exposure default)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"Kzt","label":"Kzt (topographic)","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1.0"}},{"key":"Kd","label":"Kd (directionality)","kind":"number","options":null,"default":0.85,"attrs":{"step":"any","min":"0","value":"0.85"}},{"key":"G","label":"G (gust factor)","kind":"number","options":null,"default":0.85,"attrs":{"step":"any","min":"0","value":"0.85"}}],"citation":"Citation: q = 0.00256 * V^2 (V mph) per public ASCE 7 formula. Cp +0.8 windward, -0.5 leeward (typical)."},
  "wind-speed-from-velocity-pressure": {"inputs":[{"key":"velocity_pressure_psf","label":"Velocity pressure q (psf)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"25"}}],"citation":"Citation: ASCE 7 velocity pressure q = 0.00256 V^2 (V mph, q psf) solved for the wind speed, V = sqrt(q / 0.00256). Enter the bare velocity pressure, not a Cp-loaded design surface pressure. A design aid; ASCE 7 and the engineer of record govern."},
  "window-overhang-shade": {"inputs":[{"key":"projection_in","label":"Overhang projection (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"gap_in","label":"Gap, overhang to glass top (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"glass_height_in","label":"Glass height (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"solar_altitude_deg","label":"Solar altitude (deg)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}},{"key":"surface_solar_azimuth_deg","label":"Surface-solar azimuth (deg, 0 = sun straight on)","kind":"number","options":null,"default":0,"attrs":{"step":"any"}}],"citation":"Citation: ASHRAE Handbook-Fundamentals (Fenestration) / ACCA Manual J overhang shading by the profile-angle (shade-line) method: tan(profile angle) = tan(solar altitude) / cos(surface-solar azimuth), shade line = projection x tan(profile angle), by name. The profile-angle geometry is computed from the entered sun position rather than read from a tabulated shade-line-factor chart. Reports the DIRECT-BEAM sunlit fraction; diffuse sky and ground-reflected radiation still reach shaded glass. Overhang assumed wide enough to ignore end effects; no side fins. A design aid, not a Manual J."},
  "window-solar-heat-gain": {"inputs":[{"key":"area_ft2","label":"Glazing area (ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"40"}},{"key":"shgc","label":"SHGC (NFRC label, 0-1)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.30"}},{"key":"psf","label":"Peak solar factor (Btu/h/ft^2)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"200"}},{"key":"u_factor","label":"U-factor (Btu/h/ft^2/F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.30"}},{"key":"cltd_f","label":"Glass CLTD (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"14"}}],"citation":"Citation: ASHRAE / ACCA Manual J fenestration cooling load Q_solar = A x SHGC x PSF and Q_cond = A x U x CLTD (by name). The peak solar factor is from the ASHRAE/ACCA table for the orientation and latitude; SHGC and U come from the NFRC label; interior shades reduce the solar term by a separate shade factor. One cooling-load component, not a Manual J."},
  "wip-percent-complete": {"inputs":[{"key":"contract_usd","label":"Contract value (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"cost_to_date_usd","label":"Cost to date (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"est_total_cost_usd","label":"Estimated total cost (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"billed_to_date_usd","label":"Billed to date (USD)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: Cost-to-cost percent-of-completion revenue recognition (construction accounting, ASC 606 / AICPA construction guide): percent complete = cost to date / estimated total cost, earned revenue = percent complete x contract, over/under billing = earned revenue - billed. A management aid; the CPA-prepared WIP schedule governs."},
  "wire-feed-deposition": {"inputs":[{"key":"wfs_in_min","label":"Wire feed speed (in/min)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"wire_dia_in","label":"Wire diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"deposition_eff","label":"Deposition efficiency (0-1)","kind":"number","options":null,"default":0.92,"attrs":{"step":"any","min":"0","value":"0.92"}}],"citation":"Citation: first-principles wire-volume geometry and steel density (0.2836 lb/in3), by name. Melt-off = WFS x 60 x area x density; deposition = melt-off x efficiency. The WPS and the process (spray vs short-circuit, gas, electrode extension) govern the real efficiency."},
  "wire-feed-speed-for-deposition": {"inputs":[{"key":"target_deposit_lb_hr","label":"Target deposition rate (lb/hr)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"wire_dia_in","label":"Wire diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"deposition_eff","label":"Deposition efficiency (0-1)","kind":"number","options":null,"default":0.92,"attrs":{"step":"any","min":"0","value":"0.92"}}],"citation":"Citation: first-principles wire-volume geometry and steel density (0.2836 lb/in3), by name, solved for the feed speed: WFS = deposit / (60 x area x density x efficiency). The WPS and the process (spray vs short-circuit, gas, electrode extension) govern the real efficiency and the qualified WFS range."},
  "wire-pulling-lubricant": {"inputs":[{"key":"length_ft","label":"Conduit run length (ft)","kind":"number","options":null,"default":400,"attrs":{"step":"any","min":"0","value":"400"}},{"key":"conduit_id_in","label":"Conduit inside diameter (in)","kind":"number","options":null,"default":3,"attrs":{"step":"any","min":"0","value":"3"}},{"key":"k_factor","label":"Film-coating K factor","kind":"number","options":null,"default":0.0015,"attrs":{"step":"any","min":"0","value":"0.0015"}},{"key":"bend_factor","label":"Bend / fill multiplier","kind":"number","options":null,"default":1,"attrs":{"step":"any","min":"0","value":"1.0"}}],"citation":"Citation: film-coating estimate by name. gallons = K x length x conduit ID^2 x bend factor. K is a film-coating rule from the lubricant manufacturer (~0.0015 for the common Polywater rule); more bends and fill raise the bend factor."},
  "wire-rope-clips": {"inputs":[{"key":"rope_diameter_in","label":"Wire rope diameter (in)","kind":"number","options":null,"default":0.75,"attrs":{"step":"any","min":"0","value":"0.75"}}],"citation":"Citation: wire-rope clip count and spacing by name (OSHA 29 CFR 1926.251 Table H-2 / H-20). clips by rope diameter (1/2->3, 3/4->4, 1->5, ...); spacing = 6 x diameter. U-bolt on the dead end ('never saddle a dead horse'); torque per the maker. The manufacturer and OSHA govern the termination."},
  "wire-rope-diameter-for-wll": {"inputs":[{"key":"wll_required_tons","label":"Required working load limit (tons)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"5"}},{"key":"construction_factor","label":"Construction factor (tons/in^2)","kind":"number","options":null,"default":46,"attrs":{"step":"any","min":"0","value":"46"}},{"key":"design_factor","label":"Design factor (safety factor)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}}],"citation":"Citation: Wire Rope Users Manual rule-of-thumb solved for the diameter: d = sqrt(WLL x design factor / construction factor), from MBS = factor x d^2 (factor ~46 tons/in^2 for IPS 6x19, editable) and WLL = MBS / design factor (5:1 typical). ESTIMATE - the manufacturer's certified rating governs; never use unmarked rope."},
  "wire-rope-strength": {"inputs":[{"key":"diameter_in","label":"Rope nominal diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","value":"0.5"}},{"key":"construction_factor","label":"Construction factor (tons/in^2)","kind":"number","options":null,"default":46,"attrs":{"step":"any","min":"0","value":"46"}},{"key":"design_factor","label":"Design factor (safety factor)","kind":"number","options":null,"default":5,"attrs":{"step":"any","min":"0","value":"5"}}],"citation":"Citation: Wire Rope Users Manual rule-of-thumb by name. MBS = factor x d^2 (factor ~46 tons/in^2 for IPS 6x19, editable); WLL = MBS / design factor (5:1 typical). ESTIMATE - the manufacturer's certified rating governs; never use unmarked rope."},
  "wireway-fill": {"inputs":[{"key":"width_in","label":"Interior width (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"height_in","label":"Interior height (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"conductor_area_in2","label":"Total conductor area (in^2, Ch.9 Table 5)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"ccc_count","label":"Current-carrying conductors","kind":"number","options":null,"default":0,"attrs":{"step":"1","min":"0"}}],"citation":"Citation: NEC 2023 376.22 (metal wireways) - conductor fill no more than 20% of the interior cross-section, and the 30 current-carrying conductor threshold for 310.15(C)(1) ampacity adjustment. The same 20% rule applies to auxiliary gutters (366.22). The AHJ governs. Free at nfpa.org/freeaccess."},
  "wobbe-index": {"inputs":[{"key":"hhv_btu_ft3","label":"Higher heating value (BTU/ft^3)","kind":"number","options":null,"default":1000,"attrs":{"step":"any","min":"0","value":"1000"}},{"key":"specific_gravity","label":"Specific gravity (vs air)","kind":"number","options":null,"default":0.6,"attrs":{"step":"any","min":"0","value":"0.60"}}],"citation":"Citation: Wobbe index of a fuel gas (AGA / ISO 13686 interchangeability), by name. WI = HHV / sqrt(specific gravity). Two gases of equal Wobbe deliver the same heat input through the same orifice at the same pressure. NG ~1,291, propane ~2,040. Captures orifice/heat-input, not flame speed; the supplier's analysis, the appliance listing, and the conversion kit govern."},
  "wood-emc": {"inputs":[{"key":"temperature_F","label":"Air temperature (F)","kind":"number","options":null,"default":0,"attrs":{"step":"any","value":"70"}},{"key":"rh_pct","label":"Relative humidity (%)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0","max":"100","value":"50"}}],"citation":"Citation: USDA Forest Products Laboratory Wood Handbook (Hailwood-Horrobin sorption equation, by name, not reproduced) with its four temperature polynomials W, K, K1, K2 (T in degrees F). The exact EMC varies by species; the IICRC S500 dry standard and the unaffected reference reading govern."},
  "worm-gear-geometry": {"inputs":[{"key":"axial_pitch_in","label":"Worm axial pitch (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"worm_starts","label":"Worm starts (threads, 1-4)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"worm_pitch_dia_in","label":"Worm pitch diameter (in)","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}},{"key":"wheel_teeth","label":"Worm-wheel teeth N","kind":"number","options":null,"default":0,"attrs":{"step":"any","min":"0"}}],"citation":"Citation: worm and worm-wheel geometry (Machinery's Handbook, first-principles): lead = axial pitch x starts, lead angle = atan(lead/(pi x worm pitch dia)), ratio = wheel teeth / starts, wheel pitch dia = N x axial pitch / pi, center distance = (d_worm + d_wheel)/2; a lead angle below ~5 degrees tends to self-lock. A shop aid; the gear drawing and the AGMA / Machinery's Handbook data govern."},
  "wsfu-demand": {"inputs":[{"key":"wsfu","label":"Total water-supply fixture units (WSFU)","kind":"number","options":null,"default":null,"attrs":{"step":"any","min":"0"}},{"key":"system_type","label":"System type","kind":"select","options":[{"value":"flush_tank","label":"Flush tank (gravity)"},{"value":"flush_valve","label":"Flush valve (flushometer)"}],"default":"flush_tank","attrs":null}],"citation":"Citation: Hunter's curve (NBS BMS65, Methods of Estimating Loads in Plumbing Systems) and IPC 2021 Appendix E (Table E103.3(2)) by name; the demand curve ships as editable breakpoints, not a transcribed table."},
};
